window.SUBJECTS=[{"id": "english-lang", "name": "English Language", "board": "AQA (8700)", "weeks": [{"ht": "Aut1", "t": "Fiction: reading and language analysis", "intro": "In AQA English Language Paper 1 you read an extract from a novel or short story and answer questions about it. First you need to understand what is happening and what the big ideas are. Then you explain how the writer's words create effects on the reader.", "how": ["Read the extract twice: once for the story, then again to spot details.", "For Question 1, list four things using only the lines you are told to read.", "Find the theme (the big idea) and the message (what the writer says about it).", "In language answers, name a method, quote a short phrase, then explain its effect.", "Zoom in on single words and explore their connotations: the feelings they suggest."], "example": {"q": "Read: 'The house crouched at the end of the lane, its windows staring blankly at the empty road.' How does the writer use language to describe the house?", "steps": ["Spot the method: the house is personified with the verbs 'crouched' and 'staring'.", "Explore 'crouched': it suggests an animal hiding, ready to pounce, so the house feels threatening.", "Explore 'staring blankly': the windows seem like lifeless eyes watching, which is unsettling.", "Add 'empty road': no one else is around, so the house feels isolated and lonely.", "Sum up the overall effect on the reader: unease and a sense that something is wrong."], "a": "The writer personifies the house as a crouching, staring creature, making it seem threatening, watchful and isolated."}, "walk": [{"h": "Find the key information", "b": "Question 1 asks you to list four things you learn from a set part of the extract. Keep your answers short and take them straight from the text. For example, from 'Ana pulled her red coat tighter against the rain' you learn that Ana is wearing a red coat and that it is raining."}, {"h": "Spot theme and message", "b": "A theme is a big idea, such as loneliness, fear or family. The message is what the writer seems to say about it. A story about a girl who moves school might have the theme of belonging and the message that kindness helps newcomers feel at home."}, {"h": "Analyse language", "b": "Use the pattern: method, evidence, effect. For example: 'The writer uses a simile, 'his voice was like gravel', which suggests he sounds rough and harsh, making him seem unfriendly.' Always explain what the words make the reader think or feel."}], "qs": [["In AQA English Language Paper 1, Question 1 asks you to…", ["List four things from a set part of the extract", "Write a story based on the extract", "Compare two different extracts", "Analyse the structure of the whole text"], "Question 1 is a retrieval task: you list four things from the lines you are given."], ["What is a theme in a story?", ["A big idea the story explores, such as loneliness", "The order in which events happen", "The place where the story is set", "The name of the main character"], "A theme is a big idea, like fear, love or loneliness, that runs through a story."], ["'The trees whispered secrets to each other.' Which method is used?", ["Personification", "Simile", "Alliteration", "Onomatopoeia"], "Trees cannot really whisper or keep secrets, so they are given human qualities: personification."], ["Which of these is a simile?", ["Her eyes sparkled like diamonds.", "Her eyes were diamonds.", "Her eyes sparkled brightly.", "Diamonds danced in the dark."], "A simile compares two things using 'like' or 'as'."], ["What are the connotations of a word?", ["The ideas or feelings a word suggests", "The dictionary meaning of a word", "Words that sound the same", "The number of syllables in a word"], "Connotations are the extra ideas a word brings to mind, beyond its basic meaning."], ["In 'The old man shuffled slowly to the door', what does 'shuffled' suggest?", ["He is weak, tired or frail", "He is excited and full of energy", "He is angry with the visitor", "He is in a great hurry"], "To shuffle is to walk dragging your feet, which suggests weakness or tiredness."], ["'The classroom was a zoo.' What does this metaphor suggest?", ["The room was noisy, wild and out of control", "The class was learning about animals", "The pupils were calm and quiet", "The room had cages in it"], "Comparing the room to a zoo suggests wild, noisy, uncontrolled behaviour."], ["Which of these is a MESSAGE rather than just a theme?", ["Dishonesty can destroy trust between friends", "Friendship", "Honesty", "Trust"], "A single word is a theme; a message is a statement about the theme."], ["Which sentence best explains the effect of language?", ["The verb 'slammed' suggests anger, showing his frustration", "The writer uses a verb, which is good", "This makes the reader want to read on", "The word 'slammed' is in the third paragraph"], "It names the word, explores what it suggests and links it to the character's feelings."], ["A family dinner is described with 'battle', 'wounded', 'retreat' and 'enemy'. This creates…", ["A semantic field of war, suggesting conflict", "A simile comparing dinner to war", "Onomatopoeia that copies sounds", "A calm and peaceful mood"], "A semantic field is a group of words linked to one topic; here war words suggest the family is in conflict."]], "bonus": ["What is a verb?", ["A word that shows an action or state, like 'run'", "A describing word, like 'tall'", "A naming word, like 'table'", "A word that describes how, like 'quickly'"], "Verbs are doing or being words; spotting them is key to language analysis."]}, {"ht": "Aut2", "t": "Fiction: structure, evaluation and writing", "intro": "Structure is how a writer orders and organises a text to keep the reader interested. Evaluation means judging how well a writer achieves an effect. In Section B of Paper 1 you write your own description or story, which is worth half the marks on the paper.", "how": ["For structure, track what the writer focuses on at the start, middle and end, and how that focus shifts.", "For evaluation (Question 4), say how far you agree with the statement and support it with quotations.", "Spend about five minutes planning your own writing before you start.", "Show, don't tell: reveal characters through actions, speech and small details.", "Give your story a clear shape and vary your sentence lengths and paragraph openings."], "example": {"q": "Write the opening of a story set in an abandoned fairground.", "steps": ["Plan four or five paragraphs that zoom from the whole fairground to one small detail.", "Hook the reader with a short opening sentence, such as 'Rust. That was the first thing Maya smelt.'", "Describe the setting using several senses: the creak of a rusty wheel, peeling paint, cold wind.", "Introduce the character through action, such as Maya gripping the gate before stepping through.", "End the section with a shift or mystery, such as a single light flickering on in the ghost train."], "a": "A strong opening hooks the reader, builds a vivid setting with the senses, shows the character through action and ends with a shift that creates tension."}, "walk": [{"h": "Analysing structure", "b": "Structure is about the order of ideas, not individual words. Ask what the writer focuses on first and why the focus changes. For example, a writer might begin with a wide view of a snowy village, then zoom in on one lit window, then on a child's face, to draw the reader closer."}, {"h": "Evaluating a statement", "b": "Question 4 gives you a statement, such as 'This part of the story is really tense', and asks how far you agree. Give your opinion clearly, then prove it with evidence and methods. For example: 'I strongly agree, because the short sentence 'Then nothing.' makes the reader hold their breath.'"}, {"h": "Writing description and narrative", "b": "Build characters by showing: instead of 'Tom was nervous', write 'Tom picked at the edge of his sleeve.' Make settings vivid with the senses. Shape a narrative with an opening, rising tension, a climax and an ending, and keep the number of characters small so you have time to develop them."}], "qs": [["What does 'structure' mean in a fiction extract?", ["How the text is ordered and organised", "The individual words the writer chooses", "The spelling and punctuation used", "The number of characters in the story"], "Structure is about the order and organisation of a text, such as shifts in focus."], ["Which Paper 1 question asks how far you agree with a statement?", ["Question 4, evaluation", "Question 1, list four things", "Question 2, language", "Question 3, structure"], "Question 4 gives you a statement to evaluate and is worth 20 marks."], ["What does 'show, don't tell' mean?", ["Reveal feelings through actions, speech and details", "Tell the reader exactly how characters feel", "Draw pictures alongside your writing", "Write only in dialogue"], "Showing lets the reader work out feelings from clues, which is more engaging."], ["Which sentence SHOWS that a character is nervous?", ["Her fingers drummed on the table as she checked the clock.", "She was very nervous.", "She felt nervous and scared.", "Nervousness was what she felt."], "The drumming fingers and clock-checking let us work out her nerves without being told."], ["Starting a story in the middle of the action is called…", ["In medias res", "Flashback", "Cliffhanger", "Foreshadowing"], "In medias res is Latin for 'in the middle of things'."], ["A writer opens with a wide view of a city, then focuses on one lit window. This is…", ["Zooming in to narrow the focus", "A flashback", "A circular structure", "A cliffhanger ending"], "Moving from a wide view to one detail is zooming in, like a camera."], ["What is the best way to make a setting vivid?", ["Use the senses to build a clear picture", "List every object in the room", "Describe only what it looks like", "Avoid using any adjectives"], "Sights, sounds, smells and textures help the reader imagine being there."], ["A story that ends in the same place it began has…", ["A cyclical (circular) structure", "A linear structure", "An in medias res opening", "A flashback structure"], "A cyclical structure returns to its starting point, often showing change or no change."], ["Why might a writer use a one-word paragraph, such as 'Silence.'?", ["To create emphasis and tension", "To save space on the page", "Because the writer forgot to finish", "To show the narrator has changed"], "Isolating one word makes it stand out and slows the reader down."], ["In Paper 1 Section B, how many marks are for technical accuracy?", ["16 out of 40", "24 out of 40", "8 out of 40", "40 out of 40"], "Section B gives 24 marks for content and organisation and 16 for technical accuracy."]], "bonus": ["Which sentence uses speech punctuation correctly?", ["'Wait for me,' called Sam.", "'Wait for me' called Sam.", "'Wait for me, called Sam.'", "Wait for me, called 'Sam.'"], "The spoken words and the comma go inside the speech marks, then the rest of the sentence follows."]}, {"ht": "Spr1", "t": "Unseen poetry: meaning and methods", "intro": "An unseen poem is one you have never read before, and you have to make sense of it on your own. These skills are tested in the AQA English Literature exam and help you read closely in Language too. You work out what the poem means, then how the poet's language and structure create that meaning.", "how": ["Read the poem at least twice and work out what it is literally about first.", "Ask who is speaking, who they are speaking to and how they feel.", "Comment on language: imagery, word choices and sound effects.", "Comment on structure and form: stanzas, line breaks, rhyme and rhythm.", "Look for a shift in tone, often in the final stanza, and explain what changes."], "example": {"q": "Read this poem: 'The door complains on rusted hinges, / and dust hangs gold in the slanted light. / His tools still wait in patient rows, / as if he'll be back before tonight.' How does the poet present memories of Grandad?", "steps": ["Meaning first: the speaker visits Grandad's shed, and the clues suggest he has died or gone.", "Language: the door 'complains' and the tools 'wait in patient rows', personification that makes the shed seem to miss him.", "Imagery: 'dust hangs gold' shows time has passed, but 'gold' suggests the memories are precious.", "Structure: the rhyme of 'light' and 'tonight' ends the poem on a hopeful word that feels sad, because he will not return."], "a": "The poet presents loving but sad memories, using personification to make the shed seem to wait loyally for a Grandad who will not come back."}, "walk": [{"h": "Reading for meaning", "b": "Start with the surface: what is happening, where and to whom? Then look for a deeper idea. A poem about a broken toy might really be about growing up and leaving childhood behind. Remember the speaker is the voice of the poem and is not always the poet."}, {"h": "Analysing language", "b": "Look for imagery such as similes, metaphors and personification, and for sound effects. In 'the sea's soft sigh', the repeated 's' sounds (sibilance) create a calm, hushed mood. Always explain what the image or sound makes you feel."}, {"h": "Analysing structure and form", "b": "Structure is how the poem is built: stanzas, line lengths, rhyme and punctuation. Enjambment, where a sentence runs over a line break, can create speed or surprise. A caesura, a pause in the middle of a line, can show hesitation or shock."}], "qs": [["What is the 'speaker' of a poem?", ["The voice telling the poem, not always the poet", "Always the poet themselves", "The person the poem is written about", "The person reading the poem aloud"], "Poets often invent a voice, so we call it the speaker."], ["A group of lines in a poem is called a…", ["Stanza", "Paragraph", "Chapter", "Caption"], "In poetry, a group of lines is a stanza, like a paragraph in prose."], ["When a sentence runs on from one line to the next with no punctuation, this is…", ["Enjambment", "Caesura", "End-stopping", "Rhyme"], "Enjambment carries the sense over the line break."], ["A pause in the middle of a line, often marked by punctuation, is a…", ["Caesura", "Enjambment", "Stanza", "Couplet"], "A caesura is a break or pause within a line."], ["Repeated 's' sounds, as in 'the sea's soft sigh', are called…", ["Sibilance", "Assonance", "Onomatopoeia", "Plosives"], "Sibilance is the repetition of soft 's' and 'sh' sounds."], ["Lines end with 'night', 'tree', 'light', 'sea'. What is the rhyme scheme?", ["ABAB", "AABB", "ABCB", "ABBA"], "Night and light rhyme (A), tree and sea rhyme (B), alternating: ABAB."], ["What is a volta?", ["A turning point in a poem's mood or argument", "The final line of any poem", "A type of half-rhyme", "A line that is repeated"], "Volta is Italian for 'turn'; it marks a shift in the poem."], ["'My heart is a locked box.' What does this metaphor suggest?", ["The speaker keeps their feelings hidden", "The speaker has a heart problem", "The speaker loves collecting boxes", "The speaker is open and honest"], "A locked box keeps things inside, suggesting hidden emotions."], ["A poem with no regular rhyme or rhythm is written in…", ["Free verse", "Sonnet form", "Ballad form", "Limerick form"], "Free verse does not follow a fixed pattern of rhyme or metre."], ["Which is the strongest analysis of 'The cold sea swallowed the boat whole'?", ["'Swallowed' presents the sea as a hungry beast, showing nature's power", "The writer uses a verb to describe the sea", "This is a simile because it compares the sea", "The sea is cold, which is a fact about weather"], "It picks out a key word, explains the image and links it to a bigger idea."]], "bonus": ["How many syllables are in the word 'beautiful'?", ["Three", "Two", "Four", "Five"], "Beau-ti-ful has three beats; counting syllables helps you hear a poem's rhythm."]}, {"ht": "Spr2", "t": "Comparing two unseen poems", "intro": "Sometimes you are given two poems on a similar theme and asked to compare them. In AQA English Literature Paper 2, the second unseen poetry question asks you to compare the methods the two poets use. Good comparison shows how poems are alike and different at the same time.", "how": ["Find what the two poems have in common, usually the theme or subject.", "Compare throughout your answer instead of writing about one poem and then the other.", "Use comparative connectives such as 'similarly', 'whereas' and 'in contrast'.", "Compare methods (language, structure and form), not just what the poems are about.", "Support each point with a short quotation from both poems."], "example": {"q": "Poem A: 'Horns blare. The traffic snarls and spits; / grey towers block the sun. / I push through crowds who never look, / and run, and run, and run.' Poem B: 'The cockerel calls; the mist lifts slow / from fields of quiet green. / My neighbour waves across the hedge, / the gentlest morning seen.' Compare how the poets present a morning.", "steps": ["Find the link: both poems describe the start of a day.", "Compare tone: Poem A is stressful and hostile, whereas Poem B is calm and peaceful.", "Compare language: Poem A personifies traffic as an animal that 'snarls and spits', while Poem B uses the gentle verb 'lifts'.", "Compare people: in Poem A the crowds 'never look', showing loneliness, but in Poem B the neighbour 'waves', showing community.", "Compare structure: the repetition 'run, and run, and run' creates a rushed rhythm, in contrast to Poem B's slow, smooth lines."], "a": "Both poems describe a morning, but Poem A presents it as rushed, hostile and lonely, whereas Poem B presents it as calm, gentle and friendly."}, "walk": [{"h": "Find the link", "b": "Before comparing, decide what joins the poems. It might be a theme like loss, a setting like the sea, or a relationship like parent and child. For example, two poems about leaving home might share sadness but differ in whether the speaker feels hopeful."}, {"h": "Compare the methods", "b": "Look at what each poet does with language, structure and form. One poem might use harsh, short lines while the other flows with enjambment. Ask why each poet made that choice: short, broken lines might show grief, while long lines might show calm thinking."}, {"h": "Write comparatively", "b": "Weave both poems into each paragraph. Try this frame: 'Both poets present..., but in Poem A... whereas in Poem B...'. For example: 'Both poets present a morning, but Poem A uses violent verbs whereas Poem B uses soft, gentle ones.'"}], "qs": [["When comparing two poems, what should you look for first?", ["What they have in common, such as a shared theme", "Which poem is longer", "Which poet is more famous", "How many words rhyme"], "A shared link gives your comparison a clear focus."], ["Which connective shows a DIFFERENCE?", ["Whereas", "Similarly", "Likewise", "Also"], "'Whereas' introduces a contrast between two things."], ["Which connective shows a SIMILARITY?", ["Likewise", "However", "In contrast", "On the other hand"], "'Likewise' means 'in the same way'."], ["In AQA Literature Paper 2, the unseen poetry comparison question (27.2) is worth…", ["8 marks", "24 marks", "4 marks", "30 marks"], "Question 27.1 on one poem is worth 24 marks; the comparison, 27.2, is worth 8."], ["What does the comparison question (27.2) focus on?", ["The methods the two poets use", "Facts about the poets' lives", "Writing your own poem on the theme", "Spelling mistakes in the poems"], "It asks you to compare how the poets use language, structure and form."], ["Poem A: 'The traffic snarls and spits.' Poem B: 'The mist lifts slow.' What contrast do these create?", ["An aggressive city against a calm countryside", "Both show a peaceful morning", "Both show an angry morning", "A hot city against a cold village"], "'Snarls and spits' sounds violent, while 'lifts slow' sounds gentle."], ["Which is the best comparative sentence?", ["Both poets present love, but Poem A celebrates it whereas Poem B mourns it.", "Poem A is about love. Poem B is also a poem.", "I prefer Poem A because it is shorter.", "Poem B uses words in its lines."], "It links both poems in one sentence and shows a clear similarity and difference."], ["One poem is a tightly rhymed sonnet; the other is free verse. What are you comparing?", ["Form", "Theme", "Context", "Setting"], "Form is the type or shape of a poem, such as sonnet or free verse."], ["Both poems are about loss, and one uses short, broken lines. What might this suggest?", ["Grief makes the speaker struggle to speak", "The poet ran out of ideas", "The speaker feels calm and content", "The poem is meant to be funny"], "Broken lines can mirror broken feelings, like sobbing or hesitating."], ["Why is integrated comparison better than writing about each poem separately?", ["It shows links and differences clearly at every point", "It lets you write about only one poem", "It means you need no quotations", "It is shorter, so it saves time"], "Comparing in every paragraph keeps both poems in focus, which is what the question rewards."]], "bonus": ["What is the opposite (antonym) of 'calm'?", ["Agitated", "Peaceful", "Quiet", "Still"], "Agitated means worried or restless, the opposite of calm; the other words are synonyms."]}, {"ht": "Sum1", "t": "Non-fiction: purpose and viewpoint", "intro": "Non-fiction texts are about real life, such as articles, letters, speeches and diaries. AQA English Language Paper 2 gives you two sources, one from the 19th century and one from the 20th or 21st century, and asks how writers present their viewpoints. Understanding purpose and perspective helps you read the world around you more critically.", "how": ["Work out the purpose: to inform, persuade, argue, advise or entertain.", "Identify the writer's perspective: their attitude or point of view on the topic.", "Look at how the viewpoint is shown through tone, language choices and structure.", "When comparing perspectives, compare both what the writers think and how they show it.", "Think about when each source was written, because attitudes change over time."], "example": {"q": "Read: 'Every morning I cycle to school. Ten minutes, fresh air, no traffic jams. Yet only one in twenty pupils joins me. Why? Because we have convinced ourselves that roads are too dangerous. The real danger is a generation that never moves.' What is the writer's perspective, and how does she present it?", "steps": ["Identify the perspective: she strongly believes pupils should cycle to school.", "List of benefits: 'Ten minutes, fresh air, no traffic jams' makes cycling sound quick and easy.", "Statistic: 'one in twenty' shows how few pupils cycle, adding authority.", "Rhetorical question: 'Why?' makes the reader think about their own reasons.", "Final twist: 'The real danger' turns the worry about danger around, ending powerfully."], "a": "The writer believes pupils should cycle to school and persuades with a list of benefits, a statistic, a rhetorical question and a final sentence that turns the idea of danger around."}, "walk": [{"h": "Purpose and audience", "b": "Ask why the text was written and who it is for. A leaflet called 'Five Ways to Save Water' is written to advise families. A newspaper column attacking a new road is written to argue. Purpose and audience shape every choice a writer makes."}, {"h": "Perspective and tone", "b": "Perspective is the writer's attitude, such as for, against or mixed. Tone is the feeling in their voice, such as angry, humorous or worried. In 'This shameful plan must be stopped', the word 'shameful' shows a strongly critical tone."}, {"h": "How viewpoints are presented", "b": "Writers use methods such as anecdotes (short personal stories), statistics, rhetorical questions, emotive language and expert opinion. Structure matters too: a writer might open with a shocking fact and end with a call to action. Always explain how each method pushes the reader towards the writer's view."}], "qs": [["What does 'purpose' mean in non-fiction?", ["Why the text was written, such as to persuade", "Who the text is written for", "Where the text was published", "How long the text is"], "Purpose is the reason for writing; who it is for is the audience."], ["A leaflet telling you how to stay safe online mainly aims to…", ["Advise", "Entertain", "Argue against the internet", "Describe a place"], "It gives helpful guidance, so its main purpose is to advise."], ["What is a writer's 'perspective'?", ["Their point of view or attitude on a topic", "The list of facts in the text", "The layout of the text", "The title of the text"], "Perspective is how the writer sees and feels about the topic."], ["Which of these is a FACT rather than an opinion?", ["The school opened in 1998.", "The school has an amazing atmosphere.", "Everyone should love maths.", "Homework is a waste of time."], "A date can be checked and proved; the others are personal views."], ["In AQA Paper 2, how many sources do you read?", ["Two: one 19th-century, one 20th- or 21st-century", "One modern newspaper article", "Three, all from the 21st century", "Four short poems"], "Paper 2 always pairs a 19th-century source with a 20th- or 21st-century one."], ["'Why should we let our parks disappear?' This is…", ["A rhetorical question", "A statistic", "An anecdote", "A simile"], "It is asked for effect, to make the reader think, not to get an answer."], ["A writer tells a short personal story to support their argument. This is…", ["An anecdote", "A statistic", "A counter-argument", "A metaphor"], "An anecdote is a brief real-life story that makes a point feel personal."], ["'This disgraceful, shameful decision' suggests the writer's tone is…", ["Angry and critical", "Neutral and balanced", "Joyful and excited", "Confused and unsure"], "The strong negative adjectives show anger and criticism."], ["Paper 2 Question 4 asks you to compare…", ["The writers' perspectives and how they convey them", "Only the facts in each source", "Which source is longer", "The spelling in each source"], "Question 4 compares viewpoints and the methods used to present them."], ["Why might a 19th-century writer's view of children working differ from a modern one?", ["Attitudes and laws on child labour have changed", "Children did not work in the 19th century", "Modern writers never discuss work", "Old texts always agree with modern ones"], "Many children worked in Victorian times; laws and attitudes have changed greatly since."]], "bonus": ["What is the main purpose of a recipe?", ["To instruct", "To persuade", "To entertain", "To argue"], "A recipe tells you step by step how to make something, so it instructs."]}, {"ht": "Sum2", "t": "Non-fiction writing and speeches", "intro": "In Section B of Paper 2 you write your own non-fiction text giving your viewpoint, such as an article, letter or speech. You also prepare and deliver a speech for the Spoken Language endorsement, which is graded separately from your GCSE. Choosing the right genre, register and persuasive devices makes your voice powerful.", "how": ["Check GAP before writing: genre (form), audience and purpose.", "Match your register to the audience: formal for a headteacher, semi-formal for your year group.", "Use persuasive devices such as rhetorical questions, the rule of three, emotive language and direct address.", "Plan an introduction, three or four points including a counter-argument, and a strong conclusion.", "When delivering a speech, use Standard English, speak clearly, make eye contact and pause for effect."], "example": {"q": "Write the opening of a speech to your year group arguing that school should start at 10am.", "steps": ["Check GAP: genre is a speech, audience is your year group, purpose is to persuade.", "Choose a semi-formal register: friendly, but in Standard English with no slang.", "Hook with direct address and a rhetorical question: 'Who here felt truly awake at 8:30 this morning?'", "Add a rule of three: 'Imagine waking naturally, eating a proper breakfast and arriving ready to learn.'", "State your viewpoint clearly: 'That is why I believe school should start at 10am.'"], "a": "A strong opening hooks the audience with direct address and a rhetorical question, uses a rule of three and clearly states the speaker's viewpoint."}, "walk": [{"h": "Genre and register", "b": "Genre is the type of text, such as a letter, article, leaflet or speech, and each has features: a letter has a greeting, an article has a headline. Register is how formal your language is. A letter to a council would say 'I am writing to express my concern', not 'This is well bad'."}, {"h": "Persuasive and rhetorical devices", "b": "Rhetorical questions make the audience think. The rule of three, like 'safer, cleaner, healthier', sounds memorable. Emotive language stirs feelings, and direct address ('you') makes listeners feel involved. Use a counter-argument, then knock it down, to show your view is stronger."}, {"h": "Planning and delivering a speech", "b": "For Spoken Language you plan a short presentation, deliver it and answer questions from your audience. It is graded Pass, Merit or Distinction and reported separately from your GCSE grade. Practise aloud, use cue cards with key words, look up at your audience and pause after important points."}], "qs": [["What does 'register' mean?", ["How formal or informal your language is", "The list of names taken in class", "The topic you are writing about", "The length of your writing"], "Register is the level of formality, chosen to suit the audience."], ["Which opening suits a formal letter to a headteacher?", ["Dear Mrs Patel,", "Hey Miss!", "Yo, what's up?", "To whoever reads this,"], "A formal letter starts with 'Dear' and the person's title and surname."], ["'Stand up, speak out and make a difference.' This uses…", ["The rule of three", "A rhetorical question", "A statistic", "An anecdote"], "Three linked phrases in a row make a memorable triple."], ["Using 'you' to speak straight to the audience is called…", ["Direct address", "Emotive language", "Hyperbole", "Alliteration"], "Direct address involves the reader or listener personally."], ["Why include a counter-argument in persuasive writing?", ["To show you've considered other views, then rebut them", "To change your mind halfway through", "To confuse the reader", "To make the piece longer"], "Answering the other side makes your argument look fair and stronger."], ["'This is the worst decision in the history of the universe!' is an example of…", ["Hyperbole", "A statistic", "Understatement", "A simile"], "Hyperbole is deliberate exaggeration for effect."], ["In the GCSE Spoken Language endorsement, students are graded…", ["Pass, Merit or Distinction", "Grades 1 to 9", "A* to G", "Out of 40 marks"], "Spoken Language is reported separately as Pass, Merit or Distinction."], ["When delivering a speech, which helps your audience most?", ["Speaking clearly, pausing and making eye contact", "Reading quickly with your head down", "Whispering so they lean in", "Using lots of slang"], "Clear delivery and eye contact keep listeners engaged."], ["Which sentence is in Standard English?", ["We were going to the shops.", "We was going to the shops.", "We is going to the shops.", "Us was going to the shops."], "Standard English uses 'we were', with the subject and verb agreeing."], ["Which is a form you could be asked to write in Paper 2 Section B?", ["A newspaper article giving your view", "A sonnet about nature", "A ghost story", "A play script"], "Paper 2 Section B asks for non-fiction, such as articles, letters, speeches, essays or leaflets."]], "bonus": ["Which of these words is a conjunction?", ["Because", "Quickly", "Happy", "Under"], "Conjunctions like 'because' join ideas, which helps you build reasons in an argument."]}]}, {"id": "english-lit", "name": "English Literature", "board": "AQA (8702)", "weeks": [{"ht": "Aut1", "t": "Things Fall Apart: plot and characters", "intro": "Things Fall Apart is a novel by the Nigerian writer Chinua Achebe, published in 1958. It follows Okonkwo, a proud and respected man in the Igbo village of Umuofia, whose life collapses as his world changes. Knowing the plot and the key characters well is the foundation for everything else you write about the novel.", "how": ["Learn the novel in its three parts: life in Umuofia, exile in Mbanta, and the return as colonial rule arrives.", "For each character, know what they want, what they fear and how they change.", "Link characters to Okonkwo: many of them show a different way of being a man or a family member.", "Describe events in your own words and keep the order of events clear.", "Pick out a few key moments for each character that you can use as evidence."], "example": {"q": "How does Achebe present the relationship between Okonkwo and his father, Unoka?", "steps": ["Describe Unoka: a gentle, music-loving man who enjoyed his flute, avoided fighting and died owing money to many people.", "Describe Okonkwo's reaction: he is ashamed of his father and builds his whole life around being the opposite.", "Give evidence in your own words: Okonkwo works hard on his farm, wins titles and becomes famous as a wrestler.", "Explain the effect: his fear of seeming weak like Unoka drives his harsh and sometimes violent actions.", "Conclude: Achebe shows that Okonkwo's greatest strength and his downfall both come from fear of his father's failure."], "a": "Achebe presents Okonkwo as defined by shame about Unoka, so his fear of being seen as weak shapes his success and leads to his tragic choices."}, "walk": [{"h": "Part One: Umuofia", "b": "Okonkwo has become a great man through hard work, after throwing a famous wrestler known as the Cat. A boy called Ikemefuna is given to Umuofia by a neighbouring village as compensation for a killing and lives in Okonkwo's household for three years. When the village elders decide the boy must die, Okonkwo joins in and strikes the fatal blow himself, because he is afraid of looking weak."}, {"h": "Part Two: exile in Mbanta", "b": "At a funeral, Okonkwo's gun goes off by accident and kills a boy. This is a crime against the earth goddess, so he must leave Umuofia for seven years and live in his mother's village, Mbanta. During his exile, Christian missionaries arrive, and his eldest son Nwoye joins them."}, {"h": "Part Three: return", "b": "Okonkwo returns to find the church and a colonial government with its own courts in Umuofia. After clashes, village leaders are imprisoned and humiliated. Okonkwo kills a court messenger, but the village does not rise up with him, and he takes his own life. His friend Obierika blames the colonisers for driving a great man to this end."}], "qs": [["Who wrote Things Fall Apart?", ["Chinua Achebe", "Wole Soyinka", "Ngũgĩ wa Thiong'o", "Chimamanda Ngozi Adichie"], "Chinua Achebe, a Nigerian writer, published the novel in 1958."], ["In which village does Okonkwo live at the start of the novel?", ["Umuofia", "Mbanta", "Mbaino", "Abame"], "Okonkwo is a leading man of Umuofia; Mbanta is his mother's village."], ["How did Okonkwo first become famous as a young man?", ["He threw a great wrestler called the Cat", "He inherited his father's wealth", "He became a Christian missionary", "He was chosen as a priest"], "Beating the unbeaten wrestler brought Okonkwo fame across the villages."], ["What is Okonkwo's father, Unoka, known for?", ["Being gentle, playing the flute and owing debts", "Being a fearsome warrior with many titles", "Being the richest farmer in the village", "Being a strict and violent father"], "Unoka loved music and conversation but was poor and in debt."], ["Why does Ikemefuna come to live in Okonkwo's household?", ["He is given to Umuofia as compensation for a killing", "He is Okonkwo's nephew from Mbanta", "He runs away from his own family", "He is sent to train as a wrestler"], "His village handed him over to avoid war after a woman of Umuofia was killed."], ["Why does Okonkwo kill Ikemefuna, even though he cares for him?", ["He is afraid of being thought weak", "Ikemefuna has betrayed the village", "Ikemefuna attacks Nwoye", "The missionaries order him to"], "Okonkwo's fear of weakness makes him strike the blow, despite being warned not to take part."], ["Which character joins the Christian missionaries?", ["Nwoye", "Ezinma", "Obierika", "Unoka"], "Nwoye, Okonkwo's eldest son, is drawn to the church and leaves his father."], ["Why is Okonkwo exiled for seven years?", ["His gun goes off by accident and kills a boy", "He refuses to pay his debts", "He burns down the church", "He breaks the rules of a wrestling match"], "An accidental killing is an offence against the earth goddess, so he must leave."], ["What does Okonkwo often wish about his daughter Ezinma?", ["That she had been born a boy", "That she would become a priestess", "That she would marry a missionary", "That she would leave Umuofia"], "Okonkwo sees Ezinma as understanding him best and wishes she were a son."], ["What role does Obierika mainly play in the novel?", ["A loyal friend who questions some traditions", "Okonkwo's greatest enemy", "The leader of the missionaries", "The district commissioner's messenger"], "Obierika supports Okonkwo but quietly asks whether some customs are right."]], "bonus": ["What do we call the main character of a story?", ["The protagonist", "The narrator", "The antagonist", "The author"], "The protagonist is the central character; in this novel it is Okonkwo."]}, {"ht": "Aut2", "t": "Things Fall Apart: themes and context", "intro": "Things Fall Apart explores identity, masculinity, culture and the damage caused by colonialism. Achebe wrote it partly to show Igbo society as complex and full of meaning, rather than the simple picture given in many European books about Africa. Understanding the themes and context helps you explain why the novel matters.", "how": ["Know that the novel is set in the late 1800s in what is now south-eastern Nigeria, before and during British colonial rule.", "Show that Achebe presents Igbo society fairly: rich in law, art and debate, but with flaws too.", "Link each theme to Okonkwo and at least one other character.", "Use context to explain choices, for example why the missionaries attract outcasts first.", "Use phrases like 'Achebe suggests...' to show the ideas are the writer's choices."], "example": {"q": "How does Achebe explore masculinity through Okonkwo?", "steps": ["State the idea: Okonkwo believes a real man must be strong, hard-working and never show gentle feelings.", "Give evidence in your own words: he hides his love for Ikemefuna and is harsh with Nwoye.", "Show Achebe's challenge: his exile is to his mother's village, where his uncle Uchendu teaches him the value of the mother's side.", "Link to the ending: his rigid idea of manhood leaves him unable to adapt when Umuofia changes.", "Conclude with the message: Achebe suggests that a narrow, fearful idea of masculinity is destructive."], "a": "Achebe presents Okonkwo's extreme view of masculinity as rooted in fear and shows that his inability to be gentle or flexible leads to tragedy."}, "walk": [{"h": "Igbo society", "b": "Umuofia has its own government, made up of elders, titles, courts and religious beliefs. People believe in a personal spirit called a chi, and the egwugwu, masked figures representing ancestral spirits, settle disputes. Achebe also shows harsh customs, such as leaving newborn twins to die in the forest, which troubles characters like Nwoye and Obierika."}, {"h": "Patriarchy and identity", "b": "Umuofia is patriarchal: men hold power and titles, and qualities seen as 'female' are looked down on. Okonkwo's identity is built on rejecting anything he sees as weak or womanly. Yet the novel also shows the importance of women, such as the priestess of the oracle and the role of the mother's family during Okonkwo's exile."}, {"h": "Change and colonialism", "b": "Missionaries bring a new religion, then colonial officials bring courts and prisons. The church first attracts people who were outcasts or unhappy in the old system, which splits the community from within. The title comes from a poem by W. B. Yeats: 'Things fall apart; the centre cannot hold', which captures how the village's unity is broken."}], "qs": [["Roughly when is Things Fall Apart set?", ["The late 1800s", "The 1500s", "The 1960s", "The 21st century"], "The novel is set in the late 19th century, when British colonial rule was spreading."], ["The novel's setting is in what is now…", ["Nigeria", "Kenya", "South Africa", "Ghana"], "Umuofia is a fictional village in Igboland, south-eastern Nigeria."], ["In Igbo belief in the novel, what is a 'chi'?", ["A person's personal spirit or god", "A type of yam festival", "A village court", "A wrestling champion"], "A chi is a personal spirit that is believed to guide each person's fortune."], ["What does 'patriarchy' mean?", ["A society in which men hold most of the power", "A society ruled by priests", "A society with no laws", "A society where everyone is equal"], "Patriarchy comes from the Greek for 'rule of the father'."], ["Why do many outcasts join the church first?", ["It welcomes people the old system rejected", "They are paid to join", "The elders order them to", "They want to become warriors"], "People treated as outcasts find acceptance in the new religion, which divides the village."], ["Where does the title Things Fall Apart come from?", ["A poem by W. B. Yeats", "A speech by a British governor", "A traditional Igbo proverb", "A line from the Bible"], "Achebe took the title from Yeats's poem 'The Second Coming'."], ["What is 'cultural relativism'?", ["Judging a culture by its own values, not outsiders'", "Believing one culture is better than all others", "Copying another country's customs", "Refusing to learn about other cultures"], "Achebe asks readers to understand Igbo society on its own terms."], ["Why did Achebe partly write the novel?", ["To give a fuller picture of Igbo life than many European books did", "To argue that colonial rule was always good", "To write a guide to farming yams", "To retell an old English legend"], "Achebe wanted to show African society as complex and meaningful."], ["Which character shows the gentler missionary approach, listening to local beliefs?", ["Mr Brown", "Reverend Smith", "The District Commissioner", "Enoch"], "Mr Brown is patient and respectful; his strict replacement, Reverend Smith, causes conflict."], ["How does Okonkwo's ending link to the theme of change?", ["He cannot adapt, and his village will not fight with him", "He becomes a missionary and is welcomed", "He leaves to start a new village far away", "He is crowned king by the colonisers"], "Okonkwo's rigid identity cannot survive the changes, and he dies alone."]], "bonus": ["What is a 'theme' in literature?", ["A big idea a text explores, like identity", "The order of events in the plot", "The main character's name", "The place where a story is set"], "Themes are the big ideas, such as identity, change and power."]}, {"ht": "Spr1", "t": "Merchant of Venice: plot and characters", "intro": "The Merchant of Venice is a play by William Shakespeare, written around 1596–1597. It tells of a loan with a terrible condition, a test of three caskets and a dramatic trial. You need to know the plot and the main characters well for AQA Literature Paper 1, Section A.", "how": ["Learn the two settings: Venice, a busy city of trade and law, and Belmont, Portia's peaceful estate.", "Follow the two main plots: the bond between Antonio and Shylock, and the casket test for Portia's hand.", "For each character, learn one or two short quotations and what they show.", "Track how each character changes from the start of the play to the end.", "Remember the play is called a comedy, but it has serious and troubling scenes."], "example": {"q": "How does Shakespeare present Antonio at the start of the play?", "steps": ["Find the key line: he opens with 'In sooth, I know not why I am so sad.'", "Explain: Antonio is melancholy and cannot explain why, which creates mystery.", "Add his generosity: he agrees to borrow money from Shylock so that Bassanio can woo Portia.", "Add a contrast: he has insulted and spat at Shylock in the past, showing prejudice.", "Sum up: Antonio is loyal and generous to friends but cruel to Shylock."], "a": "Shakespeare presents Antonio as sad, generous and loyal to Bassanio, but also prejudiced and cruel towards Shylock."}, "walk": [{"h": "The bond", "b": "Bassanio needs money to travel to Belmont and woo the wealthy Portia. His friend Antonio, a merchant whose money is tied up in ships at sea, borrows 3,000 ducats from the moneylender Shylock. Shylock asks for a pound of Antonio's flesh if the loan is not repaid in three months, calling it a 'merry bond'."}, {"h": "The caskets and Jessica", "b": "Portia's dead father has ruled that suitors must choose between gold, silver and lead caskets. The Prince of Morocco picks gold, Arragon picks silver, and Bassanio wins by choosing lead. Meanwhile, Shylock's daughter Jessica runs away with the Christian Lorenzo, taking her father's money and jewels."}, {"h": "The trial and rings", "b": "Antonio's ships are reported lost, and Shylock demands his pound of flesh. Portia, disguised as a young lawyer, asks Shylock to show mercy, then rules that he may take flesh but no blood. Shylock loses his wealth and is forced to become a Christian, and the play ends in Belmont with a comic quarrel over rings."}], "qs": [["Who wrote The Merchant of Venice?", ["William Shakespeare", "Christopher Marlowe", "Charles Dickens", "Ben Jonson"], "Shakespeare wrote the play around 1596–1597."], ["Who is the 'merchant' in the title?", ["Antonio", "Shylock", "Bassanio", "Lorenzo"], "Antonio is the merchant of Venice whose ships are at sea."], ["Why does Bassanio need money?", ["To travel to Belmont and woo Portia", "To pay for a new ship", "To pay off Shylock's debts", "To buy a house in Venice"], "Bassanio wants to look like a worthy suitor for the rich Portia."], ["How much money does Shylock lend?", ["3,000 ducats", "300 ducats", "10,000 ducats", "1,000 ducats"], "The bond is for 3,000 ducats for three months."], ["What is the penalty in Shylock's bond?", ["A pound of Antonio's flesh", "Antonio's house in Venice", "All of Antonio's ships", "Ten years in prison"], "If the loan is not repaid in time, Shylock may cut a pound of flesh."], ["Which casket does Bassanio choose to win Portia?", ["Lead", "Gold", "Silver", "Bronze"], "Bassanio rejects showy outward appearance and picks the plain lead casket."], ["Who is Jessica?", ["Shylock's daughter, who elopes with Lorenzo", "Portia's maid", "Antonio's sister", "A judge in Venice"], "Jessica leaves her father and runs off with the Christian Lorenzo."], ["How does Portia disguise herself at the trial?", ["As a young doctor of law", "As a merchant from Tripoli", "As Shylock's servant", "As the Duke of Venice"], "Portia disguises herself as a male lawyer called Balthazar."], ["How does Portia save Antonio?", ["Shylock may take flesh but not one drop of blood", "She pays Shylock ten times the money", "She proves the bond was never signed", "She persuades the Duke to pardon Antonio"], "Cutting flesh without blood is impossible, so Shylock cannot claim the bond."], ["What happens to Shylock at the end of the trial?", ["He loses his wealth and must become a Christian", "He is given Antonio's ships", "He is made Duke of Venice", "He marries Portia"], "Shylock is punished harshly, which modern audiences often find troubling."]], "bonus": ["What is a 'scene' in a play?", ["A section of an act, usually in one place and time", "The whole play from start to finish", "A list of characters", "A song sung by the cast"], "Plays are divided into acts, and acts into scenes."]}, {"ht": "Spr2", "t": "Merchant of Venice: themes and methods", "intro": "The Merchant of Venice explores prejudice, justice, mercy and greed. It was written when Jewish people had been expelled from England, so many audiences then held prejudiced views. Today the play is often read as raising hard questions about how Shylock is treated, and AQA rewards you for exploring different interpretations.", "how": ["Know the context: Jews were expelled from England in 1290 and only readmitted in 1656.", "Explain how Christians and Jews treat each other, rather than seeing either side as simply good or bad.", "Compare justice and mercy, especially in the trial scene in Act 4.", "Discuss Shakespeare's methods: verse and prose, imagery, dramatic irony and structure.", "Offer alternative interpretations, such as 'Shylock can be seen as a villain, or as a victim.'"], "example": {"q": "Is Shylock presented as a villain or a victim?", "steps": ["Villain: he demands a pound of flesh and refuses money, showing a wish for revenge.", "Victim: Antonio has spat on him, and the Christians mock him for his religion.", "Key speech: 'If you prick us, do we not bleed?' reminds the audience that Jews are fully human.", "Context: an Elizabethan audience may have seen him as a villain, while many modern audiences feel sympathy.", "Judgement: Shakespeare makes Shylock both, showing how prejudice can create the hatred it fears."], "a": "Shylock can be read as both villain and victim: his revenge is cruel, but Shakespeare shows that it grows from the prejudice he has suffered."}, "walk": [{"h": "Prejudice and context", "b": "In Shakespeare's time, Christians were taught that charging interest (usury) was sinful, so moneylending was linked to Jewish people, who were often banned from other trades. Shylock is called names and insulted throughout. His speech beginning 'Hath not a Jew eyes?' argues for shared humanity, but he goes on to use it to justify revenge."}, {"h": "Justice, mercy and greed", "b": "Portia's speech 'The quality of mercy is not strained' says mercy 'droppeth as the gentle rain from heaven'. Shylock insists on strict justice, the law exactly as written, but the law is then used strictly against him. Greed appears too: Shylock is reported to cry 'My daughter! O my ducats!', mixing love and money."}, {"h": "Shakespeare's methods", "b": "Noble characters usually speak in verse, while comic characters such as the servant Lancelot often use prose. The caskets carry the message that outward show can be misleading. Dramatic irony makes the trial gripping: the audience knows the 'lawyer' is Portia, but the characters on stage do not."}], "qs": [["In which year were Jewish people expelled from England?", ["1290", "1590", "1066", "1656"], "Edward I expelled Jews in 1290; they were readmitted in 1656."], ["What is 'usury'?", ["Lending money and charging interest", "Stealing from a merchant", "Trading goods by ship", "Breaking a legal contract"], "Usury was seen as sinful by many Christians at the time."], ["Which line asks the audience to see Jews as fully human?", ["'If you prick us, do we not bleed?'", "'All that glisters is not gold'", "'In sooth, I know not why I am so sad'", "'O my ducats!'"], "Shylock's speech shows Jews feel pain like everyone else."], ["Which character makes the famous speech about mercy?", ["Portia", "Shylock", "Antonio", "The Duke"], "Portia says 'The quality of mercy is not strained' at the trial."], ["Portia says mercy 'droppeth as the gentle rain from heaven'. Which method is this?", ["Simile", "Metaphor", "Personification", "Alliteration"], "It compares mercy to rain using 'as', making it seem gentle and God-given."], ["Shylock's cry 'My daughter! O my ducats!' suggests…", ["He mixes grief for Jessica with grief for money", "He is happy that Jessica has left", "He has never cared about money", "He is planning a party"], "Placing daughter and ducats side by side links love and greed."], ["Why is the trial scene full of dramatic irony?", ["The audience knows the lawyer is Portia in disguise", "Shylock knows he will lose all along", "Antonio has secretly paid the debt", "The Duke is Shylock's brother"], "Dramatic irony is when the audience knows more than the characters."], ["What does the lead casket's victory suggest?", ["Outward appearance can be misleading", "Gold is always the best choice", "Bassanio cheated in the test", "Wealth matters more than love"], "The lead casket shows that true worth is not always on the surface, linking to 'All that glisters is not gold'."], ["Why do many modern audiences find the play's ending uncomfortable?", ["Shylock is forced to convert and loses everything", "Portia marries the wrong man", "Antonio dies at the trial", "The play has no happy scenes"], "Modern audiences often see Shylock's punishment as cruel and prejudiced."], ["Which statement best shows an alternative interpretation?", ["Shylock can be seen as a villain, but also as a victim of prejudice", "Shylock is the villain and that is all", "The play is only a comedy", "Antonio does nothing wrong in the play"], "Offering more than one reading shows deeper thinking, which AQA rewards."]], "bonus": ["What is a 'monologue'?", ["A long speech by one character", "A conversation between two characters", "A stage direction", "A song for the whole cast"], "Shylock's 'Hath not a Jew eyes?' and Portia's mercy speech are famous speeches by one character."]}, {"ht": "Sum1", "t": "Writing a literature essay", "intro": "A literature essay is an argument about a text, backed up with evidence. AQA marks you on four Assessment Objectives: your ideas and evidence (AO1), the writer's methods (AO2), context (AO3) and, on some questions, spelling and grammar (AO4). Learning to write a clear essay helps you in every English exam.", "how": ["Start with a thesis: a one-sentence answer to the question that the whole essay argues.", "Embed short quotations in your own sentences instead of copying long chunks.", "Analyse methods: name the technique, zoom in on key words and explain their effect.", "Link context to your point, explaining how it helps us understand the writer's choices.", "Begin each paragraph with a topic sentence that links back to your thesis."], "example": {"q": "Write a paragraph on how Shakespeare presents Portia as clever.", "steps": ["Topic sentence: 'Shakespeare presents Portia as cleverer than the men of Venice.'", "Embed evidence: when she rules that Shylock can take flesh but no 'jot of blood', she finds a gap in the law that no one else saw.", "Analyse the method: the dramatic irony of her disguise lets the audience enjoy her outwitting the court.", "Add context: Elizabethan women could not be lawyers, so her success challenges the audience's expectations.", "Link back: this shows that intelligence matters more than gender or status."], "a": "A strong paragraph uses a topic sentence, embedded evidence, analysis of methods and context, then links back to the thesis."}, "walk": [{"h": "Build a thesis", "b": "Your thesis is your overall argument. For 'How does Achebe present Okonkwo?', a strong thesis is: 'Achebe presents Okonkwo as a tragic hero whose fear of weakness destroys him.' Every paragraph should then prove one part of this."}, {"h": "Embed your evidence", "b": "Weave quotations into your sentences: 'Antonio admits he has much ado to know himself.' For Things Fall Apart, which is still in copyright, you can refer closely to moments in your own words, such as 'when Okonkwo hides his feelings after Ikemefuna's death'. Short, precise evidence is better than long quotations."}, {"h": "Analyse methods and context", "b": "Methods are the writer's choices, such as imagery, structure or a character's speech. Ask why the writer made them: Achebe uses Igbo proverbs to show his characters are wise and skilled with words. Context should explain the text, so link the colonial setting to the novel's ending rather than just listing facts."}], "qs": [["What is a 'thesis' in a literature essay?", ["Your overall argument answering the question", "A long quotation from the text", "A summary of the whole plot", "A list of the characters"], "A thesis is the main argument that the essay sets out to prove."], ["Which Assessment Objective is about context?", ["AO3", "AO1", "AO2", "AO4"], "AO3 rewards understanding of the links between texts and their contexts."], ["Which Assessment Objective is about the writer's methods?", ["AO2", "AO1", "AO3", "AO4"], "AO2 is analysing language, form and structure."], ["What is an 'embedded' quotation?", ["A short quotation woven into your own sentence", "A quotation on a separate line", "A quotation from a different book", "A quotation you have made up"], "Embedding makes your writing flow and shows close reading."], ["Which is the best embedded quotation?", ["Shylock calls the deal a 'merry bond', hiding his true aim.", "Shylock says 'merry bond'. This is a quote.", "'Merry bond.' That is what he says.", "In the play there is a quote which is 'merry bond'."], "The quotation fits smoothly into a sentence that also makes a point."], ["Why should you describe Things Fall Apart in your own words, rather than quote at length?", ["The novel is still in copyright", "The novel has no dialogue", "Achebe wrote in a code", "Examiners ban all quotations"], "In this course we refer to the copyrighted novel by describing its events closely."], ["What is the job of a topic sentence?", ["To state the main point of the paragraph", "To end the essay", "To give the author's date of birth", "To list every quotation you will use"], "A topic sentence tells the reader what the paragraph will argue."], ["Which sentence uses context best?", ["Because women could not be lawyers, Portia's success would surprise audiences.", "Shakespeare was born in 1564 in Stratford.", "The Elizabethans liked plays.", "Venice is in Italy, which is a country."], "Good context explains the text; random facts do not earn marks."], ["Which is the strongest thesis for 'How does Achebe present change?'", ["Achebe shows change as painful, splitting families and the village", "There is change in the novel", "Things Fall Apart is set in Nigeria", "Change is a word with six letters"], "It gives a clear argument that can be proved across the essay."], ["What does 'zooming in' on a quotation mean?", ["Analysing a single key word and its connotations", "Making the quotation bigger on the page", "Using a longer quotation", "Reading only the first line of the text"], "Focusing on one word lets you explore its precise effect."]], "bonus": ["What is the purpose of a paragraph?", ["To group sentences about one main idea", "To make writing look longer", "To show a change of font", "To list spelling words"], "Each paragraph develops one idea, which keeps essays clear."]}, {"ht": "Sum2", "t": "Exam practice: extracts and whole texts", "intro": "In the exam you will meet two types of question: an extract question, where you start from a printed passage, and a whole-text question, where you write about the text as a whole. In AQA Literature Paper 1, the Shakespeare question always gives an extract and then asks about the play as a whole. Practising both types helps you use your time well and plan quickly.", "how": ["Underline the key words in the question, such as the character, theme and 'how'.", "Spend about five minutes planning three or four points before you write.", "For extract questions, analyse the extract closely, then link it to other moments in the text.", "For whole-text questions, choose key moments from the beginning, middle and end.", "Leave time to check spelling and punctuation, which earn marks on the Shakespeare question."], "example": {"q": "Starting with Portia's 'quality of mercy' speech, explore how Shakespeare presents mercy in the play.", "steps": ["Key words: 'starting with', 'how' and 'mercy', so you must cover the extract and the whole play.", "Extract: Portia uses the simile of mercy as 'gentle rain from heaven', presenting it as a gift from God.", "Elsewhere: Shylock refuses mercy, but the Christians then show him little mercy when they force him to convert.", "Context: Christian audiences valued mercy as a religious virtue, so the play tests whether its Christians live up to it.", "Thesis: Shakespeare presents mercy as an ideal that characters praise but struggle to practise."], "a": "A strong answer analyses the extract closely, moves to other moments in the play, includes context and argues a clear thesis."}, "walk": [{"h": "Extract questions", "b": "Read the extract twice and work out where it fits in the story. Pick three or four short quotations and analyse the methods in them. Then show you know the whole text: 'This links to the end of the play, when...'. In Paper 1, the Shakespeare question is worth 30 marks plus 4 for spelling, punctuation and grammar."}, {"h": "Whole-text questions", "b": "For a question like 'How does Achebe present Nwoye?', choose moments across the novel. For example: his closeness to Ikemefuna, his sadness at the boy's death and his decision to join the missionaries. Showing how a character changes from beginning to end is a strong way to structure your answer."}, {"h": "Timing and planning", "b": "Spend about five minutes planning, then about 40 minutes writing, and keep a few minutes to check. A quick plan could be a thesis plus three points, each with evidence. Under pressure, a clear argument with good evidence scores better than lots of points made briefly."}], "qs": [["What is an 'extract question'?", ["A question starting from a printed passage", "A question with no text at all", "A question about a film version", "A question you write yourself"], "Extract questions give you a passage to analyse, then often ask about the whole text."], ["In AQA Literature Paper 1, which section is the Shakespeare question?", ["Section A", "Section B", "Section C", "It is on Paper 2"], "Paper 1 Section A is Shakespeare; Section B is the 19th-century novel."], ["How many marks are there for spelling, punctuation and grammar on the Shakespeare question?", ["4", "10", "30", "0"], "The question is worth 30 marks plus 4 for AO4 accuracy."], ["Roughly how long should you spend planning an essay answer?", ["About 5 minutes", "No time at all", "About 30 minutes", "Half the exam"], "A short plan gives your answer a clear structure without wasting writing time."], ["A question says 'Starting with this extract...'. What must you do?", ["Analyse the extract, then write about the whole text", "Write only about the extract", "Write only about the rest of the text", "Copy out the extract"], "These questions test close reading and knowledge of the whole text."], ["For 'How does Achebe present Nwoye?', which plan is best?", ["Bond with Ikemefuna, grief at his death, joining the church", "Okonkwo's wrestling, Unoka's debts, the yam harvest", "Only Nwoye's first appearance", "A summary of the whole plot"], "It covers Nwoye across the novel and shows how he changes."], ["In an exam, which opening sentence is strongest?", ["Shakespeare presents Shylock as both cruel and wronged.", "In this essay I am going to write about Shylock.", "Shylock is a character in a play.", "The Merchant of Venice was written by Shakespeare."], "It answers the question straight away with a clear argument."], ["The extract shows Okonkwo beating his wife during the Week of Peace. A good link elsewhere would be…", ["His fear of weakness, as when he kills Ikemefuna", "Portia's choice of caskets", "The arrival of the Prince of Morocco", "Unoka's love of music, which Okonkwo shares"], "Both moments show Okonkwo's violence driven by his fear of looking weak."], ["Why should a whole-text answer use moments from the beginning, middle and end?", ["It shows how characters and themes develop", "It makes the essay shorter", "Examiners only read the ending", "The middle of a text never matters"], "Covering the whole text shows understanding of change and development."], ["Which is the best use of the last few minutes of the exam?", ["Check spelling, punctuation and that your argument is clear", "Start a brand-new essay", "Rewrite your whole plan", "Copy out the question again"], "Checking catches errors, which matter especially for the AO4 marks."]], "bonus": ["Which word in an exam question tells you to focus on the writer's methods?", ["How", "Who", "When", "Where"], "'How' asks you to explain the methods the writer uses, not just what happens."]}]}, {"id": "maths", "name": "Maths", "board": "Pearson Edexcel (1MA1)", "weeks": [{"ht": "Aut1", "t": "Angles, Congruence and Similarity", "intro": "This topic is about the rules angles follow, how to construct shapes accurately, and how to tell when two shapes are identical (congruent) or the same shape but a different size (similar). These ideas appear all over GCSE geometry, from proofs to finding missing lengths.", "how": ["Angles on a straight line add up to 180° and angles around a point add up to 360°.", "Angles in a triangle add up to 180°, and the interior angles of any polygon add up to (n − 2) × 180°.", "With parallel lines, alternate angles are equal, corresponding angles are equal and co-interior angles add up to 180°.", "Two triangles are congruent if they match by SSS, SAS, ASA or RHS (AAA is not enough).", "In similar shapes, find the scale factor by dividing a new length by its matching old length, then multiply."], "example": {"q": "Triangles ABC and DEF are similar. AB = 6 cm, DE = 9 cm and BC = 8 cm. Find EF.", "steps": ["AB matches DE, so the scale factor is 9 ÷ 6 = 1.5.", "BC matches EF, so EF is BC multiplied by the scale factor.", "EF = 8 × 1.5 = 12.", "Check: the bigger triangle should have bigger sides, and 12 > 8."], "a": "EF = 12 cm."}, "walk": [{"h": "Angle facts", "b": "Learn the key totals: 180° on a straight line, 360° around a point and 180° in a triangle. Vertically opposite angles are equal. For example, if two angles on a straight line are x and 130°, then x = 180° − 130° = 50°."}, {"h": "Congruent triangles", "b": "Congruent means exactly the same shape and size. You can prove two triangles are congruent with SSS (three sides), SAS (two sides and the angle between them), ASA (two angles and a side) or RHS (right angle, hypotenuse and one side). Always say which condition you used."}, {"h": "Similarity and enlargement", "b": "Similar shapes have equal angles and sides in the same ratio. An enlargement makes a similar shape: every distance from the centre of enlargement is multiplied by the scale factor. For example, enlarging (2, 1) by scale factor 3 about the origin gives (6, 3)."}], "qs": [["Angles on a straight line add up to what?", ["180°", "360°", "90°", "270°"], "A straight line is half a full turn, and half of 360° is 180°."], ["A triangle has angles of 50° and 70°. What is the third angle?", ["60°", "120°", "70°", "110°"], "Angles in a triangle add to 180°, so 180° − 50° − 70° = 60°."], ["What do the interior angles of a pentagon add up to?", ["540°", "360°", "720°", "900°"], "Use (n − 2) × 180° = (5 − 2) × 180° = 540°."], ["What is each exterior angle of a regular hexagon?", ["60°", "120°", "36°", "720°"], "Exterior angles add to 360°, so each one is 360° ÷ 6 = 60°."], ["A line crosses two parallel lines. What is true about alternate angles?", ["They are equal", "They add up to 180°", "They add up to 90°", "They add up to 360°"], "Alternate angles (the Z shape) between parallel lines are always equal."], ["Two triangles have two pairs of equal sides and the angle between them equal. Which condition proves congruence?", ["SAS", "SSS", "ASA", "RHS"], "Two sides and the included angle is the SAS condition."], ["Which of these does NOT prove two triangles are congruent?", ["AAA", "SSS", "SAS", "RHS"], "Three equal angles only proves the triangles are similar; they could be different sizes."], ["Two shapes are similar. A 4 cm side matches a 6 cm side. A 10 cm side on the small shape matches which length?", ["15 cm", "12 cm", "16 cm", "6.67 cm"], "The scale factor is 6 ÷ 4 = 1.5, and 10 × 1.5 = 15 cm."], ["What does the perpendicular bisector of a line AB show?", ["All points the same distance from A and B", "All points the same distance from two lines", "All points exactly 1 cm from A", "All points on the line AB"], "Every point on the perpendicular bisector of AB is equidistant from A and B."], ["Point (3, 2) is enlarged by scale factor 2 with centre (1, 1). Where does it end up?", ["(5, 3)", "(6, 4)", "(4, 3)", "(7, 5)"], "From the centre the point is 2 right and 1 up; doubled that is 4 right and 2 up, giving (1 + 4, 1 + 2) = (5, 3)."]], "bonus": ["What is an acute angle?", ["An angle less than 90°", "An angle of exactly 90°", "An angle between 90° and 180°", "An angle more than 180°"], "Acute angles are smaller than a right angle, which is 90°."]}, {"ht": "Aut2", "t": "Measures, Volume and Trigonometry", "intro": "This topic covers converting units, using scale drawings and bearings, finding volumes and surface areas of 3D shapes, and working out lengths and angles in right-angled triangles. These skills are used constantly in real life, from reading maps to building things.", "how": ["Learn the key conversions: 1 km = 1000 m, 1 m = 100 cm, 1 cm = 10 mm, and 1 m² = 10 000 cm².", "Bearings are measured clockwise from North and always written with three figures, such as 070°.", "Volume of a prism or cylinder = area of cross-section × length; for a cylinder that is πr²h.", "Pyramid and cone volume = ⅓ × base area × height, and sphere volume = ⁴⁄₃πr³.", "Pythagoras (a² + b² = c²) finds a side; SOH CAH TOA finds a side or an angle in a right-angled triangle."], "example": {"q": "A 5 m ladder leans against a wall. Its foot is 3 m from the wall. How high up the wall does it reach?", "steps": ["The ladder is the hypotenuse, so c = 5 and one shorter side is 3.", "For a shorter side, subtract: h² = 5² − 3².", "h² = 25 − 9 = 16.", "h = √16 = 4."], "a": "The ladder reaches 4 m up the wall."}, "walk": [{"h": "Units, scales, bearings", "b": "To change a map length to real life, multiply by the scale. On a 1 : 50 000 map, 4 cm is 200 000 cm, which is 2 km. A bearing is the clockwise angle from North, so due East is 090°."}, {"h": "Volume and surface area", "b": "A prism has the same cross-section all the way through, so volume = cross-section area × length. A cylinder of radius 3 cm and height 10 cm has volume π × 3² × 10 = 90π cm³. Cones and pyramids are ⅓ of the matching prism, and a sphere is ⁴⁄₃πr³ with surface area 4πr². Surface area means adding the areas of all the faces."}, {"h": "Pythagoras and trigonometry", "b": "Pythagoras links the three sides: a² + b² = c², where c is the hypotenuse. Trigonometry links sides and angles: sin = O/H, cos = A/H, tan = O/A. For example, with a 30° angle and hypotenuse 10 cm, the opposite side is 10 × sin 30° = 5 cm."}], "qs": [["How many metres are in 3.5 km?", ["3500 m", "350 m", "35 000 m", "0.0035 m"], "There are 1000 m in 1 km, so 3.5 × 1000 = 3500 m."], ["A map has a scale of 1 : 50 000. What real distance is 4 cm on the map?", ["2 km", "20 km", "200 m", "0.2 km"], "4 × 50 000 = 200 000 cm = 2000 m = 2 km."], ["The bearing of B from A is 070°. What is the bearing of A from B?", ["250°", "110°", "290°", "070°"], "The back bearing is 180° more: 70° + 180° = 250°."], ["A prism has a cross-section area of 12 cm² and a length of 5 cm. What is its volume?", ["60 cm³", "17 cm³", "120 cm³", "30 cm³"], "Volume of a prism = cross-section area × length = 12 × 5 = 60 cm³."], ["A cylinder has radius 3 cm and height 10 cm. What is its volume?", ["90π cm³", "60π cm³", "360π cm³", "30π cm³"], "V = πr²h = π × 9 × 10 = 90π cm³."], ["A square-based pyramid has a 6 cm by 6 cm base and height 5 cm. What is its volume?", ["60 cm³", "180 cm³", "90 cm³", "30 cm³"], "V = ⅓ × base area × height = ⅓ × 36 × 5 = 60 cm³."], ["A right-angled triangle has shorter sides of 6 cm and 8 cm. How long is the hypotenuse?", ["10 cm", "14 cm", "100 cm", "7 cm"], "c² = 6² + 8² = 36 + 64 = 100, so c = √100 = 10 cm."], ["A right-angled triangle has a 30° angle and a hypotenuse of 10 cm. How long is the side opposite 30°?", ["5 cm", "8.66 cm", "5.77 cm", "20 cm"], "Opposite = hypotenuse × sin 30° = 10 × 0.5 = 5 cm."], ["What is the volume of a sphere with radius 6 cm?", ["288π cm³", "864π cm³", "144π cm³", "48π cm³"], "V = ⁴⁄₃πr³ = ⁴⁄₃ × π × 216 = 288π cm³."], ["In a right-angled triangle the opposite side is 7 cm and the hypotenuse is 14 cm. Find the angle.", ["30°", "60°", "26.6°", "45°"], "sin x = 7 ÷ 14 = 0.5, so x = sin⁻¹(0.5) = 30°."]], "bonus": ["What is the area of a rectangle 7 cm long and 4 cm wide?", ["28 cm²", "22 cm²", "11 cm²", "56 cm²"], "Area of a rectangle = length × width = 7 × 4 = 28 cm²."]}, {"ht": "Spr1", "t": "Expanding, Factorising and Formulae", "intro": "This topic is about multiplying out brackets, putting expressions back into brackets, and rearranging formulae. These are the core tools of algebra that you will use to solve equations throughout GCSE Maths.", "how": ["To expand two brackets, multiply every term in the first bracket by every term in the second, then collect like terms.", "To factorise x² + bx + c, find two numbers that multiply to c and add to b.", "To factorise ax² + bx + c, find two numbers that multiply to a × c and add to b, split the middle term, then factorise in pairs.", "Spot the difference of two squares: x² − a² = (x + a)(x − a).", "To rearrange a formula, do the same inverse operation to both sides until the new subject is on its own."], "example": {"q": "Factorise 3x² + 10x + 8.", "steps": ["Multiply a × c: 3 × 8 = 24.", "Find two numbers that multiply to 24 and add to 10: they are 4 and 6.", "Split the middle term: 3x² + 4x + 6x + 8.", "Factorise in pairs: x(3x + 4) + 2(3x + 4) = (3x + 4)(x + 2).", "Check by expanding: 3x² + 6x + 4x + 8 = 3x² + 10x + 8."], "a": "3x² + 10x + 8 = (3x + 4)(x + 2)."}, "walk": [{"h": "Expanding brackets", "b": "Each term in one bracket multiplies each term in the other. For (x + 3)(x + 5) you get x² + 5x + 3x + 15 = x² + 8x + 15. For three brackets, expand two first, then multiply the answer by the third bracket."}, {"h": "Factorising quadratics", "b": "Factorising is expanding in reverse. For x² + 7x + 12, look for two numbers that multiply to 12 and add to 7: 3 and 4, so it is (x + 3)(x + 4). When there is a number in front of x², use the a × c method to split the middle term."}, {"h": "Rearranging formulae", "b": "Treat a formula like an equation and undo the operations in reverse order. For y = 3x − 5, add 5 to get y + 5 = 3x, then divide by 3 to get x = (y + 5)/3. Whatever you do to one side, do to the other."}], "qs": [["Expand 3(x + 4).", ["3x + 12", "3x + 4", "x + 12", "3x + 7"], "The 3 multiplies both terms: 3 × x = 3x and 3 × 4 = 12."], ["Expand (x + 3)(x + 5).", ["x² + 8x + 15", "x² + 15x + 8", "x² + 8x + 8", "x² + 15"], "x² + 5x + 3x + 15 = x² + 8x + 15."], ["Expand (x − 4)(x + 2).", ["x² − 2x − 8", "x² + 2x − 8", "x² − 2x + 8", "x² − 6x − 8"], "x² + 2x − 4x − 8 = x² − 2x − 8."], ["Expand (x + 5)².", ["x² + 10x + 25", "x² + 25", "x² + 5x + 25", "x² + 10x + 10"], "(x + 5)(x + 5) = x² + 5x + 5x + 25 = x² + 10x + 25."], ["Factorise x² + 7x + 12.", ["(x + 3)(x + 4)", "(x + 2)(x + 6)", "(x + 1)(x + 12)", "(x + 7)(x + 12)"], "3 × 4 = 12 and 3 + 4 = 7."], ["Factorise x² − 9.", ["(x + 3)(x − 3)", "(x − 3)²", "(x + 3)²", "(x − 9)(x + 1)"], "This is the difference of two squares: x² − 3² = (x + 3)(x − 3)."], ["Factorise 2x² + 7x + 3.", ["(2x + 1)(x + 3)", "(2x + 3)(x + 1)", "(2x − 1)(x − 3)", "(2x + 6)(x + 1)"], "Expanding (2x + 1)(x + 3) gives 2x² + 6x + x + 3 = 2x² + 7x + 3."], ["Make x the subject of y = 3x − 5.", ["x = (y + 5)/3", "x = (y − 5)/3", "x = y/3 + 5", "x = 3y + 5"], "Add 5 to both sides to get y + 5 = 3x, then divide both sides by 3."], ["Expand (x + 1)(x + 2)(x + 3).", ["x³ + 6x² + 11x + 6", "x³ + 5x² + 11x + 6", "x³ + 6x² + 9x + 6", "x³ + 11x² + 6x + 6"], "(x + 1)(x + 2) = x² + 3x + 2, and (x² + 3x + 2)(x + 3) = x³ + 6x² + 11x + 6."], ["Make r the subject of A = πr².", ["r = √(A/π)", "r = A/(2π)", "r = √A/π", "r = (A/π)²"], "Divide both sides by π to get r² = A/π, then square root both sides."]], "bonus": ["What is −3 × −4?", ["12", "−12", "−7", "7"], "A negative times a negative gives a positive, and 3 × 4 = 12."]}, {"ht": "Spr2", "t": "Simultaneous Equations and Inequalities", "intro": "This topic covers solving two equations at the same time, solving and showing inequalities, and breaking numbers into prime factors to find the HCF and LCM. These skills help you solve real problems with more than one unknown and work confidently with numbers.", "how": ["To solve simultaneous equations by elimination, make the coefficient of one letter match, then add or subtract the equations.", "Substitute your first answer back into an original equation to find the second letter, then check in the other equation.", "The graphical solution of simultaneous equations is the point where the two lines cross.", "Solve inequalities like equations, but if you multiply or divide by a negative number, flip the inequality sign.", "Write a number as a product of primes using a factor tree; the HCF uses shared primes and the LCM uses every prime at its highest power."], "example": {"q": "Solve the simultaneous equations 2x + y = 7 and 3x − y = 8.", "steps": ["The y terms are +y and −y, so add the equations to eliminate y.", "2x + 3x = 7 + 8, so 5x = 15 and x = 3.", "Substitute into 2x + y = 7: 6 + y = 7, so y = 1.", "Check in 3x − y = 8: 9 − 1 = 8, which is correct."], "a": "x = 3 and y = 1."}, "walk": [{"h": "Prime factors, HCF, LCM", "b": "Use a factor tree to split a number into primes, for example 60 = 2² × 3 × 5. The HCF is the biggest number that divides both numbers, and the LCM is the smallest number both divide into. For 12 and 18, the HCF is 6 and the LCM is 36."}, {"h": "Linear inequalities", "b": "Solve 2x + 3 < 11 just like an equation: subtract 3 to get 2x < 8, then divide by 2 to get x < 4. On a number line, use an open circle for < or > and a filled circle for ≤ or ≥. Remember to flip the sign if you divide by a negative."}, {"h": "Simultaneous equations", "b": "Two equations with two unknowns share one solution. Eliminate one letter by adding or subtracting, multiplying an equation first if needed. On a graph, the solution is where the two lines cross; for example y = 2x + 1 and y = x + 3 meet at (2, 5)."}], "qs": [["What is 60 written as a product of prime factors?", ["2² × 3 × 5", "2 × 3 × 10", "2 × 30", "2² × 15"], "2, 3 and 5 are all prime, and 4 × 3 × 5 = 60; the others contain non-primes."], ["What is the HCF of 12 and 18?", ["6", "36", "3", "2"], "6 is the largest number that divides into both 12 and 18."], ["What is the LCM of 4 and 6?", ["12", "24", "2", "10"], "12 is the smallest number in both the 4 and 6 times tables."], ["Solve 2x + 3 < 11.", ["x < 4", "x > 4", "x < 7", "x ≤ 4"], "Subtract 3 to get 2x < 8, then divide by 2 to get x < 4."], ["List the integers n where −2 < n ≤ 3.", ["−1, 0, 1, 2, 3", "−2, −1, 0, 1, 2, 3", "−2, −1, 0, 1, 2", "−1, 0, 1, 2"], "−2 is not included (strict <) but 3 is included (≤)."], ["Solve −3x > 12.", ["x < −4", "x > −4", "x < 4", "x > 4"], "Dividing by −3 gives −4, and dividing by a negative flips > to <."], ["Solve x + y = 10 and x − y = 4.", ["x = 7, y = 3", "x = 3, y = 7", "x = 6, y = 4", "x = 14, y = −4"], "Adding gives 2x = 14, so x = 7, then y = 10 − 7 = 3."], ["Solve 2x + 3y = 13 and x + y = 5.", ["x = 2, y = 3", "x = 3, y = 2", "x = 5, y = 1", "x = −1, y = 5"], "Double the second equation to get 2x + 2y = 10, subtract to get y = 3, then x = 2."], ["Where do the lines y = 2x + 1 and y = x + 3 cross?", ["(2, 5)", "(5, 2)", "(1, 3)", "(2, 3)"], "Set 2x + 1 = x + 3 to get x = 2, then y = 2 + 3 = 5."], ["72 = 2³ × 3² and 120 = 2³ × 3 × 5. What is the LCM of 72 and 120?", ["360", "24", "720", "8640"], "Take each prime at its highest power: 2³ × 3² × 5 = 8 × 9 × 5 = 360."]], "bonus": ["Which of these is a prime number?", ["13", "9", "15", "1"], "13 has exactly two factors, 1 and 13; 1 is not prime because it has only one factor."]}, {"ht": "Sum1", "t": "Indices, Standard Form and Percentages", "intro": "This topic covers powers that are fractions or negative, writing very large and very small numbers in standard form, error intervals, and using multipliers for reverse percentages, compound interest and decay. These skills are used in science, finance and everyday money problems.", "how": ["A power of ½ means square root, a power of ⅓ means cube root, and a negative power means 1 over the number.", "Standard form is A × 10ⁿ where 1 ≤ A < 10 and n is a whole number.", "If a number is truncated to 1 decimal place as 4.7, its error interval is 4.7 ≤ x < 4.8.", "For a reverse percentage, divide the final amount by the multiplier (for example, ÷ 0.8 after a 20% decrease).", "Compound change: final amount = original × multiplierⁿ, where n is the number of years."], "example": {"q": "After a 12% price increase, a phone costs £336. What was the original price?", "steps": ["A 12% increase means the new price is 112% of the original.", "The multiplier is 1.12, so original × 1.12 = £336.", "Divide: £336 ÷ 1.12 = £300.", "Check: £300 × 1.12 = £336."], "a": "The original price was £300."}, "walk": [{"h": "Fractional and negative indices", "b": "The bottom of a fractional power is a root and the top is a power. So 8 to the power ⅔ means the cube root of 8 (which is 2), then squared, giving 4. A negative power means one over: 16 to the power −½ is 1/√16 = ¼."}, {"h": "Standard form", "b": "Move the decimal point until the first number is between 1 and 10, then count the moves. 3 400 000 = 3.4 × 10⁶ and 0.0042 = 4.2 × 10⁻³. To multiply, multiply the front numbers and add the powers: (2 × 10³) × (4 × 10⁵) = 8 × 10⁸."}, {"h": "Percentage multipliers", "b": "A 15% decrease is a multiplier of 0.85 and a 3% increase is 1.03. For compound interest, multiply by the multiplier once for each year: £2000 at 3% for 2 years is 2000 × 1.03² = £2121.80. For a reverse percentage, divide by the multiplier instead."}], "qs": [["Write 3 400 000 in standard form.", ["3.4 × 10⁶", "34 × 10⁵", "3.4 × 10⁵", "0.34 × 10⁷"], "The first number must be between 1 and 10, and the decimal point moves 6 places."], ["Write 4.2 × 10⁻³ as an ordinary number.", ["0.0042", "0.00042", "4200", "0.042"], "A power of −3 means move the decimal point 3 places to the left."], ["Work out (2 × 10³) × (4 × 10⁵).", ["8 × 10⁸", "8 × 10¹⁵", "6 × 10⁸", "8 × 10²"], "Multiply 2 × 4 = 8 and add the powers 3 + 5 = 8."], ["What is 25 to the power ½?", ["5", "12.5", "625", "50"], "A power of ½ means square root, and √25 = 5."], ["What is 8 to the power ⅔?", ["4", "2", "64", "5.33"], "The cube root of 8 is 2, and 2² = 4."], ["What is 16 to the power −½?", ["¼", "−4", "4", "−8"], "The ½ means √16 = 4, and the negative power means one over it: ¼."], ["A number x is truncated to 1 decimal place as 4.7. What is its error interval?", ["4.7 ≤ x < 4.8", "4.65 ≤ x < 4.75", "4.6 < x ≤ 4.7", "4.7 < x ≤ 4.8"], "Truncating chops off digits, so any number from 4.7 up to (not including) 4.8 gives 4.7."], ["After a 20% discount, a coat costs £48. What was the original price?", ["£60", "£57.60", "£38.40", "£68"], "The sale price is 80% of the original, so £48 ÷ 0.8 = £60."], ["£2000 is invested at 3% compound interest per year. What is it worth after 2 years?", ["£2121.80", "£2120.00", "£2060.00", "£2185.45"], "2000 × 1.03² = 2000 × 1.0609 = £2121.80."], ["A £12 000 car loses 15% of its value each year. What is it worth after 3 years?", ["£7369.50", "£6600.00", "£8670.00", "£18 250.50"], "12 000 × 0.85³ = 12 000 × 0.614125 = £7369.50."]], "bonus": ["What is 2³?", ["8", "6", "5", "9"], "2³ means 2 × 2 × 2, which is 8."]}, {"ht": "Sum2", "t": "Sequences and Iteration", "intro": "This topic is about recognising special number sequences, finding rules for them, and using recurrence relations and iteration to generate terms. Sequences help you spot patterns and are the basis of many problem-solving questions.", "how": ["Know the special sequences: square (1, 4, 9, 16…), cube (1, 8, 27, 64…) and triangular (1, 3, 6, 10…).", "In a Fibonacci-type sequence, each term is the sum of the two terms before it.", "In a geometric sequence, you multiply by the same number (the common ratio) each time; the nth term is a × rⁿ⁻¹.", "A recurrence relation such as uₙ₊₁ = 2uₙ + 1 tells you how to get the next term from the one before.", "To iterate, put each answer back into the formula, and keep going until the answers settle down."], "example": {"q": "A sequence has u₁ = 2 and uₙ₊₁ = 3uₙ − 2. Find u₄.", "steps": ["u₂ = 3 × 2 − 2 = 4.", "u₃ = 3 × 4 − 2 = 10.", "u₄ = 3 × 10 − 2 = 28."], "a": "u₄ = 28."}, "walk": [{"h": "Special sequences", "b": "Square numbers are 1², 2², 3²… = 1, 4, 9, 16. Cube numbers are 1, 8, 27, 64. Triangular numbers go up by 2, then 3, then 4 and so on: 1, 3, 6, 10, 15."}, {"h": "Fibonacci-type and geometric", "b": "A Fibonacci-type sequence adds the previous two terms: 2, 3, 5, 8, 13, 21. A geometric sequence multiplies by a common ratio: 3, 6, 12, 24 has ratio 2. Its nth term is first term × ratioⁿ⁻¹, so 5, 10, 20, 40 has nth term 5 × 2ⁿ⁻¹."}, {"h": "Recurrence and iteration", "b": "A recurrence relation builds each term from the previous one. Iteration uses the same idea to home in on a solution: with xₙ₊₁ = √(xₙ + 6) and x₁ = 1, the answers 1, 2.646, 2.940, 2.990… get closer and closer to 3, which solves x² = x + 6."}], "qs": [["What is the next square number after 49?", ["64", "56", "50", "81"], "49 = 7², so the next square number is 8² = 64."], ["What is the 5th triangular number?", ["15", "10", "25", "21"], "The triangular numbers are 1, 3, 6, 10, 15."], ["What comes next in 1, 8, 27, 64, …?", ["125", "100", "81", "216"], "These are cube numbers, and 5³ = 125."], ["What comes next in the Fibonacci-type sequence 2, 3, 5, 8, 13, …?", ["21", "18", "26", "20"], "Add the two previous terms: 8 + 13 = 21."], ["What is the nth term of 5, 8, 11, 14, …?", ["3n + 2", "n + 3", "3n + 5", "5n + 3"], "It goes up by 3, so 3n, and 3 × 1 + 2 = 5 for the first term."], ["What is the next term of the geometric sequence 81, 27, 9, 3, …?", ["1", "0", "⅓", "−3"], "The common ratio is ⅓ (divide by 3 each time), and 3 ÷ 3 = 1."], ["u₁ = 3 and uₙ₊₁ = 2uₙ + 1. What is u₃?", ["15", "7", "31", "9"], "u₂ = 2 × 3 + 1 = 7, then u₃ = 2 × 7 + 1 = 15."], ["A Fibonacci-type sequence starts 4, x, … and its 4th term is 18. What is x?", ["7", "14", "9", "11"], "The terms are 4, x, 4 + x, 4 + 2x, so 4 + 2x = 18 and x = 7."], ["What is the nth term of the geometric sequence 5, 10, 20, 40, …?", ["5 × 2ⁿ⁻¹", "5 × 2ⁿ", "2 × 5ⁿ⁻¹", "5n"], "First term 5, ratio 2, so the nth term is 5 × 2ⁿ⁻¹ (n = 1 gives 5)."], ["Using xₙ₊₁ = √(xₙ + 6) with x₁ = 1, find x₃ to 3 decimal places.", ["2.940", "2.646", "2.990", "3.000"], "x₂ = √7 = 2.6458…, then x₃ = √8.6458… = 2.940 to 3 d.p."]], "bonus": ["What is the next term in 4, 9, 14, 19, …?", ["24", "23", "25", "29"], "The sequence goes up by 5 each time, and 19 + 5 = 24."]}]}, {"id": "biology", "name": "Biology", "board": "OCR Twenty First Century Science", "weeks": [{"ht": "Aut1", "t": "B1 You and your genes", "intro": "Your genome is the full set of genetic instructions inside your cells, written in a chemical called DNA. Genes are short sections of DNA that help decide features like eye colour or blood group. This topic explains how features are passed on from parents to children, and how scientists can now change genes on purpose.", "how": ["DNA is a polymer made of two strands twisted into a double helix, and it is found in chromosomes inside the nucleus.", "A gene is a section of DNA that codes for a protein, and different versions of the same gene are called alleles.", "You get one allele of each gene from each parent, so you have two alleles for most genes.", "A dominant allele (capital letter, e.g. B) shows its effect even if only one copy is present; a recessive allele (small letter, e.g. b) only shows if there are two copies.", "A Punnett square shows all the possible allele combinations a child could inherit from two parents."], "example": {"q": "In pea plants, the allele for tall (T) is dominant over the allele for short (t). Two Tt plants are crossed. What fraction of the offspring will be short?", "steps": ["Write the gametes from each parent: T or t, and T or t.", "Draw a 2 × 2 Punnett square and fill it in: TT, Tt, Tt, tt.", "Only tt has no dominant allele, so only tt plants are short.", "1 out of 4 boxes is tt, so the probability is 1 in 4."], "a": "One quarter (25%) of the offspring are expected to be short, giving a 3 tall : 1 short ratio."}, "walk": [{"h": "Genome, DNA and genes", "b": "Your genome is all of the DNA in one of your cells. DNA is coiled up into 23 pairs of chromosomes, and each chromosome carries many genes. For example, one gene helps decide whether your earlobes are attached or free."}, {"h": "Alleles, genotype, phenotype", "b": "Alleles are different versions of a gene. Your genotype is the pair of alleles you have, such as Bb, and your phenotype is the feature you can see, such as brown eyes. If both alleles are the same (BB or bb) you are homozygous; if they are different (Bb) you are heterozygous."}, {"h": "Crosses and engineering", "b": "A Punnett square predicts the chance of each genotype in the offspring, such as a 3 : 1 ratio from two heterozygous parents. Genetic engineering means changing an organism's genome, for example by cutting out the human insulin gene and putting it into bacteria. The bacteria then make human insulin for people with diabetes."}], "qs": [["What is the name of the chemical that genes are made of?", ["DNA", "Protein", "Glucose", "Starch"], "Genes are short sections of DNA, the molecule that carries genetic information."], ["What is a gene?", ["A section of DNA that codes for a protein", "A whole chromosome", "A type of cell", "A strand of protein in the nucleus"], "Each gene is a short length of DNA that holds the code for making a particular protein."], ["What is the genome of an organism?", ["All of its genetic material", "Only the genes it shows", "One single chromosome", "Its cell membrane"], "The genome is the entire set of genetic material (DNA) of an organism."], ["What are alleles?", ["Different versions of the same gene", "Two copies of a chromosome pair", "Cells that carry genes", "Proteins made by genes"], "Alleles are alternative forms of one gene, such as alleles for brown or blue eyes."], ["A person has the alleles Ff. What word describes this genotype?", ["Heterozygous", "Homozygous dominant", "Homozygous recessive", "Phenotype"], "Having two different alleles of a gene is called heterozygous."], ["Brown eyes (B) is dominant over blue eyes (b). What colour eyes does a person with Bb have?", ["Brown", "Blue", "Half brown, half blue", "Green"], "One dominant allele is enough for its effect to show, so Bb gives brown eyes."], ["Which word means the features an organism shows, like its height or eye colour?", ["Phenotype", "Genotype", "Genome", "Allele"], "The phenotype is the observable characteristic, produced by the genotype and the environment."], ["Two parents are both Bb. What is the chance their child will be bb?", ["25%", "50%", "75%", "0%"], "The Punnett square gives BB, Bb, Bb and bb, so 1 out of 4 outcomes is bb."], ["A parent BB is crossed with a parent bb. What percentage of children will be Bb?", ["100%", "50%", "25%", "0%"], "Every child gets B from one parent and b from the other, so all are Bb."], ["Which is an example of genetic engineering?", ["Putting the human insulin gene into bacteria", "Choosing the tallest plants to breed", "Giving a child a vaccine", "Growing plants in more light"], "Genetic engineering means changing an organism's genome by adding a gene from another organism."]], "bonus": ["Where in an animal cell is most of the DNA found?", ["In the nucleus", "In the cell membrane", "In the cytoplasm only", "In the cell wall"], "The nucleus contains the chromosomes, which are made of DNA."]}, {"ht": "Aut2", "t": "B4 Using food and controlling growth", "intro": "Plants make their own food by photosynthesis, and all living things release energy from food by respiration. Cells also need to divide so that organisms can grow, repair themselves and reproduce. This topic links these life processes together.", "how": ["Photosynthesis: carbon dioxide + water → glucose + oxygen, using light energy absorbed by chlorophyll in chloroplasts.", "Aerobic respiration: glucose + oxygen → carbon dioxide + water, and it releases a lot of energy in the mitochondria.", "Anaerobic respiration happens without oxygen: in muscles glucose → lactic acid, and in yeast glucose → ethanol + carbon dioxide.", "Mitosis makes two genetically identical body cells for growth and repair; meiosis makes four genetically different gametes with half the chromosomes.", "Stem cells are unspecialised cells that can divide and turn into different types of cell."], "example": {"q": "A sprinter's legs ache at the end of a 400 m race. Explain why, using ideas about respiration.", "steps": ["During the race the muscles need energy very quickly.", "The heart and lungs cannot deliver oxygen fast enough for aerobic respiration alone.", "The muscles also respire anaerobically: glucose → lactic acid.", "Lactic acid builds up and causes muscle fatigue, and it releases much less energy than aerobic respiration."], "a": "The muscles respired anaerobically because they ran short of oxygen, and the build-up of lactic acid made them ache."}, "walk": [{"h": "Photosynthesis makes food", "b": "Plants take in carbon dioxide through their leaves and water through their roots. Chlorophyll in the chloroplasts absorbs light energy to turn these into glucose and oxygen. More light, more carbon dioxide or a warmer temperature (up to a point) can speed it up."}, {"h": "Respiration releases energy", "b": "Every living cell respires all the time to release energy from glucose. Aerobic respiration uses oxygen and takes place in mitochondria. Anaerobic respiration needs no oxygen but releases much less energy; yeast uses it to make bread rise because it gives off carbon dioxide."}, {"h": "Mitosis, meiosis, stem cells", "b": "In mitosis one body cell divides into two identical cells, which is how a cut on your skin heals. In meiosis one cell divides twice to make four gametes, each with 23 chromosomes instead of 46. Stem cells, found in embryos, bone marrow and plant meristems, can become many different types of specialised cell."}], "qs": [["Which gas do plants take in for photosynthesis?", ["Carbon dioxide", "Oxygen", "Nitrogen", "Hydrogen"], "Carbon dioxide and water are the reactants of photosynthesis."], ["In which part of a plant cell does photosynthesis take place?", ["Chloroplast", "Mitochondrion", "Nucleus", "Vacuole"], "Chloroplasts contain chlorophyll, which absorbs the light energy needed."], ["What are the products of aerobic respiration?", ["Carbon dioxide and water", "Glucose and oxygen", "Lactic acid only", "Ethanol and carbon dioxide"], "Glucose + oxygen → carbon dioxide + water, releasing energy."], ["Where in a cell does aerobic respiration mainly take place?", ["Mitochondria", "Chloroplasts", "Cell wall", "Ribosomes"], "Mitochondria are where most of the reactions of aerobic respiration happen."], ["What is made by anaerobic respiration in human muscles?", ["Lactic acid", "Ethanol", "Carbon dioxide and water", "Oxygen"], "In human muscle cells, glucose is broken down to lactic acid when oxygen is short."], ["Why does bread dough rise when yeast is added?", ["Yeast respires anaerobically and gives off carbon dioxide", "Yeast photosynthesises and makes oxygen", "Yeast makes lactic acid gas", "Yeast absorbs water and swells"], "Anaerobic respiration in yeast makes ethanol and carbon dioxide; the gas bubbles make the dough rise."], ["What is the main purpose of mitosis?", ["Growth and repair", "Making gametes", "Making cells with half the chromosomes", "Making genetically different cells"], "Mitosis produces genetically identical cells so the body can grow and replace damaged cells."], ["A human body cell has 46 chromosomes. How many chromosomes are in a human sperm cell?", ["23", "46", "92", "12"], "Meiosis halves the chromosome number, so gametes have 23."], ["How many cells are made when one cell divides by meiosis?", ["Four genetically different cells", "Two identical cells", "Two different cells", "Four identical cells"], "Meiosis involves two divisions, producing four genetically different gametes."], ["Why could stem cells be useful in medicine?", ["They can turn into many types of specialised cell", "They cannot divide", "They are already fully specialised", "They have no nucleus"], "Stem cells are unspecialised and could replace damaged cells, such as nerve or blood cells."]], "bonus": ["Which part of a cell controls its activities and holds the genetic material?", ["Nucleus", "Cell membrane", "Cytoplasm", "Cell wall"], "The nucleus contains the chromosomes and controls what the cell does."]}, {"ht": "Spr1", "t": "B2 Health and disease: pathogens", "intro": "Some diseases are caught from other people or animals, and some are not. Communicable diseases are caused by tiny living things called pathogens, and your body has clever defences to stop them. Understanding this helps you stay healthy and explains how diseases spread.", "how": ["A communicable disease is caused by a pathogen and can spread from one person to another; a non-communicable disease, like most heart disease, cannot.", "The four main types of pathogen are bacteria, viruses, fungi and protists.", "Pathogens spread through air (coughs and sneezes), water, food, direct contact and animals called vectors, such as mosquitoes.", "Your first defences are barriers: skin, mucus and cilia in your airways, and stomach acid.", "If pathogens get in, white blood cells attack them by engulfing them, making antibodies and making antitoxins."], "example": {"q": "Malaria is caused by a protist carried by mosquitoes. Suggest two ways to reduce the spread of malaria.", "steps": ["Identify the vector: the mosquito carries the pathogen from person to person.", "Stop mosquitoes biting people, for example by sleeping under insecticide-treated nets.", "Reduce the number of mosquitoes, for example by draining standing water where they breed.", "Explain: fewer bites means fewer people infected."], "a": "Using mosquito nets and removing standing water both cut the number of bites, so fewer people catch malaria."}, "walk": [{"h": "Two kinds of disease", "b": "Communicable diseases, like flu or measles, are caused by pathogens and can be passed on. Non-communicable diseases, like type 2 diabetes or most cancers, cannot be caught from someone. They are often linked to genes, age or lifestyle."}, {"h": "Pathogens and spread", "b": "Bacteria are tiny cells that can make toxins, while viruses are even smaller and reproduce inside your cells, damaging them. Fungi cause athlete's foot, and a protist causes malaria. Washing hands, covering sneezes and clean water all help stop spread."}, {"h": "The immune system", "b": "Skin acts as a barrier, and mucus traps microbes which cilia then sweep away. White blood cells can engulf pathogens, which is called phagocytosis. Others make antibodies that stick to a specific pathogen, and if the same pathogen returns, memory cells help make antibodies much faster."}], "qs": [["What is a pathogen?", ["A microorganism that causes disease", "A white blood cell", "A type of medicine", "A healthy body cell"], "Pathogens are disease-causing microorganisms such as bacteria and viruses."], ["Which of these is a non-communicable disease?", ["Coronary heart disease", "Measles", "Influenza", "Malaria"], "Heart disease cannot be passed from person to person, so it is non-communicable."], ["Which type of pathogen can only reproduce inside living cells?", ["Virus", "Bacterium", "Fungus", "Protist"], "Viruses take over host cells to make copies of themselves."], ["Malaria is caused by which type of pathogen?", ["Protist", "Virus", "Bacterium", "Fungus"], "Malaria is caused by a protist (Plasmodium) carried by mosquitoes."], ["Athlete's foot is caused by which type of pathogen?", ["Fungus", "Virus", "Bacterium", "Protist"], "Athlete's foot is a fungal infection of the skin."], ["What is a vector in disease spread?", ["An organism that carries a pathogen to another organism", "A medicine that kills bacteria", "A type of white blood cell", "A barrier such as skin"], "A vector, such as a mosquito, transfers a pathogen without being the main host."], ["How does stomach acid help defend the body?", ["It kills pathogens in food and drink", "It makes antibodies", "It traps dust in the nose", "It sweeps mucus away"], "The hydrochloric acid in the stomach kills many microorganisms that are swallowed."], ["What do cilia in the airways do?", ["Sweep mucus and trapped microbes away from the lungs", "Make antibodies", "Engulf bacteria", "Release antitoxins"], "Cilia are tiny hairs that move mucus, carrying trapped pathogens up and away."], ["What is the job of antibodies?", ["To attach to specific pathogens so they can be destroyed", "To carry oxygen", "To digest food", "To clot the blood"], "Antibodies bind to antigens on a specific pathogen, helping white blood cells destroy it."], ["Why are you usually ill only once with diseases like chickenpox?", ["Memory cells make antibodies quickly if it returns", "The virus cannot ever enter you again", "Your skin becomes thicker", "Antibiotics stay in your blood"], "Memory cells remember the pathogen, so a second response is fast and stops you feeling ill."]], "bonus": ["Which of these is a good way to stop the spread of germs?", ["Washing your hands with soap", "Sharing drinking cups", "Coughing into the air", "Eating more sugar"], "Hand washing removes microorganisms before they can spread to others or into your mouth."]}, {"ht": "Spr2", "t": "B2 Health and disease: treatment", "intro": "Doctors have powerful tools to prevent and treat disease, such as vaccines and antibiotics. But bacteria can become resistant, and new medicines take years of careful testing. Your lifestyle choices also have a big effect on your risk of non-communicable diseases.", "how": ["A vaccine contains a dead, weakened or harmless part of a pathogen, which makes your white blood cells produce antibodies and memory cells.", "Antibiotics kill bacteria or stop them growing, but they do not work on viruses.", "Antibiotic resistance happens when random mutations let some bacteria survive; they reproduce and pass on the resistance.", "New medicines are tested in the lab on cells and animals, then in clinical trials on healthy volunteers and then on patients.", "Smoking, poor diet, too much alcohol and lack of exercise increase the risk of diseases such as heart disease, some cancers and type 2 diabetes."], "example": {"q": "Explain why doctors tell patients to finish the full course of antibiotics.", "steps": ["Antibiotics kill most of the bacteria quickly, so the patient feels better.", "The bacteria that survive longest are the ones that are more resistant.", "If the course is stopped early, these surviving bacteria can reproduce.", "This can spread resistant bacteria, making the antibiotic less useful in future."], "a": "Finishing the course kills all the bacteria, so no resistant survivors are left to multiply and spread."}, "walk": [{"h": "How vaccines work", "b": "A vaccine gives your body a safe preview of a pathogen. Your white blood cells make antibodies and memory cells, without you getting ill. If the real pathogen arrives later, you make antibodies so quickly that you are protected; when most people are vaccinated, this herd immunity also protects others."}, {"h": "Antibiotics and resistance", "b": "Antibiotics like penicillin kill bacteria but are useless against viruses such as colds and flu. Overusing them lets resistant bacteria, like MRSA, survive and spread by natural selection. To slow this, doctors only prescribe antibiotics when needed and patients finish the course."}, {"h": "New medicines and lifestyle", "b": "A new drug is tested for safety, effectiveness and the right dose. In a double-blind trial, neither the patients nor the doctors know who has the drug or the placebo, so the results are fair. Lifestyle matters too: smoking is a major cause of lung cancer, and regular exercise lowers the risk of heart disease."}], "qs": [["What do antibiotics kill?", ["Bacteria", "Viruses", "All pathogens", "White blood cells"], "Antibiotics work against bacteria but have no effect on viruses."], ["Why should antibiotics not be given for a cold?", ["Colds are caused by viruses, which antibiotics do not kill", "Colds are caused by fungi", "Antibiotics make colds last longer", "Colds are non-communicable"], "Colds are viral, so antibiotics would not help and would encourage resistance."], ["What does a vaccine contain?", ["Dead, weakened or harmless parts of a pathogen", "Ready-made antibiotics", "Live, full-strength pathogens", "Extra red blood cells"], "A vaccine contains a safe form of the pathogen's antigens to trigger an immune response."], ["What does a vaccine cause your body to make?", ["Antibodies and memory cells", "Antibiotics", "Red blood cells", "Toxins"], "The vaccine triggers white blood cells to make antibodies and long-lasting memory cells."], ["What is herd immunity?", ["When most people are vaccinated, protecting those who are not", "When animals pass on immunity", "When antibiotics stop working", "When everyone catches a disease at once"], "If most people are immune, a pathogen struggles to spread, so unvaccinated people are protected too."], ["How does antibiotic resistance spread through a population of bacteria?", ["Resistant bacteria survive and reproduce", "Bacteria learn to avoid antibiotics", "Antibiotics turn into viruses", "Patients become resistant to bacteria"], "Mutations make some bacteria resistant; they survive treatment and multiply, which is natural selection."], ["MRSA is an example of what?", ["An antibiotic-resistant bacterium", "A vaccine", "A virus", "A painkiller"], "MRSA is a bacterium resistant to several common antibiotics."], ["What is a placebo in a clinical trial?", ["A dummy treatment with no drug in it", "A stronger version of the drug", "A type of vaccine", "The final approved medicine"], "A placebo looks like the real treatment but contains no active drug, so results can be compared fairly."], ["In a double-blind trial, who knows which patients get the real drug?", ["Neither the patients nor the doctors", "Only the patients", "Only the doctors", "Both patients and doctors"], "Neither group knows, which stops expectations from biasing the results."], ["Which lifestyle factor is the biggest cause of lung cancer?", ["Smoking", "Eating fruit", "Drinking water", "Regular exercise"], "Tobacco smoke contains carcinogens, and smoking is the leading cause of lung cancer."]], "bonus": ["Which of these is part of a healthy balanced diet?", ["Plenty of fruit and vegetables", "Mostly sweets and crisps", "No water at all", "Only one type of food"], "A balanced diet includes lots of fruit and vegetables plus the right amounts of each food group."]}, {"ht": "Sum1", "t": "B6 Life on Earth: evolution", "intro": "No two living things are exactly alike, and these differences are called variation. Over millions of years, variation and natural selection have produced all the species alive today. This idea, called evolution, is one of the most important in all of biology.", "how": ["Variation is caused by genes, by the environment, or by both together.", "Mutations are changes in DNA that create new alleles, which is the original source of genetic variation.", "Natural selection: individuals best suited to their environment are more likely to survive, reproduce and pass on their alleles.", "Over many generations, natural selection changes the characteristics of a species, and this is evolution.", "Evidence for evolution includes fossils, antibiotic-resistant bacteria and similarities in DNA between species."], "example": {"q": "Peppered moths come in pale and dark forms. During the Industrial Revolution, soot darkened tree bark and dark moths became more common. Explain why.", "steps": ["There was variation: some moths were pale and some were dark, caused by different alleles.", "On dark, sooty bark, pale moths were easier for birds to see and eat.", "Dark moths were camouflaged, so more of them survived and reproduced.", "They passed on the allele for dark colour, so over generations dark moths became more common."], "a": "Natural selection favoured dark moths on sooty trees, so the dark allele became more common in the population."}, "walk": [{"h": "Variation", "b": "Some differences are genetic, like blood group, and some are environmental, like a scar. Many, like height, are affected by both genes and environment. Continuous variation, such as height, has a range of values, while discontinuous variation, such as blood group, falls into clear groups."}, {"h": "Natural selection", "b": "Charles Darwin explained that organisms produce more offspring than can survive. Those with helpful variations, like a giraffe with a slightly longer neck, survive and breed more often. Their helpful alleles are passed on, so the population slowly changes."}, {"h": "Evidence for evolution", "b": "Fossils show how organisms have changed over millions of years, such as the ancestors of horses. Bacteria evolving resistance to antibiotics lets us watch evolution happen in years, not millions of years. DNA comparisons show that species with more similar DNA, such as humans and chimpanzees, share a more recent common ancestor."}], "qs": [["What is variation?", ["Differences between individuals", "A type of cell division", "A disease caused by genes", "The death of a species"], "Variation means the differences in characteristics between organisms."], ["Which of these is caused only by the environment?", ["A scar from a cut", "Natural eye colour", "Blood group", "Being able to roll your tongue"], "A scar is caused by an injury, not by your genes."], ["What is the original source of new genetic variation?", ["Mutation", "Exercise", "Diet", "Mitosis"], "Mutations are random changes in DNA that create new alleles."], ["Who proposed the theory of evolution by natural selection?", ["Charles Darwin", "Isaac Newton", "Louis Pasteur", "Gregor Mendel"], "Charles Darwin published On the Origin of Species in 1859."], ["Which is an example of continuous variation?", ["Height", "Blood group", "Tongue rolling", "Whether earlobes are attached or free"], "Height can take any value within a range, so it is continuous."], ["In natural selection, which individuals are most likely to pass on their alleles?", ["Those best adapted to their environment", "The oldest individuals", "Those that try hardest to change", "Those with the fewest offspring"], "Better-adapted individuals survive and reproduce more, passing on their alleles."], ["Why did dark peppered moths become more common on sooty trees?", ["They were camouflaged, so fewer were eaten by birds", "Soot turned pale moths dark", "Dark moths chose to be dark", "Birds preferred eating dark moths"], "Camouflaged dark moths survived and bred more, so the dark allele increased."], ["Which of these is evidence for evolution?", ["Fossils", "Vaccines", "Photosynthesis", "Digestion"], "Fossils show how organisms have changed over very long periods of time."], ["Why are antibiotic-resistant bacteria good evidence for evolution?", ["We can see natural selection happen over a short time", "They prove bacteria are plants", "They show bacteria never change", "They were found as fossils"], "Bacteria reproduce so fast that resistance spreading by natural selection can be seen in years."], ["Humans share more DNA with chimpanzees than with mice. What does this suggest?", ["Humans and chimps share a more recent common ancestor", "Humans evolved from mice", "Chimpanzees evolved from humans", "Mice are not living things"], "More similar DNA suggests species split from a common ancestor more recently."]], "bonus": ["What does it mean if an animal is adapted to its habitat?", ["It has features that help it survive there", "It has moved to a new habitat", "It is the biggest animal there", "It has no predators anywhere"], "Adaptations are features, like thick fur in the Arctic, that help an organism survive in its habitat."]}, {"ht": "Sum2", "t": "B6 Life on Earth: biodiversity", "intro": "Scientists sort living things into groups so they can study and name them clearly. Biodiversity means the variety of living things in an area, and it is under threat from human activity. You will also practise using a microscope, a key practical skill in biology.", "how": ["Organisms are classified into groups: kingdom, phylum, class, order, family, genus, species.", "Each species has a two-part scientific name: genus then species, such as Homo sapiens (the binomial system).", "A species is a group of organisms that can breed together to produce fertile offspring.", "Extinction can be caused by new predators, new diseases, competition, habitat loss and climate change.", "Magnification = image size ÷ actual size, and you must use the same units for both."], "example": {"q": "A cell appears 6 mm wide in a drawing. Its actual width is 0.02 mm. What is the magnification?", "steps": ["Write the formula: magnification = image size ÷ actual size.", "Check both sizes are in the same units: both are in mm.", "Substitute: 6 ÷ 0.02.", "6 ÷ 0.02 = 300."], "a": "The magnification is × 300."}, "walk": [{"h": "Classifying living things", "b": "Carl Linnaeus grouped organisms by shared features, from large groups (kingdoms) down to single species. Today scientists also compare DNA to check how closely species are related. The lion is Panthera leo and the tiger is Panthera tigris; sharing the genus Panthera shows they are close relatives."}, {"h": "Biodiversity and extinction", "b": "High biodiversity makes ecosystems more stable, because species depend on each other for food and shelter. Humans reduce biodiversity by cutting down forests, polluting water and changing the climate. Conservation, such as protected areas, seed banks and breeding programmes, helps protect species from extinction."}, {"h": "Using a microscope", "b": "Start with the lowest-power objective lens and use the coarse focus to find the cells. Then switch to a higher power and use the fine focus to make the image sharp. Total magnification = eyepiece × objective, so a × 10 eyepiece with a × 40 objective gives × 400."}], "qs": [["What does biodiversity mean?", ["The variety of living things in an area", "The number of humans on Earth", "The study of fossils", "The weather in a habitat"], "Biodiversity is the range of different species and the variation within them."], ["What is the correct order of these groups, from largest to smallest?", ["Kingdom, family, genus, species", "Species, genus, family, kingdom", "Genus, kingdom, species, family", "Family, species, kingdom, genus"], "Classification goes from kingdom (largest) down to species (smallest)."], ["In the name Homo sapiens, what does Homo refer to?", ["The genus", "The species", "The kingdom", "The family"], "In the binomial system, the first word is the genus and the second is the species."], ["Which scientist developed the binomial naming system?", ["Carl Linnaeus", "Charles Darwin", "Alexander Fleming", "Marie Curie"], "Linnaeus introduced two-part Latin names for species in the 1700s."], ["What defines a species?", ["Organisms that can breed to produce fertile offspring", "Organisms that look exactly the same", "Organisms that live in the same place", "Organisms that eat the same food"], "Members of a species can interbreed and their offspring can also reproduce."], ["Which human activity reduces biodiversity?", ["Deforestation", "Setting up nature reserves", "Seed banks", "Breeding programmes in zoos"], "Cutting down forests destroys habitats, so many species lose their homes."], ["Which is a way of conserving species?", ["Storing seeds in a seed bank", "Draining wetlands", "Introducing new predators", "Increasing pollution"], "Seed banks keep seeds safe so plant species can be regrown if they die out in the wild."], ["When using a microscope, which objective lens should you start with?", ["The lowest-power lens", "The highest-power lens", "Any lens at random", "No lens at all"], "Low power shows a wider area, making it easier to find and focus on the specimen."], ["A microscope has a × 10 eyepiece and a × 40 objective lens. What is the total magnification?", ["× 400", "× 50", "× 4", "× 30"], "Total magnification = eyepiece × objective = 10 × 40 = 400."], ["An image is 12 mm long and the real object is 0.04 mm long. What is the magnification?", ["× 300", "× 30", "× 0.48", "× 3000"], "Magnification = image ÷ actual = 12 ÷ 0.04 = 300."]], "bonus": ["How many millimetres are in 1 centimetre?", ["10", "100", "1000", "1"], "1 cm = 10 mm, which you need when converting units for magnification."]}]}, {"id": "chemistry", "name": "Chemistry", "board": "OCR Twenty First Century Science", "weeks": [{"ht": "Aut1", "t": "Particles, the atmosphere and water", "intro": "Everything is made of tiny particles, and the way they are arranged explains solids, liquids and gases. The air around us is a mixture of gases that has changed a lot since the Earth formed. We also need clean, safe drinking water, called potable water, and chemistry explains how we make it.", "how": ["In a solid, particles are close together in a regular pattern and only vibrate; in a liquid they are close but move past each other; in a gas they are far apart and move quickly in all directions.", "Today's dry air is about 78% nitrogen, 21% oxygen, almost 1% argon and about 0.04% carbon dioxide.", "The early atmosphere was mostly carbon dioxide from volcanoes; oxygen increased when plants and algae began to photosynthesise.", "Burning fossil fuels adds carbon dioxide, and incomplete combustion makes carbon monoxide and particulates, which are harmful pollutants.", "Potable water is safe to drink but not pure; it is made by sedimentation, filtration and then chlorination to kill microbes."], "example": {"q": "Describe how water from a river is made safe to drink.", "steps": ["Sedimentation: let the water stand so that large bits of solid sink to the bottom.", "Filtration: pass the water through beds of sand and gravel to remove smaller solid particles.", "Chlorination: add a small amount of chlorine to kill bacteria and other microbes.", "The water is now potable: it still contains some dissolved substances, so it is not pure."], "a": "River water is made potable by sedimentation, then filtration, then chlorination to kill microbes."}, "walk": [{"h": "The particle model", "b": "Melting, boiling and condensing are physical changes where particles gain or lose energy but do not change. When ice melts, the water particles gain energy and start to move past each other. Gas particles hitting the walls of a container cause gas pressure, and heating the gas makes them hit harder and more often."}, {"h": "Gases in the atmosphere", "b": "The Earth's early atmosphere was mostly carbon dioxide and water vapour released by volcanoes. As the Earth cooled, water vapour condensed to form the oceans, and later photosynthesis removed carbon dioxide and added oxygen. Today, humans add extra carbon dioxide by burning fuels, which is linked to climate change."}, {"h": "Making potable water", "b": "Potable means safe to drink, which is different from pure. Tap water contains dissolved minerals, so it is a mixture. Where fresh water is scarce, seawater can be made drinkable by distillation, but this uses a lot of energy."}], "qs": [["In which state are particles far apart and moving quickly in all directions?", ["Gas", "Solid", "Liquid", "Crystal"], "Gas particles have the most energy and are spread far apart."], ["What is the main gas in the air today?", ["Nitrogen", "Oxygen", "Carbon dioxide", "Argon"], "Nitrogen makes up about 78% of dry air."], ["About what percentage of the air is oxygen?", ["21%", "78%", "1%", "50%"], "Oxygen makes up about one fifth (21%) of the atmosphere."], ["What happens to particles when a solid melts?", ["They gain energy and can move past each other", "They get bigger", "They lose energy and stop moving", "They turn into new substances"], "Melting gives particles enough energy to break out of fixed positions, but the particles themselves do not change."], ["Where did most of the carbon dioxide in the Earth's early atmosphere come from?", ["Volcanoes", "Plants", "Cars and factories", "The oceans freezing"], "Volcanic activity released large amounts of carbon dioxide and water vapour."], ["What process increased the amount of oxygen in the atmosphere?", ["Photosynthesis", "Respiration", "Combustion", "Volcanic eruptions"], "Plants and algae photosynthesise, taking in carbon dioxide and giving out oxygen."], ["Which pollutant is made by incomplete combustion and is toxic?", ["Carbon monoxide", "Nitrogen", "Oxygen", "Water vapour"], "Carbon monoxide forms when fuel burns without enough oxygen, and it stops blood carrying oxygen."], ["Why is chlorine added to drinking water?", ["To kill microbes", "To remove sand", "To make it taste sweet", "To make it pure"], "Chlorine kills bacteria and other microorganisms so the water is safe to drink."], ["What does potable water mean?", ["Water that is safe to drink", "Water with nothing dissolved in it", "Water from the sea", "Water that has been boiled"], "Potable water is safe to drink but can still contain dissolved substances."], ["Why does a gas in a sealed container have a higher pressure when heated?", ["Particles move faster and hit the walls harder and more often", "The particles get bigger", "More particles are created", "The particles stop moving"], "Heating gives particles more energy, so collisions with the walls are faster and more frequent."]], "bonus": ["What is the name for a gas turning into a liquid?", ["Condensing", "Evaporating", "Melting", "Freezing"], "Condensation is when a gas cools and turns into a liquid, like steam on a cold window."]}, {"ht": "Aut2", "t": "Atoms and the periodic table", "intro": "Our ideas about atoms have changed as scientists did new experiments. Atoms are made of protons, neutrons and electrons, and the number of protons decides which element an atom is. The periodic table arranges all the elements so that ones with similar properties sit together.", "how": ["Dalton thought atoms were solid spheres; Thomson discovered electrons and proposed the plum pudding model; Rutherford found the nucleus; Bohr put electrons in shells.", "Protons have a +1 charge and a relative mass of 1, neutrons are neutral with a mass of 1, and electrons are −1 with almost no mass.", "Atomic number = number of protons; mass number = protons + neutrons; in an atom, electrons = protons.", "The periodic table is in order of atomic number; columns are groups and rows are periods.", "Electrons fill shells in order: 2 in the first shell, then up to 8 in the second, then 8 in the third (for the first 20 elements)."], "example": {"q": "Sodium has atomic number 11 and mass number 23. How many protons, neutrons and electrons does a sodium atom have, and what is its electronic configuration?", "steps": ["Protons = atomic number = 11.", "Neutrons = mass number − atomic number = 23 − 11 = 12.", "Electrons = protons in a neutral atom = 11.", "Fill shells: 2 in the first, 8 in the second, 1 in the third, giving 2.8.1."], "a": "Sodium has 11 protons, 12 neutrons and 11 electrons, with electronic configuration 2.8.1."}, "walk": [{"h": "History of the atom", "b": "John Dalton described atoms as tiny solid balls. J.J. Thomson found electrons and imagined a ball of positive charge with electrons dotted through it, like a plum pudding. Rutherford's gold foil experiment showed most alpha particles went straight through, but a few bounced back, so atoms must have a tiny, dense, positive nucleus; Bohr then showed electrons orbit in fixed shells."}, {"h": "Subatomic particles", "b": "The nucleus holds protons and neutrons, and electrons are in shells around it. Carbon has atomic number 6, so every carbon atom has 6 protons. Isotopes are atoms of the same element with different numbers of neutrons, such as carbon-12 and carbon-14."}, {"h": "Periodic table and shells", "b": "Mendeleev arranged the elements and left gaps for ones not yet discovered, predicting their properties. The group number tells you how many electrons are in the outer shell, and the period number tells you how many shells there are. Chlorine is 2.8.7: three shells (period 3) and 7 outer electrons (Group 7)."}], "qs": [["Which particle has a negative charge?", ["Electron", "Proton", "Neutron", "Nucleus"], "Electrons have a relative charge of −1."], ["What does the atomic number tell you?", ["The number of protons", "The number of neutrons", "Protons plus neutrons", "The number of shells"], "The atomic number is the number of protons, which identifies the element."], ["Where are protons and neutrons found?", ["In the nucleus", "In the electron shells", "Spread evenly through the atom", "Outside the atom"], "Protons and neutrons are packed together in the tiny central nucleus."], ["Which scientist proposed the plum pudding model?", ["J.J. Thomson", "John Dalton", "Ernest Rutherford", "Niels Bohr"], "Thomson discovered the electron and suggested electrons were embedded in a ball of positive charge."], ["What did Rutherford's gold foil experiment show?", ["Atoms have a small, dense, positive nucleus", "Atoms are solid spheres", "Electrons are in shells", "Atoms have no charge"], "A few alpha particles bounced back, which only a tiny dense positive nucleus could explain."], ["An atom has a mass number of 19 and atomic number 9. How many neutrons does it have?", ["10", "9", "19", "28"], "Neutrons = mass number − atomic number = 19 − 9 = 10."], ["What is the electronic configuration of magnesium (atomic number 12)?", ["2.8.2", "2.10", "2.2.8", "8.2.2"], "12 electrons fill as 2 in the first shell, 8 in the second and 2 in the third."], ["What are isotopes?", ["Atoms of an element with different numbers of neutrons", "Atoms with different numbers of protons", "Atoms with no electrons", "Different elements in the same group"], "Isotopes have the same number of protons but a different number of neutrons."], ["Why did Mendeleev leave gaps in his periodic table?", ["For elements not yet discovered", "Because he made mistakes", "To make it look neat", "For gases only"], "He predicted that undiscovered elements would fill the gaps, and they later did."], ["An element has the configuration 2.8.6. Which group is it in?", ["Group 6", "Group 2", "Group 8", "Group 3"], "The number of outer-shell electrons (6) gives the group number."]], "bonus": ["What is an element?", ["A substance made of only one type of atom", "A mixture of two substances", "A substance made of different atoms bonded together", "Any liquid"], "An element contains only one type of atom, such as oxygen or iron."]}, {"ht": "Spr1", "t": "Bonding and groups 1, 7 and 0", "intro": "Atoms join together by bonding, and the type of bond explains a substance's properties. Elements in the same group of the periodic table behave in similar ways because they have the same number of outer electrons. This topic looks at the alkali metals, the halogens and the noble gases.", "how": ["Ionic bonding happens between a metal and a non-metal: the metal loses electrons to form positive ions and the non-metal gains them to form negative ions.", "Covalent bonding happens between non-metals, which share pairs of electrons.", "Metallic bonding is a lattice of positive metal ions in a sea of delocalised electrons, which is why metals conduct electricity.", "Group 1 metals get more reactive down the group; Group 7 halogens get less reactive down the group; Group 0 noble gases are unreactive because they have full outer shells.", "A more reactive halogen displaces a less reactive halogen from a solution of its salt."], "example": {"q": "Chlorine water is added to potassium bromide solution. Will a reaction happen? Write the word equation if it does.", "steps": ["Compare reactivity: chlorine is higher in Group 7 than bromine, so chlorine is more reactive.", "A more reactive halogen displaces a less reactive one, so a reaction happens.", "Chlorine takes bromine's place: chlorine + potassium bromide → potassium chloride + bromine.", "You would see the solution turn orange as bromine is formed."], "a": "Yes: chlorine + potassium bromide → potassium chloride + bromine, and the solution turns orange."}, "walk": [{"h": "Three types of bonding", "b": "In sodium chloride, sodium (2.8.1) gives one electron to chlorine (2.8.7), forming Na⁺ and Cl⁻ ions that attract strongly. In water, H₂O, oxygen shares a pair of electrons with each hydrogen atom in covalent bonds. In metals like copper, free electrons can move through the structure and carry current."}, {"h": "Groups 1 and 0", "b": "Group 1 metals, like lithium, sodium and potassium, have one outer electron and react with water to make an alkaline hydroxide and hydrogen. Potassium reacts more violently than sodium because its outer electron is further from the nucleus and is lost more easily. Group 0 gases, like helium and neon, have full outer shells so they hardly react at all."}, {"h": "Group 7 and displacement", "b": "Halogens have 7 outer electrons and exist as pairs of atoms, such as Cl₂. Going down the group, from fluorine to iodine, they become less reactive and their melting and boiling points rise. So bromine can displace iodine from potassium iodide, but iodine cannot displace bromine."}], "qs": [["What type of bonding is found in sodium chloride?", ["Ionic", "Covalent", "Metallic", "No bonding"], "Sodium is a metal and chlorine is a non-metal, so they form ionic bonds."], ["What happens in a covalent bond?", ["Atoms share a pair of electrons", "Electrons are transferred", "Protons are shared", "Ions are formed"], "Covalent bonds form when non-metal atoms share pairs of electrons."], ["Why can metals conduct electricity?", ["They have delocalised electrons that can move", "They contain ions in solution", "Their atoms share protons", "They have no electrons"], "In metallic bonding, free electrons move through the lattice and carry charge."], ["What is the charge on a sodium ion?", ["+1", "−1", "+2", "0"], "Sodium loses its one outer electron, so it forms Na⁺."], ["Why are noble gases unreactive?", ["They have full outer shells of electrons", "They are very heavy", "They have no electrons", "They are metals"], "With a full outer shell, they do not need to gain, lose or share electrons."], ["What gas is given off when sodium reacts with water?", ["Hydrogen", "Oxygen", "Chlorine", "Carbon dioxide"], "sodium + water → sodium hydroxide + hydrogen."], ["Which Group 1 metal is the most reactive of these?", ["Potassium", "Sodium", "Lithium", "They are all equally reactive"], "Reactivity increases down Group 1, and potassium is below sodium and lithium."], ["How does reactivity change going down Group 7?", ["It decreases", "It increases", "It stays the same", "It increases then decreases"], "Halogens get less reactive down the group because it is harder to gain an electron."], ["Which pair will react in a displacement reaction?", ["Bromine + potassium iodide", "Iodine + potassium chloride", "Iodine + potassium bromide", "Bromine + potassium chloride"], "Bromine is more reactive than iodine, so it displaces iodine; the other pairs do not react."], ["What forms when chlorine reacts with sodium bromide solution?", ["Sodium chloride and bromine", "Sodium and bromine chloride", "No reaction happens", "Sodium bromide and chlorine"], "Chlorine is more reactive, so it displaces bromine: chlorine + sodium bromide → sodium chloride + bromine."]], "bonus": ["Which of these is a metal?", ["Iron", "Oxygen", "Sulfur", "Carbon"], "Iron is a metal; oxygen, sulfur and carbon are non-metals."]}, {"ht": "Spr2", "t": "Mass, reactivity and extracting metals", "intro": "In a chemical reaction, atoms are rearranged but never created or destroyed, so the total mass stays the same. Metals can be put in order of how reactive they are, and this order tells us how to get them out of their ores. This explains why some metals were discovered thousands of years before others.", "how": ["Conservation of mass: the total mass of the reactants equals the total mass of the products.", "If mass seems to change in an open container, a gas has either escaped or been taken in from the air.", "Reactivity series (most to least): potassium, sodium, calcium, magnesium, aluminium, (carbon), zinc, iron, tin, lead, (hydrogen), copper, silver, gold.", "A more reactive metal displaces a less reactive metal from a solution of its compound.", "Metals below carbon, like iron, are extracted by heating with carbon (reduction); metals above carbon, like aluminium, are extracted by electrolysis."], "example": {"q": "24 g of magnesium burns completely in oxygen to make 40 g of magnesium oxide. What mass of oxygen reacted?", "steps": ["Use conservation of mass: mass of reactants = mass of products.", "Mass of magnesium + mass of oxygen = mass of magnesium oxide.", "24 g + oxygen = 40 g.", "Oxygen = 40 − 24 = 16 g."], "a": "16 g of oxygen reacted with the magnesium."}, "walk": [{"h": "Conservation of mass", "b": "When you burn magnesium in a crucible, the mass goes up because oxygen from the air joins on. When you heat calcium carbonate, the mass goes down because carbon dioxide escapes. In a sealed container the mass never changes, because no atoms can get in or out."}, {"h": "The reactivity series", "b": "Reactive metals like potassium fizz in water, while unreactive metals like gold do not react even with acids. If you put an iron nail in copper sulfate solution, the iron is more reactive, so it pushes the copper out. The nail becomes coated with pink-brown copper and the blue solution fades."}, {"h": "Extracting metals", "b": "Most metals are found as ores, which are compounds such as oxides. Iron oxide is heated with carbon in a blast furnace: iron oxide + carbon → iron + carbon dioxide; removing oxygen like this is called reduction. Aluminium is more reactive than carbon, so it must be extracted by electrolysis, which uses lots of electricity."}], "qs": [["What does the law of conservation of mass say?", ["Total mass of reactants equals total mass of products", "Mass always increases in a reaction", "Mass always decreases in a reaction", "Only solids have mass"], "Atoms are rearranged, not made or destroyed, so the total mass stays the same."], ["Which metal is the most reactive of these?", ["Potassium", "Iron", "Copper", "Gold"], "Potassium is at the top of the reactivity series."], ["Why is gold found as the pure metal in the ground?", ["It is very unreactive", "It is very reactive", "It is a non-metal", "It is always mixed with carbon"], "Gold is so unreactive that it does not form compounds easily."], ["Magnesium is heated in an open crucible and its mass increases. Why?", ["It combines with oxygen from the air", "Magnesium atoms are created", "Water is lost", "Heat has mass"], "Oxygen atoms from the air join the magnesium to make magnesium oxide, which is heavier."], ["When calcium carbonate is heated in an open tube, why does the mass decrease?", ["Carbon dioxide gas escapes", "Calcium atoms are destroyed", "Oxygen is absorbed", "The tube melts"], "calcium carbonate → calcium oxide + carbon dioxide, and the gas leaves the tube."], ["12 g of carbon reacts with 32 g of oxygen. What mass of carbon dioxide forms?", ["44 g", "20 g", "32 g", "384 g"], "Mass of products = 12 + 32 = 44 g."], ["An iron nail is placed in blue copper sulfate solution. What happens?", ["Copper coats the nail and the blue colour fades", "Nothing happens", "Iron coats the copper", "The solution turns red"], "Iron is more reactive than copper, so it displaces copper from the solution."], ["How is iron extracted from iron oxide?", ["Heating with carbon", "Electrolysis only", "Dissolving in water", "Heating with gold"], "Iron is less reactive than carbon, so carbon can remove the oxygen from iron oxide."], ["Why must aluminium be extracted by electrolysis?", ["It is more reactive than carbon", "It is less reactive than carbon", "It is found pure in the ground", "It is a liquid"], "Carbon cannot reduce compounds of metals that are more reactive than it."], ["In iron oxide + carbon → iron + carbon dioxide, what happens to the iron oxide?", ["It is reduced", "It is oxidised", "It is neutralised", "It is evaporated"], "The iron oxide loses oxygen, which is reduction."]], "bonus": ["What is a chemical reaction?", ["A change where new substances are made", "A change of state like melting", "Mixing sand and water", "Dissolving sugar in tea"], "In a chemical reaction new substances form, unlike physical changes such as melting."]}, {"ht": "Sum1", "t": "Electrolysis", "intro": "Electrolysis uses electricity to break down a compound into simpler substances. It is how we extract reactive metals like aluminium and make useful chemicals like chlorine and hydrogen. You will also carry out electrolysis yourself as a core practical.", "how": ["Electrolysis needs an electrolyte: an ionic compound that is molten or dissolved in water, so that its ions can move.", "The negative electrode is the cathode and the positive electrode is the anode.", "Positive ions (cations) move to the cathode; negative ions (anions) move to the anode.", "In a molten compound, the metal forms at the cathode and the non-metal forms at the anode.", "In a solution, hydrogen forms at the cathode if the metal is more reactive than hydrogen; halide ions form a halogen at the anode, otherwise oxygen forms."], "example": {"q": "Molten lead bromide is electrolysed. What forms at each electrode?", "steps": ["Lead bromide contains Pb²⁺ ions and Br⁻ ions, which can move because it is molten.", "Positive Pb²⁺ ions are attracted to the negative cathode, where they gain electrons to form lead.", "Negative Br⁻ ions are attracted to the positive anode, where they lose electrons to form bromine.", "You would see molten lead at the cathode and brown bromine vapour at the anode."], "a": "Lead forms at the cathode and bromine forms at the anode."}, "walk": [{"h": "Why ions must move", "b": "Solid ionic compounds cannot be electrolysed, because their ions are fixed in place. Melting or dissolving them frees the ions to move to the electrodes. That is why solid salt does not conduct, but salty water does."}, {"h": "Molten compounds", "b": "In a molten compound there are only two kinds of ion, so the result is simple. Molten zinc chloride gives zinc at the cathode and chlorine at the anode. Aluminium is made this way from molten aluminium oxide, giving aluminium at the cathode and oxygen at the anode."}, {"h": "Solutions and the practical", "b": "Water adds H⁺ and OH⁻ ions, so the products can change. Electrolysing sodium chloride solution gives hydrogen at the cathode, because sodium is more reactive than hydrogen, and chlorine at the anode. In the core practical, copper sulfate solution with inert electrodes gives pink copper on the cathode and bubbles of oxygen at the anode."}], "qs": [["What is the name of the negative electrode?", ["Cathode", "Anode", "Electrolyte", "Cation"], "The cathode is negative and attracts positive ions."], ["What is an electrolyte?", ["An ionic compound that is molten or dissolved", "A metal wire", "A solid that does not conduct", "A type of battery"], "An electrolyte contains ions that are free to move and carry charge."], ["Why can solid sodium chloride not be electrolysed?", ["Its ions cannot move", "It has no ions", "It is a metal", "It is too reactive"], "In a solid, the ions are held in fixed positions in the lattice."], ["To which electrode do positive ions move?", ["The cathode", "The anode", "Both electrodes", "Neither electrode"], "Opposite charges attract, so positive ions move to the negative cathode."], ["What forms at the cathode when molten zinc chloride is electrolysed?", ["Zinc", "Chlorine", "Hydrogen", "Oxygen"], "Zn²⁺ ions gain electrons at the cathode to form zinc metal."], ["What forms at the anode when molten lead bromide is electrolysed?", ["Bromine", "Lead", "Hydrogen", "Oxygen"], "Br⁻ ions lose electrons at the anode to form bromine."], ["Which metal is extracted from its molten oxide by electrolysis?", ["Aluminium", "Gold", "Iron", "Copper"], "Aluminium is too reactive to be extracted with carbon, so electrolysis is used."], ["Sodium chloride solution is electrolysed. What forms at the cathode?", ["Hydrogen", "Sodium", "Chlorine", "Oxygen"], "Sodium is more reactive than hydrogen, so hydrogen is produced instead."], ["Copper sulfate solution is electrolysed with inert electrodes. What forms at the cathode?", ["Copper", "Hydrogen", "Sulfur", "Oxygen"], "Copper is less reactive than hydrogen, so copper metal is deposited."], ["In the same copper sulfate electrolysis, what forms at the anode?", ["Oxygen", "Copper", "Sulfur dioxide", "Hydrogen"], "Sulfate does not contain a halide, so oxygen is given off at the anode."]], "bonus": ["Which of these materials conducts electricity?", ["Copper", "Plastic", "Wood", "Glass"], "Copper is a metal and a good electrical conductor; the others are insulators."]}, {"ht": "Sum2", "t": "Corrosion, half equations and LCAs", "intro": "Metals like iron slowly react with their surroundings and corrode, which costs a lot of money to fix. Half equations show exactly what happens to electrons during reactions like electrolysis. Life cycle assessments help us judge how much a product affects the environment from start to finish.", "how": ["Rusting is the corrosion of iron and needs both oxygen and water: iron + oxygen + water → hydrated iron(III) oxide.", "Rusting can be prevented by barriers (paint, oil, grease, plastic) or by sacrificial protection with a more reactive metal such as zinc (galvanising).", "Oxidation is loss of electrons and reduction is gain of electrons (remember OIL RIG).", "A half equation shows electrons as e⁻, for example Cu²⁺ + 2e⁻ → Cu at the cathode and 2Cl⁻ → Cl₂ + 2e⁻ at the anode.", "A life cycle assessment (LCA) looks at four stages: getting the raw materials, making the product, using it, and disposing of it."], "example": {"q": "Write the half equation for the formation of chlorine at the anode, and say whether it is oxidation or reduction.", "steps": ["Chloride ions are Cl⁻, and chlorine gas is made of molecules, Cl₂.", "Two chloride ions are needed to make one Cl₂ molecule: 2Cl⁻ → Cl₂.", "Balance the charge: the left side is 2−, so 2 electrons must be released: 2Cl⁻ → Cl₂ + 2e⁻.", "The chloride ions lose electrons, and loss of electrons is oxidation."], "a": "2Cl⁻ → Cl₂ + 2e⁻, which is oxidation because electrons are lost."}, "walk": [{"h": "Corrosion and rust", "b": "In a classic experiment, iron nails are put in three tubes: air and water, dry air only, and boiled water with no air. Only the nail with both air and water rusts. Galvanised iron is coated in zinc, which corrodes first because it is more reactive, protecting the iron even if scratched."}, {"h": "Half equations", "b": "A half equation shows one electrode at a time. At the cathode, positive ions gain electrons, such as Cu²⁺ + 2e⁻ → Cu, which is reduction. At the anode, negative ions lose electrons, such as 2Br⁻ → Br₂ + 2e⁻, which is oxidation; the charges on both sides must balance."}, {"h": "Life cycle assessments", "b": "An LCA adds up the energy, water, raw materials and pollution at every stage of a product's life. For example, a plastic bag uses crude oil but little energy to make, while a paper bag uses trees and more energy and water. Some parts of an LCA are hard to measure, such as how much pollution is fair to count, so judgements can differ."}], "qs": [["What two things are needed for iron to rust?", ["Oxygen and water", "Oxygen and salt", "Water and carbon dioxide", "Nitrogen and water"], "Iron only rusts when both oxygen and water are present."], ["A nail is kept in boiled water with a layer of oil on top. Why does it not rust?", ["There is no oxygen", "There is no water", "Oil is a type of rust", "Boiling makes iron unreactive"], "Boiling removes dissolved air and the oil stops more air getting in, so no oxygen reaches the nail."], ["Which of these prevents rusting by acting as a barrier?", ["Painting", "Adding salt", "Keeping the iron wet", "Heating the iron"], "Paint stops oxygen and water from reaching the iron surface."], ["What is galvanising?", ["Coating iron with zinc", "Coating iron with copper", "Melting iron", "Mixing iron with carbon"], "Galvanised iron has a zinc coating that protects it."], ["Why does zinc protect iron even when the coating is scratched?", ["Zinc is more reactive, so it corrodes first", "Zinc is less reactive than iron", "Zinc stops all electricity", "Zinc is a non-metal"], "This is sacrificial protection: the more reactive zinc loses electrons instead of the iron."], ["What does OIL RIG stand for?", ["Oxidation is loss, reduction is gain of electrons", "Oxygen in, lead released in gas", "Oxidation is light, reduction is gas", "Oxygen is lost, reduction is gained"], "OIL RIG reminds you that oxidation is loss and reduction is gain of electrons."], ["Which half equation is correct for copper forming at the cathode?", ["Cu²⁺ + 2e⁻ → Cu", "Cu²⁺ → Cu + 2e⁻", "Cu + 2e⁻ → Cu²⁺", "Cu²⁺ + e⁻ → Cu"], "A Cu²⁺ ion needs two electrons to become a neutral copper atom."], ["Which half equation correctly shows bromine forming at the anode?", ["2Br⁻ → Br₂ + 2e⁻", "Br⁻ → Br₂ + e⁻", "2Br⁻ + 2e⁻ → Br₂", "Br₂ → 2Br⁻ + 2e⁻"], "Two bromide ions each lose one electron to form one Br₂ molecule, and the charges balance."], ["Which is NOT one of the stages in a life cycle assessment?", ["Advertising the product", "Extracting raw materials", "Using the product", "Disposing of the product"], "An LCA covers raw materials, manufacture, use and disposal, not advertising."], ["Why can different LCAs of the same product give different conclusions?", ["Some effects are hard to measure and need judgement", "LCAs never use numbers", "Products have no environmental effects", "All products have identical impacts"], "Values like pollution effects can be estimated differently, so LCAs can be biased or uncertain."]], "bonus": ["Which of these is a renewable resource?", ["Wood from managed forests", "Crude oil", "Natural gas", "Coal"], "Trees can be replanted and regrown, but fossil fuels take millions of years to form."]}]}, {"id": "physics", "name": "Physics", "board": "OCR Twenty First Century Science", "weeks": [{"ht": "Aut1", "t": "Waves and the photon model", "intro": "Waves carry energy from one place to another without carrying matter with them. Sound, light and ripples on water are all waves. This topic shows you the two types of wave, how to work out a wave's speed, and how light can also be thought of as tiny packets of energy called photons.", "how": ["In a transverse wave the vibrations are at right angles (perpendicular) to the direction the wave travels, like ripples on water or light.", "In a longitudinal wave the vibrations are along (parallel to) the direction the wave travels, like sound.", "Amplitude is the maximum distance a point moves from its rest position, and wavelength is the distance from one point on a wave to the same point on the next wave.", "Frequency is the number of waves passing a point each second, measured in hertz (Hz).", "Use wave speed (m/s) = frequency (Hz) × wavelength (m)."], "example": {"q": "A water wave has a frequency of 50 Hz and a wavelength of 4 m. What is its wave speed?", "steps": ["Write the equation: wave speed = frequency × wavelength.", "Put in the numbers: wave speed = 50 × 4.", "Work it out: 50 × 4 = 200.", "Add the unit: metres per second (m/s)."], "a": "The wave speed is 200 m/s."}, "walk": [{"h": "Two types of wave", "b": "Shake a slinky up and down and the wave moves along while the coils move side to side: that is transverse. Push and pull the end instead and you get squashed and stretched parts (compressions and rarefactions): that is longitudinal. Light is transverse; sound is longitudinal."}, {"h": "Measuring a wave", "b": "Wavelength (λ) is measured in metres, from crest to crest. Frequency (f) is how many waves pass each second, in hertz, so 10 Hz means 10 waves every second. Amplitude is the height from the middle line to a crest, and a bigger amplitude means more energy."}, {"h": "Wave speed and photons", "b": "Wave speed = frequency × wavelength, so a wave of 5 Hz and 2 m travels at 10 m/s. To find wavelength, rearrange: wavelength = speed ÷ frequency. In the photon model, light and other electromagnetic radiation travel as packets of energy called photons, and a higher frequency photon carries more energy."}], "qs": [["In a transverse wave, how do the vibrations move?", ["At right angles to the direction the wave travels", "In the same direction the wave travels", "In circles around the wave", "They do not move at all"], "Transverse means the vibrations are perpendicular (at 90°) to the direction of energy transfer."], ["Which of these is a longitudinal wave?", ["A sound wave", "A light wave", "A ripple on a pond", "A microwave"], "Sound is made of compressions and rarefactions that vibrate along the direction of travel."], ["What is the unit of frequency?", ["Hertz (Hz)", "Metres (m)", "Metres per second (m/s)", "Joules (J)"], "Frequency is the number of waves per second, measured in hertz."], ["What is the amplitude of a wave?", ["The maximum distance a point moves from its rest position", "The distance from one crest to the next crest", "The number of waves passing each second", "How fast the wave travels"], "Amplitude is the biggest displacement from the middle (rest) line."], ["What is the wavelength of a wave?", ["The distance from one point to the same point on the next wave", "The height of a crest above the rest line", "The time for one wave to pass", "The number of waves made per second"], "Wavelength is measured from crest to crest (or any point to the matching point on the next wave)."], ["Which equation links wave speed, frequency and wavelength?", ["wave speed = frequency × wavelength", "wave speed = frequency ÷ wavelength", "wave speed = wavelength ÷ frequency", "wave speed = frequency + wavelength"], "Multiplying the number of waves per second by the length of each wave gives the distance travelled per second."], ["A wave has a frequency of 10 Hz and a wavelength of 3 m. What is its speed?", ["30 m/s", "3.3 m/s", "13 m/s", "0.3 m/s"], "wave speed = 10 × 3 = 30 m/s."], ["Sound travels at 340 m/s. A note has a frequency of 170 Hz. What is its wavelength?", ["2 m", "0.5 m", "510 m", "57 800 m"], "wavelength = speed ÷ frequency = 340 ÷ 170 = 2 m."], ["What does the photon model say about light?", ["Light travels as tiny packets of energy called photons", "Light is made of tiny particles of matter with mass", "Light needs air to travel through", "Light is a longitudinal wave"], "In the photon model, electromagnetic radiation is carried in packets of energy called photons."], ["Which of these photons carries the most energy?", ["An X-ray photon", "A radio wave photon", "An infrared photon", "A visible light photon"], "Photon energy increases with frequency, and X-rays have the highest frequency of these."]], "bonus": ["A cyclist travels 100 m in 20 s. What is their average speed?", ["5 m/s", "2000 m/s", "0.2 m/s", "120 m/s"], "speed = distance ÷ time = 100 ÷ 20 = 5 m/s."]}, {"ht": "Aut2", "t": "EM spectrum, environment and energy", "intro": "The electromagnetic (EM) spectrum is a family of waves, from radio waves to gamma rays, that all travel at the speed of light. Some of these waves affect our planet, for example by warming it through the greenhouse effect. This topic also looks at where our energy comes from and which resources will run out.", "how": ["In order of increasing frequency (and decreasing wavelength): radio, microwave, infrared, visible light, ultraviolet, X-rays, gamma rays.", "All EM waves are transverse and travel at the same speed in a vacuum: 300 000 000 m/s (3 × 10⁸ m/s).", "High-frequency radiation (ultraviolet, X-rays and gamma rays) is ionising and can damage living cells.", "Greenhouse gases such as carbon dioxide and methane absorb infrared radiation given off by the Earth, which keeps the Earth warmer.", "Renewable resources (wind, solar, hydroelectric, tidal, geothermal, biofuel) will not run out; non-renewable resources (coal, oil, gas, nuclear fuel) will."], "example": {"q": "A radio station broadcasts at a frequency of 200 000 Hz. Radio waves travel at 300 000 000 m/s. What is the wavelength?", "steps": ["Rearrange wave speed = frequency × wavelength to get wavelength = wave speed ÷ frequency.", "Put in the numbers: wavelength = 300 000 000 ÷ 200 000.", "Cancel the zeros: 3 000 ÷ 2 = 1 500.", "Add the unit: metres."], "a": "The wavelength is 1 500 m."}, "walk": [{"h": "The EM spectrum", "b": "A handy way to remember the order is 'Rich Men In Vegas Use X-ray Glasses': radio, microwave, infrared, visible, ultraviolet, X-ray, gamma. Moving along that list, frequency and photon energy go up and wavelength goes down. Radio waves can be longer than a building, while gamma rays are smaller than an atom."}, {"h": "Waves and our planet", "b": "The Sun's radiation warms the Earth, and the warm Earth gives off infrared. Greenhouse gases like CO₂ and methane absorb some of that infrared, so burning fossil fuels, which adds CO₂, is linked to global warming. High in the atmosphere, the ozone layer absorbs much of the Sun's harmful ultraviolet."}, {"h": "Energy resources", "b": "Fossil fuels (coal, oil, gas) are reliable but non-renewable and release CO₂ when burned. Nuclear fuel gives no CO₂ while running but is non-renewable and makes radioactive waste. Wind and solar are renewable and clean, but they depend on the weather, so they are not always available."}], "qs": [["Which part of the EM spectrum has the longest wavelength?", ["Radio waves", "Gamma rays", "Visible light", "Ultraviolet"], "Radio waves are at the low-frequency, long-wavelength end of the spectrum."], ["How fast do all EM waves travel in a vacuum?", ["300 000 000 m/s", "340 m/s", "3 000 m/s", "They all travel at different speeds"], "All EM waves travel at the speed of light, 3 × 10⁸ m/s, in a vacuum."], ["Which of these types of radiation is ionising?", ["Gamma rays", "Radio waves", "Microwaves", "Visible light"], "Gamma rays have very high frequency and enough energy to ionise atoms and damage cells."], ["Which list is in order of increasing frequency?", ["Radio, microwave, infrared, visible", "Visible, infrared, microwave, radio", "Microwave, radio, visible, infrared", "Infrared, radio, visible, microwave"], "Frequency increases from radio towards gamma rays."], ["Which of these is a greenhouse gas?", ["Carbon dioxide", "Oxygen", "Nitrogen", "Helium"], "Carbon dioxide absorbs infrared radiation and helps keep the Earth warm."], ["How do greenhouse gases warm the Earth?", ["They absorb infrared radiation given off by the Earth", "They reflect visible light back to the Sun", "They give out gamma rays", "They block all ultraviolet from the Sun"], "Greenhouse gases absorb infrared from the Earth's surface and re-emit it, keeping heat in the atmosphere."], ["Which energy resource is renewable?", ["Wind", "Coal", "Natural gas", "Oil"], "Wind will not run out, while coal, gas and oil are fossil fuels that will."], ["Why is nuclear power described as non-renewable?", ["Its fuel, such as uranium, will eventually run out", "It releases lots of carbon dioxide", "It only works when the wind blows", "It uses up sunlight"], "Uranium is mined from the ground and there is a limited amount of it."], ["What is one disadvantage of wind turbines?", ["They do not produce electricity when there is no wind", "They release carbon dioxide while running", "Their fuel will run out", "They produce radioactive waste"], "Wind power depends on the weather, so it is not reliable all the time."], ["A microwave has a frequency of 2 500 000 000 Hz and travels at 300 000 000 m/s. What is its wavelength?", ["0.12 m", "8.3 m", "1.2 m", "0.012 m"], "wavelength = 300 000 000 ÷ 2 500 000 000 = 0.12 m."]], "bonus": ["Which of these is a fossil fuel?", ["Coal", "Wood", "Sunlight", "Uranium"], "Coal formed from the remains of ancient plants over millions of years, so it is a fossil fuel."]}, {"ht": "Spr1", "t": "Domestic electricity and efficiency", "intro": "The electricity in your home comes from the mains supply, which is different from the electricity from a battery. This topic explains how plugs keep us safe and why energy is never really lost, only moved around. You will also learn how to calculate how efficient a device is.", "how": ["Direct current (DC) flows in one direction only, like from a battery; alternating current (AC) keeps changing direction, like the mains.", "UK mains electricity is AC at about 230 V with a frequency of 50 Hz.", "In a plug the live wire is brown, the neutral wire is blue and the earth wire is green and yellow striped; the fuse is connected to the live wire.", "Conservation of energy: energy cannot be created or destroyed, only transferred from one store to another.", "Efficiency = useful energy out ÷ total energy in, and multiply by 100 to get a percentage."], "example": {"q": "A light bulb is supplied with 200 J of energy and gives out 50 J as light. What is its efficiency?", "steps": ["Write the equation: efficiency = useful energy out ÷ total energy in.", "Put in the numbers: efficiency = 50 ÷ 200 = 0.25.", "Multiply by 100 to make a percentage: 0.25 × 100 = 25%.", "Check: the other 150 J is wasted, mostly as heat to the surroundings."], "a": "The bulb is 25% efficient."}, "walk": [{"h": "AC and DC", "b": "A battery pushes current one way round the circuit, which is DC. The mains supply makes the current flow back and forth 50 times every second, which is AC. On an oscilloscope, DC is a flat line and AC is a wave that goes above and below zero."}, {"h": "Plugs and safety", "b": "The live wire (brown) carries the 230 V supply, and the neutral wire (blue) completes the circuit. The earth wire (green and yellow) is a safety wire that connects a metal case to the ground. If too much current flows, the fuse in the live wire melts and cuts off the supply."}, {"h": "Energy and efficiency", "b": "Energy is always conserved: if 100 J goes into a motor, 100 J comes out in total, for example 70 J as useful kinetic energy and 30 J wasted as heat. Efficiency = 70 ÷ 100 = 0.7, or 70%. No device can be more than 100% efficient, because that would mean creating energy."}], "qs": [["What is the voltage of UK mains electricity?", ["About 230 V", "About 12 V", "About 1.5 V", "About 50 V"], "UK mains is supplied at about 230 volts."], ["What is the frequency of UK mains electricity?", ["50 Hz", "230 Hz", "60 Hz", "5 Hz"], "UK mains current changes direction in a cycle repeated 50 times each second."], ["What is alternating current (AC)?", ["Current that keeps changing direction", "Current that flows in one direction only", "Current that only flows in a battery", "Current that never stops flowing"], "AC repeatedly reverses its direction of flow."], ["What type of current does a battery supply?", ["Direct current (DC)", "Alternating current (AC)", "Mains current", "No current"], "A battery pushes charge in one direction only, which is DC."], ["What colour is the live wire in a UK plug?", ["Brown", "Blue", "Green and yellow", "Red"], "The live wire is brown; blue is neutral and green and yellow is earth."], ["What colour is the earth wire in a UK plug?", ["Green and yellow stripes", "Brown", "Blue", "Black"], "The earth wire is green and yellow, so it is easy to spot as the safety wire."], ["What does the law of conservation of energy say?", ["Energy cannot be created or destroyed, only transferred", "Energy is used up when a device is switched on", "Energy can be created by machines", "Wasted energy is destroyed"], "The total amount of energy always stays the same; it just moves between stores."], ["A kettle takes in 2 000 J and transfers 1 800 J usefully to the water. What is its efficiency?", ["90%", "10%", "111%", "180%"], "Efficiency = 1 800 ÷ 2 000 = 0.9, which is 90%."], ["A motor takes in 500 J and is 40% efficient. How much energy is wasted?", ["300 J", "200 J", "460 J", "540 J"], "Useful energy = 40% of 500 = 200 J, so wasted energy = 500 − 200 = 300 J."], ["A device is 80% efficient and gives out 400 J of useful energy. How much energy was put in?", ["500 J", "320 J", "480 J", "80 J"], "Total in = useful out ÷ efficiency = 400 ÷ 0.8 = 500 J."]], "bonus": ["What is the unit of energy?", ["Joule (J)", "Watt (W)", "Volt (V)", "Newton (N)"], "Energy is measured in joules."]}, {"ht": "Spr2", "t": "Magnetism, resistance and circuits", "intro": "Magnets create invisible magnetic fields that push and pull on other magnets and on magnetic materials. An electric current also makes a magnetic field, which is how electromagnets work. This topic also explains resistance and how to build and measure simple circuits.", "how": ["Every magnet has a north and a south pole: like poles repel and unlike poles attract.", "Magnetic field lines point from the north pole to the south pole, and the field is strongest where the lines are closest together.", "A current in a wire makes a magnetic field; coiling the wire around an iron core makes an electromagnet that can be switched on and off.", "Resistance = potential difference ÷ current (R = V ÷ I), measured in ohms (Ω).", "An ammeter is connected in series to measure current, and a voltmeter is connected in parallel across a component to measure potential difference."], "example": {"q": "There is a potential difference of 12 V across a resistor and a current of 3 A through it. What is its resistance?", "steps": ["Write the equation: resistance = potential difference ÷ current.", "Put in the numbers: R = 12 ÷ 3.", "Work it out: 12 ÷ 3 = 4.", "Add the unit: ohms (Ω)."], "a": "The resistance is 4 Ω."}, "walk": [{"h": "Magnets and fields", "b": "Bring two north poles together and they push apart; bring a north and a south together and they pull. Iron, steel, nickel and cobalt are magnetic, but copper and aluminium are not. Sprinkling iron filings around a bar magnet shows the field lines curving from north to south."}, {"h": "Electromagnets", "b": "A current in a straight wire makes circular field lines around the wire. Wind the wire into a coil (a solenoid) and the field looks like a bar magnet's. Put an iron core inside, add more turns or increase the current, and the electromagnet gets stronger, which is why scrapyard cranes use them."}, {"h": "Resistance in circuits", "b": "Resistance tells you how hard it is for current to flow. If a bulb has 6 V across it and 2 A through it, R = 6 ÷ 2 = 3 Ω. You can rearrange to V = I × R, so 2 A through a 10 Ω resistor needs 20 V. Current only flows if the circuit is a complete loop."}], "qs": [["What happens when two north poles are brought together?", ["They repel", "They attract", "Nothing happens", "They become south poles"], "Like poles repel each other."], ["Which way do magnetic field lines point outside a bar magnet?", ["From north to south", "From south to north", "Round in circles around the middle", "Straight up from both poles"], "Field lines are drawn leaving the north pole and entering the south pole."], ["Which of these metals is magnetic?", ["Iron", "Copper", "Aluminium", "Gold"], "Iron, steel, nickel and cobalt are magnetic; most other metals are not."], ["What shape is the magnetic field around a straight wire carrying a current?", ["Circles around the wire", "Straight lines along the wire", "A figure of eight", "There is no field"], "The field lines form circles centred on the wire."], ["Which change would make an electromagnet stronger?", ["Adding more turns of wire to the coil", "Using fewer turns of wire", "Using a smaller current", "Replacing the iron core with a wooden one"], "More turns, more current or an iron core all make the field stronger."], ["What is the main advantage of an electromagnet over a permanent magnet?", ["It can be switched on and off", "It never needs electricity", "It has no poles", "It only attracts copper"], "Switching off the current switches off the magnetism, which is useful in cranes, doorbells and relays."], ["What is the unit of resistance?", ["Ohm (Ω)", "Ampere (A)", "Volt (V)", "Watt (W)"], "Resistance is measured in ohms."], ["A bulb has 6 V across it and 2 A through it. What is its resistance?", ["3 Ω", "12 Ω", "8 Ω", "0.33 Ω"], "R = V ÷ I = 6 ÷ 2 = 3 Ω."], ["How should an ammeter be connected to measure the current through a bulb?", ["In series with the bulb", "In parallel across the bulb", "Not connected to the circuit", "Across the battery only"], "Current must flow through the ammeter, so it goes in series."], ["A current of 2 A flows through a 10 Ω resistor. What is the potential difference across it?", ["20 V", "5 V", "0.2 V", "12 V"], "V = I × R = 2 × 10 = 20 V."]], "bonus": ["Why does a bulb not light if there is a gap in the circuit?", ["Current can only flow around a complete loop", "The gap uses up all the energy", "The battery becomes magnetic", "The bulb's resistance becomes zero"], "Without a complete circuit there is no path for the charge to flow around."]}, {"ht": "Sum1", "t": "Work done, sensors, series and parallel", "intro": "When charge flows through a component, energy is transferred, and we call this work done. Some components, such as LDRs and thermistors, change their resistance when light or temperature changes, so they make great sensors. This topic also compares the two main ways of connecting a circuit: series and parallel.", "how": ["Energy transferred (work done, J) = charge (C) × potential difference (V), and charge (C) = current (A) × time (s).", "The resistance of a light-dependent resistor (LDR) goes down as light gets brighter.", "The resistance of a thermistor goes down as temperature goes up.", "In a series circuit the current is the same everywhere, the potential differences add up to the supply, and total resistance = R₁ + R₂.", "In a parallel circuit each branch has the same potential difference as the supply, and the branch currents add up to the total current."], "example": {"q": "A charge of 3 C flows through a lamp with a potential difference of 12 V across it. How much energy is transferred?", "steps": ["Write the equation: energy transferred = charge × potential difference.", "Put in the numbers: energy = 3 × 12.", "Work it out: 3 × 12 = 36.", "Add the unit: joules (J)."], "a": "36 J of energy is transferred."}, "walk": [{"h": "Electrical work done", "b": "Potential difference tells you how much energy each coulomb of charge transfers: 1 V means 1 joule per coulomb. So 5 C through 6 V transfers 5 × 6 = 30 J. If you are given a current and a time, first find the charge: 2 A for 10 s gives 20 C."}, {"h": "LDRs and thermistors", "b": "An LDR has a high resistance in the dark and a low resistance in bright light, so it can switch on street lights at night. A thermistor has a lower resistance when it is hot, so it can be used in a fire alarm or a digital thermometer. Both are input sensors."}, {"h": "Series and parallel", "b": "In series there is one loop: 4 Ω and 6 Ω in series give 10 Ω, and a 9 V battery is shared, so if one bulb has 4 V the other has 5 V. In parallel each branch gets the full supply p.d., and branch currents of 0.5 A and 0.3 A add to 0.8 A from the battery. Adding a resistor in parallel makes the total resistance smaller."}], "qs": [["Which equation gives the energy transferred by a charge?", ["energy = charge × potential difference", "energy = charge ÷ potential difference", "energy = current ÷ time", "energy = resistance × charge"], "Each coulomb transfers energy equal to the p.d. in volts, so multiply charge by p.d."], ["A charge of 5 C flows through a potential difference of 6 V. How much energy is transferred?", ["30 J", "1.2 J", "11 J", "0.83 J"], "energy = 5 × 6 = 30 J."], ["What happens to the resistance of an LDR in bright light?", ["It goes down", "It goes up", "It stays the same", "It becomes infinite"], "An LDR's resistance falls as light intensity increases."], ["What happens to the resistance of a thermistor as it gets hotter?", ["It goes down", "It goes up", "It stays the same", "It doubles every degree"], "A thermistor's resistance falls as temperature rises."], ["How does the current compare at different points in a series circuit?", ["It is the same at every point", "It is biggest next to the battery", "It gets used up by each bulb", "It is zero after the first bulb"], "There is only one path, so the same current flows through every component."], ["A 4 Ω resistor and a 6 Ω resistor are connected in series. What is the total resistance?", ["10 Ω", "2.4 Ω", "24 Ω", "2 Ω"], "In series, resistances add: 4 + 6 = 10 Ω."], ["Two bulbs are in series with a 9 V battery. One bulb has 4 V across it. What is the p.d. across the other?", ["5 V", "4 V", "9 V", "13 V"], "In series the p.d.s add up to the supply: 9 − 4 = 5 V."], ["In a parallel circuit, what is the potential difference across each branch?", ["The same as the supply p.d.", "Shared equally between the branches", "Zero", "Double the supply p.d."], "Each branch is connected directly across the supply, so each gets the full p.d."], ["Two parallel branches carry currents of 0.5 A and 0.3 A. What current flows from the battery?", ["0.8 A", "0.2 A", "0.15 A", "0.5 A"], "In parallel, branch currents add: 0.5 + 0.3 = 0.8 A."], ["A current of 2 A flows for 30 s through a lamp with 3 V across it. How much energy is transferred?", ["180 J", "6 J", "90 J", "20 J"], "charge = 2 × 30 = 60 C, then energy = 60 × 3 = 180 J."]], "bonus": ["What is the unit of electric current?", ["Ampere (A)", "Volt (V)", "Ohm (Ω)", "Coulomb (C)"], "Current is measured in amperes, or amps, using an ammeter."]}, {"ht": "Sum2", "t": "Circuit testing, power and transformers", "intro": "Electrical power tells you how quickly a device transfers energy, which is why a kettle and a phone charger have very different power ratings. Engineers test circuits with meters to find faults and check that components work. Transformers change the size of the voltage, which lets the National Grid send electricity across the country efficiently.", "how": ["To test a circuit, measure current with an ammeter in series and p.d. with a voltmeter in parallel; an ammeter reading of zero in a series circuit means there is a break somewhere.", "Power (W) = current (A) × potential difference (V), so P = IV.", "Power (W) = current² × resistance, so P = I²R.", "Energy transferred (J) = power (W) × time (s), so E = Pt, with time always in seconds.", "A step-up transformer increases the voltage and a step-down transformer decreases it; transformers only work with AC, and Vp ÷ Vs = Np ÷ Ns."], "example": {"q": "A kettle runs on 230 V and draws a current of 10 A. What is its power, and how much energy does it transfer in 60 s?", "steps": ["Use P = I × V: P = 10 × 230 = 2 300 W.", "Use E = P × t, with time in seconds: E = 2 300 × 60.", "Work it out: 2 300 × 60 = 138 000.", "Add the units: watts for power, joules for energy."], "a": "The power is 2 300 W and it transfers 138 000 J in 60 s."}, "walk": [{"h": "Testing circuits", "b": "When a circuit does not work, take measurements instead of guessing. If the ammeter reads 0 A in a series circuit, there is a break, such as a loose wire or a blown bulb. Measuring both V and I lets you calculate a component's resistance and check that it matches what it should be."}, {"h": "Electrical power", "b": "Power is energy transferred per second, so a 100 W bulb transfers 100 J every second. Use P = IV when you know current and p.d., and P = I²R when you know current and resistance: 3 A through 5 Ω gives 3² × 5 = 45 W. For energy, use E = Pt, so 100 W for 20 s is 2 000 J."}, {"h": "Transformers", "b": "A transformer has two coils on an iron core. If the secondary coil has 5 times as many turns as the primary, the voltage is 5 times bigger, so 20 V becomes 100 V. The National Grid steps the voltage up so the current is small, which wastes less energy heating the cables, then steps it down again for homes."}], "qs": [["In a series circuit the bulbs are off and the ammeter reads 0 A. What is the most likely fault?", ["There is a break in the circuit", "The ammeter is in series", "The current is too high", "The bulbs are in parallel"], "No current at all in a series circuit means the loop is broken somewhere."], ["A lamp has 12 V across it and 2 A through it. What is its power?", ["24 W", "6 W", "14 W", "0.17 W"], "P = I × V = 2 × 12 = 24 W."], ["A current of 3 A flows through a 5 Ω resistor. What is the power?", ["45 W", "15 W", "225 W", "30 W"], "P = I²R = 3² × 5 = 9 × 5 = 45 W."], ["A 100 W bulb is on for 20 s. How much energy does it transfer?", ["2 000 J", "5 J", "120 J", "0.2 J"], "E = P × t = 100 × 20 = 2 000 J."], ["A 1 000 W hair dryer is used for 5 minutes. How much energy does it transfer?", ["300 000 J", "5 000 J", "200 J", "300 J"], "5 minutes = 300 s, so E = 1 000 × 300 = 300 000 J."], ["What does a step-up transformer do?", ["Increases the voltage", "Decreases the voltage", "Changes AC into DC", "Stores electrical energy"], "A step-up transformer has more turns on the secondary coil, so it increases the voltage."], ["What type of current do transformers work with?", ["Alternating current (AC) only", "Direct current (DC) only", "Both AC and DC equally", "Neither AC nor DC"], "A transformer needs a changing magnetic field, which only AC provides."], ["A transformer has 100 turns on the primary and 500 on the secondary. The input is 20 V. What is the output?", ["100 V", "4 V", "400 V", "120 V"], "Vs = Vp × Ns ÷ Np = 20 × 500 ÷ 100 = 100 V."], ["Why does the National Grid transmit electricity at a very high voltage?", ["To make the current small so less energy is wasted heating cables", "To make the current bigger so it travels faster", "Because homes need very high voltages", "To change AC into DC"], "For the same power, higher voltage means lower current, and heating losses depend on I²R."], ["An ideal transformer has 230 V and 0.5 A on the primary. The secondary voltage is 11.5 V. What is the secondary current?", ["10 A", "0.025 A", "5 A", "20 A"], "Power in = power out: 230 × 0.5 = 115 W, so I = 115 ÷ 11.5 = 10 A."]], "bonus": ["How many seconds are there in 2 minutes?", ["120 s", "200 s", "60 s", "100 s"], "There are 60 seconds in a minute, so 2 × 60 = 120 s."]}]}, {"id": "re", "name": "Religious Studies", "board": "AQA (Specification A, 8062)", "weeks": [{"ht": "Aut1", "t": "Human rights and prejudice", "intro": "This topic looks at how people should be treated fairly, and what Christians, Muslims and non-religious people say about prejudice and discrimination. It matters because laws like the Equality Act 2010 protect everyone in the UK, and religions have strong teachings about equality.", "how": ["Prejudice is a thought or feeling: judging someone unfairly before knowing them.", "Discrimination is an action: treating someone unfairly because of who they are.", "Learn one Christian and one Muslim teaching about equality to use as evidence.", "Always give more than one view, including non-religious views, when you evaluate.", "Link examples to UK law, such as the Equality Act 2010 and the Human Rights Act 1998."], "example": {"q": "Explain two religious beliefs about prejudice. (4 marks)", "steps": ["Give a first belief: Christians believe all people are made in the image of God (Genesis 1:27).", "Develop it: so treating anyone as less valuable goes against how God created them.", "Give a second belief: the Qur'an teaches God made people into nations and tribes so they may know one another (49:13).", "Develop it: so differences in race or culture are part of God's plan and should not lead to hatred."], "a": "Both religions teach that all humans have equal worth, so prejudice is wrong."}, "walk": [{"h": "Prejudice versus discrimination", "b": "Prejudice happens in the mind, for example thinking a new pupil will be rude because of their accent. Discrimination is acting on it, like refusing to let them join your group. The law can punish discrimination but cannot control thoughts, which is why education matters too."}, {"h": "Rights, freedom and the law", "b": "The Universal Declaration of Human Rights (1948) says everyone has rights such as freedom of religion and free speech. In the UK, people can follow any religion or none, as long as they do not break the law or harm others. Freedom of speech has limits: for example, stirring up religious hatred is illegal."}, {"h": "Sexism and positive discrimination", "b": "Sexism is prejudice or discrimination because of someone's sex. Many Christians and Muslims believe men and women are equal in worth, though some believe they have different roles; for example, the Church of England has had women bishops since 2015, while the Catholic Church only ordains men as priests. Positive discrimination means treating a group more favourably to make up for past unfairness, such as ramps for wheelchair users. Some see it as fair, others feel it is unfair to people who miss out."}], "qs": [["What is prejudice?", ["Unfairly judging someone before knowing them", "Treating someone unfairly by your actions", "A law that protects people's rights", "Choosing the best person for a job"], "Prejudice is an attitude or thought, not an action."], ["What is discrimination?", ["Acting against someone because of prejudice", "Having an unfair thought about someone", "Giving to charity", "Asking God for forgiveness"], "Discrimination is the action that can come from prejudice."], ["Which UK law protects people from discrimination at work and in services?", ["The Equality Act 2010", "The Divorce Reform Act 1969", "The Human Rights Act 1965", "The Race Act 1900"], "The Equality Act 2010 brought anti-discrimination laws together in Great Britain."], ["What is sexism?", ["Prejudice or discrimination because of someone's sex", "Prejudice because of someone's religion", "Prejudice because of someone's age", "Treating everyone exactly the same"], "Sexism is unfair treatment based on whether someone is male or female."], ["Which Christian teaching is often used to show all people are equal?", ["Humans are made in the image of God", "God created only one nation", "People should keep apart from others", "Only priests are made by God"], "Genesis 1:27 says humans are made in God's image, so all have equal worth."], ["What does the Qur'an say about why God made different nations and tribes?", ["So that people may know one another", "So that one tribe could rule the rest", "So that people would stay apart", "So that wars could be won"], "Surah 49:13 teaches diversity is so people can learn about each other."], ["What is positive discrimination?", ["Treating a group more favourably to correct unfairness", "Treating everyone badly", "Ignoring discrimination", "Punishing people who are prejudiced"], "Positive discrimination gives an advantage to a group that has faced disadvantage."], ["In the UK, religious freedom means people can:", ["Follow any religion, or none, within the law", "Only follow the Church of England", "Ignore laws if their religion says so", "Never talk about their beliefs"], "UK law protects the right to hold and practise beliefs, provided others are not harmed."], ["Which document from 1948 lists rights for all people?", ["The Universal Declaration of Human Rights", "The Magna Carta", "The Equality Act", "The Ten Commandments"], "The UN adopted the Universal Declaration of Human Rights in 1948."], ["Which is the most balanced evaluation of positive discrimination?", ["It can help fairness but may feel unfair to others", "It is always completely fair to everyone", "No religious person has any view on it", "It is the same thing as prejudice"], "A good evaluation weighs both sides instead of giving only one view."]], "bonus": ["What does 'equality' mean?", ["Everyone has the same worth and fair treatment", "Everyone must look the same", "Some people matter more than others", "Only adults have rights"], "Equality means everyone is valued equally and treated fairly."]}, {"ht": "Aut2", "t": "Wealth, poverty and charity", "intro": "This topic explores why some people are rich and others are poor, and what Christians and Muslims believe about using money well. It matters because poverty affects millions of people, and many religious and non-religious people work hard to help.", "how": ["Know the difference between wealth (having plenty) and poverty (lacking basic needs).", "Learn reasons for inequality, such as unemployment, low pay, debt, war and natural disasters.", "Learn key duties: Christian tithing and Muslim zakah and sadaqah.", "Name a religious charity for each religion, such as Christian Aid and Islamic Relief.", "Explain the difference between short-term aid and long-term development."], "example": {"q": "Explain two ways religious believers help people living in poverty. (4 marks)", "steps": ["First way: Muslims pay zakah, 2.5% of their savings above a set amount, to help the poor.", "Develop it: zakah is one of the Five Pillars, so it is a duty to Allah, not just a choice.", "Second way: Christians support charities such as Christian Aid, which help communities grow food and earn a living.", "Develop it: this follows the Parable of the Sheep and the Goats, where helping those in need is helping Jesus."], "a": "Muslims give zakah and Christians support charities, both because their faith teaches care for the poor."}, "walk": [{"h": "Why wealth is unequal", "b": "Wealth is not shared evenly, within the UK or across the world. Causes include low wages, unemployment, debt, poor education, war and disasters like drought. For example, a family that loses its crops to drought may have to borrow money and then struggle to pay it back."}, {"h": "Exploitation of the poor", "b": "Exploitation means taking unfair advantage of someone. Examples include paying very low wages, charging very high interest on loans, and people trafficking. Islam forbids riba (charging interest), and Christians often support fair trade so farmers get a fair price."}, {"h": "Religious duties to give", "b": "Many Christians tithe, giving about a tenth of their income, and the Bible warns that 'the love of money is the root of all evil' (1 Timothy 6:10). Muslims give zakah (compulsory, 2.5% of savings) and sadaqah (voluntary giving). Non-religious people also give, for example through Oxfam, because they believe in fairness and human dignity."}], "qs": [["What is poverty?", ["Lacking the money for basic needs like food and shelter", "Having a lot of money", "Choosing not to buy luxuries", "Giving money to charity"], "Poverty means not having enough to meet basic needs."], ["What percentage of savings above a set amount do Muslims give as zakah?", ["2.5%", "10%", "25%", "50%"], "Zakah is 2.5% of savings above the nisab (minimum amount)."], ["What is tithing?", ["Giving about a tenth of income, often to the church", "Giving 2.5% of savings", "Borrowing money from a bank", "Fasting during Lent"], "A tithe traditionally means a tenth (10%)."], ["What is sadaqah?", ["Voluntary giving or good deeds in Islam", "The compulsory charity pillar of Islam", "A Christian prayer for the poor", "Interest charged on a loan"], "Sadaqah is extra, voluntary charity on top of zakah."], ["Which charity is a Muslim charity?", ["Islamic Relief", "Christian Aid", "CAFOD", "Tearfund"], "Islamic Relief is a Muslim aid charity; the others are Christian."], ["Which is an example of exploiting the poor?", ["Paying workers far less than a fair wage", "Giving food to a food bank", "Paying the minimum wage or more", "Buying fair trade bananas"], "Exploitation means taking unfair advantage of people who have few choices."], ["Why do many Muslims avoid loans that charge interest?", ["Islam forbids riba, which can trap the poor in debt", "Interest is only banned on Fridays", "The Qur'an says banks are holy", "Muslims are not allowed to use money"], "Riba (interest) is forbidden because it can exploit borrowers."], ["In the Parable of the Sheep and the Goats, helping the hungry is like:", ["Helping Jesus himself", "Breaking a religious law", "Wasting your money", "Becoming a priest"], "Jesus says whatever you did for the least of these, you did for me (Matthew 25)."], ["What is the difference between emergency aid and long-term aid?", ["Emergency aid helps now; long-term aid builds a better future", "There is no difference", "Long-term aid is only food parcels", "Emergency aid lasts for many years"], "Short-term aid meets urgent needs; long-term aid helps people become self-sufficient."], ["Which is the best evaluation of 'Charity solves poverty'?", ["Charity helps, but low pay and debt also need fair laws", "Charity is pointless in every case", "Only religious people can end poverty", "Poverty cannot be helped at all"], "A balanced answer shows charity helps but deeper causes need wider change too."]], "bonus": ["What is the main difference between a need and a want?", ["A need is essential to live; a want is nice to have", "A want is more important than a need", "They mean exactly the same thing", "A need is always expensive"], "Needs like food and shelter are essential; wants are extras."]}, {"ht": "Spr1", "t": "Denominations and the nature of God", "intro": "Christians and Muslims share some beliefs about God but understand God in different ways, and each religion has different groups called denominations. Knowing these key beliefs is the foundation for the whole Beliefs paper.", "how": ["Christianity has three main branches: Catholic, Orthodox and Protestant.", "Islam has two main branches: Sunni (about 85–90%) and Shi'a (about 10–15%).", "Learn the key words: omnipotent, omniscient, benevolent, transcendent and immanent.", "Christians believe in the Trinity; Muslims believe in Tawhid, the strict oneness of God.", "Back up each belief with a teaching or example."], "example": {"q": "Explain two Christian beliefs about the nature of God. (4 marks)", "steps": ["Belief one: God is omnipotent, meaning all-powerful.", "Develop it: the Bible shows this in the creation story, where God creates the world by speaking.", "Belief two: God is the Trinity: one God in three persons, the Father, the Son and the Holy Spirit.", "Develop it: Christians say the Nicene Creed, which states belief in Father, Son and Holy Spirit."], "a": "Christians believe God is all-powerful and is one God in three persons (the Trinity)."}, "walk": [{"h": "Denominations explained", "b": "A denomination is a branch of a religion with its own traditions. In Christianity, the split between Orthodox and Catholic Churches came in 1054, and Protestant churches such as Anglican, Methodist and Baptist began after the Reformation in the 1500s. In Islam, Sunni and Shi'a Muslims split over who should lead after the Prophet Muhammad died; Shi'a Muslims believe it should have been his cousin and son-in-law Ali."}, {"h": "God's key qualities", "b": "Omnipotent means all-powerful, omniscient means all-knowing, and benevolent means all-loving or all-good. Transcendent means God is beyond and outside the universe, while immanent means God is close and active in the world. For example, a Muslim might say God is transcendent because nothing is like Him, but also immanent because the Qur'an says He is closer than our jugular vein (50:16)."}, {"h": "Trinity and Tawhid", "b": "Christians believe in one God in three persons: Father, Son (Jesus) and Holy Spirit. Muslims believe in Tawhid, that God (Allah) is one and has no partners or equals. Because of this, Muslims believe Jesus was a great prophet but not God, which is an important difference between the two faiths."}], "qs": [["What does omnipotent mean?", ["All-powerful", "All-knowing", "All-loving", "Everywhere at once"], "Omni means all and potent means powerful."], ["What does omniscient mean?", ["All-knowing", "All-powerful", "All-loving", "Beyond the universe"], "Omniscient comes from Latin for knowing all things."], ["What does benevolent mean?", ["All-loving or all-good", "All-powerful", "All-knowing", "Unchanging"], "Benevolent describes God's love and goodness."], ["What is Tawhid?", ["The Muslim belief that God is one", "A Christian sacrament", "The Muslim pilgrimage", "The Christian Trinity"], "Tawhid is the oneness of Allah, the most important Muslim belief."], ["What is the Trinity?", ["One God as Father, Son and Holy Spirit", "Three separate gods", "Three Christian holy books", "Three Muslim prophets"], "Christians believe in one God in three persons, not three gods."], ["Which are the two main denominations of Islam?", ["Sunni and Shi'a", "Catholic and Protestant", "Orthodox and Anglican", "Sunni and Methodist"], "Most Muslims are Sunni; a minority are Shi'a."], ["Which is NOT one of the three main branches of Christianity?", ["Shi'a", "Catholic", "Orthodox", "Protestant"], "Shi'a is a branch of Islam, not Christianity."], ["What does it mean to say God is immanent?", ["God is close and active in the world", "God is far beyond the universe", "God does not exist", "God is only in heaven"], "Immanent means God is present within creation and in people's lives."], ["Why do Shi'a Muslims believe Ali should have led after Muhammad?", ["He was Muhammad's chosen family member", "He was elected by Christians", "He wrote the Qur'an", "He was the first prophet"], "Shi'a Muslims believe Muhammad chose Ali, his cousin and son-in-law."], ["Why do Muslims not accept that Jesus is God?", ["It would go against Tawhid, God's oneness", "They do not believe Jesus existed", "They think Jesus was an angel", "The Bible says he was not God"], "Muslims respect Jesus as a prophet, but Tawhid means God has no partner or son."]], "bonus": ["What is a monotheistic religion?", ["A religion that believes in one God", "A religion with many gods", "A religion with no gods", "A religion with only one follower"], "Mono means one and theism means belief in God; both Christianity and Islam are monotheistic."]}, {"ht": "Spr2", "t": "Evil, creation and prophets", "intro": "This topic asks why a loving, all-powerful God would allow suffering, and looks at what Christians and Muslims believe about creation, Jesus and the prophets. These are some of the biggest questions people ask about religion.", "how": ["The inconsistent triad says these three cannot all be true: God is omnipotent, God is benevolent, and evil exists.", "Moral evil is caused by humans (like theft); natural evil comes from nature (like earthquakes).", "Learn religious responses: free will, suffering as a test, and suffering helping people grow.", "Know both creation accounts: Genesis in the Bible and the Qur'an's teachings.", "Muslims believe Muhammad is the final prophet; Christians believe Jesus is the Son of God."], "example": {"q": "Explain the inconsistent triad and one religious response to it.", "steps": ["State the three ideas: God is all-powerful, God is all-loving, and evil exists.", "Explain the problem: if God is all-loving He would want to stop evil, and if all-powerful He could.", "So, critics argue, either God is not both of these, or God does not exist.", "Response: many believers say God gave humans free will, and free will means people can choose evil."], "a": "The triad suggests God and evil cannot both exist, but believers often answer that evil comes from human free will."}, "walk": [{"h": "The problem of evil", "b": "The inconsistent triad is linked to ancient Greek thinker Epicurus and modern philosopher J. L. Mackie. It says that if God were all-powerful and all-loving, there would be no evil, yet evil exists. Some atheists use this to argue there is no God, especially because of natural evil like disease, which no human causes."}, {"h": "How believers respond", "b": "Many Christians and Muslims say free will explains moral evil: God lets us choose, so we can choose wrongly. Some Christians say suffering helps people grow kinder and stronger, an idea linked to Irenaeus. Many Muslims see life as a test, and the Qur'an says God will test people with fear, hunger and loss (2:155)."}, {"h": "Creation and key figures", "b": "Genesis 1 describes God creating the world in six days and resting on the seventh. The Qur'an says Allah created the heavens and earth in six days or periods, and Adam was made from clay. Christians believe Jesus is the Son of God who died and rose again; Muslims believe Muhammad received the Qur'an from the angel Jibril (Gabriel) starting in 610 CE and is the Seal of the Prophets, the last one."}], "qs": [["Which is an example of natural evil?", ["An earthquake", "A burglary", "Bullying", "A war"], "Natural evil is suffering caused by nature, not by human choices."], ["Which is an example of moral evil?", ["Stealing from a shop", "A flood", "A volcano erupting", "A disease spreading naturally"], "Moral evil is caused by human choices."], ["Which three ideas make up the inconsistent triad?", ["God is all-powerful, all-loving, and evil exists", "God is one, God is three, God is good", "Heaven, hell and earth", "Prayer, fasting and charity"], "The triad claims these three statements cannot all be true together."], ["Who do Muslims believe was the final prophet?", ["Muhammad", "Adam", "Ibrahim", "Isa (Jesus)"], "Muhammad is called the Seal of the Prophets."], ["Who do Muslims believe was the first prophet?", ["Adam", "Muhammad", "Musa (Moses)", "Nuh (Noah)"], "Muslims believe Adam was both the first human and the first prophet."], ["What does Risalah mean in Islam?", ["Prophethood: God's messages sent through prophets", "The Muslim pilgrimage to Makkah", "Charity paid to the poor", "The day of judgement"], "Risalah is the belief that God communicates through chosen prophets."], ["In Genesis 1, what does God do on the seventh day?", ["Rests", "Creates humans", "Creates light", "Floods the earth"], "God finishes creation in six days and rests on the seventh."], ["What is the free will response to the problem of evil?", ["God lets humans choose, so some choose evil", "Evil is not real", "God enjoys suffering", "Only animals cause evil"], "Free will explains moral evil as the result of human choices."], ["Christians believe that Jesus:", ["Is the Son of God, who died and rose again", "Was the final prophet of Islam", "Wrote the book of Genesis", "Was only an ordinary teacher"], "Christians believe in the incarnation, crucifixion and resurrection of Jesus."], ["Why do some think natural evil is harder to explain than moral evil?", ["Free will cannot explain disasters no human caused", "Natural evil never hurts anyone", "Natural evil is always deserved", "Religions never discuss natural evil"], "Free will explains human wrongdoing, but not earthquakes or disease."]], "bonus": ["What does a 'prophet' mean in religion?", ["A person who brings God's message to people", "A person who earns a lot of money", "A type of angel", "A building for worship"], "Prophets are messengers believed to speak for God."]}, {"ht": "Sum1", "t": "Crime, punishment aims, forgiveness", "intro": "This topic looks at why people commit crimes, whether people are good or evil, what punishment should achieve, and why forgiveness matters. It helps you understand how religious teachings shape views about justice.", "how": ["A crime is breaking the law; a sin is breaking a religious rule. Some actions are both.", "Learn causes of crime: poverty, upbringing, addiction, mental illness, greed, hate and opposing an unjust law.", "Remember the four aims of punishment: retribution, deterrence, reformation and protection.", "Christians and Muslims both teach forgiveness, but forgiveness does not always mean no punishment.", "Use examples and teachings to support each point."], "example": {"q": "A man steals food to feed his hungry children. Which cause of crime is this, and how might a Christian respond?", "steps": ["Identify the cause: this is poverty, because he cannot afford food.", "Note that the crime is still wrong, but the reason affects how people judge it.", "A Christian might think of Jesus' teaching to care for those in need.", "So they may want him punished fairly but also helped, for example through a food bank."], "a": "The cause is poverty, and a Christian would likely want justice with compassion and practical help."}, "walk": [{"h": "Why crime happens", "b": "People commit crimes for many reasons, such as poverty, a hard upbringing, addiction or greed. Some break laws they think are unfair, like people in history who protested peacefully against unjust laws. A hate crime is a crime targeting someone because of their race, religion, disability, sexuality or gender identity."}, {"h": "Good and evil intentions", "b": "Many Christians believe humans are born with a tendency to do wrong, linked to the idea of original sin, but can choose good. Muslims believe people are born good (in fitrah) and can be led astray. Most people think intentions matter: hurting someone by accident is judged differently from hurting them on purpose."}, {"h": "Four aims of punishment", "b": "Retribution means making the criminal pay back for what they did. Deterrence means putting people off committing crime. Reformation means helping the offender change and become law-abiding, and protection means keeping the public safe. For example, a prison education course aims to reform, while a long sentence for a dangerous person aims to protect."}], "qs": [["What is a crime?", ["An action that breaks the law", "An action that breaks a religious rule only", "Any bad thought", "A punishment given by a judge"], "A crime is against the law of the country."], ["Which aim of punishment is about putting people off committing crime?", ["Deterrence", "Retribution", "Reformation", "Protection"], "Deterrence aims to discourage the offender and others from crime."], ["Which aim of punishment is about helping the offender change?", ["Reformation", "Retribution", "Deterrence", "Protection"], "Reformation means reforming the offender into a law-abiding person."], ["Which aim of punishment means 'getting back' at the criminal?", ["Retribution", "Reformation", "Deterrence", "Forgiveness"], "Retribution makes the criminal pay for the harm they caused."], ["Keeping a violent criminal away from the public is mainly:", ["Protection", "Reformation", "Retribution", "Forgiveness"], "Protection keeps society safe from dangerous offenders."], ["What is a hate crime?", ["A crime targeting someone because of who they are", "Any crime done in anger", "A crime that hurts nobody", "A crime against property only"], "Hate crimes target people for their race, religion, disability, sexuality or gender identity."], ["How many times did Jesus tell Peter to forgive (in the King James Bible)?", ["Seventy times seven", "Seven times", "Once", "Three times"], "Matthew 18:22 means forgiveness should be without limit."], ["Which Muslim belief about human nature means people are born good?", ["Fitrah", "Original sin", "Zakah", "Riba"], "Fitrah is the natural, pure state Muslims believe everyone is born in."], ["Can someone forgive a criminal and still want them punished?", ["Yes, forgiveness and justice can go together", "No, forgiving means no punishment at all", "Only judges can forgive", "Forgiveness is illegal in the UK"], "Many believers forgive personally but still support fair justice."], ["Which is the strongest argument that reformation is the best aim?", ["A reformed offender is less likely to reoffend", "It makes criminals suffer the most", "It costs nothing at all", "It ignores the victim completely"], "Reformation tackles the reasons for crime, reducing future offending."]], "bonus": ["Which word means a person's ideas about what is right and wrong?", ["Morality", "Geography", "Democracy", "Economy"], "Morality is about deciding what is right and wrong."]}, {"ht": "Sum2", "t": "Prisons and capital punishment", "intro": "This topic looks at how offenders are treated, including prisoners, young offenders, and the debate about the death penalty. Religious and non-religious people disagree strongly about some of these issues, so you need to know several viewpoints.", "how": ["Know the main punishments in the UK: prison, community service, fines and suspended sentences.", "Parole is early release from prison under supervision and conditions.", "Corporal punishment means physical punishment; it is banned in all UK schools.", "Capital punishment (the death penalty) was abolished for murder in Great Britain in 1965 (made permanent in 1969).", "Give arguments for and against the death penalty, with Christian, Muslim and non-religious views."], "example": {"q": "Give two arguments against capital punishment.", "steps": ["Argument one: an innocent person might be executed, and the mistake cannot be undone.", "Example: Timothy Evans was hanged in 1950 and later given a pardon in 1966.", "Argument two: many Christians believe only God should take life, and that people can always be reformed.", "You could add Amnesty International's view that it breaks the human right to life."], "a": "It risks killing innocent people, and many believe life is sacred and every person can change."}, "walk": [{"h": "Prisons and parole", "b": "Prisoners lose their freedom but keep basic human rights, such as food, safety and medical care. Many Christians, including the Quaker Elizabeth Fry in the 1800s, campaigned for prisoners to be treated humanely. Parole lets some prisoners leave early if they keep strict rules, which can help them rebuild their lives."}, {"h": "Corporal punishment and young offenders", "b": "Corporal punishment was banned in UK state schools in 1987 and later in private schools too. The age of criminal responsibility in England and Wales is 10. Young offenders are usually dealt with differently from adults, often with a focus on reformation, through youth courts and special institutions."}, {"h": "Capital punishment debate", "b": "Supporters say the death penalty deters and is fair retribution for murder; some Muslims point out that Shari'ah law allows it for murder, though the victim's family may choose forgiveness or compensation instead. Opponents say innocent people may die, it does not clearly deter, and life is sacred. The Catholic Church teaches it is not acceptable, and Amnesty International, founded in 1961, campaigns against it everywhere."}], "qs": [["What is capital punishment?", ["The death penalty", "A fine", "Community service", "Early release from prison"], "Capital punishment is when the state executes a criminal."], ["What is parole?", ["Early release from prison under supervision", "A prison sentence for life", "A fine paid to the victim", "A type of corporal punishment"], "Parole lets prisoners out early if they keep strict conditions."], ["What is corporal punishment?", ["Physical punishment, such as hitting", "A punishment for soldiers only", "A punishment using fines", "Locking someone in prison"], "Corporal comes from the Latin word for body."], ["What is the age of criminal responsibility in England and Wales?", ["10", "14", "16", "18"], "Children aged 10 and over can be charged with a crime in England and Wales."], ["When was the death penalty for murder abolished in Great Britain?", ["1965 (made permanent in 1969)", "1900", "1998 for the first time", "It has never been abolished"], "The Murder Act 1965 suspended it, and it was made permanent in 1969."], ["What does Amnesty International campaign for?", ["Human rights, including ending the death penalty", "More prisons around the world", "Lower taxes for businesses", "Banning religion"], "Amnesty International, founded in 1961, campaigns for human rights worldwide."], ["Which is an argument FOR capital punishment?", ["It may deter others from committing murder", "Innocent people could be executed", "Life is sacred", "It stops criminals reforming"], "Supporters often argue it deters crime and gives retribution."], ["In Shari'ah law, what can a murder victim's family choose instead of execution?", ["Forgiveness or compensation", "A longer prison sentence only", "Nothing at all", "Exile from the country"], "The family may forgive or accept compensation (diyah) instead."], ["Which Christian campaigned in the 1800s for better treatment of prisoners?", ["Elizabeth Fry", "Florence Nightingale", "Henry VIII", "Charles Darwin"], "Elizabeth Fry, a Quaker, worked to improve conditions in prisons."], ["Which is the best reason the Timothy Evans case is used in debates?", ["It shows an innocent person could be executed", "It proves the death penalty always works", "It shows prisons are too comfortable", "It is about corporal punishment"], "Evans was executed in 1950 and later pardoned, showing mistakes cannot be undone."]], "bonus": ["What is a 'right' in human rights?", ["Something every person is entitled to", "A reward only for good behaviour", "A rule only for adults", "A punishment from the law"], "Human rights belong to everyone just because they are human."]}]}, {"id": "history", "name": "History", "board": "Pearson Edexcel", "weeks": [{"ht": "Aut1", "t": "Elizabeth's accession and religious settlement", "intro": "In November 1558 Elizabeth I became queen of a country that was in debt, divided over religion and threatened by France. Her religious settlement of 1559 created the Church of England that still exists today, so this topic explains how she tried to unite the country.", "how": ["Learn the problems Elizabeth faced in 1558: legitimacy, gender, marriage, debt, religion and foreign threats.", "Remember the three parts of the settlement: the Act of Supremacy, the Act of Uniformity and the Royal Injunctions (all 1559).", "Explain the settlement as a 'middle way' between Protestant beliefs and some Catholic traditions.", "Always back up points with a specific detail, such as a date, a name or a law.", "For 'explain why' questions, give two or three clear reasons and link each one back to the question."], "example": {"q": "Explain why Elizabeth faced problems when she became queen in 1558.", "steps": ["Pick a first reason: many Catholics saw her as illegitimate because they did not accept Henry VIII's marriage to Anne Boleyn.", "Add a second reason: the Crown was badly in debt, around £300,000, after Mary I's wars.", "Add a third reason: England was weak abroad, having lost Calais to France in 1558, and France had links to Scotland.", "Link each reason to why it made her position insecure."], "a": "Elizabeth faced problems because her legitimacy was questioned, the Crown was in debt and England was weak against France and Scotland."}, "walk": [{"h": "England in 1558", "b": "Elizabeth was 25, unmarried and Protestant, ruling a country that had just switched back to Catholicism under Mary I. Many people expected a queen to marry and let her husband help rule. For example, her advisers worried that without an heir there could be a civil war over who came next."}, {"h": "The 1559 settlement", "b": "The Act of Supremacy made Elizabeth Supreme Governor of the Church of England, a softer title than 'Supreme Head'. The Act of Uniformity set out how churches should look and worship, using a new Book of Common Prayer. The Royal Injunctions gave clergy detailed instructions, such as preaching sermons regularly."}, {"h": "How people reacted", "b": "Most ordinary people accepted the settlement. People who refused to attend church, called recusants, could be fined one shilling a week. Some bishops refused the Oath of Supremacy and lost their jobs, while some Puritans felt the settlement kept too many Catholic features, such as special clothes called vestments."}], "qs": [["In which year did Elizabeth I become queen?", ["1558", "1547", "1559", "1588"], "Elizabeth became queen in November 1558 when her half-sister Mary I died."], ["What title did the Act of Supremacy give Elizabeth?", ["Supreme Governor of the Church of England", "Supreme Head of the Church of England", "Pope of England", "Defender of Rome"], "She chose 'Governor' rather than 'Head', which was less offensive to Catholics and to those who felt a woman should not head the Church."], ["Which Act set out how church services should be held?", ["The Act of Uniformity", "The Act of Supremacy", "The Poor Law", "The Act of Union"], "The Act of Uniformity of 1559 set the appearance of churches and the form of services."], ["Which book did the 1559 settlement require churches to use?", ["The Book of Common Prayer", "The Latin Missal", "The Bible in Latin only", "The Book of Martyrs"], "The Act of Uniformity required the Book of Common Prayer to be used in all churches."], ["What was the fine for not attending church under the 1559 settlement?", ["One shilling per week", "One pound per day", "Twenty pounds per year", "There was no fine"], "Recusants were fined one shilling a week, which was a lot for poor people but small for the rich."], ["Why did some Catholics see Elizabeth as illegitimate?", ["They did not accept Henry VIII's marriage to Anne Boleyn", "She was born in France", "She was not related to Henry VIII", "She had been married before"], "The Pope never accepted Henry's divorce from Catherine of Aragon, so Catholics saw his marriage to Anne Boleyn as invalid."], ["Which English territory in France was lost in 1558?", ["Calais", "Normandy", "Paris", "Brittany"], "Calais, England's last possession in France, was lost in January 1558 under Mary I."], ["Who became Elizabeth's Secretary of State and most trusted adviser in 1558?", ["Sir William Cecil", "Sir Francis Drake", "Thomas Cromwell", "Sir Walter Raleigh"], "William Cecil was appointed Secretary of State and served Elizabeth for about 40 years."], ["What was the 'vestment controversy' about?", ["Whether clergy should wear special clothing", "How much tax churches paid", "Who could become a bishop", "Whether churches could have bells"], "Puritans objected to clergy wearing special vestments, seeing them as too Catholic."], ["Why is the settlement often called a 'middle way'?", ["It was Protestant but kept some Catholic features", "It was fully Catholic", "It banned all religion", "It let each town choose its own religion"], "The settlement was Protestant in belief but kept features like bishops, vestments and some decorations to reassure Catholics."]], "bonus": ["Who was Elizabeth I's father?", ["Henry VIII", "Edward VI", "Henry VII", "James I"], "Elizabeth was the daughter of Henry VIII and his second wife, Anne Boleyn."]}, {"ht": "Aut2", "t": "Challenges to Elizabeth at home and abroad", "intro": "Between 1558 and 1588 Elizabeth faced threats from Puritans, Catholics, plots around Mary, Queen of Scots, and finally war with Spain. Learning how she survived shows how her government, especially Walsingham's spies, protected her.", "how": ["Put the key events in order: Mary arrives 1568, Northern Revolt 1569, Ridolfi 1571, Throckmorton 1583, Babington 1586, Mary executed 1587, Armada 1588.", "Know why Mary, Queen of Scots was a threat: she was a Catholic with a strong claim to the English throne.", "Explain how Walsingham used spies, code-breaking and agents to uncover plots.", "For the Armada, explain reasons for England's victory using English strengths, Spanish mistakes and luck (the weather).", "Remember that Puritans were a challenge too, wanting the Church to be more Protestant."], "example": {"q": "Explain why the Babington Plot of 1586 led to the execution of Mary, Queen of Scots.", "steps": ["Describe the plot: Catholics planned to kill Elizabeth and put Mary on the throne with foreign help.", "Explain Walsingham's role: he intercepted the coded letters hidden in beer barrels and had them decoded.", "Show that Mary wrote back approving the plan, so there was clear evidence against her.", "Conclude that this proof finally persuaded Elizabeth to sign the death warrant; Mary was executed in February 1587."], "a": "Walsingham's agents caught Mary approving a plot to kill Elizabeth, giving the evidence needed to execute her in 1587."}, "walk": [{"h": "Mary and the Northern Revolt", "b": "Mary fled from Scotland to England in 1568 and Elizabeth kept her under house arrest. In 1569 the Catholic Earls of Northumberland and Westmorland rebelled, held a Catholic Mass in Durham Cathedral and hoped to free Mary. The revolt collapsed, and in 1570 the Pope excommunicated Elizabeth, making Catholics a bigger worry."}, {"h": "Plots and Walsingham", "b": "The Ridolfi Plot (1571) planned a Spanish invasion and Mary's marriage to the Duke of Norfolk, who was executed in 1572. The Throckmorton Plot (1583) involved a French invasion led by the Duke of Guise. Sir Francis Walsingham, Elizabeth's spymaster, used informers and code-breakers to uncover these plots, including Babington in 1586."}, {"h": "War with Spain", "b": "Relations with Spain grew worse because of religion, English privateers attacking Spanish ships and English help for Dutch Protestant rebels in the Treaty of Nonsuch (1585). In 1587 Drake attacked Cádiz, delaying the invasion. In 1588 English fireships broke the Armada's crescent formation at Calais, the English won at Gravelines and storms wrecked many Spanish ships on the way home."}], "qs": [["In which year was the Spanish Armada defeated?", ["1588", "1558", "1569", "1603"], "The Spanish Armada sailed against England and was defeated in 1588."], ["Who was Elizabeth's spymaster?", ["Sir Francis Walsingham", "Sir Francis Drake", "Robert Dudley", "Anthony Babington"], "Walsingham ran a network of spies and code-breakers to protect Elizabeth."], ["Why was Mary, Queen of Scots a threat to Elizabeth?", ["She was a Catholic with a claim to the English throne", "She led the English navy", "She was a Puritan leader", "She controlled Parliament"], "Many Catholics saw Mary as the rightful queen, so she became a focus for plots."], ["What did Puritans want?", ["A purer, more Protestant Church without Catholic features", "A return to Catholicism", "The Pope to run the Church", "No church services at all"], "Puritans felt the settlement kept too many Catholic features like vestments and crucifixes."], ["Which two nobles led the Revolt of the Northern Earls in 1569?", ["Northumberland and Westmorland", "Norfolk and Leicester", "Essex and Kent", "Cecil and Walsingham"], "The Earls of Northumberland and Westmorland led the revolt, hoping to restore Catholicism and free Mary."], ["What did the Pope's bull of 1570 do?", ["Excommunicated Elizabeth", "Made Elizabeth head of the Catholic Church", "Ordered Mary to be executed", "Declared war on Spain"], "The papal bull excommunicated Elizabeth and told Catholics they need not obey her."], ["Which plot of 1583 involved a planned French invasion led by the Duke of Guise?", ["The Throckmorton Plot", "The Ridolfi Plot", "The Babington Plot", "The Gunpowder Plot"], "Francis Throckmorton was arrested in 1583 after plotting an invasion by the Duke of Guise."], ["When was Mary, Queen of Scots executed?", ["1587", "1568", "1572", "1588"], "Mary was executed at Fotheringhay Castle in February 1587 after the Babington Plot."], ["What did the Treaty of Nonsuch (1585) agree?", ["English troops would help the Dutch rebels against Spain", "England and Spain would make peace", "Mary would marry Philip II", "France would join England's navy"], "England sent soldiers under the Earl of Leicester to support the Dutch Protestant rebels."], ["Which tactic broke the Armada's crescent formation off Calais?", ["English fireships", "A Spanish mutiny", "English cannons fired from Dover", "A Dutch ambush on land"], "English fireships caused the Spanish to cut their anchors and scatter, before the Battle of Gravelines."]], "bonus": ["What is the main difference between Catholics and Protestants in Tudor times?", ["Catholics accept the Pope as Church leader; Protestants do not", "Protestants accept the Pope; Catholics do not", "Catholics do not believe in God", "There is no difference"], "Catholics follow the Pope in Rome as head of the Church, while Protestants rejected his authority."]}, {"ht": "Spr1", "t": "Origins of the Cold War 1941–49", "intro": "The USA, USSR and Britain fought together against Hitler, but after 1945 the USA and USSR became rivals in a Cold War. This topic explains how a wartime alliance turned into a divided Europe by 1949.", "how": ["Learn the two ideologies: capitalism (USA) and communism (USSR).", "Know what was agreed and argued about at Tehran (1943), Yalta (February 1945) and Potsdam (July–August 1945).", "Explain how the atomic bomb and the Long and Novikov telegrams increased mistrust.", "Put the key events in order: Truman Doctrine and Marshall Plan (1947), Berlin Blockade (1948–49), NATO (1949).", "In narrative questions, show how one event led to another, not just what happened."], "example": {"q": "Write a short account of how the Berlin Blockade came about in 1948.", "steps": ["Start with the division of Germany and Berlin into four zones after 1945.", "Explain that Britain and the USA joined their zones (Bizonia, then Trizonia with France) and planned to rebuild West Germany.", "Add that in June 1948 a new currency, the Deutschmark, was introduced in the western zones.", "Explain that Stalin saw this as a threat and cut off road, rail and canal links to West Berlin in June 1948."], "a": "Stalin blockaded West Berlin in June 1948 because the West was uniting and strengthening its zones with a new currency."}, "walk": [{"h": "Allies with differences", "b": "The USA was capitalist and democratic, with free elections and private businesses. The USSR was communist, with one party and the state owning industry. They worked together in the Grand Alliance only because they shared an enemy, Nazi Germany."}, {"h": "Conferences and mistrust", "b": "At Yalta they agreed to divide Germany into four zones and Stalin promised free elections in Eastern Europe. By Potsdam, Roosevelt had died, Truman was more suspicious of Stalin, and the USA had tested the atomic bomb, which it used on Hiroshima in August 1945. The Long Telegram (1946) warned the USA that the USSR wanted to expand, and the Novikov Telegram said the USA wanted world domination."}, {"h": "Two camps form", "b": "Stalin set up communist satellite states in Eastern Europe. In 1947 the Truman Doctrine promised to contain communism, and the Marshall Plan offered billions of dollars of aid to rebuild Europe. The USSR replied with Cominform and Comecon, the Berlin airlift beat the blockade by May 1949, and NATO was formed in April 1949."}], "qs": [["Which countries made up the Grand Alliance?", ["USA, USSR and Britain", "USA, France and Germany", "USSR, China and Japan", "Britain, France and Italy"], "The Grand Alliance was the wartime alliance of the USA, the USSR and Britain against Nazi Germany."], ["Which ideology did the USSR follow?", ["Communism", "Capitalism", "Fascism", "Monarchy"], "The USSR was a communist state where the government owned industry and there was one party."], ["What was agreed about Germany at Yalta in February 1945?", ["It would be divided into four zones", "It would join the USSR", "It would be given to France", "It would stay united under Hitler"], "The Allies agreed to divide Germany, and Berlin, into four zones of occupation."], ["Who led the USA at the Potsdam Conference?", ["Truman", "Roosevelt", "Eisenhower", "Kennedy"], "Roosevelt died in April 1945, so Truman represented the USA at Potsdam."], ["How did the atomic bomb increase tension?", ["Stalin felt the USA was trying to intimidate him", "The USSR used it on Berlin", "It was shared equally with the USSR", "It ended the Grand Alliance's trade deals"], "The USA did not share the bomb with its ally, which made Stalin suspicious and started an arms race."], ["Who wrote the Long Telegram in 1946?", ["George Kennan", "Nikolai Novikov", "Winston Churchill", "Harry Truman"], "George Kennan, an American diplomat in Moscow, warned that the USSR wanted to spread communism."], ["What did the Truman Doctrine (1947) promise?", ["To help countries resist communism", "To share the atomic bomb", "To leave Europe", "To support Stalin in Eastern Europe"], "The Truman Doctrine set out the policy of containment, starting with aid to Greece and Turkey."], ["What was the Marshall Plan?", ["American economic aid to rebuild Europe", "A Soviet plan to invade Berlin", "A peace treaty with Japan", "A plan to divide Korea"], "The Marshall Plan gave billions of dollars of aid to European countries to rebuild and resist communism."], ["How did the West respond to the Berlin Blockade?", ["By flying supplies into West Berlin", "By invading East Germany", "By building the Berlin Wall", "By giving West Berlin to Stalin"], "The Berlin airlift flew food and fuel into West Berlin until Stalin lifted the blockade in May 1949."], ["What was set up in April 1949 as a result of the Berlin Crisis?", ["NATO", "The Warsaw Pact", "Comecon", "The United Nations"], "NATO was a military alliance of Western countries who agreed to defend each other; the Warsaw Pact came later in 1955."]], "bonus": ["Which country did the Allies defeat in Europe in 1945?", ["Germany", "Italy only", "Russia", "Spain"], "Nazi Germany surrendered in May 1945, ending the Second World War in Europe."]}, {"ht": "Spr2", "t": "Elizabethan society and exploration", "intro": "Elizabethan England was a time of new schools, playhouses and daring voyages across the world. It was also a time when poverty grew, so this topic looks at how people lived, played and explored.", "how": ["Know who got an education and where: petty schools, grammar schools, and the universities of Oxford and Cambridge.", "Learn popular pastimes, from bear-baiting and football to the theatre.", "Explain why poverty increased and how laws treated the 'deserving' and 'undeserving' poor.", "Know the key voyages: Drake's circumnavigation (1577–80) and Raleigh's attempts to settle Virginia (1585 and 1587).", "Explain reasons for exploration: trade, wealth, new technology and rivalry with Spain."], "example": {"q": "Explain why Raleigh's attempts to colonise Virginia failed.", "steps": ["Give a first reason: poor planning, with settlers arriving too late to plant crops.", "Give a second reason: relations with local Native American people broke down.", "Give a third reason: supply ships were delayed because the war with Spain and the Armada kept ships in England.", "Link these together: without food or help, the colonies could not survive."], "a": "Raleigh's colonies at Roanoke failed due to poor planning, bad relations with local people and supplies delayed by the war with Spain."}, "walk": [{"h": "Education and leisure", "b": "Education was mainly for boys from wealthier families, who might go to a grammar school to learn Latin, then to Oxford or Cambridge. Girls from rich families were usually taught at home. For fun, people enjoyed hunting, bear-baiting, cockfighting and rough football, and from 1576 permanent theatres such as The Theatre opened in London."}, {"h": "The problem of the poor", "b": "Poverty grew because of rising population, bad harvests, rising prices and changes in farming like enclosure. The government saw the 'deserving poor' (old, sick, very young) as needing help, but the 'undeserving poor' or vagabonds were punished. The 1601 Poor Law made each parish responsible for its poor, paid for by a local tax called the poor rate."}, {"h": "Voyages of exploration", "b": "Better ships, maps and tools such as the astrolabe made long voyages possible. Francis Drake sailed around the world in the Golden Hind between 1577 and 1580, returning with Spanish treasure, and was knighted in 1581. Walter Raleigh sent settlers to Roanoke Island in Virginia in 1585 and 1587, but both attempts failed."}], "qs": [["Which ship did Drake sail around the world?", ["The Golden Hind", "The Mary Rose", "The Mayflower", "The Victory"], "Drake's ship, originally called the Pelican, was renamed the Golden Hind during the voyage."], ["Which two universities existed in Elizabethan England?", ["Oxford and Cambridge", "London and Manchester", "Oxford and Durham", "Cambridge and Leeds"], "Oxford and Cambridge were England's only universities in Elizabethan times."], ["Which of these was a popular Elizabethan blood sport?", ["Bear-baiting", "Tennis on grass courts", "Cricket", "Snooker"], "Bear-baiting, where dogs attacked a chained bear, was popular with rich and poor alike."], ["Who were the 'deserving poor'?", ["People who could not work, such as the old, sick or very young", "Healthy people who refused to work", "Rich merchants", "Soldiers returning from war only"], "The deserving poor were seen as genuinely unable to support themselves, so they received help."], ["Which of these was a cause of rising poverty?", ["A growing population and rising prices", "Falling food prices", "Fewer people in England", "Higher wages for everyone"], "A rising population and inflation meant wages were worth less, pushing more people into poverty."], ["What did the 1601 Poor Law do?", ["Made each parish responsible for its poor, paid for by a poor rate", "Banned all charity", "Sent all poor people to the colonies", "Gave every family free land"], "The 1601 Act for the Relief of the Poor set up a national system run by parishes."], ["When did Drake sail around the world?", ["1577–80", "1558–60", "1588–90", "1600–03"], "Drake left Plymouth in 1577 and returned in 1580, the first Englishman to circumnavigate the globe."], ["Where did Raleigh try to set up a colony?", ["Roanoke Island, Virginia", "Jamaica", "Newfoundland", "Cádiz"], "Raleigh's settlers went to Roanoke Island in 1585 and 1587, in the land named Virginia."], ["Which piece of technology helped sailors work out their position?", ["The astrolabe", "The telescope satellite", "The steam engine", "The electric compass"], "The astrolabe measured the angle of the sun or stars to help work out latitude."], ["Why did the 1587 Roanoke colony become known as the 'Lost Colony'?", ["Supply ships were delayed and the settlers had vanished by 1590", "It was captured by France", "The settlers sailed home in 1588", "It became a large city"], "The Armada delayed supply ships, and when they finally arrived in 1590 the settlers had disappeared."]], "bonus": ["What does 'circumnavigate' mean?", ["To sail all the way around the world", "To discover a new island", "To sail across one ocean", "To draw a map"], "To circumnavigate means to travel completely around something, here the whole globe."]}, {"ht": "Sum1", "t": "Cold War crises 1949–62", "intro": "In the 1950s the superpowers raced to build nuclear weapons and faced dangerous crises in Hungary, Berlin and Cuba. The Cuban Missile Crisis of 1962 was the closest the world came to nuclear war.", "how": ["Learn the arms race: the USSR tested an atomic bomb in 1949, and both sides built hydrogen bombs in the early 1950s.", "Know why the Warsaw Pact formed in 1955 and what happened in Hungary in 1956.", "Explain the Berlin refugee problem and why the Berlin Wall was built in August 1961.", "Put the Cuban events in order: Cuban Revolution (1959), Bay of Pigs (April 1961), Missile Crisis (October 1962).", "For consequence questions, explain what changed because of an event."], "example": {"q": "Explain one consequence of the building of the Berlin Wall in 1961.", "steps": ["State the consequence: the flow of refugees from East to West Germany was stopped.", "Give detail: before 1961 millions of East Germans, many of them skilled workers, had escaped through Berlin.", "Explain why it mattered: East Germany kept its workers and the USSR avoided further embarrassment.", "Add a wider point: the Wall became a symbol of the divided world."], "a": "The Berlin Wall stopped East Germans escaping to the West, ending the refugee problem but becoming a symbol of Cold War division."}, "walk": [{"h": "Arms race and alliances", "b": "The USA lost its nuclear lead when the USSR tested an atomic bomb in 1949. Both sides then built more powerful hydrogen bombs and later long-range missiles. When West Germany joined NATO in 1955, the USSR set up its own alliance, the Warsaw Pact, with its Eastern European satellite states."}, {"h": "Hungary and Berlin", "b": "In 1956 Hungary's leader Imre Nagy announced Hungary would leave the Warsaw Pact, so Khrushchev sent in Soviet tanks and crushed the uprising. Meanwhile, millions of East Germans fled to the West through Berlin. To stop this, the Berlin Wall was built overnight on 13 August 1961."}, {"h": "Cuba", "b": "Fidel Castro took power in Cuba in 1959 and grew closer to the USSR. In April 1961 a CIA-backed invasion by Cuban exiles at the Bay of Pigs failed badly. In October 1962 US spy planes found Soviet missile sites on Cuba; Kennedy ordered a naval blockade, and after thirteen tense days Khrushchev agreed to remove the missiles while the USA secretly agreed to remove its missiles from Turkey."}], "qs": [["In which year did the USSR first test an atomic bomb?", ["1949", "1945", "1955", "1962"], "The Soviet test in August 1949 ended the USA's monopoly on nuclear weapons."], ["When was the Berlin Wall built?", ["1961", "1949", "1956", "1989"], "Construction began on 13 August 1961; it was finally knocked down in 1989."], ["Who led the Cuban Revolution of 1959?", ["Fidel Castro", "Che Guevara alone", "Nikita Khrushchev", "Fulgencio Batista"], "Fidel Castro overthrew the US-friendly dictator Batista in 1959."], ["What was the Warsaw Pact?", ["A military alliance of the USSR and its satellite states", "An American aid programme", "A peace treaty ending the Cold War", "A trade deal between Cuba and the USA"], "The Warsaw Pact of 1955 was the communist answer to NATO."], ["What triggered the formation of the Warsaw Pact in 1955?", ["West Germany joining NATO", "The Cuban Missile Crisis", "The building of the Berlin Wall", "The death of Kennedy"], "The USSR feared a rearmed West Germany inside NATO, so it formed its own alliance."], ["Why did the USSR invade Hungary in 1956?", ["Hungary's leader announced it would leave the Warsaw Pact", "Hungary attacked the USSR", "Hungary joined the Marshall Plan in 1947", "Hungary built nuclear missiles"], "Nagy's plan to leave the Warsaw Pact threatened Soviet control of Eastern Europe."], ["Why was the 'refugee problem' a concern for East Germany?", ["Many skilled workers were escaping to the West", "Too many West Germans were moving East", "Refugees were arriving from Cuba", "It had too many soldiers"], "Losing young, skilled workers damaged East Germany's economy and embarrassed communism."], ["What was the Bay of Pigs (1961)?", ["A failed CIA-backed invasion of Cuba by exiles", "A Soviet naval base", "A successful US bombing of Cuba", "A peace conference"], "About 1,400 Cuban exiles trained by the CIA landed in April 1961 and were quickly defeated."], ["How did Kennedy first respond to the missiles on Cuba in October 1962?", ["He ordered a naval blockade of Cuba", "He invaded Cuba immediately", "He launched nuclear missiles", "He ignored them"], "Kennedy chose a blockade (called a quarantine) to stop more Soviet weapons reaching Cuba."], ["What did the USA secretly agree to during the Cuban Missile Crisis?", ["To remove its missiles from Turkey", "To give Berlin to the USSR", "To leave NATO", "To hand over its atomic bombs"], "In return for the Soviet missiles leaving Cuba, the USA promised not to invade Cuba and secretly agreed to remove Jupiter missiles from Turkey."]], "bonus": ["What does 'superpower' mean in the Cold War?", ["A country with huge military and economic strength", "A small country with many allies", "Any country with a king", "A country that stays neutral"], "The USA and USSR were superpowers because they were far stronger than other countries."]}, {"ht": "Sum2", "t": "Reactions to crisis 1962–70", "intro": "After nearly going to war over Cuba, the superpowers took steps to reduce the risk of nuclear war. But tension continued in Europe, especially in Berlin and Czechoslovakia.", "how": ["Learn the four agreements in order: Hotline (1963), Limited Test Ban Treaty (1963), Outer Space Treaty (1967), Nuclear Non-Proliferation Treaty (1968).", "Explain what each agreement did in one simple sentence.", "Know why Kennedy's visit to West Berlin in June 1963 mattered.", "Explain the Prague Spring (1968), the Warsaw Pact invasion and the Brezhnev Doctrine.", "Show how the period mixed better relations (agreements) with continued rivalry (Czechoslovakia)."], "example": {"q": "Explain why the Soviet Union invaded Czechoslovakia in August 1968.", "steps": ["Describe Dubček's reforms: more freedom of speech, less censorship and some private business, called 'socialism with a human face'.", "Explain Soviet fears that reforms would weaken communist control and spread to other satellite states.", "Add that Brezhnev worried Czechoslovakia might move closer to the West.", "Conclude that Warsaw Pact troops invaded to stop the reforms, followed by the Brezhnev Doctrine."], "a": "The USSR invaded because Dubček's reforms threatened communist control and might spread across Eastern Europe."}, "walk": [{"h": "Making the world safer", "b": "During the Cuban Missile Crisis, messages between Kennedy and Khrushchev took hours. In 1963 a direct telephone hotline linked Washington and Moscow. The same year, the Limited Test Ban Treaty banned nuclear tests in the atmosphere, in space and underwater, but still allowed underground tests."}, {"h": "More treaties", "b": "The Outer Space Treaty of 1967 banned nuclear weapons from being placed in space. The Nuclear Non-Proliferation Treaty of 1968 tried to stop nuclear weapons spreading to more countries. Together these show the superpowers starting to cooperate, sometimes called the beginning of détente."}, {"h": "Berlin and Prague", "b": "In June 1963 Kennedy visited West Berlin and declared 'Ich bin ein Berliner', showing that the USA would support the city. In 1968 Alexander Dubček brought in reforms in Czechoslovakia, known as the Prague Spring. In August 1968 Warsaw Pact troops invaded, and the Brezhnev Doctrine said the USSR would intervene in any communist country that threatened the communist bloc."}], "qs": [["What was the 'hotline' set up in 1963?", ["A direct communication link between Washington and Moscow", "A spy satellite", "A new nuclear missile", "A radio station in Berlin"], "The hotline allowed the two leaders to communicate quickly and avoid misunderstandings."], ["Who led the reforms of the Prague Spring?", ["Alexander Dubček", "Leonid Brezhnev", "Imre Nagy", "Fidel Castro"], "Dubček became leader of Czechoslovakia in January 1968 and brought in reforms."], ["In which year did Kennedy visit West Berlin and give his famous speech?", ["1963", "1961", "1968", "1949"], "Kennedy spoke in West Berlin in June 1963, five months before his assassination."], ["What did the Limited Test Ban Treaty (1963) ban?", ["Nuclear tests in the atmosphere, space and underwater", "All nuclear weapons", "Underground nuclear tests only", "Building new missiles"], "Underground tests were still allowed, which is why the treaty was 'limited'."], ["What did the Outer Space Treaty (1967) do?", ["Banned nuclear weapons from being placed in space", "Allowed missiles on the Moon", "Gave space to the USA", "Ended the space race"], "Countries agreed not to put nuclear weapons in orbit or on the Moon."], ["What was the aim of the Nuclear Non-Proliferation Treaty (1968)?", ["To stop nuclear weapons spreading to more countries", "To give every country nuclear weapons", "To test bombs underwater", "To end the Warsaw Pact"], "Proliferation means spreading, so the treaty aimed to limit the number of nuclear powers."], ["What did Dubček call his reforms?", ["Socialism with a human face", "Containment", "Peaceful coexistence", "The Iron Curtain"], "Dubček wanted to keep communism but make it fairer and freer."], ["What happened in Czechoslovakia in August 1968?", ["Warsaw Pact troops invaded", "NATO troops invaded", "Dubček joined the USA", "A wall was built in Prague"], "Hundreds of thousands of Warsaw Pact troops entered Czechoslovakia and ended the reforms."], ["What did the Brezhnev Doctrine state?", ["The USSR would intervene if a communist state threatened the bloc", "The USSR would leave Eastern Europe", "Communist countries could choose capitalism", "The USSR would remove its missiles from Cuba"], "The doctrine justified the Czech invasion and warned other satellite states."], ["Why did the superpowers agree to the hotline and test ban treaty?", ["The Cuban Missile Crisis showed how close they came to nuclear war", "They had become allies again", "The USSR had given up communism", "Britain forced them to"], "The scare of October 1962 convinced both sides they needed ways to reduce the risk of war."]], "bonus": ["What does a 'treaty' mean?", ["A formal agreement between countries", "A type of weapon", "A government election", "A military invasion"], "A treaty is an official written agreement signed by two or more countries."]}]}, {"id": "geography", "name": "Geography", "board": "AQA (8035)", "weeks": [{"ht": "Aut1", "t": "Tectonic hazards", "intro": "Earthquakes and volcanoes are natural hazards caused by the movement of the Earth's plates. Learning where and why they happen, and how people respond, helps explain why some countries suffer far more than others.", "how": ["A natural hazard is a natural event that threatens people or property; hazard risk is the chance of being affected.", "Learn the Earth's layers: inner core, outer core, mantle and crust.", "Know the three main plate margins: destructive, constructive and conservative.", "Compare effects and responses in a richer country and a poorer one, using primary and secondary effects and immediate and long-term responses.", "Remember the four Ps for reducing risk: monitoring, prediction, protection and planning."], "example": {"q": "Explain why earthquakes often cause more deaths in lower-income countries than in higher-income countries.", "steps": ["Point 1: buildings in poorer countries are less likely to be earthquake-proof, so more collapse.", "Point 2: there is less money for monitoring, warning systems and emergency services.", "Point 3: people may be less prepared, with fewer earthquake drills and poorer healthcare.", "Link to vulnerability: these factors make people more vulnerable, so the same-sized earthquake causes more deaths."], "a": "Poorer countries usually suffer more deaths because weaker buildings, fewer resources and less preparation make people more vulnerable."}, "walk": [{"h": "Earth's structure", "b": "The Earth has a solid inner core, a liquid outer core, a thick mantle and a thin crust. The crust is broken into tectonic plates that move a few centimetres a year, driven by heat in the mantle. Oceanic crust is thinner and denser than continental crust."}, {"h": "Plate margins", "b": "At destructive margins, denser oceanic crust sinks beneath continental crust, causing explosive volcanoes and strong earthquakes, as in the Andes. At constructive margins plates move apart and magma rises, as at the Mid-Atlantic Ridge in Iceland. At conservative margins plates slide past each other, causing earthquakes but no volcanoes, like the San Andreas Fault. Hot spots, such as Hawaii, form volcanoes away from margins."}, {"h": "Effects and reducing risk", "b": "Primary effects happen straight away, such as buildings collapsing; secondary effects follow, such as fires or disease. People live near hazards because of fertile soil, jobs or tourism. Risk can be reduced by monitoring (for example tiltmeters on volcanoes), prediction, protection such as earthquake-resistant buildings, and planning such as evacuation routes."}], "qs": [["What is the outermost layer of the Earth called?", ["The crust", "The mantle", "The outer core", "The inner core"], "The crust is the thin rocky outer layer that we live on."], ["Which type of plate margin is where plates move apart?", ["Constructive", "Destructive", "Conservative", "Collision only"], "At constructive margins plates move apart and magma rises to form new crust."], ["Which plate margin causes earthquakes but not volcanoes?", ["Conservative", "Constructive", "Destructive", "Hot spot"], "At conservative margins plates slide past each other, so no magma reaches the surface."], ["Which is a primary effect of an earthquake?", ["Buildings collapsing", "Disease spreading weeks later", "Rising food prices", "People losing jobs months later"], "Primary effects are caused directly by the shaking itself."], ["Why does oceanic crust sink at a destructive margin?", ["It is denser than continental crust", "It is thicker than continental crust", "It is hotter than continental crust", "It is lighter than continental crust"], "Denser oceanic crust is pulled down beneath lighter continental crust in a process called subduction."], ["What is a hot spot?", ["A place where magma rises through the middle of a plate", "A place where two plates collide", "The hottest part of the core", "A volcano that never erupts"], "Hot spots like Hawaii are areas of very hot mantle, away from plate margins."], ["Which is an example of protection against earthquakes?", ["Building with cross-bracing and rubber shock absorbers", "Measuring gas from a volcano", "Writing an evacuation plan", "Using a seismometer to record past quakes"], "Protection means designing buildings so they can withstand shaking."], ["Which is a reason people continue to live near volcanoes?", ["Volcanic soils are fertile for farming", "Volcanoes never erupt again", "Land is always flat there", "Eruptions improve air quality"], "Volcanic ash breaks down into rich soils, and volcanoes can also bring tourism and geothermal energy."], ["Which is a long-term response to a tectonic hazard?", ["Rebuilding homes and roads", "Search and rescue for survivors", "Handing out emergency tents", "Giving first aid at the scene"], "Long-term responses happen months or years later to rebuild and reduce future risk."], ["Which factor increases a community's vulnerability to a tectonic hazard?", ["Poor-quality housing and little emergency planning", "Strict building laws", "Well-trained emergency services", "A working warning system"], "Vulnerability is how likely people are to be harmed; weak housing and poor planning raise it."]], "bonus": ["What does a key on a map show?", ["What the symbols and colours mean", "The map's north direction only", "The height of the land", "The date the map was made"], "A key explains the symbols, helping you read maps of hazards and plate boundaries."]}, {"ht": "Aut2", "t": "Weather hazards", "intro": "Weather hazards include tropical storms, which can be among the most destructive events on Earth, and extreme weather in the UK. This topic explains how the atmosphere moves heat around the planet and how people cope with dangerous weather.", "how": ["Learn the three cells of global atmospheric circulation: Hadley, Ferrel and Polar.", "Remember that high pressure brings dry, settled weather and low pressure brings rain and wind.", "Know the conditions for a tropical storm: ocean water of at least 26–27°C, between about 5° and 30° from the Equator.", "Use Typhoon Haiyan (Philippines, November 2013) as a case study of effects and responses.", "Know examples of UK weather hazards such as flooding, heatwaves, snow and strong winds."], "example": {"q": "Describe how a tropical storm forms.", "steps": ["Warm ocean water, at least 26–27°C, heats the air above it.", "Warm, moist air rises quickly, creating an area of very low pressure.", "As the air rises it cools and condenses, forming huge clouds and releasing heat, which powers the storm.", "The Earth's spin (the Coriolis effect) makes the storm rotate, with a calm eye in the middle."], "a": "Tropical storms form over warm oceans where rising moist air creates low pressure, condenses and is spun by the Earth's rotation."}, "walk": [{"h": "Global circulation", "b": "The Sun heats the Equator more than the poles, so air moves to spread the heat out. Air rises at the Equator (low pressure) and sinks at about 30° north and south (high pressure), forming the Hadley cell. Sinking air at 30° explains why many hot deserts are found there, and surface winds blowing between the cells are called trade winds and westerlies."}, {"h": "Tropical storms", "b": "Tropical storms are called hurricanes in the Atlantic, typhoons in the north-west Pacific and cyclones in the Indian Ocean. They have a calm eye surrounded by the eyewall, where winds and rain are strongest. Climate change may make storms more intense because oceans are getting warmer."}, {"h": "Haiyan and the UK", "b": "Typhoon Haiyan hit the Philippines in November 2013, with a storm surge of about 5 metres that flooded the city of Tacloban. Over 6,000 people died, and international aid included shelters, food and medical help. In the UK, hazards include flooding, drought, heatwaves and snow, and extreme weather seems to be becoming more frequent."}], "qs": [["What is a tropical storm called in the north-west Pacific Ocean?", ["A typhoon", "A hurricane", "A tornado", "A cyclone"], "Typhoon is the name used near countries like the Philippines and Japan."], ["What weather does high pressure usually bring?", ["Dry and settled weather", "Heavy rain and storms", "Strong winds and snow every time", "Thunder and lightning"], "In high pressure, air sinks, which stops clouds forming."], ["What is the calm centre of a tropical storm called?", ["The eye", "The eyewall", "The front", "The core"], "The eye has light winds and clear skies, surrounded by the violent eyewall."], ["Roughly what sea temperature is needed for a tropical storm to form?", ["At least 26–27°C", "At least 10°C", "Below 0°C", "Exactly 15°C"], "Very warm water provides the heat and moisture that powers the storm."], ["Which country was hit by Typhoon Haiyan in 2013?", ["The Philippines", "Japan", "Bangladesh", "The USA"], "Haiyan struck the Philippines in November 2013."], ["What is a storm surge?", ["A rise in sea level caused by strong winds and low pressure", "A sudden drop in temperature", "A type of earthquake", "Heavy snowfall"], "Winds push water onto the coast and low pressure lets the sea rise, causing flooding."], ["Why do tropical storms rarely form right on the Equator?", ["The Coriolis effect is too weak there to make them spin", "The water is too cold", "There is no wind at all", "The air pressure is too high everywhere"], "The Earth's spin effect is almost zero at the Equator, so storms cannot begin to rotate."], ["At about which latitude does air sink, creating many of the world's hot deserts?", ["30°", "0°", "60°", "90°"], "Sinking air at about 30° north and south forms high pressure and dry conditions."], ["How might climate change affect tropical storms?", ["Warmer oceans could make storms more intense", "Storms will stop forming completely", "Storms will only form in the UK", "It will have no effect"], "Warmer seas give storms more energy, so they may become stronger."], ["Which is an example of a UK weather hazard?", ["Flooding after heavy rain", "A typhoon hitting London every year", "A volcanic eruption in Wales", "A tsunami in Scotland every winter"], "Flooding, as well as heatwaves, drought and snow, are UK weather hazards."]], "bonus": ["Which line of latitude runs around the middle of the Earth?", ["The Equator", "The Prime Meridian", "The Tropic of Cancer", "The Arctic Circle"], "The Equator is 0° latitude, halfway between the North and South Poles."]}, {"ht": "Spr1", "t": "Climate change", "intro": "Climate change is the long-term change in the Earth's temperatures and weather patterns. Scientists have strong evidence that human activity is causing rapid warming, so this topic looks at the evidence, the causes and what we can do about it.", "how": ["Know evidence for climate change: ice cores, tree rings, temperature records, shrinking glaciers and rising sea levels.", "Learn natural causes: orbital changes, solar output and volcanic eruptions.", "Learn human causes: burning fossil fuels, farming and deforestation, which increase greenhouse gases.", "Mitigation means reducing the causes, such as renewable energy and carbon capture.", "Adaptation means coping with the effects, such as flood defences and drought-resistant crops."], "example": {"q": "Explain the difference between mitigation and adaptation, with one example of each.", "steps": ["Define mitigation: actions that reduce the causes of climate change.", "Give an example: carbon capture, which stores CO₂ from power stations underground.", "Define adaptation: actions that help people cope with the effects of climate change.", "Give an example: building higher sea walls to protect against rising sea levels."], "a": "Mitigation reduces the causes, like carbon capture, while adaptation helps people cope with the effects, like sea walls."}, "walk": [{"h": "The evidence", "b": "Air bubbles trapped in ice cores show past CO₂ levels and temperatures going back hundreds of thousands of years. Tree rings are thicker in warm, wet years, and accurate thermometer records go back to about 1850. Today, glaciers are shrinking and sea levels are rising as ice melts and warm water expands."}, {"h": "Natural and human causes", "b": "Natural causes include changes in the Earth's orbit, changes in the Sun's output and large volcanic eruptions, which can cool the planet for a short time. The enhanced greenhouse effect is caused by humans adding gases like CO₂ and methane. For example, burning coal releases CO₂, and cattle farming releases methane."}, {"h": "Managing climate change", "b": "Mitigation includes switching to renewable energy, planting trees, carbon capture and international agreements such as the Paris Agreement of 2015. Adaptation includes changing farming methods, managing water supplies and protecting coasts from rising seas. Both are needed because some warming is already happening."}], "qs": [["Which gas is released when fossil fuels are burned?", ["Carbon dioxide (CO₂)", "Oxygen (O₂)", "Nitrogen (N₂)", "Helium (He)"], "Burning coal, oil and gas releases CO₂, the main greenhouse gas from human activity."], ["Which of these is evidence of climate change?", ["Shrinking glaciers", "Earthquakes in Japan", "Changes in tide times each day", "The phases of the Moon"], "Glaciers around the world are retreating as temperatures rise."], ["What can ice cores tell scientists?", ["Past levels of CO₂ and temperature", "The age of the Moon", "Future earthquake locations", "Exact rainfall in a single day"], "Air bubbles trapped in the ice preserve the atmosphere from long ago."], ["Which is a natural cause of climate change?", ["Changes in the Earth's orbit", "Burning coal", "Deforestation", "Cattle farming"], "Orbital changes alter how much sunlight reaches the Earth over thousands of years."], ["How can a large volcanic eruption affect the climate?", ["Ash can block sunlight and cool the Earth for a short time", "It always heats the Earth for centuries", "It has no effect at all", "It melts the polar ice caps immediately"], "Ash and gases in the atmosphere reflect sunlight, causing short-term cooling."], ["Which human activity releases large amounts of methane?", ["Cattle farming", "Using solar panels", "Planting trees", "Cycling to school"], "Cattle produce methane as they digest food, and methane is a powerful greenhouse gas."], ["What is the enhanced greenhouse effect?", ["Extra warming caused by humans adding greenhouse gases", "The natural warming that keeps the Earth habitable", "Cooling caused by clouds", "Growing plants in greenhouses"], "The natural greenhouse effect keeps Earth warm; humans have enhanced it by adding more gases."], ["Which is an example of mitigation?", ["Carbon capture and storage", "Building flood defences", "Growing drought-resistant crops", "Storing water in reservoirs"], "Carbon capture reduces CO₂ entering the atmosphere, tackling the cause."], ["Which is an example of adaptation?", ["Building higher sea walls", "Switching to wind power", "Planting forests to absorb CO₂", "Signing an agreement to cut emissions"], "Sea walls help people cope with a consequence, rising sea levels."], ["What is the main aim of the 2015 Paris Agreement?", ["Keep global warming well below 2°C", "Ban all cars by 2020", "Stop all volcanic eruptions", "Increase coal use worldwide"], "Countries agreed to limit warming to well below 2°C, ideally 1.5°C, above pre-industrial levels."]], "bonus": ["Which process do plants use to take in carbon dioxide?", ["Photosynthesis", "Respiration", "Evaporation", "Condensation"], "Plants absorb CO₂ during photosynthesis, which is why trees help reduce greenhouse gases."]}, {"ht": "Spr2", "t": "The living world", "intro": "An ecosystem is a community of plants and animals interacting with their environment. This topic studies tropical rainforests, such as the Amazon, and hot deserts, such as the Western Desert of the USA, and how people can manage them sustainably.", "how": ["Know the parts of an ecosystem: producers, consumers, decomposers, food chains and food webs.", "Learn the layers of a rainforest: emergent, canopy, under canopy and shrub layer.", "Know causes of Amazon deforestation: cattle ranching, logging, mining, road building and farming.", "Learn sustainable management ideas: selective logging, ecotourism, education and protected areas.", "Know how plants and animals adapt to hot deserts, and the opportunities and challenges of the Western Desert."], "example": {"q": "Explain how a cactus is adapted to survive in a hot desert.", "steps": ["Identify the challenge: very little rain and high temperatures.", "Adaptation 1: spines instead of leaves reduce water loss and protect it from animals.", "Adaptation 2: a thick, waxy skin and stem store water and reduce evaporation.", "Adaptation 3: long or wide shallow roots collect water quickly when it rains."], "a": "A cactus survives by storing water in its stem, losing little through spines and waxy skin, and collecting rain with its roots."}, "walk": [{"h": "Ecosystems", "b": "Producers, such as plants, use sunlight to make energy. Consumers eat producers or other consumers, and decomposers like fungi break down dead material and return nutrients to the soil. A food web shows how many food chains link together, so if one species disappears, others are affected."}, {"h": "Tropical rainforests", "b": "Rainforests are hot and wet all year, with around 2,000 mm of rain or more and temperatures of about 27°C. Animals and plants adapt, for example buttress roots support tall trees and drip-tip leaves shed heavy rain. In the Amazon, deforestation is caused mainly by cattle ranching, plus logging, mining and roads, and it can be managed by selective logging, ecotourism and protected areas."}, {"h": "Hot deserts", "b": "Hot deserts get less than 250 mm of rain a year and can be very hot by day and cold at night. Camels store fat in their humps and can survive for long periods without drinking. In the Western Desert of the USA, there are opportunities like solar energy, mining and tourism, but challenges include extreme heat, water shortages and poor access."}], "qs": [["What is a producer in a food chain?", ["A plant that makes its own food using sunlight", "An animal that eats plants", "A fungus that breaks down dead material", "An animal that eats other animals"], "Producers, usually green plants, are at the start of every food chain."], ["What is the main role of decomposers?", ["Breaking down dead material and recycling nutrients", "Making food from sunlight", "Hunting other animals", "Pollinating flowers"], "Decomposers such as fungi and bacteria return nutrients to the soil."], ["Roughly how much rain do hot deserts receive each year?", ["Less than 250 mm", "Over 2,000 mm", "About 1,000 mm", "Exactly 500 mm"], "Hot deserts are defined by very low rainfall, under 250 mm a year."], ["Which layer of the rainforest has the tallest trees that stick out above the rest?", ["The emergent layer", "The shrub layer", "The under canopy", "The forest floor"], "Emergent trees can reach around 50 metres, above the main canopy."], ["What are buttress roots?", ["Large roots that support very tall rainforest trees", "Roots that store water in deserts", "Roots that grow on the canopy", "Roots that only grow in winter"], "Shallow rainforest soils mean tall trees need wide buttress roots for support."], ["What is the biggest cause of deforestation in the Amazon?", ["Cattle ranching", "Ecotourism", "Building ski resorts", "Fishing"], "Clearing land for cattle pasture is the largest single cause of Amazon deforestation."], ["Which is an example of sustainable rainforest management?", ["Selective logging", "Clear-felling large areas", "Building new highways", "Burning forest for farmland"], "Selective logging removes only some mature trees, letting the forest recover."], ["Why do drip-tip leaves help rainforest plants?", ["They let heavy rain run off quickly", "They store water for dry seasons", "They trap insects for food", "They keep the plant warm"], "Water runs off quickly, stopping mould and algae growing on the leaf."], ["Which is an opportunity in the Western Desert of the USA?", ["Generating solar energy", "Plentiful rainfall for farming", "Cool weather all year", "Thick forests for logging"], "Strong sunshine and open land make the Western Desert ideal for solar power."], ["Which is a challenge of developing the Western Desert?", ["Water shortages", "Too much rainfall", "Freezing temperatures all year", "Frequent tropical storms"], "Low rainfall and rising demand from cities and farms make water a major challenge."]], "bonus": ["In the food chain grass → rabbit → fox, what does the fox eat?", ["The rabbit", "The grass", "Nothing", "Other foxes"], "The arrow shows the direction energy flows, so the fox eats the rabbit."]}, {"ht": "Sum1", "t": "Geographical skills: OS maps", "intro": "Ordnance Survey (OS) maps are detailed maps of Great Britain used by walkers, planners and geographers. Being able to read grid references, scale, contours and photographs is tested across the whole GCSE.", "how": ["For grid references, go along the corridor before up the stairs: read eastings first, then northings.", "A four-figure reference gives a whole grid square; a six-figure reference gives a precise point within it.", "Use the scale to measure distance: on a 1:50,000 map, 2 cm = 1 km; on a 1:25,000 map, 4 cm = 1 km.", "Contour lines join places of equal height; close together means steep, far apart means gentle.", "When describing a photograph, look at the foreground, middle ground and background."], "example": {"q": "On a 1:50,000 OS map, a road measures 7 cm long. How long is it in real life?", "steps": ["1:50,000 means 1 cm on the map equals 50,000 cm in real life.", "50,000 cm = 500 m, so 1 cm = 0.5 km.", "Multiply: 7 × 0.5 km = 3.5 km."], "a": "The road is 3.5 km long."}, "walk": [{"h": "Grid references", "b": "OS maps are covered by numbered grid lines. Eastings run along the bottom and increase to the east; northings run up the side and increase to the north. For a four-figure reference, use the bottom-left corner of the square, such as 4527; for a six-figure reference, imagine each square split into tenths, such as 453274."}, {"h": "Scale and distance", "b": "Scale shows how much smaller the map is than real life. On a 1:25,000 map, 1 cm stands for 25,000 cm, which is 250 m, so 4 cm = 1 km. For a winding road, lay a piece of string or the edge of paper along it, then measure against the scale bar."}, {"h": "Relief and photographs", "b": "Relief means the height and shape of the land. Contour lines usually show height at 10 m intervals on 1:50,000 maps and 5 m on 1:25,000 maps, and spot heights give exact heights. When you describe a photo, use compass directions or 'foreground and background' and describe land use, settlement and landforms."}], "qs": [["When giving a grid reference, which do you read first?", ["Eastings (along the bottom)", "Northings (up the side)", "The scale bar", "The key"], "Remember 'along the corridor, then up the stairs': eastings first."], ["What do contour lines join?", ["Places of equal height", "Places with the same rainfall", "Roads of the same width", "Towns of equal size"], "Contours connect points that are the same height above sea level."], ["What does it mean if contour lines are very close together?", ["The land is steep", "The land is flat", "There is a river", "There is a town"], "Height changes a lot over a short distance when contours are close."], ["On a 1:50,000 map, how many centimetres represent 1 km?", ["2 cm", "4 cm", "1 cm", "5 cm"], "1 cm = 50,000 cm = 0.5 km, so 2 cm = 1 km."], ["On a 1:25,000 map, how many centimetres represent 1 km?", ["4 cm", "2 cm", "25 cm", "1 cm"], "1 cm = 25,000 cm = 250 m, so 4 cm = 1 km."], ["A four-figure grid reference refers to what?", ["One whole grid square", "An exact point", "A single contour line", "The whole map"], "Four figures identify a square by its bottom-left corner."], ["On a 1:50,000 map, a footpath is 5 cm long. What is the real distance?", ["2.5 km", "5 km", "25 km", "0.5 km"], "Each cm is 0.5 km, so 5 × 0.5 = 2.5 km."], ["A church is in square 3846, three-tenths across and seven-tenths up. What is its six-figure reference?", ["383467", "387463", "384637", "463837"], "Write the easting 38 plus 3, then the northing 46 plus 7: 383467."], ["What is a spot height?", ["A dot with a number showing the exact height at that point", "A symbol for a church", "A grid line", "A type of contour that shows depth"], "Spot heights show the precise height in metres at one point."], ["In a photograph, what is the 'foreground'?", ["The part nearest to the camera", "The part furthest away", "The sky", "The middle of the picture"], "Foreground is closest, then middle ground, then background."]], "bonus": ["Which compass direction is opposite to north-east?", ["South-west", "South-east", "North-west", "West"], "Opposite directions are 180° apart, so north-east is opposite south-west."]}, {"ht": "Sum2", "t": "Fieldwork and issue evaluation", "intro": "Geographers collect their own data in the real world through fieldwork, then present and analyse it. In the GCSE you also evaluate a geographical issue, weighing up evidence to make a decision.", "how": ["Primary data is collected by you; secondary data is collected by someone else, such as census data or maps.", "Choose a sampling method: random, systematic or stratified.", "Present data with suitable graphs or maps, such as bar charts, line graphs or choropleth maps.", "Analyse by describing patterns and anomalies, then explain them.", "When evaluating an issue, consider social, economic and environmental impacts and reach a justified decision."], "example": {"q": "A student counts pedestrians at 5 sites: 12, 18, 25, 18 and 37. Work out the mean, median, mode and range.", "steps": ["Mean: add them up (12 + 18 + 25 + 18 + 37 = 110), then divide by 5: 110 ÷ 5 = 22.", "Median: put them in order (12, 18, 18, 25, 37); the middle value is 18.", "Mode: the most common value is 18.", "Range: highest minus lowest: 37 − 12 = 25."], "a": "Mean = 22, median = 18, mode = 18 and range = 25."}, "walk": [{"h": "Collecting data", "b": "Primary data might come from questionnaires, traffic counts, river measurements or field sketches. Secondary data might come from websites, census results or old photos. Using both lets you compare your findings with wider information."}, {"h": "Sampling methods", "b": "Random sampling means every point has an equal chance, such as using random numbers. Systematic sampling means taking samples at regular intervals, such as every 10 metres along a beach. Stratified sampling means splitting the area or people into groups and sampling each group fairly."}, {"h": "Presenting and evaluating", "b": "Choose graphs that suit the data: a line graph for change over time, a bar chart for categories and a choropleth map for differences between areas. Look for patterns and anomalies, then evaluate your fieldwork, such as noting that you only collected data on one day. For an issue evaluation, compare options, use evidence and justify your choice."}], "qs": [["What is primary data?", ["Data you collect yourself", "Data from the census", "Data from a textbook", "Data from a website"], "Primary data is first-hand information that you gather during fieldwork."], ["Which is an example of secondary data?", ["Census population figures", "Your own traffic count", "A questionnaire you carried out", "Your field sketch"], "Secondary data has been collected by someone else."], ["Taking a sample every 10 metres along a transect is which type of sampling?", ["Systematic", "Random", "Stratified", "Opportunistic"], "Systematic sampling uses regular intervals."], ["Which graph is best for showing change in temperature over time?", ["A line graph", "A pie chart", "A pictogram", "A Venn diagram"], "Line graphs show trends over time clearly."], ["What is the mean of 4, 6, 8 and 10?", ["7", "6", "8", "28"], "Add them (28) and divide by 4, which gives 7."], ["What is the range of 5, 9, 14, 20 and 22?", ["17", "14", "22", "70"], "Range = highest − lowest = 22 − 5 = 17."], ["What is the median of 3, 7, 9, 12 and 15?", ["9", "7", "12", "9.2"], "The middle value of the ordered list is 9; 9.2 is the mean."], ["What does a choropleth map show?", ["Differences between areas using shading", "Exact heights using contour lines", "Flows of people using arrows", "Routes using lines only"], "Choropleth maps shade areas darker for higher values."], ["What is an anomaly in a data set?", ["A result that does not fit the general pattern", "The most common value", "The average value", "The first result collected"], "Anomalies stand out from the trend and should be explained."], ["Why might stratified sampling be used in a questionnaire?", ["To make sure each group, such as age groups, is fairly represented", "To pick people completely at random", "To ask only one person", "To avoid collecting any data"], "Stratified sampling makes the sample match the make-up of the whole population."]], "bonus": ["What is the mode of 2, 3, 3, 5 and 7?", ["3", "2", "4", "5"], "The mode is the most common value, and 3 appears twice."]}]}, {"id": "computing", "name": "Computer Science", "board": "OCR (J277)", "weeks": [{"ht": "Aut1", "t": "Boolean logic and logic gates", "intro": "Computers make decisions using Boolean logic, where every value is either True (1) or False (0). Logic gates are tiny electronic circuits inside the processor that combine these 1s and 0s. Learning AND, OR and NOT lets you understand how a computer works things out at the simplest level.", "how": ["AND gives 1 only when both inputs are 1.", "OR gives 1 when at least one input is 1.", "NOT has one input and flips it: 1 becomes 0 and 0 becomes 1.", "In diagrams, AND is a D shape, OR is a curved arrow-head shape, and NOT is a triangle with a small circle on its tip.", "A truth table lists every possible input combination; with 2 inputs there are 4 rows and with 3 inputs there are 8 rows."], "example": {"q": "Complete the output for P = NOT (A AND B) when A = 1 and B = 0.", "steps": ["Work out the gate in the brackets first: A AND B.", "1 AND 0 = 0, because AND needs both inputs to be 1.", "Now apply NOT to that result: NOT 0 = 1.", "So the output P is 1."], "a": "P = 1."}, "walk": [{"h": "The three gates", "b": "Think of AND as a door with two locks: it only opens (1) if both keys are turned. OR is a door with two separate keys: either one opens it. NOT is a contrary friend who always says the opposite: give it 1 and it says 0."}, {"h": "Truth tables", "b": "Write the inputs in a counting pattern so you never miss a row: 00, 01, 10, 11. For A OR B the outputs are 0, 1, 1, 1. For A AND B the outputs are 0, 0, 0, 1."}, {"h": "Combining gates", "b": "In a logic diagram, the output of one gate can feed into another. For P = (A OR B) AND C, add a column for A OR B first, then AND that column with C. With 3 inputs, list 8 rows from 000 to 111."}], "qs": [["What is the output of 1 AND 1?", ["1", "0", "2", "11"], "AND outputs 1 only when both inputs are 1, which they are."], ["What is the output of 1 AND 0?", ["0", "1", "10", "2"], "AND needs both inputs to be 1, so one 0 makes the output 0."], ["What is the output of 0 OR 1?", ["1", "0", "01", "2"], "OR outputs 1 if at least one input is 1."], ["What is the output of NOT 1?", ["0", "1", "−1", "10"], "NOT reverses the input, so 1 becomes 0."], ["Which gate has only one input?", ["NOT", "AND", "OR", "None of them"], "NOT takes a single input and inverts it."], ["Which gate is drawn as a triangle with a small circle at its point?", ["NOT", "AND", "OR", "XOR"], "The triangle and the small circle (the inversion bubble) make the NOT symbol."], ["How many rows does a truth table need for 3 inputs?", ["8", "6", "3", "9"], "Each input can be 0 or 1, so there are 2 × 2 × 2 = 8 combinations."], ["For which inputs does A OR B give 0?", ["A = 0 and B = 0", "A = 1 and B = 0", "A = 0 and B = 1", "A = 1 and B = 1"], "OR only outputs 0 when neither input is 1."], ["What is P = NOT (A OR B) when A = 0 and B = 1?", ["0", "1", "Cannot be worked out", "2"], "0 OR 1 = 1, then NOT 1 = 0."], ["What is P = (A AND B) OR C when A = 1, B = 0 and C = 1?", ["1", "0", "2", "10"], "1 AND 0 = 0, then 0 OR 1 = 1."]], "bonus": ["A light only turns on if switch X AND switch Y are pressed. X is pressed, Y is not. Is the light on?", ["No, both must be pressed", "Yes, one switch is enough", "Yes, because X is pressed first", "It flickers on and off"], "AND means both conditions must be true at the same time."]}, {"ht": "Aut2", "t": "Data units and number systems", "intro": "Everything a computer stores, from photos to music, is turned into binary: 1s and 0s. This topic explains why computers use binary, how we measure the amount of data, and how to convert between binary, denary (our normal numbers) and hexadecimal. These skills come up in almost every exam.", "how": ["Computers use binary because their circuits are made of switches (transistors) that have only two states: on (1) and off (0).", "Units: 8 bits = 1 byte, 4 bits = 1 nibble, and then 1 000 bytes = 1 kilobyte, 1 000 KB = 1 MB, 1 000 MB = 1 GB, 1 000 GB = 1 TB, 1 000 TB = 1 PB.", "An 8-bit binary number has place values 128, 64, 32, 16, 8, 4, 2, 1; add the values where there is a 1 to get denary.", "Hexadecimal uses 0–9 and then A–F for 10–15, and each hex digit stands for exactly 4 bits (one nibble).", "For file sizes, multiply to find the total in bits, then divide by 8 for bytes and by 1 000 for each step up (KB, MB, GB)."], "example": {"q": "Convert the binary number 10110110 to denary and then to hexadecimal.", "steps": ["Write the place values: 128, 64, 32, 16, 8, 4, 2, 1 above the bits 1 0 1 1 0 1 1 0.", "Add the values with a 1: 128 + 32 + 16 + 4 + 2 = 182.", "For hex, split into nibbles: 1011 and 0110.", "1011 = 8 + 2 + 1 = 11 = B, and 0110 = 4 + 2 = 6, so the hex is B6."], "a": "10110110 is 182 in denary and B6 in hexadecimal."}, "walk": [{"h": "Bits, bytes and beyond", "b": "A bit is a single 0 or 1, and 8 bits make a byte, enough to store one character like 'A'. The units go up in thousands: kilobyte, megabyte, gigabyte, terabyte, petabyte. So a 2 GB memory stick holds 2 000 MB."}, {"h": "Binary and denary", "b": "To turn 00001101 into denary, add 8 + 4 + 1 = 13. To go the other way, take away place values from left to right: 45 = 32 + 8 + 4 + 1, so 45 is 00101101. The biggest 8-bit number is 11111111 = 255."}, {"h": "Hexadecimal", "b": "Hex is a short way for humans to write binary because one hex digit replaces four bits. 2F in hex means 2 × 16 + 15 = 47 in denary. In binary, 2 is 0010 and F is 1111, so 2F = 00101111."}], "qs": [["Why do computers use binary?", ["Their circuits have switches with only two states, on and off", "Binary numbers are shorter than denary numbers", "Humans find binary easier to read", "Binary uses less electricity than denary"], "Transistors are either on or off, which matches the two binary digits 1 and 0."], ["How many bits are there in a byte?", ["8", "4", "10", "16"], "A byte is a group of 8 bits."], ["Which list of units is in order from smallest to largest?", ["Byte, kilobyte, megabyte, gigabyte", "Kilobyte, byte, gigabyte, megabyte", "Megabyte, kilobyte, gigabyte, byte", "Gigabyte, megabyte, kilobyte, byte"], "Each unit is 1 000 times bigger than the one before."], ["What is the binary number 00001010 in denary?", ["10", "2", "1010", "5"], "8 + 2 = 10."], ["What is denary 25 in 8-bit binary?", ["00011001", "00010101", "00011010", "00110001"], "25 = 16 + 8 + 1, so the bits for 16, 8 and 1 are set."], ["What is the largest denary number that can be stored in 8 bits?", ["255", "256", "128", "8"], "11111111 = 128 + 64 + 32 + 16 + 8 + 4 + 2 + 1 = 255."], ["What is the hexadecimal digit for denary 12?", ["C", "B", "12", "D"], "In hex, A = 10, B = 11, C = 12."], ["What is the hexadecimal number 2F in denary?", ["47", "32", "215", "17"], "2 × 16 + 15 = 32 + 15 = 47."], ["How many 4 MB photos can be stored on a 2 GB memory stick?", ["500", "50", "5 000", "2 000"], "2 GB = 2 000 MB, and 2 000 ÷ 4 = 500."], ["A sound file has 2 000 000 bits. What is its size in kilobytes?", ["250 KB", "2 000 KB", "16 000 KB", "25 KB"], "2 000 000 ÷ 8 = 250 000 bytes, and 250 000 ÷ 1 000 = 250 KB."]], "bonus": ["What is the value of the 3 in the denary number 345?", ["300", "30", "3", "3 000"], "The 3 is in the hundreds column, so it is worth 300; binary uses the same idea with powers of 2."]}, {"ht": "Spr1", "t": "Programming fundamentals", "intro": "A program is a set of instructions that tells a computer exactly what to do. Every program, from a calculator to a game, is built from a few basic ideas: storing data in variables, making decisions and repeating actions. This topic uses Python to show these building blocks.", "how": ["The main data types are integer (whole number), real or float (decimal), Boolean (True or False), character (one symbol) and string (text).", "A variable is a named store whose value can change while the program runs; a constant is a named value that stays the same.", "Sequence means instructions run in order, selection means choosing a path with if / elif / else, and iteration means repeating with for or while loops.", "Operators include + − * / for maths, // for integer division (DIV), % for remainder (MOD), and == != < > <= >= for comparisons.", "input() always returns a string, so use int() to turn it into a number; print() shows an output; random.randint(1, 6) gives a random whole number from 1 to 6."], "example": {"q": "What does this program print? total = 0, then for i in range(1, 4): total = total + i, then print(total)", "steps": ["range(1, 4) gives the values 1, 2 and 3 (it stops before 4).", "First loop: total = 0 + 1 = 1.", "Second loop: total = 1 + 2 = 3.", "Third loop: total = 3 + 3 = 6, then the loop ends and total is printed."], "a": "The program prints 6."}, "walk": [{"h": "Variables and data types", "b": "age = 13 stores an integer, height = 1.62 stores a real, and name = \"Sam\" stores a string. A constant such as VAT = 0.2 is written in capitals to show it should not change. Choosing the right data type matters: you cannot do maths on the string \"13\" until you convert it with int()."}, {"h": "Selection", "b": "Selection lets a program choose. For example: if score >= 50: print(\"Pass\") else: print(\"Try again\"). Use == to compare (is it equal?) and a single = to assign (store a value)."}, {"h": "Iteration and random", "b": "A for loop repeats a set number of times: for i in range(5) runs 5 times, with i going 0, 1, 2, 3, 4. A while loop repeats while a condition is True, such as while guess != 7. After import random, the line roll = random.randint(1, 6) simulates rolling a dice."}], "qs": [["Which data type would best store the number of pupils in a class?", ["Integer", "Real", "String", "Boolean"], "The number of pupils is always a whole number."], ["Which data type stores only True or False?", ["Boolean", "Integer", "Character", "String"], "A Boolean has just two possible values: True and False."], ["What is the difference between a variable and a constant?", ["A variable can change while the program runs; a constant cannot", "A constant can change; a variable cannot", "Variables store only numbers; constants store only text", "There is no difference"], "Constants hold fixed values such as VAT or pi, while variables can be updated."], ["Which programming construct is used by an if statement?", ["Selection", "Sequence", "Iteration", "Recursion"], "An if statement chooses which path to follow, which is selection."], ["What is the result of 17 % 5 in Python?", ["2", "3", "3.4", "12"], "% (MOD) gives the remainder: 17 ÷ 5 = 3 remainder 2."], ["What is the result of 17 // 5 in Python?", ["3", "2", "3.4", "85"], "// (DIV) gives the whole-number part of the division: 17 ÷ 5 = 3 remainder 2."], ["What data type does input() return in Python?", ["String", "Integer", "Real", "Boolean"], "input() always gives a string, so you must convert it to use it as a number."], ["How many times will for i in range(5): print(\"Hi\") print Hi?", ["5", "4", "6", "1"], "range(5) gives 0, 1, 2, 3, 4, which is 5 values."], ["What values can random.randint(1, 6) return?", ["Any whole number from 1 to 6", "Any whole number from 1 to 5", "Any decimal between 1 and 6", "Only 1 or 6"], "randint includes both end values, so it can return 1, 2, 3, 4, 5 or 6."], ["x = 10, then while x > 4: x = x − 3. What is x when the loop ends?", ["4", "1", "7", "−2"], "x goes 10 → 7 → 4, and 4 > 4 is False, so the loop stops at 4."]], "bonus": ["What is the correct order of steps for making toast?", ["Put bread in, switch on toaster, wait, take toast out", "Take toast out, put bread in, wait, switch on", "Switch on, take toast out, put bread in, wait", "Wait, put bread in, take toast out, switch on"], "Algorithms need steps in the right sequence, just like a program."]}, {"ht": "Spr2", "t": "Strings, arrays and character sets", "intro": "Lots of data in programs is text, such as names, passwords and messages, so you need to know how to work with strings. Arrays let you store many values under one name instead of making lots of separate variables. Underneath it all, every character is stored as a number using a character set like ASCII or Unicode.", "how": ["Characters in a string are numbered from 0, so in word = \"PYTHON\", word[0] is \"P\".", "len(word) gives the number of characters, .upper() and .lower() change the case, and + joins (concatenates) strings.", "word[1:4] gives a substring from position 1 up to, but not including, position 4.", "A 1D array (a list in Python) stores several values of the same type under one name, and each item is found by its index, starting at 0.", "A character set gives each character a binary code: ASCII uses 7 bits (128 characters) and Unicode uses more bits so it can represent characters from almost every language and emoji."], "example": {"q": "word = \"COMPUTER\". What is len(word) and what is word[2:5]?", "steps": ["Count the characters: C O M P U T E R is 8 characters, so len(word) = 8.", "Number the positions from 0: C=0, O=1, M=2, P=3, U=4, T=5.", "word[2:5] starts at position 2 and stops before position 5.", "So it takes positions 2, 3 and 4: M, P, U."], "a": "len(word) is 8 and word[2:5] is \"MPU\"."}, "walk": [{"h": "Working with strings", "b": "If name = \"Ali\", then len(name) is 3 and name.upper() is \"ALI\". Concatenation joins strings: \"Hi \" + name gives \"Hi Ali\". Remember the first character is at index 0, so name[2] is \"i\"."}, {"h": "1D arrays", "b": "Instead of score1, score2 and score3, use one array: scores = [12, 7, 9]. scores[0] is 12 and scores[2] is 9, and you can change an item with scores[1] = 8. A for loop can visit every item, for example to add them all up."}, {"h": "ASCII and Unicode", "b": "In ASCII, 'A' is 65, 'B' is 66 and so on, and lowercase 'a' is 97. Because the codes are in order, you can work out that 'E' is 69. In Python, ord(\"A\") gives 65 and chr(66) gives \"B\". Unicode keeps the same codes for these characters but adds many more."}], "qs": [["What is len(\"HELLO\")?", ["5", "4", "6", "1"], "HELLO has 5 characters."], ["If word = \"PYTHON\", what is word[0]?", ["P", "Y", "N", "Nothing, indexes start at 1"], "String indexes start at 0, so position 0 is the first character."], ["What is \"Good\" + \"Day\" in Python?", ["\"GoodDay\"", "\"Good Day\"", "\"Good+Day\"", "An error"], "Concatenation joins strings exactly, with no space added."], ["What does \"hello\".upper() return?", ["\"HELLO\"", "\"Hello\"", "\"hello\"", "\"hELLO\""], ".upper() changes every letter to uppercase."], ["If word = \"COMPUTER\", what is word[0:3]?", ["\"COM\"", "\"COMP\"", "\"OMP\"", "\"OM\""], "The slice takes positions 0, 1 and 2 and stops before 3."], ["What is an array?", ["A data structure that stores several values under one name", "A single variable that stores one number", "A type of loop", "A logic gate"], "An array groups related items so each can be found by its index."], ["scores = [12, 7, 9, 15]. What is scores[2]?", ["9", "7", "15", "12"], "Index 0 is 12, index 1 is 7, index 2 is 9."], ["How many characters can standard 7-bit ASCII represent?", ["128", "256", "7", "65 536"], "7 bits give 2⁷ = 128 different codes."], ["Why was Unicode introduced?", ["To represent characters from many languages, plus symbols and emoji", "To make text files smaller than ASCII", "To store only numbers", "To replace binary"], "ASCII only covers English characters, while Unicode covers most of the world's writing systems."], ["In ASCII, 'A' is 65. What is the code for 'E'?", ["69", "68", "70", "101"], "The letters are in order: A=65, B=66, C=67, D=68, E=69."]], "bonus": ["In the word \"BANANA\", how many times does the letter A appear?", ["3", "2", "4", "6"], "B-A-N-A-N-A has A in positions 2, 4 and 6 when counting from 1."]}, {"ht": "Sum1", "t": "CPU architecture and performance", "intro": "The CPU (central processing unit) is the brain of the computer: it carries out every instruction in a program. It does this by repeating the fetch–execute cycle billions of times per second. This topic shows what is inside a CPU and what makes one CPU faster than another.", "how": ["The fetch–execute cycle: fetch an instruction from memory, decode it to work out what it means, then execute it, and repeat.", "In Von Neumann architecture, the Program Counter (PC) holds the address of the next instruction, the MAR holds the address being used, the MDR holds the data or instruction just fetched or about to be stored, and the Accumulator (ACC) holds the results of calculations.", "The ALU (arithmetic logic unit) does calculations and logical comparisons, and the CU (control unit) decodes instructions and controls the flow of data.", "Cache is very fast memory inside the CPU that stores frequently used instructions and data; more cache, a higher clock speed and more cores can all improve performance.", "An embedded system is a computer built into a larger device to do one dedicated job, such as in a washing machine or a microwave."], "example": {"q": "A CPU has a clock speed of 3 GHz. How many fetch–execute cycles can it carry out per second, assuming one cycle per clock tick?", "steps": ["Hertz means 'per second', and giga means one billion (1 000 000 000).", "So 3 GHz = 3 × 1 000 000 000.", "That gives 3 000 000 000 cycles per second.", "This is why a higher clock speed usually means a faster CPU."], "a": "It can carry out 3 billion (3 000 000 000) cycles per second."}, "walk": [{"h": "Fetch, decode, execute", "b": "First, the address in the PC is copied to the MAR, and the PC goes up by 1 ready for next time. The instruction at that address is fetched from RAM into the MDR. The CU decodes it, then it is executed, perhaps by the ALU, with the result stored in the ACC."}, {"h": "Inside the CPU", "b": "Think of the CU as the conductor of an orchestra, telling everything when to act. The ALU is the calculator that does sums like 5 + 3 and comparisons like 'is 5 > 3?'. Registers such as the PC, MAR, MDR and ACC are tiny, super-fast stores inside the CPU."}, {"h": "What makes it faster", "b": "A 3.5 GHz CPU does 3.5 billion cycles per second, more than a 2 GHz one. A quad-core CPU has 4 processing units that can work on different tasks at once, but not every program can split its work, so doubling the cores does not always double the speed. Bigger cache means fewer slow trips to RAM."}], "qs": [["What are the three stages of the CPU cycle, in order?", ["Fetch, decode, execute", "Decode, fetch, execute", "Execute, fetch, decode", "Fetch, execute, decode"], "An instruction is fetched from memory, decoded, then carried out."], ["Which part of the CPU carries out calculations and logical comparisons?", ["ALU", "CU", "Cache", "MAR"], "The arithmetic logic unit does maths and logic operations."], ["What is the job of the control unit (CU)?", ["To decode instructions and control the flow of data", "To store files permanently", "To carry out calculations", "To display images on screen"], "The CU coordinates the CPU and decodes each instruction."], ["Which register holds the address of the next instruction to be fetched?", ["Program Counter (PC)", "Memory Data Register (MDR)", "Accumulator (ACC)", "Arithmetic Logic Unit (ALU)"], "The PC keeps track of where the next instruction is in memory."], ["Which register holds the data or instruction that has just been fetched from memory?", ["MDR", "MAR", "PC", "CU"], "The Memory Data Register holds the contents that have been read from or will be written to memory."], ["What is stored in the Accumulator (ACC)?", ["The results of calculations done by the ALU", "The address of the next instruction", "The operating system", "All the files on the computer"], "The ACC temporarily stores the results of processing."], ["What is cache memory?", ["Very fast memory in the CPU that stores frequently used data", "Slow storage used to keep files permanently", "A type of input device", "The part of the CPU that decodes instructions"], "Cache is quicker to access than RAM, so it speeds up processing."], ["A CPU has a clock speed of 2.5 GHz. How many cycles per second is that?", ["2 500 000 000", "2 500 000", "250 000", "25 000 000"], "Giga means billion, so 2.5 × 1 000 000 000 = 2 500 000 000."], ["Why might doubling the number of cores not double a computer's speed?", ["Some programs cannot split their tasks across several cores", "Extra cores slow down the clock speed to zero", "Cores can only be used for storage", "More cores always halve the cache size"], "If a task must be done in one sequence, extra cores cannot help much."], ["Which of these is an example of an embedded system?", ["The controller in a washing machine", "A desktop PC used for gaming", "A laptop used for homework", "A web server running many websites"], "An embedded system is built into a device to do one specific job."]], "bonus": ["Which of these is an input device?", ["Keyboard", "Monitor", "Speaker", "Printer"], "A keyboard sends data into the computer; the others show or give out data."]}, {"ht": "Sum2", "t": "Searching and sorting algorithms", "intro": "Computers often need to find an item in a list or put a list in order, and different algorithms do this in different ways. Some are simple but slow, while others are cleverer and much quicker on big lists. For J277 you need to know how linear search, binary search, bubble sort, merge sort and insertion sort work, step by step.", "how": ["Linear search checks each item in turn from the start until it finds the target or reaches the end; the list does not need to be sorted.", "Binary search only works on a sorted list: check the middle item, then throw away the half that cannot contain the target, and repeat.", "Bubble sort compares neighbouring pairs and swaps them if they are in the wrong order, making passes until no swaps happen.", "Merge sort splits the list into single items, then merges them back together in order, pair by pair.", "Insertion sort takes each item in turn and inserts it into the correct place in the sorted part on the left."], "example": {"q": "Use binary search to find 23 in the sorted list 3, 8, 12, 17, 23, 31, 40.", "steps": ["There are 7 items, so the middle is the 4th item: 17.", "23 is bigger than 17, so discard 17 and everything to its left, leaving 23, 31, 40.", "The middle of these 3 items is 31.", "23 is smaller than 31, so discard 31 and 40, leaving 23, which is the target."], "a": "23 is found after 3 comparisons (17, 31, then 23)."}, "walk": [{"h": "Searching", "b": "To find 9 in 4, 9, 2, 7 with linear search, check 4 (no), then 9 (yes): 2 comparisons. Binary search is much faster on big lists: with 1 000 sorted items it needs at most about 10 comparisons, because each check halves the list. But if the list is not sorted, you must use linear search or sort it first."}, {"h": "Bubble and insertion sort", "b": "Bubble sort on 5, 2, 4: compare 5 and 2, swap to get 2, 5, 4; compare 5 and 4, swap to get 2, 4, 5. The biggest value 'bubbles' to the end after each pass. Insertion sort builds a sorted section on the left: with 5, 2, 4 it inserts 2 before 5, then inserts 4 between 2 and 5."}, {"h": "Merge sort", "b": "Merge sort uses 'divide and conquer'. Split 6, 1, 5, 3 into 6 | 1 | 5 | 3, then merge pairs in order to get 1, 6 and 3, 5. Finally merge those two lists by comparing their front items: 1, 3, 5, 6. It is usually much faster than bubble sort for large lists."}], "qs": [["Which search algorithm checks every item in order from the start?", ["Linear search", "Binary search", "Merge sort", "Bubble sort"], "Linear search goes through the list one item at a time."], ["What must be true of a list before you can use binary search?", ["It must be sorted", "It must contain only even numbers", "It must have fewer than 10 items", "It must be unsorted"], "Binary search relies on order to know which half to discard."], ["In binary search, which item is checked first?", ["The middle item", "The first item", "The last item", "A random item"], "Binary search always starts by comparing the target with the middle item."], ["Using linear search on 4, 9, 2, 7, 5, how many comparisons are needed to find 7?", ["4", "3", "1", "5"], "It checks 4, 9, 2 and then 7, which is 4 comparisons."], ["What does bubble sort do on each comparison?", ["Swaps two neighbouring items if they are in the wrong order", "Splits the list in half", "Inserts an item into the sorted section", "Checks the middle item"], "Bubble sort compares adjacent pairs and swaps them if needed."], ["After the first pass of bubble sort (ascending) on 5, 1, 4, 2, what is the list?", ["1, 4, 2, 5", "1, 2, 4, 5", "1, 5, 4, 2", "5, 4, 2, 1"], "5 and 1 swap, 5 and 4 swap, 5 and 2 swap, giving 1, 4, 2, 5."], ["Which sorting algorithm starts by splitting the list into single items?", ["Merge sort", "Bubble sort", "Insertion sort", "Linear sort"], "Merge sort divides the list down to single items, then merges them in order."], ["Merge the sorted lists 2, 7 and 3, 5 in merge sort. What is the result?", ["2, 3, 5, 7", "2, 7, 3, 5", "3, 5, 2, 7", "2, 3, 7, 5"], "Compare front items each time: 2, then 3, then 5, then 7."], ["How does insertion sort work?", ["It puts each item in turn into its correct place in the sorted part", "It repeatedly checks the middle item", "It splits the list in half until single items are left", "It swaps the first and last items"], "Insertion sort grows a sorted section one item at a time."], ["Why is binary search usually faster than linear search on a large sorted list?", ["Each comparison removes half of the remaining items", "It checks every item twice to be sure", "It does not need to compare any items", "It always starts at the end of the list"], "Halving each time means far fewer comparisons, e.g. about 10 for 1 000 items."]], "bonus": ["Put these numbers in ascending order: 14, 3, 27, 9.", ["3, 9, 14, 27", "27, 14, 9, 3", "3, 14, 9, 27", "9, 3, 14, 27"], "Ascending means from smallest to largest."]}]}, {"id": "french", "name": "French", "board": "AQA (8652)", "weeks": [{"ht": "Aut1", "t": "Describing yourself and others", "intro": "This topic teaches you to describe what people look like and what they are like as a person. It uses two of the most important verbs in French, avoir (to have) and être (to be), and you will use them in every GCSE exam.", "how": ["Use être for personality and size: je suis timide, il est grand.", "Use avoir for age, eyes and hair: j'ai quatorze ans, elle a les yeux bleus.", "Make adjectives agree: add -e for feminine, -s for plural, -es for feminine plural.", "Some adjectives change more: sportif becomes sportive, heureux becomes heureuse.", "Most adjectives go after the noun, but small common ones like petit, grand and bon go before it."], "example": {"q": "Translate: My sister is short and she has long brown hair.", "steps": ["My sister is feminine, so it is ma sœur.", "Is short uses être: est petite, with -e because sœur is feminine.", "She has uses avoir: elle a.", "Cheveux is masculine plural, so long brown becomes longs bruns (or châtains)."], "a": "Ma sœur est petite et elle a les cheveux longs et bruns."}, "walk": [{"h": "Avoir and être", "b": "Être means to be: je suis, tu es, il/elle est, ils/elles sont. Avoir means to have: j'ai, tu as, il/elle a, ils/elles ont. In French you have your age, so I am 13 is j'ai treize ans, not je suis treize."}, {"h": "Making adjectives agree", "b": "An adjective must match the person it describes. Il est grand, elle est grande, ils sont grands, elles sont grandes. Words ending in -e already, like timide or drôle, do not add another -e for feminine."}, {"h": "Tricky endings and position", "b": "Some endings change: sportif becomes sportive, paresseux becomes paresseuse, gentil becomes gentille. Colours and most adjectives go after the noun (un chat noir), but petit, grand, bon, beau and jeune go before it (un petit chat noir)."}], "qs": [["A girl says 'I am tall'. Which is correct?", ["Je suis grande.", "J'ai grande.", "Je suis grand.", "Je suis grandes."], "A girl uses être plus the feminine singular form grande."], ["Complete: Il ___ les yeux bleus.", ["a", "est", "as", "ont"], "Eye colour uses avoir, and the il form of avoir is a."], ["Which word means 'funny'?", ["drôle", "timide", "bavard", "méchant"], "Drôle means funny; timide is shy, bavard is chatty and méchant is nasty."], ["What does 'paresseux' mean?", ["lazy", "hard-working", "shy", "generous"], "Paresseux means lazy; hard-working is travailleur."], ["Complete: Elle a les cheveux ___ (long).", ["longs", "long", "longue", "longues"], "Cheveux is masculine plural, so the adjective takes -s: longs."], ["Complete: Mes sœurs sont ___ (sporty).", ["sportives", "sportif", "sportive", "sportifs"], "Sœurs is feminine plural, so sportif becomes sportives."], ["What is the feminine form of 'heureux' (happy)?", ["heureuse", "heureuxe", "heureusse", "heureux"], "Adjectives ending in -eux change to -euse in the feminine."], ["How do you say 'I am fourteen years old'?", ["J'ai quatorze ans.", "Je suis quatorze ans.", "J'ai quatorze.", "Je suis quatorze années."], "French uses avoir for age and you must include the word ans."], ["Translate: My brother is quite tall and he has brown hair.", ["Mon frère est assez grand et il a les cheveux bruns.", "Mon frère a assez grand et il est les cheveux bruns.", "Ma frère est assez grand et il a les cheveux bruns.", "Mon frère est assez grande et il a les cheveux bruns."], "Frère is masculine (mon, grand), size uses être and hair uses avoir."], ["Which is correct for 'a small black cat'?", ["un petit chat noir", "un noir petit chat", "un petit noir chat", "un chat petit noir"], "Petit goes before the noun, but colours like noir go after it."]], "bonus": ["In French, what does 'la' in front of a noun tell you?", ["The noun is feminine and singular", "The noun is masculine and singular", "The noun is plural", "The noun is a verb"], "La means 'the' for feminine singular nouns, such as la maison."]}, {"ht": "Aut2", "t": "Leisure activities", "intro": "This topic is about what you do in your free time, how often you do it and what you think of it. Giving opinions and reasons is one of the easiest ways to gain marks in speaking and writing.", "how": ["Use jouer à for sports and games: au foot, à la pétanque, aux cartes.", "Use jouer de for musical instruments: du piano, de la guitare.", "Use faire de for many other activities: du vélo, de la natation, de l'équitation.", "After j'aime, j'adore, je déteste and je préfère, use the infinitive: j'aime nager.", "Add a frequency word (souvent, parfois, jamais) and a reason (parce que c'est…)."], "example": {"q": "Translate: I often play football because it is fun.", "steps": ["I play a sport is je joue à.", "Football is masculine, so à + le becomes au: je joue au foot.", "Often is souvent, placed after the verb.", "Because it is fun is parce que c'est amusant."], "a": "Je joue souvent au foot parce que c'est amusant."}, "walk": [{"h": "Jouer à and jouer de", "b": "For sports and games, use jouer à: à + le becomes au, à + les becomes aux, and à la stays the same. For instruments, use jouer de: de + le becomes du. So je joue au tennis, but je joue du piano."}, {"h": "Faire de", "b": "Faire (je fais) is used for lots of activities. De + le becomes du, de + la stays de la, and before a vowel you use de l'. For example: je fais du vélo, je fais de la natation, je fais de l'escalade."}, {"h": "Opinions and frequency", "b": "Start with an opinion verb and an infinitive: j'adore regarder la télé, je déteste faire du jogging. Say how often with tous les jours, souvent, parfois or de temps en temps. For never, wrap the verb: je ne joue jamais au rugby."}], "qs": [["Complete: Je joue ___ football.", ["au", "à la", "du", "de la"], "Football is masculine and it is a sport, so à + le becomes au."], ["Complete: Je fais ___ natation.", ["de la", "du", "au", "à la"], "Natation is feminine and uses faire de, so it is de la natation."], ["What does 'souvent' mean?", ["often", "never", "sometimes", "every day"], "Souvent means often; parfois is sometimes and jamais is never."], ["Complete: Je fais ___ vélo.", ["du", "de la", "au", "à le"], "Vélo is masculine and uses faire de, so de + le becomes du."], ["Which means 'I play the piano'?", ["Je joue du piano.", "Je joue au piano.", "Je joue le piano.", "Je joue à piano."], "Instruments use jouer de, and de + le becomes du."], ["What does 'Je ne joue jamais au tennis' mean?", ["I never play tennis.", "I always play tennis.", "I don't like tennis.", "I sometimes play tennis."], "Ne … jamais around the verb means never."], ["Complete: J'aime ___ au basket (playing).", ["jouer", "joue", "jouant", "joué"], "After an opinion verb like aimer, French uses the infinitive."], ["How do you say 'I love going to the cinema'?", ["J'adore aller au cinéma.", "J'adore aller à le cinéma.", "J'adore va au cinéma.", "Je adore aller au cinéma."], "Use the infinitive aller, à + le becomes au, and je shortens to j' before a vowel."], ["Which phrase gives a reason?", ["parce que c'est amusant", "le week-end", "avec mes amis", "de temps en temps"], "Parce que means because, so it introduces a reason."], ["Translate: I go to the swimming pool twice a week.", ["Je vais à la piscine deux fois par semaine.", "Je vais à la piscine deux temps par semaine.", "Je vais au piscine deux fois par semaine.", "Je va à la piscine deux fois par semaine."], "Times is fois, piscine is feminine (à la) and the je form of aller is vais."]], "bonus": ["Which day is 'samedi'?", ["Saturday", "Sunday", "Friday", "Monday"], "Samedi is Saturday; dimanche is Sunday and vendredi is Friday."]}, {"ht": "Spr1", "t": "My town and the weather", "intro": "This topic teaches you to describe where you live, what there is to do and what the weather is like. These phrases come up in every theme of the GCSE, so they are worth learning well.", "how": ["Use il y a for 'there is' or 'there are': il y a un parc.", "For 'there isn't', use il n'y a pas de: il n'y a pas de cinéma.", "Most weather phrases use il fait: il fait chaud, il fait froid, il fait beau.", "Some weather phrases use their own verb: il pleut, il neige.", "Use en for seasons (en été, en hiver, en automne) but au printemps."], "example": {"q": "Translate: In my town there is a park but there isn't a cinema.", "steps": ["Ville is feminine, so in my town is dans ma ville.", "There is a park is il y a un parc.", "But is mais.", "After a negative, un becomes de: il n'y a pas de cinéma."], "a": "Dans ma ville, il y a un parc mais il n'y a pas de cinéma."}, "walk": [{"h": "Il y a", "b": "Il y a means there is or there are. Il y a une piscine (there is a pool), il y a des magasins (there are some shops). Add adjectives to make it richer: il y a beaucoup de magasins."}, {"h": "Saying what's missing", "b": "In the negative, un, une and des all change to de (or d' before a vowel). Il n'y a pas de piscine. Il n'y a pas d'hôpital. You can also give an opinion: c'est nul pour les jeunes."}, {"h": "The weather", "b": "Il fait chaud (hot), il fait froid (cold), il fait beau (nice), il fait mauvais (bad). Il pleut (it rains), il neige (it snows), il y a du vent (windy), il y a du brouillard (foggy). Add a season: en hiver, il fait froid."}], "qs": [["What does 'il fait chaud' mean?", ["It's hot.", "It's cold.", "It's sunny.", "It's windy."], "Chaud means hot; froid means cold."], ["What does 'il pleut' mean?", ["It's raining.", "It's snowing.", "It's cloudy.", "It's windy."], "Il pleut comes from pleuvoir, to rain; it's snowing is il neige."], ["What does 'il y a du brouillard' mean?", ["It's foggy.", "It's stormy.", "It's sunny.", "It's freezing."], "Le brouillard is fog."], ["How do you say 'In my town there is a park'?", ["Dans ma ville, il y a un parc.", "Dans ma ville, il est un parc.", "Dans mon ville, il y a un parc.", "Dans ma ville, il a un parc."], "There is is il y a, and ville is feminine so it takes ma."], ["What does 'Il n'y a pas de cinéma' mean?", ["There isn't a cinema.", "There is a cinema.", "There are some cinemas.", "There is a big cinema."], "Ne … pas makes il y a negative: there isn't."], ["Which means 'There isn't a swimming pool'?", ["Il n'y a pas de piscine.", "Il n'y a de pas piscine.", "Il y a pas de la piscine.", "Il n'y a pas la piscine."], "After a negative, une changes to de, and ne … pas goes around y a."], ["Complete: Ma ville est très ___ (beautiful).", ["belle", "beau", "bel", "beaux"], "Ville is feminine singular, so beau becomes belle."], ["Complete: ___ printemps, il fait doux.", ["Au", "En", "À la", "Dans"], "Printemps is the one season that takes au; the others take en."], ["What does 'il y a beaucoup de magasins' mean?", ["There are lots of shops.", "There are no shops.", "There are a few shops.", "There is a big shop."], "Beaucoup de means lots of or many."], ["Translate: In winter it is cold and it snows.", ["En hiver, il fait froid et il neige.", "Au hiver, il fait froid et il neige.", "En hiver, il est froid et il neige.", "En hiver, il fait froid et il pleut."], "Winter takes en, cold weather uses il fait and it snows is il neige."]], "bonus": ["Which word is the opposite of 'grand'?", ["petit", "gros", "long", "haut"], "Grand means big or tall, and petit means small."]}, {"ht": "Spr2", "t": "School, timetable, rules and uniform", "intro": "This topic is about your school day: your subjects, the timetable, the rules and what you wear. You will learn two key structures for rules, il faut and il est interdit de, which are useful all through GCSE.", "how": ["Use le, la or les with subjects after opinion verbs: j'aime les maths.", "Tell the time with à … heures: à neuf heures, à dix heures et demie.", "Il faut + infinitive means you must: il faut porter un uniforme.", "Il est interdit de + infinitive means it is forbidden to: il est interdit de courir.", "Uniform colours are adjectives, so they agree: une jupe grise, des chaussures noires."], "example": {"q": "Translate: You must wear a tie but it is forbidden to wear jewellery.", "steps": ["You must is il faut, followed by the infinitive porter.", "A tie is une cravate.", "It is forbidden to is il est interdit de, also followed by an infinitive.", "Jewellery is des bijoux, and porter stays in the infinitive both times."], "a": "Il faut porter une cravate mais il est interdit de porter des bijoux."}, "walk": [{"h": "Subjects and timetable", "b": "Subjects include les maths, le français, l'histoire, la géographie and les sciences. Give the day and time: le lundi, j'ai maths à neuf heures. Le lundi means on Mondays, every week."}, {"h": "School rules", "b": "Il faut + infinitive means you must: il faut arriver à l'heure. Il est interdit de + infinitive means you're not allowed to: il est interdit d'utiliser son portable. Both are followed by the infinitive, not a conjugated verb."}, {"h": "Uniform and opinions", "b": "Je porte un pantalon noir, une chemise blanche et une cravate. Colours agree with the noun: une veste bleue. Add an opinion: je n'aime pas l'uniforme parce que c'est démodé."}], "qs": [["What is 'la récré'?", ["break time", "lunch", "assembly", "homework"], "La récré (la récréation) is break time; lunch is le déjeuner."], ["What is 'une cravate'?", ["a tie", "a jumper", "a skirt", "a blazer"], "Une cravate is a tie; a jumper is un pull and a skirt is une jupe."], ["Which is correct for 'I like science'?", ["J'aime les sciences.", "J'aime sciences.", "Je aime les sciences.", "J'aime le sciences."], "French needs the article les with subjects, and je becomes j' before a vowel."], ["What does 'à dix heures et demie' mean?", ["at half past ten", "at half past nine", "at quarter past ten", "at ten to ten"], "Et demie means half past, so dix heures et demie is 10:30."], ["What does 'Il faut porter un uniforme' mean?", ["You must wear a uniform.", "You can wear a uniform.", "You mustn't wear a uniform.", "I like wearing a uniform."], "Il faut means you must or it is necessary to."], ["What does 'Il est interdit de mâcher du chewing-gum' mean?", ["Chewing gum is forbidden.", "Chewing gum is allowed.", "You must chew gum.", "Chewing gum is sold here."], "Il est interdit de means it is forbidden to."], ["Complete: Je porte une jupe ___ (grey).", ["grise", "gris", "grises", "grisse"], "Jupe is feminine singular, so gris becomes grise."], ["Complete: Il est interdit d'___ son portable en classe.", ["utiliser", "utilise", "utilisons", "utilisé"], "Il est interdit de is always followed by an infinitive."], ["What does 'Je n'aime pas l'histoire car c'est ennuyeux' mean?", ["I don't like history because it's boring.", "I like history because it's interesting.", "I don't like history because it's hard.", "I like history but it's boring."], "Ne … pas is negative, car means because and ennuyeux means boring."], ["Translate: You must not run in the corridors.", ["Il est interdit de courir dans les couloirs.", "Il faut courir dans les couloirs.", "Il est interdit de cours dans les couloirs.", "Il est interdit courir dans les couloirs."], "Forbidden is il est interdit de, followed by the infinitive courir."]], "bonus": ["How do you say 'nine' in French?", ["neuf", "dix", "huit", "sept"], "Neuf is nine; dix is ten, huit is eight and sept is seven."]}, {"ht": "Sum1", "t": "Health and healthy living", "intro": "This topic teaches you the parts of the body, how to say what hurts, and how to talk about healthy and unhealthy habits. It links to the theme of lifestyle, which often appears in GCSE reading and listening papers.", "how": ["To say something hurts, use j'ai mal + à + the body part.", "À + le becomes au (j'ai mal au dos), à + les becomes aux (j'ai mal aux dents).", "À la and à l' do not change: j'ai mal à la tête, j'ai mal à l'oreille.", "After quantities like beaucoup, trop and peu, use de: beaucoup de fruits.", "Use frequency words for habits: je mange des légumes tous les jours."], "example": {"q": "Translate: I have a sore throat and my feet hurt.", "steps": ["Sore throat uses j'ai mal à + la gorge: j'ai mal à la gorge.", "Feet is plural (les pieds), so à + les becomes aux.", "Join with et (and).", "You only need j'ai mal once if you want, but repeating it is also correct."], "a": "J'ai mal à la gorge et j'ai mal aux pieds."}, "walk": [{"h": "Parts of the body", "b": "Learn la tête (head), le bras (arm), la main (hand), la jambe (leg), le pied (foot), le dos (back), le ventre (stomach), la gorge (throat) and les dents (teeth). Knowing whether each is le, la or les helps with the next step."}, {"h": "J'ai mal à…", "b": "J'ai mal means I have pain. Then use à with the body part: j'ai mal à la tête (headache), j'ai mal au ventre (stomach ache), j'ai mal aux dents (toothache). Never say à le or à les; they always become au and aux."}, {"h": "Healthy and unhealthy habits", "b": "Healthy: je bois beaucoup d'eau, je fais du sport, je me couche tôt. Unhealthy: je mange trop de sucre, je ne dors pas assez. After beaucoup, trop and peu, use de or d', never des."}], "qs": [["What does 'J'ai mal à la tête' mean?", ["I have a headache.", "I have stomach ache.", "I have a sore throat.", "I have toothache."], "La tête is the head, so it means my head hurts."], ["What does 'la jambe' mean?", ["leg", "arm", "foot", "back"], "La jambe is the leg; arm is le bras and foot is le pied."], ["Complete: J'ai mal ___ ventre.", ["au", "à la", "aux", "à le"], "Ventre is masculine, so à + le becomes au."], ["Complete: J'ai mal ___ gorge.", ["à la", "au", "aux", "à le"], "Gorge is feminine, and à la does not change."], ["Complete: J'ai mal ___ dents.", ["aux", "au", "à la", "à les"], "Dents is plural, so à + les becomes aux."], ["Which is a healthy habit?", ["Je bois beaucoup d'eau.", "Je fume tous les jours.", "Je mange des bonbons tous les jours.", "Je me couche à deux heures du matin."], "Drinking lots of water is healthy; the others are unhealthy."], ["What does 'Je mange trop de sucre' mean?", ["I eat too much sugar.", "I eat a little sugar.", "I don't eat sugar.", "I eat a lot of salt."], "Trop de means too much and le sucre is sugar."], ["Complete: Je mange beaucoup ___ légumes.", ["de", "des", "du", "les"], "After a quantity like beaucoup, French uses de, not des."], ["Translate: My arm hurts.", ["J'ai mal au bras.", "J'ai mal à le bras.", "J'ai mal à la bras.", "Je suis mal au bras."], "Bras is masculine, so à + le becomes au, and the phrase uses avoir."], ["Which means 'I go to bed early'?", ["Je me couche tôt.", "Je me lève tôt.", "Je me couche tard.", "Je couche tôt."], "Se coucher means to go to bed and tôt means early; se lever means to get up."]], "bonus": ["Which French word means 'water'?", ["l'eau", "le lait", "le pain", "le jus"], "L'eau is water; le lait is milk, le pain is bread and le jus is juice."]}, {"ht": "Sum2", "t": "Plans to stay healthy: the future", "intro": "This topic teaches you to talk about your future plans to be healthy. You will learn the near future (aller + infinitive) and the simple future tense, which help you reach higher grades by using more than one time frame.", "how": ["Near future: present tense of aller + infinitive, for example je vais manger.", "Aller: je vais, tu vas, il/elle va, nous allons, vous allez, ils/elles vont.", "Simple future: add -ai, -as, -a, -ons, -ez, -ont to the infinitive: je mangerai.", "Learn key irregular future stems: aller → ir- (j'irai), faire → fer- (je ferai), être → ser-, avoir → aur-.", "In the near future negative, ne … pas goes around aller: je ne vais pas fumer."], "example": {"q": "Translate: Next year I am going to eat more fruit and I will do more sport.", "steps": ["Next year is l'année prochaine.", "I am going to eat is the near future: je vais manger.", "More fruit is plus de fruits.", "I will do is the simple future of faire: je ferai, then plus de sport."], "a": "L'année prochaine, je vais manger plus de fruits et je ferai plus de sport."}, "walk": [{"h": "The near future", "b": "To say what you are going to do, use aller in the present plus an infinitive. Je vais boire plus d'eau (I'm going to drink more water). Nous allons faire du vélo (we are going to go cycling). The second verb never changes."}, {"h": "The simple future", "b": "To say what you will do, take the infinitive and add the endings -ai, -as, -a, -ons, -ez, -ont. Je jouerai (I will play), nous mangerons (we will eat). For -re verbs, drop the final e: boire → je boirai."}, {"h": "Irregulars and negatives", "b": "Some verbs have special stems: j'irai (I will go), je ferai (I will do), je serai (I will be), j'aurai (I will have). In the near future negative, ne … pas wraps aller: je ne vais pas manger de chips. Use time phrases like demain, la semaine prochaine and à l'avenir."}], "qs": [["What does 'Je vais manger' mean?", ["I'm going to eat.", "I ate.", "I eat.", "I would eat."], "Aller + infinitive is the near future: going to."], ["How do you say 'I am going to play'?", ["Je vais jouer.", "Je vais joue.", "Je va jouer.", "Je suis jouer."], "Use je vais plus the infinitive jouer."], ["Complete: Nous ___ faire du sport.", ["allons", "allez", "vont", "vais"], "The nous form of aller is allons."], ["Which time phrase tells you a sentence is about the future?", ["l'année prochaine", "l'année dernière", "hier", "d'habitude"], "L'année prochaine means next year; the others refer to the past or habits."], ["What does 'je mangerai' mean?", ["I will eat.", "I ate.", "I am eating.", "I would eat."], "The -ai ending on the infinitive is the simple future; would eat is mangerais."], ["What is the future tense of 'faire' with je?", ["je ferai", "je fairai", "je ferais", "je fais"], "Faire has the irregular future stem fer-, so it is je ferai."], ["What is the future tense of 'aller' with je?", ["j'irai", "j'allerai", "j'irais", "je vais"], "Aller has the irregular future stem ir-, so it is j'irai."], ["What does 'Je ne vais pas fumer' mean?", ["I'm not going to smoke.", "I'm going to smoke.", "I don't smoke.", "I didn't smoke."], "Ne … pas around vais makes the near future negative."], ["Translate: I'm not going to eat crisps.", ["Je ne vais pas manger de chips.", "Je ne vais manger pas de chips.", "Je vais pas ne manger de chips.", "Je ne pas vais manger de chips."], "Ne … pas goes around the verb aller, and des becomes de after a negative."], ["Translate: Next week I will go to the gym.", ["La semaine prochaine, j'irai à la salle de sport.", "La semaine dernière, j'irai à la salle de sport.", "La semaine prochaine, j'allerai à la salle de sport.", "La semaine prochaine, j'irais à la salle de sport."], "Next week is la semaine prochaine and I will go is j'irai."]], "bonus": ["What does the verb 'aller' mean?", ["to go", "to have", "to do", "to be"], "Aller is to go; avoir is to have, faire is to do and être is to be."]}]}, {"id": "spanish", "name": "Spanish", "board": "AQA (8698)", "weeks": [{"ht": "Aut1", "t": "Describing yourself and others", "intro": "This topic teaches you to describe what people look like and what they are like as a person. It uses two key verbs, ser (to be) and tener (to have), which you will need in every part of the GCSE.", "how": ["Use ser for personality and looks: soy simpático, es alta.", "Use tener for age, eyes and hair: tengo catorce años, tiene los ojos azules.", "Adjectives ending in -o change to -a for feminine: alto, alta.", "Add -s for plural after a vowel (altos) and -es after a consonant (azules).", "Adjectives usually go after the noun: un perro negro."], "example": {"q": "Translate: My sister is short and she has long brown hair.", "steps": ["My sister is mi hermana.", "Is short uses ser: es baja, with -a because hermana is feminine.", "She has uses tener: tiene.", "Pelo is masculine singular, so long brown is largo y castaño."], "a": "Mi hermana es baja y tiene el pelo largo y castaño."}, "walk": [{"h": "Ser and tener", "b": "Ser means to be: soy, eres, es, somos, sois, son. Tener means to have: tengo, tienes, tiene, tenemos, tenéis, tienen. In Spanish you have your age, so I am 13 is tengo trece años."}, {"h": "Adjective agreement", "b": "Adjectives match the noun. Él es alto, ella es alta, ellos son altos, ellas son altas. Adjectives ending in -e or a consonant, like inteligente or azul, are the same for masculine and feminine: es inteligente, ojos azules."}, {"h": "Hair, eyes and extras", "b": "Tengo el pelo corto y rizado (short curly hair). Tengo los ojos marrones (brown eyes). Use qualifiers to add detail: muy (very), bastante (quite), un poco (a bit). For example: mi padre es bastante gracioso."}], "qs": [["A girl says 'I am tall'. Which is correct?", ["Soy alta.", "Tengo alta.", "Soy alto.", "Soy altas."], "A girl uses ser and the feminine singular form alta."], ["Complete: Él ___ los ojos verdes.", ["tiene", "es", "tienes", "tengo"], "Eye colour uses tener, and the él form is tiene."], ["What does 'gracioso' mean?", ["funny", "shy", "lazy", "serious"], "Gracioso means funny; tímido is shy and perezoso is lazy."], ["What does 'perezosa' mean?", ["lazy", "hard-working", "kind", "chatty"], "Perezosa means lazy; hard-working is trabajadora."], ["How do you say 'I am fourteen years old'?", ["Tengo catorce años.", "Soy catorce años.", "Tengo catorce.", "Estoy catorce años."], "Spanish uses tener for age and needs the word años."], ["Complete: Mis hermanas son ___ (tall).", ["altas", "alto", "alta", "altos"], "Hermanas is feminine plural, so alto becomes altas."], ["Complete: Tengo los ojos ___ (blue).", ["azules", "azuls", "azul", "azulas"], "Azul ends in a consonant, so the plural adds -es."], ["Which adjective stays the same for a boy and a girl?", ["inteligente", "simpático", "alto", "tímido"], "Adjectives ending in -e do not change for feminine; the others change -o to -a."], ["Translate: My brother is quite tall and he has brown hair.", ["Mi hermano es bastante alto y tiene el pelo castaño.", "Mi hermano tiene bastante alto y es el pelo castaño.", "Mi hermano es bastante alta y tiene el pelo castaño.", "Mi hermano es bastante alto y tiene el pelo castaña."], "Size uses ser, hair uses tener, and everything agrees with masculine words."], ["Which is correct for 'a black dog'?", ["un perro negro", "un negro perro", "una perro negra", "un perro negra"], "Perro is masculine and colours go after the noun."]], "bonus": ["In Spanish, what does 'la' in front of a noun tell you?", ["The noun is feminine and singular", "The noun is masculine and singular", "The noun is plural", "The noun is a verb"], "La means 'the' for feminine singular nouns, such as la casa."]}, {"ht": "Aut2", "t": "Leisure activities", "intro": "This topic is about your free time: sports, hobbies and what you like doing. You will learn jugar a, hacer and gustar, so you can say what you do, how often and what you think of it.", "how": ["Use jugar a for sports and games: juego al fútbol (a + el becomes al).", "Use hacer for many activities: hago natación, hago equitación.", "Me gusta + infinitive or singular noun: me gusta nadar, me gusta el tenis.", "Me gustan + plural noun: me gustan los videojuegos.", "Add frequency words: a menudo, a veces, todos los días, nunca."], "example": {"q": "Translate: I often play football because it is fun.", "steps": ["I play is juego (from jugar).", "Sports use jugar a, and a + el becomes al: al fútbol.", "Often is a menudo.", "Because it is fun is porque es divertido."], "a": "A menudo juego al fútbol porque es divertido."}, "walk": [{"h": "Jugar a and hacer", "b": "Jugar is a stem-changing verb: juego, juegas, juega. For sports, add a: juego al baloncesto, juego a la pelota. Many other activities use hacer (hago): hago deporte, hago ciclismo."}, {"h": "Using gustar", "b": "Me gusta literally means it pleases me. Use me gusta with one thing or an infinitive: me gusta leer. Use me gustan with plural things: me gustan los deportes. For dislike, add no: no me gusta bailar. Me encanta means I love."}, {"h": "Frequency and reasons", "b": "Say how often: todos los días (every day), a menudo (often), a veces (sometimes), nunca (never). Give a reason with porque: porque es emocionante. To ask someone, say ¿Qué haces en tu tiempo libre? Nunca can go before the verb: nunca juego al rugby."}], "qs": [["Complete: Juego ___ tenis.", ["al", "a el", "el", "la"], "Sports use jugar a, and a + el combines to al."], ["What does 'a veces' mean?", ["sometimes", "often", "never", "always"], "A veces means sometimes; a menudo is often and nunca is never."], ["Which means 'I go swimming'?", ["Hago natación.", "Juego natación.", "Hago al natación.", "Soy natación."], "Activities like swimming use hacer: hago natación."], ["Complete: Me ___ los videojuegos.", ["gustan", "gusta", "gusto", "gustas"], "Videojuegos is plural, so it needs gustan."], ["Complete: Me ___ leer.", ["gusta", "gustan", "gusto", "gustar"], "With an infinitive you always use gusta."], ["What does 'Me encanta bailar' mean?", ["I love dancing.", "I hate dancing.", "I don't like dancing.", "I can dance."], "Me encanta means I love."], ["What is the yo form of jugar?", ["juego", "jugo", "juega", "jugamos"], "Jugar changes u to ue, so I play is juego."], ["What does 'Nunca juego al rugby' mean?", ["I never play rugby.", "I always play rugby.", "I sometimes play rugby.", "I don't like rugby."], "Nunca before the verb means never."], ["Translate: I don't like playing basketball because it's boring.", ["No me gusta jugar al baloncesto porque es aburrido.", "Me no gusta jugar al baloncesto porque es aburrido.", "No me gustan jugar al baloncesto porque es aburrido.", "No me gusta juego al baloncesto porque es aburrido."], "No goes before me, gusta goes with an infinitive, and jugar stays in the infinitive."], ["Translate: I go to the cinema twice a week.", ["Voy al cine dos veces a la semana.", "Voy a el cine dos veces a la semana.", "Voy al cine dos tiempos a la semana.", "Va al cine dos veces a la semana."], "A + el becomes al, times is veces, and I go is voy."]], "bonus": ["Which day is 'sábado'?", ["Saturday", "Sunday", "Friday", "Monday"], "Sábado is Saturday; domingo is Sunday and viernes is Friday."]}, {"ht": "Spr1", "t": "My town and the weather", "intro": "This topic teaches you to describe where you live, what there is in your town and what the weather is like. These phrases are useful across the whole GCSE, especially in speaking.", "how": ["Use hay for 'there is' or 'there are': hay un parque, hay tiendas.", "For 'there isn't', use no hay: no hay cine (no un or una needed).", "Many weather phrases use hace: hace calor, hace frío, hace sol, hace viento.", "Some use their own verb: llueve (it rains), nieva (it snows).", "Use está for some weather: está nublado (it's cloudy)."], "example": {"q": "Translate: In my town there is a park but there isn't a cinema.", "steps": ["In my town is en mi ciudad (or en mi pueblo).", "There is a park is hay un parque.", "But is pero.", "There isn't a cinema is no hay cine; you drop un in the negative."], "a": "En mi ciudad hay un parque pero no hay cine."}, "walk": [{"h": "Hay and no hay", "b": "Hay means there is or there are: hay una piscina, hay muchas tiendas. In the negative, just put no in front and usually drop un or una: no hay piscina. You can add an opinion: no hay mucho para los jóvenes."}, {"h": "Describing your town", "b": "Use ser for what the town is like: mi ciudad es bonita, es ruidosa, es tranquila. Ciudad is feminine, so adjectives end in -a. Use está for where it is: está en el norte de Inglaterra."}, {"h": "The weather", "b": "Hace calor (hot), hace frío (cold), hace sol (sunny), hace viento (windy), hace buen tiempo (nice weather). Llueve (it rains), nieva (it snows), hay niebla (foggy), está nublado (cloudy). Add a season: en invierno hace frío."}], "qs": [["What does 'hace frío' mean?", ["It's cold.", "It's hot.", "It's sunny.", "It's windy."], "Frío means cold; hot is hace calor."], ["What does 'llueve' mean?", ["It's raining.", "It's snowing.", "It's cloudy.", "It's foggy."], "Llueve comes from llover, to rain; nieva means it snows."], ["What does 'hay niebla' mean?", ["It's foggy.", "It's stormy.", "It's sunny.", "It's cold."], "La niebla is fog."], ["How do you say 'There is a park'?", ["Hay un parque.", "Es un parque.", "Está un parque.", "Tiene un parque."], "Hay means there is or there are."], ["What does 'No hay cine' mean?", ["There isn't a cinema.", "There is a cinema.", "There are many cinemas.", "The cinema is closed."], "No hay means there isn't or there aren't."], ["Complete: ___ calor en verano.", ["Hace", "Es", "Hay", "Está"], "Hot weather uses hace: hace calor."], ["Complete: Mi ciudad es muy ___ (pretty).", ["bonita", "bonito", "bonitas", "bonitos"], "Ciudad is feminine singular, so it is bonita."], ["What does 'está nublado' mean?", ["It's cloudy.", "It's raining.", "It's sunny.", "It's snowing."], "Nublado means cloudy, from la nube (cloud)."], ["What does '¿Qué tiempo hace?' mean?", ["What's the weather like?", "What time is it?", "How long does it take?", "What are you doing?"], "Tiempo here means weather, and ¿Qué tiempo hace? asks about it; what time is it is ¿Qué hora es?"], ["Translate: In winter it is cold and it snows.", ["En invierno hace frío y nieva.", "En invierno es frío y nieva.", "En invierno hace frío y llueve.", "En verano hace frío y nieva."], "Winter is invierno, cold weather uses hace and it snows is nieva."]], "bonus": ["Which word is the opposite of 'grande'?", ["pequeño", "largo", "alto", "gordo"], "Grande means big, and pequeño means small."]}, {"ht": "Spr2", "t": "School, timetable, rules and uniform", "intro": "This topic covers your school day: subjects, timetable, rules and uniform. You will learn hay que and está prohibido for rules, which are simple structures that impress examiners.", "how": ["Use the article with subjects after gustar: me gustan las ciencias, me gusta el inglés.", "Tell the time with a la una, a las dos, a las nueve y media.", "Hay que + infinitive means you must: hay que llevar uniforme.", "Está prohibido + infinitive means it is forbidden to: está prohibido correr.", "Uniform colours agree: una falda gris, una camisa blanca, unos zapatos negros."], "example": {"q": "Translate: You must wear a tie but it is forbidden to wear jewellery.", "steps": ["You must is hay que, followed by the infinitive llevar.", "A tie is una corbata.", "It is forbidden is está prohibido, also followed by an infinitive.", "Jewellery is joyas."], "a": "Hay que llevar una corbata pero está prohibido llevar joyas."}, "walk": [{"h": "Subjects and timetable", "b": "Subjects include las matemáticas, el inglés, la historia, la geografía and las ciencias. Give the day and time: los lunes tengo matemáticas a las nueve. Los lunes means on Mondays, every week."}, {"h": "School rules", "b": "Hay que + infinitive means you have to: hay que llegar a tiempo. Está prohibido + infinitive means it's forbidden: está prohibido usar el móvil. No se puede also means you can't: no se puede comer chicle."}, {"h": "Uniform and opinions", "b": "Llevo un jersey azul, una camisa blanca y una corbata. Colours agree with the noun: una chaqueta negra. Give an opinion: no me gusta el uniforme porque es incómodo."}], "qs": [["What is 'el recreo'?", ["break time", "lunch", "assembly", "homework"], "El recreo is break time; lunch is la comida or el almuerzo."], ["What is 'una corbata'?", ["a tie", "a skirt", "a jumper", "a blazer"], "Una corbata is a tie; una falda is a skirt and un jersey is a jumper."], ["Which is correct for 'I like science'?", ["Me gustan las ciencias.", "Me gusta las ciencias.", "Me gustan ciencias.", "Yo gusto las ciencias."], "Ciencias is plural, so it needs gustan and the article las."], ["What does 'a las diez y media' mean?", ["at half past ten", "at half past nine", "at quarter past ten", "at ten to ten"], "Y media means half past, so diez y media is 10:30."], ["What does 'Hay que llevar uniforme' mean?", ["You have to wear uniform.", "There is a uniform.", "You can't wear uniform.", "I like wearing uniform."], "Hay que + infinitive means you have to or you must."], ["What does 'Está prohibido comer chicle' mean?", ["Chewing gum is forbidden.", "You must chew gum.", "Chewing gum is allowed.", "Chewing gum is sold here."], "Está prohibido means it is forbidden."], ["Complete: Llevo una falda ___ (black).", ["negra", "negro", "negras", "negros"], "Falda is feminine singular, so negro becomes negra."], ["Complete: Está prohibido ___ el móvil en clase.", ["usar", "uso", "usa", "usamos"], "Está prohibido is followed by an infinitive."], ["What does 'No me gusta la historia porque es aburrida' mean?", ["I don't like history because it's boring.", "I like history because it's interesting.", "I don't like history because it's hard.", "I like history but it's boring."], "No me gusta is I don't like, porque is because and aburrida is boring."], ["Translate: You must arrive on time.", ["Hay que llegar a tiempo.", "Hay llegar a tiempo.", "Hay que llego a tiempo.", "Está prohibido llegar a tiempo."], "You must is hay que plus the infinitive llegar."]], "bonus": ["How do you say 'nine' in Spanish?", ["nueve", "diez", "ocho", "siete"], "Nueve is nine; diez is ten, ocho is eight and siete is seven."]}, {"ht": "Sum1", "t": "Health and healthy living", "intro": "This topic teaches you body parts, how to say what hurts, and how to talk about healthy and unhealthy habits. Health and lifestyle often appear in GCSE reading and listening papers.", "how": ["To say something hurts, use me duele + a singular body part: me duele la cabeza.", "Use me duelen with a plural body part: me duelen los pies.", "Spanish uses el, la, los, las with body parts, not 'my': me duele la pierna.", "Tengo dolor de… also works: tengo dolor de garganta.", "Use frequency words for habits: como fruta todos los días, nunca fumo."], "example": {"q": "Translate: I have a sore throat and my feet hurt.", "steps": ["Throat is la garganta, which is singular, so me duele la garganta.", "Feet is los pies, which is plural, so the verb becomes duelen.", "Join with y (and).", "Use los, not mis, with body parts."], "a": "Me duele la garganta y me duelen los pies."}, "walk": [{"h": "Parts of the body", "b": "Learn la cabeza (head), el brazo (arm), la mano (hand), la pierna (leg), el pie (foot), la espalda (back), el estómago (stomach), la garganta (throat) and los dientes (teeth). Note that la mano is feminine even though it ends in -o."}, {"h": "Me duele and me duelen", "b": "Doler works like gustar. One thing hurts: me duele el brazo. More than one thing hurts: me duelen los ojos. For someone else, change me to le: le duele la espalda (his or her back hurts)."}, {"h": "Healthy and unhealthy habits", "b": "Healthy: bebo mucha agua, hago ejercicio, duermo ocho horas. Unhealthy: como demasiados dulces, bebo muchos refrescos. Agua is feminine, so it takes mucha, even though you say el agua."}], "qs": [["What does 'Me duele la cabeza' mean?", ["I have a headache.", "I have stomach ache.", "I have a sore back.", "I have toothache."], "La cabeza is the head, so my head hurts."], ["What does 'la pierna' mean?", ["leg", "arm", "foot", "hand"], "La pierna is the leg; arm is el brazo and foot is el pie."], ["What does 'la espalda' mean?", ["back", "shoulder", "stomach", "neck"], "La espalda is the back; stomach is el estómago."], ["Complete: Me ___ los pies.", ["duelen", "duele", "dolor", "duelo"], "Pies is plural, so the verb is duelen."], ["Complete: Me ___ el estómago.", ["duele", "duelen", "duelo", "dolor"], "Estómago is singular, so the verb is duele."], ["Which is a healthy habit?", ["Bebo mucha agua.", "Fumo todos los días.", "Como caramelos todos los días.", "Me acuesto a las tres de la mañana."], "Drinking lots of water is healthy; the others are unhealthy."], ["What does 'Como demasiados dulces' mean?", ["I eat too many sweets.", "I eat a few sweets.", "I never eat sweets.", "I eat lots of vegetables."], "Demasiados means too many and dulces are sweets."], ["Which is correct for 'My arm hurts'?", ["Me duele el brazo.", "Me duele mi brazo.", "Me duelen el brazo.", "Tengo duele el brazo."], "Spanish uses el with body parts and duele for one thing."], ["What does 'Le duelen los dientes' mean?", ["He or she has toothache.", "I have toothache.", "You have toothache.", "His teeth are white."], "Le means to him or her, and duelen los dientes means the teeth hurt."], ["Translate: I don't sleep enough.", ["No duermo lo suficiente.", "No dormo lo suficiente.", "No duermo demasiado.", "Duermo no lo suficiente."], "Dormir changes o to ue (duermo), and no goes before the verb."]], "bonus": ["Which Spanish word means 'water'?", ["el agua", "la leche", "el pan", "el zumo"], "El agua is water; la leche is milk, el pan is bread and el zumo is juice."]}, {"ht": "Sum2", "t": "Plans to stay healthy: the future", "intro": "This topic teaches you to talk about your future plans to be healthy. You will learn the near future (ir a + infinitive) and the simple future tense, which help you reach higher grades by using more than one time frame.", "how": ["Near future: present tense of ir + a + infinitive, for example voy a comer.", "Ir: voy, vas, va, vamos, vais, van.", "Simple future: add -é, -ás, -á, -emos, -éis, -án to the infinitive: comeré.", "Learn key irregular future stems: hacer → har- (haré), tener → tendr- (tendré), poder → podr- (podré).", "For negatives, put no before the verb: no voy a fumar."], "example": {"q": "Translate: Next year I am going to eat more fruit and I will do more exercise.", "steps": ["Next year is el año que viene (or el próximo año).", "I am going to eat is the near future: voy a comer.", "More fruit is más fruta.", "I will do is the simple future of hacer: haré, then más ejercicio."], "a": "El año que viene voy a comer más fruta y haré más ejercicio."}, "walk": [{"h": "The near future", "b": "To say what you are going to do, use ir in the present, then a, then an infinitive. Voy a beber más agua (I'm going to drink more water). ¡Vamos a correr! (we are going to run!). Don't forget the little word a."}, {"h": "The simple future", "b": "To say what you will do, take the whole infinitive and add -é, -ás, -á, -emos, -éis, -án. Jugaré (I will play), comeremos (we will eat), vivirán (they will live). The endings are the same for -ar, -er and -ir verbs, and most carry an accent."}, {"h": "Irregulars and time phrases", "b": "Some verbs change their stem: haré (I will do), tendré (I will have), podré (I will be able), saldré (I will go out). Use future time phrases like mañana, la semana que viene and en el futuro. For negatives, no goes first: no comeré comida basura."}], "qs": [["What does 'Voy a comer' mean?", ["I'm going to eat.", "I ate.", "I eat.", "I would eat."], "Ir a + infinitive is the near future: going to."], ["How do you say 'I am going to play'?", ["Voy a jugar.", "Voy jugar.", "Va a jugar.", "Voy a juego."], "Use voy, then a, then the infinitive jugar."], ["Complete: Nosotros ___ a hacer deporte.", ["vamos", "vais", "van", "voy"], "The nosotros form of ir is vamos."], ["Which time phrase tells you a sentence is about the future?", ["la semana que viene", "la semana pasada", "ayer", "normalmente"], "La semana que viene means next week; the others refer to the past or habits."], ["What does 'comeré' mean?", ["I will eat.", "I ate.", "I am eating.", "I would eat."], "The -é ending on the infinitive is the simple future; would eat is comería."], ["What is the future tense of 'hacer' with yo?", ["haré", "haceré", "hacería", "hago"], "Hacer has the irregular future stem har-, so it is haré."], ["What is the future tense of 'tener' with yo?", ["tendré", "teneré", "tengo", "tendría"], "Tener has the irregular future stem tendr-, so it is tendré."], ["What does 'No voy a fumar' mean?", ["I'm not going to smoke.", "I'm going to smoke.", "I don't smoke.", "I didn't smoke."], "No before voy a makes the near future negative."], ["Complete: Mañana mis amigos ___ al gimnasio (will go).", ["irán", "iré", "irá", "van"], "Ellos takes -án, and ir keeps its infinitive as the stem: irán."], ["Translate: Next week I will go to the gym.", ["La semana que viene iré al gimnasio.", "La semana pasada iré al gimnasio.", "La semana que viene iría al gimnasio.", "La semana que viene iré a el gimnasio."], "Next week is la semana que viene, I will go is iré, and a + el becomes al."]], "bonus": ["What does the verb 'ir' mean?", ["to go", "to have", "to do", "to be"], "Ir is to go; tener is to have, hacer is to do and ser is to be."]}]}, {"id": "arabic", "name": "Arabic", "board": "Pearson Edexcel (1AA0)", "weeks": [{"ht": "Aut1", "t": "Describing yourself and others", "intro": "In this topic you learn to describe what people look like and what they are like, using adjectives such as طويل (tall) and ذكي (clever). In Arabic, adjectives must match the person: masculine for a boy or man, feminine for a girl or woman. Getting this right is one of the easiest ways to pick up marks in speaking and writing.", "how": ["In the present tense Arabic has no word for 'is' or 'am': أنا طويل means 'I am tall'.", "Add ة (taa marbuta) to most adjectives to make them feminine: ذكي becomes ذكية.", "Colour adjectives have a special feminine form: أسود becomes سوداء and أزرق becomes زرقاء.", "Add ـي to a noun to say 'my': شعر (hair) becomes شعري (my hair), أخ becomes أخي (my brother).", "Plural things that are not people (like eyes) take a feminine singular adjective: عيوني بنية (my eyes are brown)."], "example": {"q": "Translate into Arabic: My sister is tall and funny, and her hair is black.", "steps": ["'My sister' is أختي, so every adjective about her must be feminine.", "Tall becomes طويلة and funny becomes مضحكة (both with ة).", "'Her hair' is شعرها, and شعر is a masculine word, so 'black' stays masculine: أسود.", "Join the parts with و (and): أختي طويلة ومضحكة، وشعرها أسود."], "a": "أختي طويلة ومضحكة، وشعرها أسود."}, "walk": [{"h": "Pronouns and 'to be'", "b": "Learn the pronouns أنا (I), أنتَ (you, to a boy), أنتِ (you, to a girl), هو (he) and هي (she). Put a pronoun or a name next to an adjective and you have a sentence, because 'is' is understood. For example, هو هادئ means 'he is calm'."}, {"h": "Masculine and feminine", "b": "Most adjectives add ة for a female: لطيف (kind, m) becomes لطيفة (kind, f). So you say أخي لطيف (my brother is kind) but أختي لطيفة (my sister is kind). Nationality words work the same way: لبناني becomes لبنانية."}, {"h": "Appearance and negatives", "b": "For looks, describe hair and eyes: شعري قصير (my hair is short) and عيوني زرقاء (my eyes are blue). Colours have special feminine forms: أسود/سوداء, أبيض/بيضاء, أزرق/زرقاء. To say 'I am not', use لستُ with the adjective ending in ـاً: أنا لستُ كسولاً (I am not lazy)."}], "qs": [["What is the feminine form of طويل (tall)?", ["طويلة", "طويلون", "طوال", "طويلاً"], "Most adjectives become feminine by adding ة, so طويل becomes طويلة."], ["Which pronoun means 'she'?", ["هي", "هو", "أنتِ", "أنا"], "هي means 'she'; هو is 'he', أنتِ is 'you' (to a girl) and أنا is 'I'."], ["What does مضحك mean?", ["Funny", "Lazy", "Calm", "Short"], "مضحك means funny; lazy is كسول, calm is هادئ and short is قصير."], ["Complete the sentence: أختي ___ (My sister is clever.)", ["ذكية", "ذكي", "أذكياء", "ذكيان"], "أختي is a girl, so the adjective needs the feminine ending: ذكية."], ["Which word is the opposite of طويل (tall)?", ["قصير", "قوي", "سمين", "كبير"], "قصير means short, which is the opposite of tall."], ["How do you say 'My hair is black'?", ["شعري أسود", "شعري سوداء", "شعرها أسود", "شعري أبيض"], "شعري is 'my hair', and شعر is masculine, so the masculine colour أسود is used."], ["What is the feminine form of أزرق (blue)?", ["زرقاء", "أزرقة", "زرقة", "أزرقي"], "Colours follow a special pattern, so أزرق becomes زرقاء, not just adding ة."], ["What does عيوني بنية mean?", ["My eyes are brown", "My eyes are blue", "Her eyes are brown", "My hair is brown"], "عيوني means 'my eyes' and بنية means brown; non-human plurals take a feminine singular adjective."], ["Which sentence correctly says 'My brother is lazy'?", ["أخي كسول", "أخي كسولة", "أختي كسول", "أخي كسالى"], "أخي is 'my brother' (one male), so the masculine singular كسول is correct."], ["What does صديقتي لبنانية mean?", ["My (female) friend is Lebanese", "My (male) friend is Lebanese", "My friend is in Lebanon", "My friends are Lebanese"], "صديقتي ends in ـتي, showing a female friend, and لبنانية is the feminine of 'Lebanese'."]], "bonus": ["In which direction is Arabic written and read?", ["From right to left", "From left to right", "From top to bottom", "Either way round"], "Arabic is always written and read from right to left, and most letters join to the next one."]}, {"ht": "Aut2", "t": "Leisure activities and opinions", "intro": "This topic is about what you do in your free time and what you think of it. You will use أحب (I like), أفضّل (I prefer) and frequency words such as أحياناً (sometimes). Giving an opinion with a reason, using لأن (because), turns a simple answer into a strong one.", "how": ["Use أحب + activity for 'I like', لا أحب for 'I don't like' and أكره for 'I hate'.", "Use أفضّل (I prefer) to compare: أفضّل السباحة (I prefer swimming).", "Add a frequency word such as دائماً (always), عادةً (usually), أحياناً (sometimes) or كل يوم (every day).", "For 'never', make the verb negative with لا and add أبداً: لا ألعب أبداً (I never play).", "Give a reason with لأن or لأنه / لأنها (because it is), matching the gender of the activity."], "example": {"q": "Translate into Arabic: I usually play football at the weekend because it is fun.", "steps": ["'Usually' is عادةً and 'I play' is ألعب.", "'Football' is كرة القدم and 'at the weekend' is في عطلة نهاية الأسبوع.", "كرة is a feminine word, so 'because it is fun' is لأنها ممتعة.", "Put it together: عادةً ألعب كرة القدم في عطلة نهاية الأسبوع لأنها ممتعة."], "a": "عادةً ألعب كرة القدم في عطلة نهاية الأسبوع لأنها ممتعة."}, "walk": [{"h": "Likes and dislikes", "b": "أحب means 'I like' or 'I love', and putting لا in front makes it negative: لا أحب الرياضة (I don't like sport). أكره is stronger and means 'I hate'. أفضّل means 'I prefer': أحب التلفاز لكن أفضّل القراءة (I like TV but I prefer reading)."}, {"h": "Activities and verbs", "b": "Useful verbs are ألعب (I play), أشاهد (I watch), أقرأ (I read) and أستمع إلى (I listen to). The first letter shows who does it: أ means I, يـ means he and تـ means she or you. So ألعب is 'I play' and يلعب is 'he plays'."}, {"h": "How often and why", "b": "Add a time word to show how often: أشاهد التلفاز كل يوم (I watch TV every day). Then give a reason: أحب الرسم لأنه ممتع (I like drawing because it is fun). Use لأنه for masculine activities like الرسم and لأنها for feminine ones like السباحة. Other opinion words are ممل (boring), رائع (great) and مفيد (useful)."}], "qs": [["What does أحب mean?", ["I like / I love", "I hate", "I prefer", "I play"], "أحب means 'I like' or 'I love'; أكره is 'I hate' and أفضّل is 'I prefer'."], ["What does أفضّل mean?", ["I prefer", "I like", "I don't like", "I watch"], "أفضّل means 'I prefer' and is used to compare two things."], ["How do you say 'sometimes' in Arabic?", ["أحياناً", "دائماً", "أبداً", "عادةً"], "أحياناً means sometimes; دائماً is always, أبداً is never and عادةً is usually."], ["What does لا أحب الرياضة mean?", ["I don't like sport", "I like sport", "I love sport a lot", "I prefer sport"], "لا before أحب makes it negative, so it means 'I don't like sport'."], ["What does ممل mean?", ["Boring", "Fun", "Useful", "Great"], "ممل means boring; fun is ممتع, useful is مفيد and great is رائع."], ["Which word means 'because'?", ["لأن", "لكن", "و", "أو"], "لأن means because; لكن is but, و is and, and أو is or."], ["What does أستمع إلى الموسيقى كل يوم mean?", ["I listen to music every day", "I play music every week", "I listen to music sometimes", "He listens to music every day"], "أستمع is 'I listen' (starts with أ) and كل يوم means every day."], ["Complete: أحب السباحة لأنها ___ (I like swimming because it is fun.)", ["ممتعة", "ممتع", "مملة", "ممتعون"], "السباحة is feminine and لأنها means 'because it (f) is', so the adjective must be feminine: ممتعة."], ["Which verb means 'he plays'?", ["يلعب", "ألعب", "تلعب", "نلعب"], "The prefix يـ shows 'he'; ألعب is 'I play', تلعب is 'she/you play' and نلعب is 'we play'."], ["How do you say 'I never watch TV'?", ["لا أشاهد التلفاز أبداً", "أشاهد التلفاز دائماً", "أحياناً أشاهد التلفاز", "لا يشاهد التلفاز أبداً"], "'Never' needs a negative verb (لا أشاهد) plus أبداً, and أشاهد starts with أ for 'I'."]], "bonus": ["Which Arabic word means 'and' and is written joined to the next word?", ["و", "في", "من", "على"], "و means 'and' and is joined straight onto the next word, as in وأحب."]}, {"ht": "Spr1", "t": "My town and the weather", "intro": "Here you learn to describe where you live, what there is in your town, and what the weather is like. These are very common speaking and writing tasks in the GCSE exam. You will also practise saying 'there is' and 'there isn't'.", "how": ["Say where you live with أسكن في: أسكن في مدينة كبيرة (I live in a big town).", "Say 'there is' with يوجد and 'there isn't' with لا يوجد: لا يوجد ملعب (there isn't a stadium).", "مدينة (town) is feminine, so its adjectives take ة: مدينتي جميلة (my town is beautiful).", "الطقس (the weather) is masculine, so weather adjectives stay masculine: الطقس بارد (the weather is cold).", "Use season phrases such as في الصيف (in summer) and في الشتاء (in winter)."], "example": {"q": "Translate into Arabic: I live in a big town. In my town there is a park, but there isn't a stadium. In winter the weather is cold.", "steps": ["'I live in a big town' is أسكن في مدينة كبيرة, with كبيرة feminine to match مدينة.", "'In my town there is a park' is في مدينتي حديقة (or يوجد في مدينتي حديقة).", "'But there isn't a stadium' is لكن لا يوجد ملعب.", "'In winter the weather is cold' is في الشتاء الطقس بارد."], "a": "أسكن في مدينة كبيرة. في مدينتي حديقة، لكن لا يوجد ملعب. في الشتاء الطقس بارد."}, "walk": [{"h": "Places in town", "b": "Learn the key places: مكتبة (library), مسبح (swimming pool), حديقة (park), سوق (market), مسجد (mosque), مستشفى (hospital), مطعم (restaurant) and ملعب (stadium or sports ground). Use يوجد to say a place exists: يوجد في مدينتي مسبح (there is a swimming pool in my town)."}, {"h": "Describing your town", "b": "Give your town adjectives, remembering مدينة is feminine: مدينتي مزدحمة (my town is busy) or قريتي هادئة (my village is quiet). Add a contrast with لكن (but): مدينتي صغيرة لكن جميلة (my town is small but beautiful)."}, {"h": "Weather and seasons", "b": "Start with الطقس (the weather) and add a masculine adjective: حار (hot), بارد (cold), مشمس (sunny), ممطر (rainy) or غائم (cloudy). Add a season to give more detail: في الصيف الطقس حار ومشمس (in summer the weather is hot and sunny). The four seasons are الربيع (spring), الصيف (summer), الخريف (autumn) and الشتاء (winter)."}], "qs": [["What does مسبح mean?", ["Swimming pool", "Library", "Hospital", "Mosque"], "مسبح is a swimming pool; library is مكتبة, hospital is مستشفى and mosque is مسجد."], ["What does ممطر mean?", ["Rainy", "Sunny", "Cloudy", "Windy"], "ممطر comes from مطر (rain), so it means rainy."], ["What does الصيف mean?", ["Summer", "Winter", "Spring", "Autumn"], "الصيف is summer; winter is الشتاء, spring is الربيع and autumn is الخريف."], ["How do you say 'In winter the weather is cold'?", ["في الشتاء الطقس بارد", "في الصيف الطقس بارد", "في الشتاء الطقس حار", "في الربيع الطقس بارد"], "في الشتاء is 'in winter' and بارد is 'cold'."], ["What does يوجد في مدينتي مسبح كبير mean?", ["There is a big swimming pool in my town", "There isn't a big swimming pool in my town", "There is a small swimming pool in my town", "There is a big market in my town"], "يوجد means 'there is', مسبح is swimming pool and كبير is big."], ["Which phrase means 'there isn't'?", ["لا يوجد", "يوجد", "هناك", "كثير"], "Putting لا in front of يوجد makes it negative: 'there isn't'."], ["Complete: مدينتي ___ (My town is beautiful.)", ["جميلة", "جميل", "جميلون", "جمال"], "مدينة is feminine, so the adjective needs ة: جميلة."], ["How do you say 'The weather is sunny'?", ["الطقس مشمس", "الطقس مشمسة", "الطقس غائم", "الشمس الطقس"], "الطقس is masculine, so the masculine adjective مشمس is correct."], ["What does أسكن في قرية هادئة mean?", ["I live in a quiet village", "I live in a busy village", "I live in a quiet city", "He lives in a quiet village"], "أسكن is 'I live', قرية is village and هادئة is quiet (feminine to match قرية)."], ["Which is the best translation of 'My town is busy but there isn't a stadium'?", ["مدينتي مزدحمة لكن لا يوجد ملعب", "مدينتي هادئة لكن لا يوجد ملعب", "مدينتي مزدحمة ويوجد ملعب", "مدينتي مزدحم لكن لا يوجد ملعب"], "مزدحمة is feminine to match مدينتي, لكن is 'but' and لا يوجد is 'there isn't'."]], "bonus": ["Which of these nouns is feminine because it ends in ة?", ["مدينة", "بيت", "شارع", "ملعب"], "The ending ة (taa marbuta) usually shows a feminine noun, as in مدينة (town)."]}, {"ht": "Spr2", "t": "School subjects, rules and uniform", "intro": "This topic covers your school day: subjects, the timetable, school rules and uniform. You will learn to give opinions on subjects and to talk about what you must and must not do. School is a favourite exam theme, so this vocabulary is used a lot.", "how": ["Say what you have with عندي (I have): يوم الاثنين عندي تاريخ (on Monday I have history).", "Give your favourite with مادتي المفضلة هي... (my favourite subject is...), as مادة is feminine.", "Say what you must do with يجب أن + present verb: يجب أن ألبس الزي المدرسي (I must wear school uniform).", "Say what is forbidden with ممنوع + noun: ممنوع الأكل في الصف (eating in class is forbidden).", "Make uniform colours agree: قميص أبيض (white shirt) but سترة سوداء (black blazer), because سترة is feminine."], "example": {"q": "Translate into Arabic: On Monday I have maths. I must wear a white shirt and using the phone is forbidden.", "steps": ["'On Monday I have maths' is يوم الاثنين عندي رياضيات.", "'I must wear' is يجب أن ألبس, and 'a white shirt' is قميصاً أبيض (object form after the verb).", "'Using the phone is forbidden' is ممنوع استعمال الهاتف.", "Join with و: يوم الاثنين عندي رياضيات. يجب أن ألبس قميصاً أبيض وممنوع استعمال الهاتف."], "a": "يوم الاثنين عندي رياضيات. يجب أن ألبس قميصاً أبيض وممنوع استعمال الهاتف."}, "walk": [{"h": "Subjects and opinions", "b": "Key subjects are الرياضيات (maths), العلوم (science), اللغة الإنجليزية (English), التاريخ (history), الجغرافيا (geography), الفن (art) and التربية البدنية (PE). Be careful: الرياضيات is maths but الرياضة is sport. Give a reason: أحب التاريخ لأنه ممتع (I like history because it is enjoyable)."}, {"h": "Days and times", "b": "The days are الأحد (Sunday), الاثنين (Monday), الثلاثاء (Tuesday), الأربعاء (Wednesday), الخميس (Thursday), الجمعة (Friday) and السبت (Saturday). For times use الساعة: تبدأ المدرسة الساعة الثامنة والنصف (school starts at half past eight). A lesson is حصة."}, {"h": "Rules and uniform", "b": "Rules use يجب أن (must) and ممنوع (forbidden): يجب أن نصل في الوقت (we must arrive on time). Uniform items include قميص (shirt), سترة (blazer), ربطة عنق (tie), بنطلون (trousers), تنورة (skirt) and حذاء (shoes). Remember feminine nouns need feminine colours: تنورة سوداء (a black skirt)."}], "qs": [["What does التاريخ mean?", ["History", "Geography", "Science", "Art"], "التاريخ is history; geography is الجغرافيا, science is العلوم and art is الفن."], ["What does الرياضيات mean?", ["Maths", "Sport", "Science", "Music"], "الرياضيات is maths; it looks like الرياضة (sport), which is a common mix-up."], ["Which day is Wednesday?", ["الأربعاء", "الثلاثاء", "الخميس", "الأحد"], "الأربعاء is Wednesday; الثلاثاء is Tuesday, الخميس is Thursday and الأحد is Sunday."], ["What does عندي mean?", ["I have", "I want", "I must", "I study"], "عندي literally means 'with me' and is used for 'I have'."], ["What does يجب أن mean?", ["Must / it is necessary to", "It is forbidden to", "I prefer to", "I like to"], "يجب أن means 'must' and is followed by a present tense verb."], ["What does ممنوع الأكل في الصف mean?", ["Eating in class is forbidden", "Eating in class is allowed", "We must eat in class", "Talking in class is forbidden"], "ممنوع means forbidden, الأكل is eating and في الصف is in class."], ["What does تبدأ المدرسة الساعة الثامنة mean?", ["School starts at eight o'clock", "School ends at eight o'clock", "School starts at seven o'clock", "School starts at half past eight"], "تبدأ means 'starts' and الساعة الثامنة is eight o'clock, with no 'and a half'."], ["How do you say 'a black blazer'?", ["سترة سوداء", "سترة أسود", "سترة سوداءة", "سوداء سترة"], "سترة is feminine, so 'black' takes the feminine colour form سوداء, after the noun."], ["What does مادتي المفضلة هي العلوم لأنها مفيدة mean?", ["My favourite subject is science because it is useful", "My favourite subject is science because it is boring", "I hate science because it is useful", "My favourite subject is maths because it is useful"], "العلوم is science and مفيدة means useful; لأنها means 'because it is'."], ["Which sentence means 'We must wear a tie'?", ["يجب أن نلبس ربطة عنق", "يجب أن ألبس ربطة عنق", "ممنوع لبس ربطة العنق", "نحب أن نلبس ربطة عنق"], "يجب أن is 'must' and نلبس starts with نـ, which shows 'we'."]], "bonus": ["What does ال at the start of a word (as in المدرسة) mean?", ["The", "A / an", "And", "In"], "ال is the Arabic word for 'the' and is joined to the front of the noun."]}, {"ht": "Sum1", "t": "Health, the body and healthy habits", "intro": "In this topic you learn the parts of the body, how to say what hurts and how to talk about healthy and unhealthy habits. This vocabulary helps in role plays, such as visiting a doctor or pharmacy. It also links to next half-term, when you make plans to stay healthy.", "how": ["Say what hurts with يؤلمني + body part with ـي: يؤلمني رأسي (my head hurts).", "If the body part is feminine (like يد, hand), use تؤلمني: تؤلمني يدي (my hand hurts).", "Use عندي for illnesses: عندي صداع (I have a headache), عندي زكام (I have a cold).", "Make مريض (ill) feminine for a girl: أنا مريضة.", "Describe habits with present verbs: آكل (I eat), أشرب (I drink), أنام (I sleep), أمارس الرياضة (I do sport)."], "example": {"q": "Sara writes this message. Translate it into Arabic: I am ill. I have a headache and my hand hurts.", "steps": ["Sara is a girl, so 'I am ill' is أنا مريضة.", "'I have a headache' is عندي صداع.", "يد (hand) is feminine, so 'my hand hurts' is تؤلمني يدي.", "Join with و: أنا مريضة. عندي صداع وتؤلمني يدي."], "a": "أنا مريضة. عندي صداع وتؤلمني يدي."}, "walk": [{"h": "Parts of the body", "b": "Learn رأس (head), بطن (stomach), ظهر (back), يد (hand), رجل (leg), عين (eye), أذن (ear) and أسنان (teeth). Add ـي for 'my': ظهري (my back). Note that يد, رجل, عين and أذن are feminine, even without ة."}, {"h": "Saying what's wrong", "b": "Use يؤلمني for masculine body parts and تؤلمني for feminine ones: يؤلمني بطني (my stomach hurts), تؤلمني عيني (my eye hurts). You can also say عندي ألم في... (I have a pain in...). Other phrases are أشعر بالتعب (I feel tired) and عندي حرارة (I have a temperature)."}, {"h": "Healthy and unhealthy", "b": "Healthy habits include أشرب الماء كثيراً (I drink lots of water) and آكل الفواكه والخضروات (I eat fruit and vegetables). Unhealthy things are الوجبات السريعة (fast food), الحلويات (sweets) and التدخين (smoking). Say why: التدخين مضر بالصحة (smoking is harmful to health)."}], "qs": [["What does رأس mean?", ["Head", "Hand", "Back", "Stomach"], "رأس is head; hand is يد, back is ظهر and stomach is بطن."], ["What does أسنان mean?", ["Teeth", "Ears", "Eyes", "Hands"], "أسنان is teeth; ears are آذان, eyes are عيون and hands are أيدٍ."], ["What does عندي صداع mean?", ["I have a headache", "I have a stomach ache", "I have a cold", "I have a sore throat"], "صداع means headache, and عندي means 'I have'."], ["What is the feminine form of مريض (ill)?", ["مريضة", "مرضى", "مريضون", "مرض"], "Adding ة makes مريض feminine; مرضى and مريضون are plurals and مرض means illness."], ["What does يؤلمني ظهري mean?", ["My back hurts", "My stomach hurts", "My back is strong", "His back hurts"], "يؤلمني means 'hurts me' and ظهري is 'my back' (ظهره would be 'his back')."], ["What does أشعر بالتعب mean?", ["I feel tired", "I feel well", "I feel hungry", "I am bored"], "أشعر means 'I feel' and التعب means tiredness."], ["Which sentence describes a healthy habit?", ["أشرب الماء كثيراً", "آكل الحلويات كل يوم", "أنام ثلاث ساعات فقط", "آكل الوجبات السريعة دائماً"], "أشرب الماء كثيراً means 'I drink lots of water', which is healthy."], ["What does التدخين مضر بالصحة mean?", ["Smoking is harmful to health", "Smoking is good for health", "Sport is harmful to health", "Smoking is a healthy habit"], "التدخين is smoking and مضر بالصحة means 'harmful to health'."], ["How do you say 'My hand hurts'?", ["تؤلمني يدي", "يؤلمني يدي", "تؤلمني يده", "تؤلمني رجلي"], "يد is feminine, so the verb takes تـ (تؤلمني), and يدي means 'my hand'."], ["Which is correct for 'I eat fruit and vegetables because they are healthy'?", ["آكل الفواكه والخضروات لأنها صحية", "آكل الفواكه والخضروات لأنهم صحيون", "آكل الفواكه والخضروات لأنها غير صحية", "آكل الحلويات لأنها صحية"], "Plurals of things (not people) use the feminine singular, so لأنها صحية is correct."]], "bonus": ["In رأسي (my head), which ending means 'my'?", ["ـي", "ـك", "ـه", "ـها"], "ـي on the end of a noun means 'my'; ـك is 'your', ـه is 'his' and ـها is 'her'."]}, {"ht": "Sum2", "t": "Future plans to stay healthy", "intro": "This topic teaches you to talk about the future, using your health vocabulary to make plans. In Arabic you make the future by putting سـ or سوف before a present tense verb. Using more than one tense is important for higher marks in speaking and writing.", "how": ["Put سـ directly onto a present verb to make the future: أشرب (I drink) becomes سأشرب (I will drink).", "Or put the separate word سوف in front: سوف أشرب (I will drink) means the same.", "For 'will not', use لن + present verb (no سـ): لن آكل الحلويات (I will not eat sweets).", "Add future time phrases: غداً (tomorrow), الأسبوع القادم (next week), في المستقبل (in the future).", "Use سأحاول أن (I will try to) to give more detail: سأحاول أن أنام مبكراً."], "example": {"q": "Translate into Arabic: Next week I will drink more water and I won't eat sweets.", "steps": ["'Next week' is في الأسبوع القادم.", "'I will drink more water' is سأشرب ماءً أكثر (سـ joined to أشرب).", "'I won't eat sweets' uses لن with no سـ: لن آكل الحلويات.", "Join with و: في الأسبوع القادم سأشرب ماءً أكثر ولن آكل الحلويات."], "a": "في الأسبوع القادم سأشرب ماءً أكثر ولن آكل الحلويات."}, "walk": [{"h": "Making the future", "b": "Take any present verb and add سـ to the front: ألعب (I play) becomes سألعب (I will play). You can use سوف instead, as a separate word: سوف ألعب. It works for everyone: سيلعب (he will play), ستلعب (she will play)."}, {"h": "Saying 'will not'", "b": "To say you will not do something, use لن before the present verb and drop the سـ. So سآكل (I will eat) becomes لن آكل (I will not eat). Don't confuse it with لا آكل (I don't eat) or لم آكل (I didn't eat)."}, {"h": "Healthy plans", "b": "Build a plan with time phrases and health verbs: في المستقبل سأمارس الرياضة كل يوم (in the future I will do sport every day). Add more with سأمشي إلى المدرسة (I will walk to school) or سأنام مبكراً (I will sleep early). Finish with a reason: لأنني أريد أن أكون بصحة جيدة (because I want to be healthy)."}], "qs": [["What does سألعب mean?", ["I will play", "I played", "I play", "He will play"], "سـ in front of ألعب makes it future: 'I will play'."], ["Which word is used to show the future tense?", ["سوف", "أمس", "الآن", "كان"], "سوف shows the future; أمس means yesterday and الآن means now."], ["What does غداً mean?", ["Tomorrow", "Yesterday", "Today", "Next year"], "غداً means tomorrow; yesterday is أمس and today is اليوم."], ["Which phrase means 'next week'?", ["الأسبوع القادم", "الأسبوع الماضي", "كل أسبوع", "نهاية الأسبوع"], "القادم means 'next' or 'coming', while الماضي means 'last'."], ["How do you make the future of أشرب الماء (I drink water)?", ["سأشرب الماء", "سشرب الماء", "أشربس الماء", "سوف شربت الماء"], "Add سـ to the front of the full verb أشرب, giving سأشرب."], ["What does سأنام مبكراً mean?", ["I will go to sleep early", "I will wake up early", "I slept early", "I will sleep late"], "سأنام is 'I will sleep' and مبكراً means early."], ["What does سوف تمارس أختي الرياضة mean?", ["My sister will do sport", "My sister does sport", "My brother will do sport", "I will do sport with my sister"], "سوف shows the future and تمارس with أختي means 'my sister does', so 'my sister will do sport'."], ["How do you say 'I will not eat fast food'?", ["لن آكل الوجبات السريعة", "لا آكل الوجبات السريعة", "سآكل الوجبات السريعة", "لم آكل الوجبات السريعة"], "لن + present verb means 'will not'; لا آكل is 'I don't eat' and لم آكل is 'I didn't eat'."], ["What does سأحاول أن آكل خضروات أكثر mean?", ["I will try to eat more vegetables", "I tried to eat more vegetables", "I will try to eat fewer vegetables", "I will eat more fruit"], "سأحاول أن is 'I will try to', خضروات is vegetables and أكثر is more."], ["Which is correct for 'Next year I will walk to school every day'?", ["في السنة القادمة سأمشي إلى المدرسة كل يوم", "في السنة الماضية سأمشي إلى المدرسة كل يوم", "في السنة القادمة مشيت إلى المدرسة كل يوم", "في السنة القادمة سأمشي إلى المدرسة أحياناً"], "السنة القادمة is next year, سأمشي is 'I will walk' and كل يوم is every day."]], "bonus": ["In the present tense verb أشرب (I drink), what does the first letter أ show?", ["That the person is 'I'", "That the person is 'he'", "That the person is 'she'", "That the person is 'we'"], "In the present tense, أ at the start shows 'I'; يـ is he, تـ is she and نـ is we."]}]}, {"id": "art", "name": "Drawing & Painting", "board": "AQA Art & Design: Fine Art (8202)", "weeks": [{"ht": "Aut1", "t": "Find Art Food: researching artists", "intro": "Artists have used food as a subject for hundreds of years, from fruit bowls to giant sculptures of snacks. In this topic you research artists who use food and collect images to inspire your own work. This is AO1: developing ideas by investigating and understanding other artists.", "how": ["Choose a few artists who use food and find out who they are, when they worked and what their art looks like.", "Collect images from primary sources (food you photograph or draw yourself) and secondary sources (books and websites).", "Annotate artists' work using art words such as line, tone, colour, shape, texture, pattern and composition.", "Give your own opinion and explain it, for example what you like and how it could inspire your ideas.", "Make a careful copy of a small part of an artist's work to learn how they used paint or line."], "example": {"q": "Practical task: make an artist research page about Wayne Thiebaud.", "steps": ["Write a short, factual introduction: an American painter famous for cakes, pies and desserts.", "Stick in two or three images of his style and label them with where you found them.", "Annotate using art words, for example: thick paint, bright colours, strong shadows, repeated shapes in rows.", "Add your opinion and say how his work could inspire your own food pieces.", "Draw or paint a small study of a cake in his style to test the technique."], "a": "A finished page that explains the artist, analyses his style with art vocabulary and links it to your own ideas."}, "walk": [{"h": "Meet the food artists", "b": "Different artists use food in very different ways. Giuseppe Arcimboldo, an Italian painter from the 1500s, made portrait heads out of fruit and vegetables. Paul Cézanne painted still lifes of apples, while Wayne Thiebaud and Claes Oldenburg are linked with Pop Art and painted or sculpted everyday foods."}, {"h": "Collect primary and secondary", "b": "A primary source is something real that you see yourself, like a pepper you draw or photograph. A secondary source is an image made by someone else, like a photo from a website. Strong research pages use both, so collect some of your own photos of food too."}, {"h": "Analyse, don't just describe", "b": "Saying 'I like this' is not enough for AO1. Use the formal elements to explain how the artist creates an effect, for example: 'The thick white paint makes the icing look real.' Then say how you might use that idea in your own work."}], "qs": [["Which Assessment Objective is about developing ideas by investigating artists?", ["AO1", "AO2", "AO3", "AO4"], "AO1 is about developing ideas through investigations and showing understanding of sources such as artists."], ["Giuseppe Arcimboldo is best known for which kind of painting?", ["Portrait heads made out of fruit and vegetables", "Giant soft sculptures of burgers", "Abstract paintings with no objects", "Black and white photographs of markets"], "Arcimboldo, working in the 1500s, built up faces using fruit, vegetables and other objects."], ["Wayne Thiebaud is famous for painting which subject?", ["Cakes, pies and desserts", "Melting clocks in deserts", "Sunflowers in a vase", "Ships at sea"], "Thiebaud is known for bright paintings of cakes and desserts made with thick paint."], ["Which artist is famous for still life paintings of apples?", ["Paul Cézanne", "Claes Oldenburg", "Salvador Dalí", "Wayne Thiebaud"], "Cézanne, a French Post-Impressionist, painted many still lifes of apples and fruit."], ["Which of these is a secondary source?", ["A photo of a cake found on a website", "A real lemon you are drawing", "A photo you took of your lunch", "A sketch of an apple in front of you"], "A secondary source is an image made by someone else, such as one found online."], ["Which of these is one of the formal elements of art?", ["Tone", "Title", "Frame", "Signature"], "The formal elements include line, tone, colour, shape, form, texture and pattern."], ["Which annotation is the strongest?", ["The thick paint makes the icing look real and shiny", "I like this picture", "This is a nice cake", "The artist painted food"], "Strong annotation uses art vocabulary and explains how an effect is created."], ["Claes Oldenburg is known for which kind of art?", ["Giant sculptures of everyday objects, including food", "Tiny watercolour paintings of flowers", "Stained glass windows", "Portraits of kings and queens"], "Oldenburg made huge sculptures of ordinary things, including soft sculptures of food."], ["Thiebaud and Oldenburg are both linked with which art movement?", ["Pop Art", "Surrealism", "Impressionism", "Cubism"], "Both artists are linked with Pop Art, which focused on everyday objects and popular culture."], ["Why do you make a careful copy of part of an artist's work?", ["To learn how they used materials and techniques", "To hand it in as your own final piece", "To avoid making your own ideas", "Because copying gets full marks for AO4"], "A study of an artist's work helps you understand their technique so you can use it in your own ideas."]], "bonus": ["What are the three primary colours in painting?", ["Red, yellow and blue", "Red, green and blue", "Orange, green and purple", "Black, white and grey"], "In paint, red, yellow and blue are primary colours because they cannot be mixed from other colours."]}, {"ht": "Aut2", "t": "Food project: scaling up a final painting", "intro": "Now you turn your food research into your own art. You make small pieces to test ideas, then develop the best one into a large final painting. You will learn about composition, colour and how to scale up accurately using the grid method.", "how": ["Plan your composition by arranging objects so there is a clear focal point.", "Test colour in small studies first, using warm, cool and complementary colours.", "Make tints by adding white and shades by adding black.", "Use the grid method to enlarge your design square by square, keeping the same proportions.", "Paint large areas first, then add details, highlights and shadows at the end."], "example": {"q": "Practical task: scale up a 10 cm × 15 cm design to three times its size using the grid method.", "steps": ["Draw a grid of 1 cm squares lightly in pencil over your small design.", "Multiply the square size by 3, so the large grid needs 3 cm squares.", "Draw the large grid on paper 30 cm × 45 cm, with the same number of squares (10 across, 15 down).", "Copy what is in each small square into the matching large square, one square at a time.", "Rub out the grid lines gently before you start painting."], "a": "The design is enlarged accurately to 30 cm × 45 cm, keeping the same proportions."}, "walk": [{"h": "Plan the composition", "b": "Composition is how you arrange things in a picture. The rule of thirds divides the picture into three equal parts each way, and placing your focal point near where the lines cross often looks good. Overlapping objects also creates a feeling of depth."}, {"h": "Choose your colours", "b": "Warm colours are reds, oranges and yellows; cool colours are blues, greens and purples. Complementary colours sit opposite on the colour wheel, such as red and green, and make each other look brighter. Add white to make a tint and black to make a shade."}, {"h": "Scale up with a grid", "b": "Draw a grid over your small design, then draw a bigger grid with the same number of squares on your large paper. If every square is twice as big, the whole picture is twice as big. Copy one square at a time so shapes stay in the right place."}], "qs": [["What is the complementary colour of red?", ["Green", "Orange", "Blue", "Purple"], "Red and green sit opposite each other on the colour wheel."], ["What do you add to a colour to make a tint?", ["White", "Black", "Its complementary colour", "Water only"], "A tint is a colour made lighter by adding white."], ["What do you add to a colour to make a shade?", ["Black", "White", "Yellow", "Grey"], "A shade is a colour made darker by adding black."], ["Which of these is a set of warm colours?", ["Red, orange and yellow", "Blue, green and purple", "Black, white and grey", "Blue, orange and purple"], "Reds, oranges and yellows are called warm colours."], ["What is the focal point of a painting?", ["The part your eye is drawn to first", "The very centre of the paper", "The darkest corner", "The artist's signature"], "The focal point is the main area of interest that catches the viewer's eye."], ["What is the main purpose of the grid method?", ["To enlarge a design accurately, square by square", "To add colour more quickly", "To make the painting look like a chessboard", "To check spelling in annotations"], "The grid method helps you copy and enlarge shapes in the right places and proportions."], ["Overlapping objects in a still life helps to create what?", ["A sense of depth and space", "A flatter picture", "Brighter colours", "A symmetrical pattern"], "When one object sits in front of another, the picture looks like it has depth."], ["A design has a 2 cm grid. You scale it up ×3. What size are the large squares?", ["6 cm", "5 cm", "3 cm", "9 cm"], "Multiply the square size by the scale factor: 2 × 3 = 6 cm."], ["A design is 10 cm × 15 cm. Enlarged, its width is 40 cm. What is the new height?", ["60 cm", "45 cm", "55 cm", "30 cm"], "The width was multiplied by 4, so the height is 15 × 4 = 60 cm to keep the same proportions."], ["Why make small pieces before your large final painting?", ["To test composition and colour before committing", "Because small pieces are worth no marks", "To use up spare paper", "So you do not need a final piece"], "Small studies let you try ideas and fix problems before working large."]], "bonus": ["Which secondary colour do you get by mixing blue and yellow?", ["Green", "Purple", "Orange", "Brown"], "Blue and yellow are primary colours that mix to make green."]}, {"ht": "Spr1", "t": "Surrealism: art of dreams", "intro": "Surrealism was an art movement that began in Paris in the 1920s. Surrealist artists wanted to show dreams and the unconscious mind, often painting strange scenes in a very realistic way. Researching it builds AO1 and gives you exciting techniques for your own ideas.", "how": ["Remember that Surrealism started in the 1920s, led by the writer André Breton, who published the Surrealist Manifesto in 1924.", "Know key artists such as Salvador Dalí (Spanish), René Magritte (Belgian) and Max Ernst (German).", "Use juxtaposition: put unrelated objects together to surprise the viewer.", "Use scale change and metamorphosis: make things the wrong size, or show one thing turning into another.", "Draw on dream imagery and try games like automatic drawing and the exquisite corpse."], "example": {"q": "Practical task: design a small Surrealist drawing using a piece of food.", "steps": ["Choose an everyday food, such as a banana, and draw it from observation.", "Pick a technique, for example scale change: make the banana as big as a house.", "Add juxtaposition by placing it somewhere unexpected, such as floating above a street.", "Try metamorphosis by letting one end of the banana slowly change into a bird.", "Annotate which Surrealist techniques you used and which artist inspired you."], "a": "A dreamlike drawing that uses scale change, juxtaposition and metamorphosis, with annotation explaining the ideas."}, "walk": [{"h": "What Surrealism is", "b": "Surrealism began in Paris in the 1920s. The artists were inspired by ideas about dreams and the unconscious mind from the psychologist Sigmund Freud. They often painted impossible scenes in a realistic style so that they felt strangely believable."}, {"h": "Key Surrealist artists", "b": "Salvador Dalí was a Spanish artist known for dreamlike landscapes and soft, strange forms. René Magritte was a Belgian painter who placed ordinary objects, such as apples, hats and clouds, in puzzling situations. Max Ernst was a German artist who invented frottage, making rubbings from textured surfaces."}, {"h": "Surrealist techniques", "b": "Juxtaposition means placing unrelated things side by side, like a fish wearing a hat. Scale change makes something the wrong size, like an apple filling a whole room. Metamorphosis shows one thing changing into another, like a leaf slowly becoming a bird."}], "qs": [["When and where did Surrealism begin?", ["Paris in the 1920s", "London in the 1960s", "Rome in the 1500s", "New York in the 1990s"], "Surrealism began in Paris in the 1920s."], ["What were Surrealists most interested in showing?", ["Dreams and the unconscious mind", "Exact copies of real landscapes", "Only straight lines and squares", "Royal portraits"], "Surrealists explored dreams and the unconscious mind."], ["What does juxtaposition mean?", ["Placing unrelated things side by side", "Drawing something very small", "Using only one colour", "Copying an artist exactly"], "Juxtaposition puts unexpected objects together to surprise the viewer."], ["A giant apple filling a whole room is an example of which technique?", ["Scale change", "Metamorphosis", "Frottage", "Cross-hatching"], "Making an object the wrong size is called scale change."], ["A leaf slowly turning into a bird is an example of what?", ["Metamorphosis", "Juxtaposition", "Scale change", "Perspective"], "Metamorphosis shows one thing transforming into another."], ["Which country was René Magritte from?", ["Belgium", "Spain", "France", "Italy"], "Magritte was a Belgian Surrealist painter."], ["Which country was Salvador Dalí from?", ["Spain", "Belgium", "Germany", "Mexico"], "Dalí was a Spanish Surrealist artist."], ["Who wrote the Surrealist Manifesto in 1924?", ["André Breton", "Salvador Dalí", "Pablo Picasso", "Claude Monet"], "The writer André Breton published the Surrealist Manifesto in 1924."], ["What is the exquisite corpse?", ["A game where people draw parts of a figure on folded paper", "A painting of food going rotten", "A type of oil paint", "A way to stretch a canvas"], "Each person draws one part without seeing the others, creating a surprising combined image."], ["What is frottage, the technique Max Ernst developed?", ["Rubbing a pencil over paper on a textured surface", "Dripping paint from a height", "Cutting shapes from magazines", "Carving into lino"], "Frottage makes rubbings of textures like wood grain, which can spark dreamlike images."]], "bonus": ["What is a collage?", ["A picture made by sticking pieces of paper or images onto a surface", "A drawing made only with dots", "A sculpture carved from stone", "A painting done with one brush stroke"], "Collage means building an image from stuck-down materials, a technique many Surrealists used."]}, {"ht": "Spr2", "t": "Recording still life and natural forms", "intro": "Recording means drawing and photographing what you see to collect ideas. In this topic you make observational studies of still life objects and natural forms, like shells and leaves, in pencil and colour. This is AO3, and good recording skills make every other part of your project stronger.", "how": ["Draw from primary sources (real objects in front of you) whenever you can, and use secondary sources like photos to add to them.", "Look carefully at shapes and proportions before adding any tone.", "Build up tone from light to dark, showing highlights, mid-tones and shadows.", "Show texture with marks such as hatching, cross-hatching, stippling and blending.", "In colour pencil, layer colours lightly and press harder at the end to blend."], "example": {"q": "Practical task: make a tonal pencil drawing of a shell from observation.", "steps": ["Use a viewfinder to choose an interesting view and lightly draw the outline with an HB pencil.", "Find where the light comes from and mark the highlight, which you leave white.", "Add mid-tones with a 2B pencil and the darkest shadows with a 4B or 6B pencil.", "Add the cast shadow on the table and use small marks to show the shell's ridges.", "Annotate the pencils and techniques you used and what you would improve."], "a": "A realistic tonal drawing that shows the shell's form, texture and shadows, recorded from a primary source."}, "walk": [{"h": "Primary and secondary sources", "b": "A primary source is the real thing, like a pine cone on your desk. A secondary source is someone else's image, like a photo online. Drawing from primary sources is best because you can see the real form, light and texture."}, {"h": "Tone and pencils", "b": "Tone means how light or dark something is. H pencils are hard and make light lines; B pencils are soft and make dark marks, so 6B is darker than 2B. The highlight is the lightest part, and the cast shadow is the shadow the object throws onto the surface."}, {"h": "Texture and colour", "b": "Hatching uses parallel lines, cross-hatching adds lines crossing over them, and stippling uses dots. Closer marks look darker. In colour pencil, build several light layers, then burnish by pressing hard to blend them into a smooth finish."}], "qs": [["Which Assessment Objective is mainly about recording observations?", ["AO3", "AO1", "AO2", "AO4"], "AO3 is about recording ideas, observations and insights."], ["Which of these is drawing from a primary source?", ["Drawing a real shell on the table in front of you", "Drawing from a photo in a book", "Copying a picture from a website", "Tracing a magazine image"], "A primary source is the real object observed directly."], ["In art, what does tone mean?", ["How light or dark something is", "How loud a colour is", "The size of the paper", "The outline of a shape"], "Tone describes the lightness or darkness of an area."], ["Which pencil makes the darkest marks?", ["6B", "2H", "HB", "2B"], "B pencils are soft and dark, and the higher the number the darker, so 6B is darkest here."], ["What is the highlight on an object?", ["The lightest part, where light hits it most", "The darkest shadow", "The outline", "The background"], "The highlight is where light falls most strongly, so it is the lightest area."], ["What is a cast shadow?", ["The shadow an object throws onto the surface", "The dark side of the object itself", "A shadow drawn in colour", "The line around the edge"], "A cast shadow falls onto the table or background, away from the light."], ["Which is a natural form?", ["A pine cone", "A teapot", "A bicycle", "A trainer"], "Natural forms are things found in nature, such as shells, leaves and pine cones."], ["What is cross-hatching?", ["Layers of crossing lines that build up darker tone", "Dots placed close together", "Smudging with a finger", "Drawing only the outline"], "Cross-hatching adds lines that cross over each other to make areas darker."], ["Stippling shows tone using what?", ["Dots", "Long straight lines", "Smudged charcoal", "Torn paper"], "Stippling uses dots, with more and closer dots creating darker tone."], ["What is burnishing in coloured pencil?", ["Pressing hard to blend layers into a smooth, shiny finish", "Rubbing out mistakes", "Wetting the pencil before drawing", "Drawing with the side of the pencil only"], "Burnishing presses colours together firmly to blend them and fill the paper's texture."]], "bonus": ["What is the difference between shape and form?", ["Shape is flat (2D); form looks three-dimensional (3D)", "Shape is 3D; form is flat (2D)", "They mean exactly the same", "Shape is about colour; form is about texture"], "A circle is a flat shape, but a sphere is a 3D form, and tone helps a drawing show form."]}, {"ht": "Sum1", "t": "Experimenting and refining ideas", "intro": "Artists rarely get it right first time. In this topic you try lots of media and techniques, see what works and improve your ideas step by step. This is AO2: refining work by experimenting with media, materials, techniques and processes, ending in small original final pieces.", "how": ["Try a range of media, such as watercolour, acrylic, oil pastel, ink, collage and printmaking.", "Test each technique on a small scale before using it in a bigger piece.", "Annotate every experiment: what worked, what did not and what you will try next.", "Refine by choosing the best results and improving them, not by starting again randomly.", "Combine your best experiments into small original final pieces."], "example": {"q": "Practical task: test a wax resist technique for a food study.", "steps": ["Draw the highlights and patterns of a slice of fruit using a white or light oil pastel.", "Brush a watercolour wash over the top.", "Watch the oil pastel resist the paint so the lines stay visible.", "Try a second version with different colours or thicker pastel.", "Annotate which version worked best and why."], "a": "Two tested wax resist studies with annotation explaining which one works best and how to refine it."}, "walk": [{"h": "Try different media", "b": "Each material gives a different effect. Watercolour is see-through and soft, acrylic is thick and bright, and oil pastel is waxy and bold. Mixed media means using more than one material in a single piece."}, {"h": "Learn key techniques", "b": "A wash is a thin, even layer of watery paint. Wet-on-wet means painting onto wet paper, which gives soft, blurry edges. In lino printing, the parts you cut away stay the colour of the paper, and the print comes out as a mirror image."}, {"h": "Review and refine", "b": "After each test, ask: what went well and what could be better? Refining means taking your best result and improving it, such as changing the colours or adding detail. Your annotations show the examiner your thinking, which is a big part of AO2."}], "qs": [["What is AO2 mainly about?", ["Refining ideas by experimenting with media and techniques", "Researching artists only", "Presenting the final piece", "Writing an essay about history"], "AO2 is about exploring, experimenting with and refining media, materials, techniques and processes."], ["What is mixed media?", ["Using more than one material in one piece", "Mixing two paint colours", "Using only pencil", "Copying another artist"], "Mixed media combines different materials, such as paint, collage and pastel."], ["What is a wash in painting?", ["A thin, even layer of watery paint", "Cleaning brushes after painting", "A thick layer of paint", "Painting with a sponge only"], "A wash is a thin layer of diluted paint spread evenly."], ["Painting wet paint onto wet paper gives what effect?", ["Soft, blurry edges", "Sharp, crisp lines", "A shiny metal look", "Raised, thick texture"], "In wet-on-wet, the paint spreads into the wet paper and blurs."], ["Why does wax resist work?", ["Oil pastel repels watery paint", "Watercolour dissolves oil pastel", "Paper absorbs the pastel", "The paint dries too quickly"], "The waxy pastel pushes the watery paint away, so the pastel lines show through."], ["In a lino print, what happens to the areas you cut away?", ["They do not print and stay the paper colour", "They print the darkest", "They print in a different colour", "They make the print bigger"], "Lino printing is a relief process: only raised areas take ink."], ["Why must letters be carved backwards on a lino block?", ["The print comes out as a mirror image", "To make the letters bigger", "So the ink dries faster", "Because lino can only be cut that way"], "A print is reversed, so backwards letters print the right way round."], ["How many prints does a monoprint usually produce?", ["One unique print", "Exactly ten identical prints", "Hundreds of copies", "None until it is framed"], "A monoprint is a one-off print that cannot be repeated exactly."], ["What does refining your work mean?", ["Improving your best idea step by step", "Starting a new idea every lesson", "Throwing away all experiments", "Making the work smaller"], "Refining means developing and improving an idea based on what you learned from tests."], ["Which annotation best shows AO2 thinking?", ["The wash was too pale, so next I will use stronger colour", "I did this on Tuesday", "This is a painting", "I used paper"], "Good AO2 annotation evaluates the result and explains the next step."]], "bonus": ["How do you make watercolour paint lighter?", ["Add more water", "Add black paint", "Add oil pastel", "Let it dry first"], "Watercolour is made lighter by adding water, so more of the white paper shows through."]}, {"ht": "Sum2", "t": "Presenting a final piece", "intro": "Your final piece is where everything comes together. You choose your strongest idea, enlarge it to A4, and present it with clear annotation. This is AO4: presenting a personal and meaningful response, and it prepares you for how GCSE work is shown.", "how": ["Choose the idea that best shows your skills and clearly links to your research and experiments.", "Enlarge it to A4 (210 mm × 297 mm) carefully, using a grid if needed.", "Annotate how your final piece links to artists and your earlier experiments.", "Evaluate it: say what went well and what you would improve.", "Present neatly, for example by mounting it on card with a clean border."], "example": {"q": "Practical task: choose and present your final food or Surrealist piece.", "steps": ["Lay out all your small final pieces and pick the one with the strongest idea and skill.", "Plan it on A4, using a grid to scale up the composition accurately.", "Complete the piece using the media that worked best in your experiments.", "Mount it neatly and add a short annotation linking it to your research and artists.", "Write an evaluation of strengths and next steps."], "a": "A well-presented A4 final piece with annotation that shows the journey from research to outcome."}, "walk": [{"h": "Choose your strongest idea", "b": "Look back over your sketchbook and pick the idea that is most personal and shows your best skills. It should clearly connect to the artists you researched and the experiments you tried. A strong idea is better than a big, rushed one."}, {"h": "Annotate and evaluate", "b": "Annotation tells the story of your project. Explain which artist inspired you, which techniques you used and why. Finish with an evaluation, such as: 'The colours work well, but I would make the shadows darker.'"}, {"h": "How GCSE art works", "b": "At GCSE, there are four Assessment Objectives, each worth 25%. The portfolio is worth 60% and the externally set assignment is worth 40%. In the externally set assignment, you prepare and then make a final piece in 10 hours of supervised time."}], "qs": [["What is AO4 about?", ["Presenting a personal and meaningful response", "Researching artists", "Recording from observation", "Experimenting with media"], "AO4 is about presenting a personal response that realises your intentions."], ["How much of the GCSE is the portfolio worth?", ["60%", "40%", "50%", "25%"], "Component 1, the portfolio, is worth 60% of the GCSE."], ["How much of the GCSE is the externally set assignment worth?", ["40%", "60%", "25%", "100%"], "Component 2, the externally set assignment, is worth 40%."], ["How long is the supervised time in the externally set assignment?", ["10 hours", "2 hours", "1 hour", "20 hours"], "Students make their final piece in 10 hours of supervised time."], ["How many Assessment Objectives are there, and how are they weighted?", ["Four, each worth 25%", "Three, each worth a third", "Four, with AO4 worth 70%", "Two, each worth 50%"], "There are four AOs in GCSE Art, and each carries an equal 25%."], ["What size is A4 paper?", ["210 mm × 297 mm", "297 mm × 420 mm", "148 mm × 210 mm", "100 mm × 150 mm"], "A4 is 210 mm × 297 mm; A3 is larger and A5 is smaller."], ["Which idea should you choose for your final piece?", ["The one that shows your best skills and links to your research", "The quickest one to finish", "The one most like an artist's work, copied exactly", "Whichever is largest"], "The strongest idea shows skill and clearly develops from your research and experiments."], ["What does mounting your work mean?", ["Fixing it onto card to give a neat border", "Hanging it on a mountain", "Painting over the edges", "Laminating every sketch"], "Mounting presents work neatly on a larger piece of card."], ["What should an evaluation of your final piece include?", ["What went well and what you would improve", "Only the date and your name", "A list of every pencil you own", "A copy of the artist's biography"], "An evaluation judges strengths and weaknesses and suggests improvements."], ["Why should your final piece link to your earlier work?", ["It shows the journey from research and experiments to outcome", "Examiners only mark the final piece", "So you can skip annotation", "Because it must be the same size as your sketches"], "Linking shows how your ideas developed, which supports all four AOs."]], "bonus": ["What does landscape orientation mean for a sheet of paper?", ["It is wider than it is tall", "It is taller than it is wide", "It is square", "It has a landscape drawn on it"], "Landscape means the long side runs across; portrait means the long side runs up and down."]}]}, {"id": "resistant-materials", "name": "Resistant Materials (D&T)", "board": "AQA Design & Technology (8552)", "weeks": [{"ht": "Aut1", "t": "Pen project: design and drawing", "intro": "Designers follow a design process to turn a problem into a finished product. In the pen project you learn that process and the main drawing systems designers use to share ideas. You also start using CAD software such as 2D Design and SketchUp.", "how": ["Follow the iterative design process: explore the problem, design, make a model, test, evaluate and improve, then repeat.", "Draw isometric views with vertical lines and lines at 30° to the horizontal.", "Draw oblique views with a flat front face and depth lines at 45°.", "Use orthographic projection to show front, side and plan views, using third angle projection in the UK.", "Use perspective drawing with a horizon line and vanishing points to make objects look realistic."], "example": {"q": "Practical task: draw a simple cuboid pen holder in isometric.", "steps": ["Draw a vertical line for the front corner of the box.", "From the bottom of that line, draw two lines at 30° to the horizontal, one left and one right.", "Mark the length and width on these lines and draw vertical lines up from each end.", "Join the tops with lines parallel to the 30° lines to complete the top face.", "Add tone, darkest on the side facing away from the light, to make it look 3D."], "a": "A clear 3D isometric drawing of the pen holder, built from vertical and 30° lines."}, "walk": [{"h": "The design process", "b": "The design process starts with a problem or brief and research into the user. You then sketch ideas, model and test them, and evaluate what works. It is iterative, which means you go round the loop again to keep improving the design."}, {"h": "3D drawing systems", "b": "Isometric uses lines at 30° and shows the object from a corner. Oblique shows the front face flat, with depth lines going back at 45°. Perspective uses vanishing points on a horizon line: one-point for looking straight at an object, two-point for looking at a corner."}, {"h": "Orthographic and CAD", "b": "Orthographic drawings show an object as separate flat views, usually front, side and plan (from above), with dimensions in millimetres. In the UK we use third angle projection. CAD software such as 2D Design and SketchUp lets you draw accurately, edit easily and send designs to machines."}], "qs": [["What angle are the receding lines in isometric drawing?", ["30°", "45°", "60°", "90°"], "Isometric drawing uses lines at 30° to the horizontal."], ["In oblique drawing, what angle are the depth lines usually drawn at?", ["45°", "30°", "60°", "90°"], "Oblique drawing shows the front face flat with depth lines going back at 45°."], ["Which drawing shows separate front, side and plan views?", ["Orthographic projection", "Isometric drawing", "Two-point perspective", "Exploded drawing"], "Orthographic projection shows an object as separate flat 2D views."], ["What is the plan view in orthographic drawing?", ["The view from above", "The view from the front", "The view from the side", "A view from underneath at 45°"], "The plan view shows the object as seen from directly above."], ["Which projection method is the standard in the UK?", ["Third angle projection", "First angle projection", "Oblique projection", "Planometric projection"], "UK and British Standards drawings normally use third angle projection."], ["What units are dimensions on a working drawing usually given in?", ["Millimetres", "Centimetres", "Metres", "Inches"], "Engineering and D&T drawings use millimetres as standard."], ["In perspective drawing, where do the vanishing points sit?", ["On the horizon line", "At the bottom of the page", "In the centre of the object", "Anywhere outside the page edge"], "Vanishing points are placed on the horizon line, which is at eye level."], ["Which drawing is best for looking at a box directly from the front with depth?", ["One-point perspective", "Two-point perspective", "Plan view", "Isometric"], "One-point perspective is used when you look straight at one face of an object."], ["What does it mean that the design process is iterative?", ["You repeat cycles of designing, testing and improving", "You only design one idea", "You make the product before designing it", "You never change your first idea"], "Iterative design repeats the loop of making, testing and improving."], ["What is one main advantage of CAD over hand drawing?", ["Designs can be edited easily and sent to machines", "It needs no computer", "It never makes mistakes even if you do", "It makes the product stronger"], "CAD is accurate, easy to change and can link straight to CAM machines."]], "bonus": ["How many degrees are in a right angle?", ["90°", "45°", "180°", "360°"], "A right angle is a quarter turn, which is 90°."]}, {"ht": "Aut2", "t": "Box project: tools, joints and timber", "intro": "In the box project you make a wooden box in the workshop. You learn to mark out, cut and shape accurately, join pieces with wood joints and finish your work, all while working safely. You also learn the difference between hardwoods, softwoods and manufactured boards.", "how": ["Mark out with a pencil, steel rule and try square, and shade the waste so you know which side to remove.", "Always cut on the waste side of the line so your piece is not too small.", "Use the right tool: a tenon saw for straight cuts, a coping saw for curves, a file and glasspaper for smoothing.", "Choose a joint that suits the job, such as a butt, lap, housing, dowel or finger joint.", "Follow workshop safety: wear goggles and an apron, tie back hair and loose clothing, and never leave a machine running."], "example": {"q": "Practical task: cut a piece of pine 150 mm long, square and neat.", "steps": ["Measure 150 mm from a straight end with a steel rule and mark a small line in pencil.", "Use a try square to draw a line straight across the wood at that mark.", "Shade the waste side, then hold the wood on a bench hook.", "Saw on the waste side of the line with a tenon saw.", "Smooth the cut end with glasspaper wrapped around a block."], "a": "A neat, square piece of pine exactly 150 mm long, ready to be joined."}, "walk": [{"h": "Know your timbers", "b": "Hardwoods come from deciduous trees, which lose their leaves in autumn, such as oak, beech and ash. Softwoods come from coniferous trees, which have needles and cones, such as pine and spruce. Manufactured boards like MDF, plywood and chipboard are made from wood fibres, layers or chips glued together and come in large, stable sheets."}, {"h": "Mark out and cut", "b": "Use a try square to draw lines at 90° and a marking gauge to draw lines parallel to an edge. Always cut on the waste side of the line. A tenon saw cuts straight lines, a coping saw cuts curves, and a pillar drill makes accurate holes."}, {"h": "Joints and finishing", "b": "A butt joint is the simplest: two ends glued together, but it is weak. Lap, housing and finger joints are stronger because there is more surface area for glue. Finish by sanding with coarse then fine glasspaper, then apply varnish, wax, oil or paint to protect the wood."}], "qs": [["Which side of the line should you cut on?", ["The waste side", "Exactly on the line", "The side you keep", "It does not matter"], "Cutting on the waste side stops your piece ending up too small."], ["Which tool is used to mark a line at 90° to an edge?", ["Try square", "Coping saw", "File", "Bench hook"], "A try square checks and marks right angles."], ["Which saw is best for cutting curves in thin wood?", ["Coping saw", "Tenon saw", "Hacksaw", "Panel saw"], "A coping saw has a thin blade that can turn to cut curves."], ["Which of these is a hardwood?", ["Oak", "Pine", "Spruce", "MDF"], "Oak comes from a deciduous tree, so it is a hardwood."], ["Softwoods come from which kind of tree?", ["Coniferous trees with needles and cones", "Deciduous trees that lose leaves", "Palm trees only", "Fruit trees only"], "Softwoods such as pine come from coniferous trees."], ["Which of these is a manufactured board?", ["MDF", "Oak", "Pine", "Beech"], "MDF is made from wood fibres and resin pressed into sheets."], ["Which tool marks a line parallel to the edge of the wood?", ["Marking gauge", "Try square", "Mallet", "Pillar drill"], "A marking gauge scribes a line at a set distance from an edge."], ["Why is a butt joint the weakest joint?", ["It has the smallest gluing area", "It uses too much glue", "It needs screws", "It is only used in metal"], "A butt joint only glues end to face, so there is little surface area."], ["What is the correct order for sanding?", ["Coarse glasspaper first, then finer", "Fine glasspaper first, then coarser", "Only use the coarsest", "Varnish first, then sand"], "Coarse paper removes marks quickly; finer paper then leaves a smooth finish."], ["What must you do before using the pillar drill?", ["Wear goggles and clamp the work securely", "Hold the wood in your hand", "Wear gloves and loose sleeves", "Turn it on and leave it running"], "Goggles protect your eyes and clamping stops the work from spinning."]], "bonus": ["How many millimetres are in 1 centimetre?", ["10", "100", "1,000", "1"], "1 cm = 10 mm, which matters because workshop measurements are in millimetres."]}, {"ht": "Spr1", "t": "Mechanical toy: motion, levers, linkages", "intro": "Mechanical toys move using simple mechanisms. Mechanisms change one kind of motion or force into another, so a small push can make a big movement. In this topic you learn the four types of motion, the three classes of lever and how linkages work.", "how": ["Learn the four types of motion: linear, rotary, reciprocating and oscillating.", "Remember a lever has three parts: the effort, the load and the fulcrum (pivot).", "Class 1 has the fulcrum in the middle, class 2 has the load in the middle and class 3 has the effort in the middle.", "Work out mechanical advantage with MA = load ÷ effort.", "Use linkages to change the direction or size of a movement."], "example": {"q": "A wheelbarrow lifts a load of 600 N with an effort of 200 N. What class of lever is it and what is its mechanical advantage?", "steps": ["Find the fulcrum: the wheel.", "Find the load: the soil in the middle. The effort is at the handles.", "The load is in the middle, so it is a class 2 lever.", "MA = load ÷ effort = 600 ÷ 200 = 3."], "a": "It is a class 2 lever with a mechanical advantage of 3."}, "walk": [{"h": "Four types of motion", "b": "Linear motion is in a straight line, like a train on a straight track. Rotary motion goes round in a circle, like a wheel. Reciprocating motion goes backwards and forwards in a straight line, like a saw, and oscillating motion swings back and forth in an arc, like a pendulum."}, {"h": "Three classes of lever", "b": "Class 1 levers have the fulcrum in the middle, like a seesaw or scissors. Class 2 levers have the load in the middle, like a wheelbarrow or nutcracker. Class 3 levers have the effort in the middle, like tweezers or your forearm, and they make movement bigger rather than reducing effort."}, {"h": "Linkages", "b": "A linkage is a set of levers joined by pivots. A reverse motion linkage makes the output move the opposite way to the input. A bell crank changes the direction of motion through 90°, and a parallel motion linkage makes the output move the same way as the input."}], "qs": [["What type of motion goes round in a circle?", ["Rotary", "Linear", "Reciprocating", "Oscillating"], "Rotary motion turns around a centre, like a wheel."], ["A pendulum swinging in an arc shows which type of motion?", ["Oscillating", "Rotary", "Linear", "Reciprocating"], "Oscillating motion swings back and forth in an arc."], ["A saw moving backwards and forwards in a straight line shows which motion?", ["Reciprocating", "Oscillating", "Rotary", "Linear"], "Reciprocating motion is back-and-forth along a straight line."], ["What is the pivot point of a lever called?", ["Fulcrum", "Load", "Effort", "Linkage"], "The fulcrum is the point the lever turns around."], ["A seesaw is which class of lever?", ["Class 1", "Class 2", "Class 3", "It is not a lever"], "A seesaw has the fulcrum in the middle, so it is class 1."], ["A wheelbarrow is which class of lever?", ["Class 2", "Class 1", "Class 3", "Class 4"], "The load sits between the wheel (fulcrum) and handles (effort), making it class 2."], ["Tweezers are which class of lever?", ["Class 3", "Class 1", "Class 2", "Class 4"], "With tweezers, the effort is in the middle, so they are a class 3 lever."], ["A lever lifts a 500 N load with a 100 N effort. What is the mechanical advantage?", ["5", "0.2", "400", "600"], "MA = load ÷ effort = 500 ÷ 100 = 5."], ["Which linkage makes the output move in the opposite direction to the input?", ["Reverse motion linkage", "Parallel motion linkage", "Bell crank", "Crank and slider"], "A reverse motion linkage pivots in the middle so the output moves the opposite way."], ["What does a bell crank do?", ["Changes the direction of motion through 90°", "Turns rotary motion into oscillating", "Makes the output twice as fast", "Reverses the motion through 180°"], "A bell crank turns movement around a corner, through 90°."]], "bonus": ["What is the unit of force?", ["Newton (N)", "Kilogram (kg)", "Metre (m)", "Joule (J)"], "Force is measured in newtons, which is why loads and efforts are given in N."]}, {"ht": "Spr2", "t": "Mechanical toy: cams, gears, forces", "intro": "This topic adds more mechanisms to your toy. Cams and followers turn rotary motion into reciprocating motion, while gears and pulleys pass on rotation and change speed. You also learn the forces that act on structures so your toy stays strong.", "how": ["A cam turns rotary motion into reciprocating motion in a follower.", "Choose the cam shape for the movement you want: circular (eccentric), pear, heart or snail (drop).", "Gear ratio = number of teeth on the driven gear ÷ number of teeth on the driver gear.", "Two meshing gears turn in opposite directions; an idler gear makes the driver and driven turn the same way.", "Know the five forces: tension, compression, torsion, shear and bending."], "example": {"q": "A driver gear with 15 teeth turns a driven gear with 45 teeth. What is the gear ratio, and how fast does the driven gear turn if the driver turns at 90 rpm?", "steps": ["Gear ratio = driven teeth ÷ driver teeth = 45 ÷ 15 = 3.", "Write it as 3:1, meaning the driver turns 3 times for every 1 turn of the driven gear.", "Output speed = input speed ÷ gear ratio = 90 ÷ 3.", "Output speed = 30 rpm."], "a": "The gear ratio is 3:1 and the driven gear turns at 30 rpm."}, "walk": [{"h": "Cams and followers", "b": "A cam is a shaped piece that rotates on a shaft and pushes a follower up and down. A circular (eccentric) cam gives smooth, constant rise and fall, and a pear cam has a dwell where the follower stays still for part of the turn. A snail cam gives a slow rise then a sudden drop, so it can only turn one way."}, {"h": "Gears and pulleys", "b": "When a small gear drives a big gear, the big gear turns slower but with more turning force (torque). With a 10-tooth driver and a 30-tooth driven gear the ratio is 3:1. Pulleys work in a similar way using a belt, and crossing the belt makes the driven pulley turn the opposite way."}, {"h": "Forces on structures", "b": "Tension is a pulling force, like a rope in a tug of war. Compression is a squashing force, like a table leg holding weight. Torsion is twisting, shear is two forces sliding parts past each other, like scissors cutting paper, and bending happens when a beam is loaded across its length."}], "qs": [["What does a cam and follower do?", ["Turns rotary motion into reciprocating motion", "Turns linear motion into rotary motion", "Makes gears spin faster", "Joins two pieces of wood"], "As the cam rotates, it pushes the follower up and down."], ["Which cam can only rotate in one direction?", ["Snail (drop) cam", "Circular (eccentric) cam", "Pear cam", "Heart cam"], "The sudden drop on a snail cam would jam the follower if it turned the other way."], ["What is a dwell in a cam movement?", ["A time when the follower does not move", "The fastest part of the rise", "When the cam changes direction", "The gap between two gears"], "During a dwell, the follower stays still while the cam keeps turning."], ["Which force is a pulling or stretching force?", ["Tension", "Compression", "Torsion", "Shear"], "Tension pulls or stretches a material."], ["Which force is a twisting force?", ["Torsion", "Tension", "Bending", "Compression"], "Torsion twists a material, like wringing out a towel."], ["A table leg holding up a heavy load is under which force?", ["Compression", "Tension", "Torsion", "Shear"], "The leg is being squashed, which is compression."], ["Two meshing spur gears turn in which directions?", ["Opposite directions", "The same direction", "They do not turn", "Only clockwise"], "When gears mesh, one turns clockwise and the other anticlockwise."], ["What is the job of an idler gear between a driver and driven gear?", ["To make them turn in the same direction", "To double the speed", "To stop the gears turning", "To change rotary into linear motion"], "An idler gear reverses the direction again, so driver and driven match."], ["A 12-tooth driver turns a 48-tooth driven gear. What is the gear ratio?", ["4:1", "1:4", "36:1", "2:1"], "Gear ratio = 48 ÷ 12 = 4, written as 4:1."], ["A driver at 200 rpm has a gear ratio of 4:1. What is the driven gear's speed?", ["50 rpm", "800 rpm", "196 rpm", "204 rpm"], "Output speed = 200 ÷ 4 = 50 rpm, because the larger driven gear turns slower."]], "bonus": ["What is 60 ÷ 4?", ["15", "14", "16", "240"], "60 ÷ 4 = 15, the kind of division used in gear speed calculations."]}, {"ht": "Sum1", "t": "Clock project: designers and specifications", "intro": "Good designers learn from the work of others. In the clock project you study famous designers and design movements, then write a design specification for your own clock. You also think about aesthetics (how it looks) and ergonomics (how well it suits people).", "how": ["Research design movements such as the Bauhaus, Art Deco and Memphis, and designers such as Marianne Brandt, Philippe Starck and Ettore Sottsass.", "Pick out key features of a style, like shapes, colours and materials, to inspire your design.", "Write a design specification: a list of clear, measurable requirements your product must meet.", "Use ACCESS FM (Aesthetics, Cost, Customer, Environment, Size, Safety, Function, Materials) to cover everything.", "Use anthropometric data, which are measurements of people, to make products ergonomic."], "example": {"q": "Practical task: write three specification points for a wall clock inspired by the Memphis style.", "steps": ["Aesthetics: the clock must use at least three bright, contrasting colours and bold geometric shapes.", "Size: the clock face must fit within 200 mm × 200 mm.", "Function: the numbers must be readable from 3 m away.", "Check each point is measurable so you can test it in your evaluation."], "a": "Three clear, measurable specification points that can be tested once the clock is made."}, "walk": [{"h": "Design movements", "b": "The Bauhaus was a German design school founded in 1919, famous for simple, functional designs and the idea that form follows function. Art Deco, popular in the 1920s and 30s, used bold geometric shapes, symmetry and luxurious materials. Memphis was a 1980s group led by Ettore Sottsass in Milan, known for bright colours, clashing patterns and playful shapes."}, {"h": "Writing a specification", "b": "A design specification lists what your product must do. Good points are measurable, for example 'must be no wider than 200 mm' rather than 'must be small'. ACCESS FM helps you remember all the areas: Aesthetics, Cost, Customer, Environment, Size, Safety, Function and Materials."}, {"h": "Aesthetics and ergonomics", "b": "Aesthetics is about how a product looks and feels, including colour, shape, texture and pattern. Ergonomics is about how well a product fits the people using it, such as numbers big enough to read easily. Designers use anthropometric data, like average hand sizes, to get this right."}], "qs": [["What is a design specification?", ["A list of requirements the product must meet", "A sketch of the final idea", "A list of famous designers", "A drawing of the workshop"], "A specification sets out the measurable requirements for a product."], ["What does aesthetics mean in design?", ["How a product looks and feels", "How much a product costs", "How strong a product is", "How a product is recycled"], "Aesthetics covers appearance: colour, shape, texture and style."], ["What does ergonomics mean?", ["How well a product suits the people using it", "How a product looks", "The cost of the materials", "The speed of production"], "Ergonomics is about making products comfortable and easy for people to use."], ["What is anthropometric data?", ["Measurements of the human body", "Information about the weather", "Data on material prices", "Results from a survey on colours"], "Anthropometrics are body measurements, like hand size or height."], ["Which is the best, measurable specification point?", ["The clock must be no wider than 200 mm", "The clock must be small", "The clock must look nice", "The clock must be good"], "A measurable point can be checked and tested."], ["In ACCESS FM, what does the F stand for?", ["Function", "Fashion", "Finish", "Fixing"], "ACCESS FM: Aesthetics, Cost, Customer, Environment, Size, Safety, Function, Materials."], ["In which country was the Bauhaus founded in 1919?", ["Germany", "Italy", "France", "USA"], "The Bauhaus was founded in Weimar, Germany, in 1919."], ["Which phrase is linked with the Bauhaus?", ["Form follows function", "Less is a bore", "More colour is better", "Decoration first"], "Bauhaus designers believed a product's shape should come from its purpose."], ["Which design movement is known for bright colours and clashing patterns in the 1980s?", ["Memphis", "Bauhaus", "Arts and Crafts", "Art Nouveau"], "The Memphis group, led by Ettore Sottsass, used bold colours and playful shapes."], ["Art Deco design is best known for what?", ["Bold geometric shapes and symmetry", "Plain, undecorated surfaces only", "Flowing plant-like curves", "Recycled materials"], "Art Deco from the 1920s and 30s used strong geometric shapes and luxury finishes."]], "bonus": ["What do we call the person a product is designed for?", ["The target user or client", "The machine operator", "The material supplier", "The shop assistant"], "Designers always start by thinking about the target user, the person the product is for."]}, {"ht": "Sum2", "t": "Clock project: CAD/CAM, acrylic and MDF", "intro": "Now you make your clock. You draw your design in CAD and cut it out using CAM, such as a laser cutter. You learn about acrylic and MDF, how to make your clock safely and accurately, and how to evaluate the finished product.", "how": ["CAD means computer-aided design; CAM means computer-aided manufacture.", "On a laser cutter, vector lines are cut or scored, and raster areas are engraved.", "Acrylic is a thermoplastic, so it can be heated and bent; MDF is a manufactured board with a smooth surface.", "Never leave a laser cutter unattended, and keep the extraction on to remove fumes.", "Evaluate your clock by testing it against each specification point and asking users for feedback."], "example": {"q": "Practical task: make an acrylic clock face using CAD/CAM.", "steps": ["Draw the clock face in 2D Design, using a circle for the outline and a small hole in the centre for the movement spindle.", "Set the outline and hole as cut lines and the numbers as engrave.", "Place the acrylic sheet in the laser cutter, check the settings and run the job without leaving the machine.", "Remove the protective film, fit the clock movement and hands.", "Test the clock against your specification and record what to improve."], "a": "An accurately cut, engraved acrylic clock face that is tested against the specification."}, "walk": [{"h": "CAD and CAM", "b": "CAD lets you draw a design on a computer, and CAM uses that file to control a machine, such as a laser cutter. CAM is accurate and repeatable, so every copy is identical. The laser cuts along vector lines and engraves raster images by burning away the surface."}, {"h": "Acrylic and MDF", "b": "Acrylic (PMMA) is a thermoplastic, which means it softens when heated and can be bent, for example on a line bender. It is hard, shiny and comes in many colours, but it can scratch and crack. MDF is a manufactured board made from wood fibres and resin; it is cheap, smooth and easy to paint, but it swells if it gets wet."}, {"h": "Make and evaluate", "b": "Check your work at each stage, such as testing the clock movement fits before gluing. An evaluation compares the finished product to every point in the specification. Get feedback from a user and suggest clear improvements, such as making the numbers bigger."}], "qs": [["What does CAM stand for?", ["Computer-aided manufacture", "Computer-aided modelling", "Computer and machine", "Cutting and making"], "CAM means using computers to control manufacturing machines."], ["What does CAD stand for?", ["Computer-aided design", "Computer and drawing", "Cutting and drilling", "Computer-aided drilling"], "CAD means designing on a computer."], ["What is acrylic?", ["A thermoplastic polymer", "A hardwood", "A manufactured board", "A metal"], "Acrylic is a thermoplastic polymer, also called PMMA."], ["Why can acrylic be bent on a line bender?", ["It is a thermoplastic that softens when heated", "It is a thermosetting plastic", "It is made of wood fibres", "It contains metal"], "Thermoplastics soften when heated and can be shaped, then harden when cooled."], ["What is MDF made from?", ["Wood fibres and resin pressed together", "Thin layers of wood glued at right angles", "Recycled plastic bottles", "Solid oak"], "MDF stands for medium-density fibreboard, made from wood fibres and resin."], ["What is a disadvantage of MDF?", ["It swells if it gets wet", "It is very expensive", "It has a rough surface", "It cannot be painted"], "MDF absorbs water and swells, so it needs sealing or painting."], ["On a laser cutter, what do raster images do?", ["Engrave the surface", "Cut right through the material", "Bend the material", "Glue parts together"], "Raster images are engraved by burning away the surface layer."], ["Why must you never leave a laser cutter unattended?", ["The material could catch fire", "It will switch itself off", "The file will be deleted", "It needs to be pushed by hand"], "Lasers produce intense heat, so there is a fire risk."], ["What is one advantage of CAM over cutting by hand?", ["Every copy is accurate and identical", "It needs no design file", "It works without electricity", "It is always cheaper for one item"], "CAM machines repeat the same design precisely every time."], ["How should you evaluate your clock?", ["Test it against every specification point", "Only say whether you like it", "Compare it with a friend's grade", "Measure how long it took"], "A good evaluation checks the product against the specification and user feedback."]], "bonus": ["Which of these materials is a plastic?", ["Acrylic", "Pine", "Steel", "Plywood"], "Acrylic is a plastic; pine and plywood are woods and steel is a metal."]}]}, {"id": "food", "name": "Food & Nutrition", "board": "AQA Food Preparation & Nutrition (8585)", "weeks": [{"ht": "Aut1", "t": "Macronutrients: protein, fats and carbs", "intro": "Macronutrients are the nutrients your body needs in large amounts: protein, fat and carbohydrate. They give you energy and the building materials for growth and repair. Knowing what each one does, where to find it and what happens if you get too little or too much is the base of everything in Food and Nutrition.", "how": ["Protein is for growth, repair and maintenance of the body, and is a secondary source of energy.", "Fat gives concentrated energy, keeps you warm, protects vital organs and carries vitamins A, D, E and K.", "Carbohydrate is the body's main source of energy and comes as sugars, starch and dietary fibre.", "Fat gives 9 kcal per gram, protein gives 4 kcal per gram and carbohydrate gives 3.75 kcal per gram.", "Too little or too much of any macronutrient causes health problems, so balance is the key."], "example": {"q": "A portion of cheese contains 8 g of fat and 6 g of protein. How much energy do the fat and protein provide altogether?", "steps": ["Fat gives 9 kcal per gram, so 8 × 9 = 72 kcal.", "Protein gives 4 kcal per gram, so 6 × 4 = 24 kcal.", "Add them together: 72 + 24 = 96 kcal.", "Notice that the fat gives three times as much energy as the protein."], "a": "The fat and protein provide 96 kcal altogether."}, "walk": [{"h": "Protein: the body builder", "b": "Protein is made of small units called amino acids. Essential amino acids cannot be made by the body, so they must come from food. High biological value (HBV) proteins, such as meat, fish, eggs, milk and soya, contain all the essential amino acids. Low biological value (LBV) proteins, such as beans, lentils, nuts and bread, are missing some, but eating two together, like beans on toast, gives you them all: this is called protein complementation."}, {"h": "Saturated and unsaturated fats", "b": "Saturated fats are usually solid at room temperature and mostly come from animals, like butter, lard and the fat on meat. Unsaturated fats are usually liquid at room temperature and come mainly from plants and oily fish, like olive oil, sunflower oil and salmon. Too much saturated fat can raise blood cholesterol and increase the risk of heart disease."}, {"h": "Sugars, starch and fibre", "b": "Sugars, like glucose, sucrose and lactose, give quick energy. Starch, found in bread, pasta, rice and potatoes, releases energy more slowly. Dietary fibre, found in wholegrain foods, fruit, vegetables and beans, cannot be digested but keeps your digestive system healthy and helps prevent constipation. Any carbohydrate you eat but do not use for energy is stored as body fat."}], "qs": [["What is the main function of protein in the body?", ["Growth, repair and maintenance of the body", "Main source of quick energy", "Insulating the body to keep it warm", "Helping the body absorb vitamin C"], "Protein provides the building material for growing, repairing damaged cells and maintaining the body."], ["Which nutrient is the body's main source of energy?", ["Carbohydrate", "Protein", "Water", "Calcium"], "Carbohydrates, such as starch and sugars, are the body's main and preferred source of energy."], ["Which food is a high biological value (HBV) protein?", ["Eggs", "Lentils", "Peanuts", "Wholemeal bread"], "Eggs contain all the essential amino acids, so they are HBV; the others are LBV plant proteins."], ["Which fat is usually solid at room temperature?", ["Butter, a saturated fat", "Olive oil", "Sunflower oil", "Rapeseed oil"], "Saturated fats like butter are usually solid at room temperature, while plant oils are liquid."], ["Which vitamins does fat carry around the body?", ["A, D, E and K", "B and C", "C and D only", "B1, B2 and B12"], "Vitamins A, D, E and K are fat-soluble, so they are carried in fat."], ["Beans on toast is a good example of what?", ["Protein complementation", "A source of saturated fat", "A source of free sugars", "Starch being turned into fibre"], "Two LBV proteins eaten together supply all the essential amino acids, which is protein complementation."], ["What can a long-term lack of dietary fibre cause?", ["Constipation", "Night blindness", "Scurvy", "Kwashiorkor"], "Fibre adds bulk and helps food move through the gut, so too little can lead to constipation."], ["Kwashiorkor is a disease caused by a severe lack of which nutrient?", ["Protein", "Fat", "Vitamin C", "Dietary fibre"], "Kwashiorkor is a protein deficiency disease that causes poor growth and a swollen stomach."], ["A snack contains 5 g of fat. How much energy does the fat provide?", ["45 kcal", "20 kcal", "18.75 kcal", "50 kcal"], "Fat gives 9 kcal per gram, so 5 × 9 = 45 kcal."], ["If you eat more carbohydrate than your body uses, what happens to the extra?", ["It is stored in the body as fat", "It is turned into vitamin C", "It is all passed out in urine", "It is used only to build muscle"], "Extra energy that is not used is stored as body fat, which can lead to weight gain."]], "bonus": ["Which of these foods is mostly carbohydrate (starch)?", ["Pasta", "Chicken", "Butter", "Cheese"], "Pasta is made from wheat flour, which is mostly starch, a type of carbohydrate."]}, {"ht": "Aut2", "t": "Micronutrients and water", "intro": "Micronutrients are vitamins and minerals. You only need them in tiny amounts, but without them your body cannot work properly. Water gives no energy, but every part of your body needs it, and you could only survive a few days without it.", "how": ["Vitamins A and D are fat-soluble, so the body can store them, and too much can be harmful.", "B vitamins and vitamin C are water-soluble, so the body cannot store them and needs them regularly.", "Calcium builds strong bones and teeth, but it needs vitamin D to be absorbed.", "Iron makes haemoglobin in red blood cells to carry oxygen, and vitamin C helps the body absorb it.", "Drink about 6 to 8 glasses of fluid a day, and more when it is hot or you are active."], "example": {"q": "Amira, aged 14, feels tired all the time and looks pale. She rarely eats meat and does not eat much fruit. Which nutrient may she be short of, and what could she change?", "steps": ["Tiredness and pale skin are signs of iron deficiency anaemia.", "Iron is found in red meat, but also in beans, lentils, dark green vegetables and fortified breakfast cereals.", "Iron from plant foods is absorbed better when eaten with vitamin C, for example from orange juice or peppers.", "Teenage girls need extra iron because they lose iron during periods.", "If the tiredness carries on, she should see a doctor."], "a": "She may be short of iron, so she could eat more iron-rich foods like lentils or fortified cereal with a vitamin C source."}, "walk": [{"h": "Fat-soluble vitamins A and D", "b": "Vitamin A helps you see in dim light and keeps your skin and immune system healthy; it is in liver, cheese and eggs, and as beta-carotene in carrots and dark green vegetables. Vitamin D helps the body absorb calcium for strong bones and teeth; your skin makes it in sunlight, and it is also in oily fish, eggs and fortified cereals. A lack of vitamin A causes night blindness, and a lack of vitamin D can cause rickets in children."}, {"h": "Water-soluble vitamins B and C", "b": "B vitamins such as thiamin, riboflavin and niacin help release energy from food, while folate and B12 help make healthy red blood cells. Vitamin C helps absorb iron, keeps skin and blood vessels healthy and helps wounds heal; it is in citrus fruits, berries, peppers and broccoli. A lack of vitamin C causes scurvy, with bleeding gums. Vitamin C is easily destroyed by heat, so steaming vegetables keeps more of it than boiling."}, {"h": "Minerals, water and life stages", "b": "Calcium (milk, cheese, yoghurt, fortified white bread) builds bones and teeth and helps blood to clot, while iron (red meat, beans, green vegetables) carries oxygen in the blood. Water controls body temperature through sweat, removes waste in urine and helps digestion. Needs change with age: teenagers need lots of calcium and iron for growth, women planning a pregnancy need folic acid, and older people need extra vitamin D because their skin makes less."}], "qs": [["Which vitamin helps you see in dim light?", ["Vitamin A", "Vitamin C", "Vitamin D", "Vitamin B12"], "Vitamin A is needed to make a pigment in the eye that helps you see in dim light."], ["Which deficiency disease is caused by a lack of vitamin C?", ["Scurvy", "Rickets", "Night blindness", "Kwashiorkor"], "Scurvy, with bleeding gums and slow wound healing, is caused by a lack of vitamin C."], ["Which mineral is needed to make haemoglobin, which carries oxygen in the blood?", ["Iron", "Calcium", "Sodium", "Fluoride"], "Iron is part of haemoglobin, the substance in red blood cells that carries oxygen."], ["How does your body make most of its vitamin D?", ["From sunlight on the skin", "From drinking water", "From eating sugar", "From breathing in oxygen"], "Your skin makes vitamin D when it is exposed to sunlight."], ["Which food is a good source of calcium?", ["Yoghurt", "Apples", "White rice", "Olive oil"], "Dairy foods like yoghurt, milk and cheese are rich in calcium."], ["Why is it helpful to have orange juice with an iron-rich meal of lentils?", ["Vitamin C helps the body absorb the iron", "Orange juice is high in natural calcium", "Vitamin C stops the lentils being digested", "Orange juice replaces the need for water"], "Vitamin C helps the body absorb non-haem iron from plant foods like lentils."], ["Which of these is a sign of dehydration?", ["Dark yellow urine and a headache", "Bleeding gums", "Night blindness", "Bowed legs"], "When you do not drink enough, urine becomes dark and you may get headaches and feel tired."], ["Why do women planning a pregnancy take folic acid?", ["It lowers the risk of neural tube defects like spina bifida", "It gives the baby extra energy", "It stops the mother getting rickets", "It replaces the need for iron"], "Folic acid helps the baby's spine and brain develop properly, reducing the risk of spina bifida."], ["Why are older people advised to make sure they get enough vitamin D?", ["Their skin makes less vitamin D from sunlight", "They need it to digest protein", "It gives them more energy than fat", "It replaces the need for calcium"], "As people age, their skin makes less vitamin D, and they need it to keep bones strong."], ["Why can too much vitamin A be harmful, while extra vitamin C is usually passed out?", ["A is stored in the body; extra C dissolves and leaves in urine", "A is water-soluble; C is fat-soluble", "C is stored in the liver; A is not", "The body cannot absorb vitamin A at all"], "Fat-soluble vitamin A builds up in the liver, but water-soluble vitamin C is not stored and leaves in urine."]], "bonus": ["Which drink is the healthiest choice for keeping hydrated every day?", ["Water", "Fizzy cola", "Energy drink", "Milkshake"], "Water hydrates the body without adding sugar, caffeine or extra calories."]}, {"ht": "Spr1", "t": "A healthy, balanced diet", "intro": "A balanced diet gives your body the right amounts of energy and nutrients. The Eatwell Guide is the UK government's picture of how much of each food group to eat across a day or a week. Different life stages need slightly different diets, because a growing teenager needs different things from an 80-year-old.", "how": ["Fruit and vegetables should make up just over a third of what you eat; aim for at least 5 portions a day.", "Starchy carbohydrates should make up just over a third; choose wholegrain or higher-fibre versions.", "Have some dairy or alternatives, and some beans, pulses, fish, eggs, meat and other proteins.", "Use small amounts of unsaturated oils and spreads, and have foods high in fat, salt and sugar less often.", "Drink 6 to 8 glasses of fluid a day, mostly water, lower-fat milk and sugar-free drinks."], "example": {"q": "A teenager's lunch is a white bread ham sandwich, a packet of crisps and a can of cola. Is it balanced, and how could it be improved?", "steps": ["Starchy carbohydrate: white bread is there, but wholemeal bread would add more fibre.", "Protein: ham is there, but it is processed and salty, so chicken, egg or tuna would be better.", "Fruit and vegetables: there are none, so add salad to the sandwich and an apple on the side.", "Crisps and cola are high in fat, salt or sugar, so swap them for a yoghurt (dairy) and water."], "a": "It is not balanced; a wholemeal chicken salad sandwich, an apple, a yoghurt and water would cover the main Eatwell groups."}, "walk": [{"h": "The five food groups", "b": "The Eatwell Guide splits food into five main groups: fruit and vegetables; potatoes, bread, rice, pasta and other starchy carbohydrates; beans, pulses, fish, eggs, meat and other proteins; dairy and alternatives; and oils and spreads. The two biggest groups, each just over a third, are fruit and vegetables and starchy carbohydrates. Oils and spreads are the smallest group, only about 1%. Foods high in fat, salt and sugar sit outside the main circle because we should eat them less often and in small amounts."}, {"h": "Variety and healthy tips", "b": "Eating a variety of foods from each group gives you a wider range of nutrients. Aim for 5 A DAY, where an adult portion is 80 g, such as one apple. Eat two portions of fish a week, one of them oily, such as salmon or mackerel, and keep salt to no more than 6 g a day for adults. Fruit juice and smoothies only count as one of your 5 A DAY, however much you drink."}, {"h": "Diets for life stages", "b": "Young children need energy and nutrients for growth, often in small, frequent meals; the Eatwell Guide does not apply to children under 2. Teenagers grow fast, so they need plenty of energy, protein, calcium and iron, especially girls once periods start. Adults need to balance energy in and out to avoid weight gain, and older people usually need less energy but plenty of calcium, vitamin D, fibre and fluids."}], "qs": [["Which two Eatwell Guide groups are the largest?", ["Fruit and vegetables, and starchy carbohydrates", "Dairy, and oils and spreads", "Proteins, and dairy", "Starchy carbohydrates, and oils and spreads"], "Fruit and vegetables and starchy carbohydrates each make up just over a third of the Eatwell Guide."], ["How many portions of fruit and vegetables should you aim to eat each day?", ["At least 5", "At least 2", "Exactly 3", "At least 10"], "The 5 A DAY advice is to eat at least 5 portions of a variety of fruit and vegetables daily."], ["Which food belongs to the 'beans, pulses, fish, eggs, meat and other proteins' group?", ["Lentils", "Cheese", "Potatoes", "Butter"], "Lentils are pulses, so they belong in the protein group; cheese is dairy and potatoes are starchy."], ["How big is one adult portion of fruit or vegetables?", ["80 g", "8 g", "800 g", "250 g"], "One adult portion of fruit or vegetables is 80 g, roughly one apple or a handful of carrots."], ["How much fluid does the Eatwell Guide recommend each day?", ["6 to 8 glasses", "1 to 2 glasses", "12 to 15 glasses", "Only when you feel thirsty"], "The Eatwell Guide recommends 6 to 8 glasses of fluid a day."], ["What is the maximum amount of salt adults should eat per day?", ["6 g", "16 g", "1 g", "60 g"], "Adults should eat no more than 6 g of salt a day, about one teaspoon."], ["Where do crisps, chocolate and sugary drinks appear on the Eatwell Guide?", ["Outside the main circle, to be eaten less often", "In the starchy carbohydrates group", "In the fruit and vegetables group", "In the dairy and alternatives group"], "Foods high in fat, salt and sugar are outside the main groups because they are not needed for a healthy diet."], ["How many portions of fish should you eat a week, and how many of them oily?", ["Two portions, one of them oily", "One portion, none of them oily", "Five portions, all of them oily", "Seven portions, two of them oily"], "The advice is two portions of fish a week, with at least one being oily fish like salmon."], ["Why do teenage girls need more iron than younger children?", ["They grow fast and lose iron during periods", "Iron gives them more energy than carbohydrate", "Iron stops them growing too tall", "They cannot absorb calcium"], "Rapid growth and blood loss during periods both increase a teenage girl's need for iron."], ["Why might an 80-year-old need fewer calories but more vitamin D?", ["They are usually less active, and their skin makes less vitamin D", "They grow faster than teenagers", "Vitamin D gives them extra energy", "They cannot digest any fat"], "Older people often move less, so need less energy, and their skin makes less vitamin D for bones."]], "bonus": ["Why do we need to eat a variety of different foods?", ["Different foods give us different nutrients", "So that we eat as many calories as possible", "Because one food contains every nutrient we need", "To make our food last longer"], "No single food has every nutrient, so eating a variety helps us get everything our body needs."]}, {"ht": "Spr2", "t": "Diet, nutrition and health", "intro": "What we eat over many years affects our health. Nutritional analysis lets us work out the energy and nutrients in a meal and compare them with what a person needs. Too much energy, saturated fat, salt or sugar is linked to obesity, heart disease and type 2 diabetes, but many other factors also affect what people choose to eat.", "how": ["Energy from food: fat 9 kcal/g, protein 4 kcal/g, carbohydrate 3.75 kcal/g.", "If energy in is more than energy out over time, the extra is stored as fat and weight goes up.", "BMI = weight in kg ÷ (height in m)²; for adults, a BMI of 30 or more is classed as obese.", "Too much saturated fat and salt raises the risk of cardiovascular disease; too much energy and sugar raises the risk of type 2 diabetes.", "Food choice is affected by cost, culture, religion, health, ethics, allergies, availability and personal likes."], "example": {"q": "A cereal bar contains 6 g of fat, 3 g of protein and 20 g of carbohydrate. How many kcal does it provide?", "steps": ["Fat: 6 × 9 = 54 kcal.", "Protein: 3 × 4 = 12 kcal.", "Carbohydrate: 20 × 3.75 = 75 kcal.", "Total: 54 + 12 + 75 = 141 kcal."], "a": "The cereal bar provides 141 kcal."}, "walk": [{"h": "Nutritional analysis", "b": "Nutritional analysis means working out the energy and nutrients in a recipe or meal, often using software. The results are compared with Dietary Reference Values (DRVs), which show how much of each nutrient different groups of people need. A person's daily energy need is their basal metabolic rate (BMR, the energy needed just to stay alive) multiplied by their physical activity level (PAL). If a recipe is too high in salt, for example, you could swap stock cubes for herbs and spices."}, {"h": "Diet-related diseases", "b": "Obesity means having so much body fat that it harms health; for adults it means a BMI of 30 or over. Cardiovascular disease includes coronary heart disease and strokes: fatty deposits linked to too much saturated fat narrow the arteries, and too much salt raises blood pressure. Type 2 diabetes happens when the body does not make enough insulin or cannot use it properly, so blood sugar stays too high; being overweight is a major risk factor."}, {"h": "Factors affecting food choice", "b": "People choose food for many reasons: cost, what is in season or in local shops, how busy they are and what they enjoy. Religion and culture matter too; for example, Muslims eat halal food and do not eat pork, and many Hindus do not eat beef. Ethical beliefs (like buying Fairtrade or free-range), allergies and intolerances (like a nut allergy or lactose intolerance) and health conditions also shape choices."}], "qs": [["What BMI is classed as obese for an adult?", ["30 or more", "18.5 or less", "20 to 24.9", "Exactly 25"], "For adults, a BMI of 30 or over is classed as obese."], ["How many kcal does 1 g of fat provide?", ["9 kcal", "4 kcal", "3.75 kcal", "7 kcal"], "Fat is the most concentrated energy source, giving 9 kcal per gram."], ["Which hormone is involved in type 2 diabetes?", ["Insulin", "Adrenaline", "Haemoglobin", "Collagen"], "In type 2 diabetes the body does not make enough insulin or cannot use it properly."], ["Eating too much salt is mainly linked to which health problem?", ["High blood pressure", "Scurvy", "Night blindness", "Tooth decay"], "Too much salt raises blood pressure, which increases the risk of heart disease and strokes."], ["Which is a religious reason for food choice?", ["Muslims eat halal food and do not eat pork", "Choosing food because it is on special offer", "Buying strawberries in summer", "Avoiding peanuts because of an allergy"], "Islamic dietary laws mean Muslims eat halal food and avoid pork; the others are cost, season and health."], ["What is nutritional analysis?", ["Working out the energy and nutrients in a food or meal", "Testing how food tastes on a panel", "Checking food for harmful bacteria", "Measuring how long food takes to cook"], "Nutritional analysis calculates the energy and nutrients in food, often using software."], ["An adult weighs 80 kg and is 2 m tall. What is their BMI?", ["20", "40", "160", "25"], "BMI = 80 ÷ (2 × 2) = 80 ÷ 4 = 20."], ["A food has 10 g of protein and 4 g of fat. How much energy is this?", ["76 kcal", "56 kcal", "106 kcal", "126 kcal"], "Protein 10 × 4 = 40 kcal, fat 4 × 9 = 36 kcal, so 40 + 36 = 76 kcal."], ["How does too much saturated fat increase the risk of coronary heart disease?", ["Fatty deposits build up and narrow the arteries", "It makes the bones weak and brittle", "It stops the body making insulin at once", "It destroys vitamin C in the blood"], "Saturated fat can raise cholesterol, which forms fatty deposits that narrow the arteries to the heart."], ["A person's BMR is 1,600 kcal and their PAL is 1.5. How many kcal do they need a day?", ["2,400 kcal", "1,601.5 kcal", "1,067 kcal", "3,200 kcal"], "Energy need = BMR × PAL = 1,600 × 1.5 = 2,400 kcal."]], "bonus": ["Energy calculations need times tables. What is 12 × 9?", ["108", "96", "117", "102"], "12 × 9 = 108 (10 × 9 = 90, plus 2 × 9 = 18)."]}, {"ht": "Sum1", "t": "British and international cuisines", "intro": "A cuisine is a style of cooking and eating that belongs to a particular country or region. Each cuisine has its own typical ingredients, cooking methods, dishes and ways of serving and eating food. Studying English, Italian and Moroccan cuisines shows how climate, farming, history and culture shape what people eat.", "how": ["A cuisine has distinctive ingredients, cooking methods, equipment, presentation and eating habits.", "Traditional English cuisine uses local meat, potatoes, root vegetables and wheat, cooked by roasting, baking and stewing.", "Italian cuisine is built on pasta, rice, tomatoes, olive oil, cheese and herbs, and varies from region to region.", "Moroccan cuisine uses couscous, chickpeas, dates, preserved lemons and warm spices, often slow-cooked in a tagine.", "When comparing cuisines, think about climate, local farming, history and religion."], "example": {"q": "Explain why the tagine is a traditional cooking method in Morocco.", "steps": ["A tagine is a clay pot with a cone-shaped lid, and also the name of the stew cooked in it.", "The cone lid traps steam, which condenses and drips back down, keeping the food moist.", "This means very little water is needed, which is useful in a hot, dry climate.", "Slow cooking also makes cheaper, tougher cuts of meat, such as lamb shoulder, tender and blends the spices."], "a": "Tagines suit Morocco because they cook tough meat slowly until tender while using very little water."}, "walk": [{"h": "What makes a cuisine", "b": "A cuisine is recognised by the ingredients grown or reared locally, its cooking methods, its special equipment and the way food is presented and eaten. For example, rice and woks are central to much Chinese cooking. Climate and geography matter too: countries with long coastlines often eat lots of fish."}, {"h": "Traditional English cuisine", "b": "England's cool, wet climate suits wheat, potatoes, root vegetables, apples and grazing animals like cattle and sheep. Traditional dishes include roast beef with Yorkshire pudding, shepherd's pie (made with lamb), Lancashire hotpot, Cornish pasties, fish and chips, and scones for afternoon tea. Common cooking methods are roasting, baking, stewing and frying."}, {"h": "Italian and Moroccan cuisines", "b": "Italian food features pasta, risotto rice, tomatoes, olive oil, garlic, basil and cheeses such as Parmesan and mozzarella; a traditional meal may include antipasto (starter), primo (pasta, risotto or soup) and secondo (meat or fish). Moroccan food mixes Berber, Arab and Mediterranean influences, using couscous, spices such as cumin, cinnamon and the blend ras el hanout, and sweet-savoury flavours like lamb with apricots. Most Moroccans are Muslim, so meat is halal and pork is not eaten, and mint tea is offered as a sign of welcome."}], "qs": [["What is a cuisine?", ["A style of cooking typical of a country or region", "A single recipe for a main course", "A piece of kitchen equipment", "A type of restaurant menu"], "A cuisine is the typical ingredients, methods and dishes of a particular country or region."], ["Which dish is traditionally English?", ["Lancashire hotpot", "Risotto", "Tagine", "Paella"], "Lancashire hotpot is a traditional English lamb and potato stew; the others are Italian, Moroccan and Spanish."], ["Shepherd's pie is traditionally made with which meat?", ["Lamb", "Beef", "Pork", "Chicken"], "Shepherd's pie uses lamb (shepherds look after sheep); the beef version is called cottage pie."], ["Which of these is a traditional Italian cheese?", ["Parmesan", "Cheddar", "Stilton", "Wensleydale"], "Parmesan (Parmigiano-Reggiano) comes from Italy; the others are English cheeses."], ["What is couscous made from?", ["Semolina from durum wheat", "Ground chickpeas", "Rice flour", "Crushed dates"], "Couscous is made from small granules of semolina, which comes from durum wheat."], ["What is ras el hanout?", ["A Moroccan blend of spices", "An Italian pasta shape", "A type of English pudding", "A Moroccan clay cooking pot"], "Ras el hanout is a warm Moroccan spice mix that can include cumin, cinnamon and ginger."], ["Why does a tagine's cone-shaped lid matter?", ["It traps steam, which drips back and keeps food moist", "It makes the food cook very fast", "It lets all the steam escape", "It is used to serve mint tea"], "The tall lid collects steam, which condenses and runs back into the food, so little water is needed."], ["In a traditional Italian meal, what is the 'primo' course?", ["A pasta, risotto or soup course", "The dessert", "The main meat or fish course", "A drink before the meal"], "The primo is the first main course, usually pasta, risotto or soup, before the secondo."], ["Why is pork not eaten in traditional Moroccan cuisine?", ["Most Moroccans are Muslim, and Islam forbids pork", "Pigs cannot be farmed anywhere in Africa", "Pork is too expensive to import", "All Moroccans are vegetarian"], "Islamic dietary law forbids pork, and most Moroccans are Muslim, so meat is halal and pork-free."], ["Why does traditional English food use lots of potatoes and root vegetables?", ["They grow well in England's cool, wet climate", "They were first brought from Morocco", "They need a hot, dry climate", "They cannot be grown in other countries"], "Cuisines use what grows locally, and potatoes and root vegetables thrive in England's climate."]], "bonus": ["Which cooking method cooks food with dry heat in an oven?", ["Baking", "Boiling", "Steaming", "Poaching"], "Baking (and roasting) use dry heat in an oven; boiling, steaming and poaching use water or steam."]}, {"ht": "Sum2", "t": "Sensory evaluation", "intro": "Sensory evaluation means judging food using our senses: sight, smell, taste, touch and hearing. Food companies and chefs use it to test new products and find out what people like. It also helps you improve your own dishes in practical lessons.", "how": ["Use all five senses: appearance, aroma, taste, texture (mouthfeel) and sound.", "The five basic tastes are sweet, salty, sour, bitter and umami.", "Make tests fair: use random codes, small samples, clean spoons and water between samples.", "Choose the right test: preference, ranking, rating or profiling.", "Use descriptive words such as crispy, tangy, smooth or aromatic, not just 'nice'."], "example": {"q": "Four tasters score the crunchiness of a cookie out of 5: 4, 3, 5 and 4. What score goes on the star profile?", "steps": ["Add the scores: 4 + 3 + 5 + 4 = 16.", "Divide by the number of tasters: 16 ÷ 4 = 4.", "Mark 4 on the 'crunchy' arm of the star diagram.", "Repeat for each attribute, then join the points to make the profile shape."], "a": "The average crunchiness score is 4 out of 5."}, "walk": [{"h": "How we taste", "b": "Your tongue is covered in tiny bumps called papillae, which hold taste buds containing taste receptors. These detect five basic tastes: sweet, salty, sour, bitter and umami, a savoury taste found in cheese, tomatoes and soy sauce. Smell is just as important: aromas travel up to the olfactory receptors in your nose, which is why food tastes bland when you have a cold."}, {"h": "Senses and food choice", "b": "We eat with our eyes first: bright colours and neat presentation make food look appealing. Smell, like freshly baked bread, can make us feel hungry, while texture, like crispy chips or creamy yoghurt, affects how much we enjoy food. Even sound matters: the crunch of an apple or the sizzle of a pan suggests freshness."}, {"h": "Sensory testing methods", "b": "In a preference test, tasters simply say which sample they like most. In a ranking test, they put samples in order, such as sweetest to least sweet. In a rating test, they score a sample on a scale, like 1 to 5. In a profiling test, they score several attributes, and the average results are plotted on a star diagram."}], "qs": [["Which of these is NOT one of the five basic tastes?", ["Spicy", "Umami", "Bitter", "Sour"], "Spicy heat is a burning sensation, not a basic taste; the five are sweet, salty, sour, bitter and umami."], ["What is umami?", ["A savoury taste, as in cheese and soy sauce", "A sour taste, as in lemons", "A type of sensory test", "A Japanese cooking method"], "Umami is the savoury taste found in foods like cheese, tomatoes, mushrooms and soy sauce."], ["Why does food taste bland when you have a cold?", ["A blocked nose stops you smelling the aromas", "Your taste buds stop working completely", "Colds make food less salty", "Your teeth cannot chew properly"], "Much of flavour comes from smell, so a blocked nose reduces how much flavour you notice."], ["Which sense judges the colour and presentation of a dish?", ["Sight", "Hearing", "Smell", "Touch"], "Colour and presentation are judged by sight, which is often the first sense we use."], ["In which test do tasters put samples in order, such as sweetest to least sweet?", ["Ranking test", "Rating test", "Profiling test", "Preference test"], "A ranking test puts samples in order of a particular characteristic."], ["In which test do tasters score a sample on a scale, such as 1 to 5?", ["Rating test", "Ranking test", "Paired preference test", "Triangle test"], "A rating test uses a scale to score how much of a quality a sample has or how much it is liked."], ["Why are samples labelled with random codes, such as 381 or 726?", ["So tasters are not biased by knowing what each one is", "To show which sample is the best", "To make the samples taste better", "So tasters know the price of each"], "Random codes hide the identity of each sample, making the test fair."], ["Why should tasters sip water between samples?", ["To cleanse the palate so flavours do not mix", "To make the food taste sweeter", "To fill them up so they eat less", "To cool the food down"], "Water clears the previous flavour from the mouth so each sample is judged fairly."], ["Which test's results are shown on a star diagram?", ["A profiling test of several attributes", "A single preference vote", "A list of product prices", "A record of cooking times"], "A star profile plots the average scores for several attributes, such as sweetness and crunchiness."], ["Three tasters rate the sweetness of a drink 2, 4 and 3 out of 5. What is the average?", ["3", "9", "4", "2.5"], "Add the scores, 2 + 4 + 3 = 9, then divide by 3 tasters: 9 ÷ 3 = 3."]], "bonus": ["How many senses do we traditionally say humans have?", ["Five", "Three", "Four", "Six"], "The five senses are sight, hearing, smell, taste and touch."]}]}, {"id": "drama", "name": "Drama", "board": "Pearson Edexcel (1DR0)", "weeks": [{"ht": "Aut1", "t": "Performance skills", "intro": "Performance skills are the tools an actor uses to tell a story: your voice, your body, your face and the space around you. Stylised movement, physical theatre and choral speaking let you show ideas in bold ways that go beyond everyday real life. You will use these skills in every devised and scripted performance at GCSE.", "how": ["Vocal skills include pitch, pace, pause, volume, tone, accent, emphasis and intonation.", "Physical skills include posture, gesture, facial expression, eye contact, movement and use of space (proxemics).", "Stylised movement changes real actions on purpose, using slow motion, repetition, exaggeration or mime to make a point.", "Frantic Assembly build physical theatre from simple building blocks such as chair duets, Round/By/Through and hymn hands.", "Choral speaking means a group speaking lines together, using unison, canon, echo and contrast for effect."], "example": {"q": "Your group must show a stressful morning commute in 30 seconds without words. How could you stage it?", "steps": ["Choose stylised movement instead of realism so the stress is easy to see.", "Create a short repeated motif, such as checking a watch, gripping a rail and swaying.", "Repeat the motif faster and faster to show rising stress, using tight proxemics to show crowding.", "Add different levels (standing, crouching, on a chair) to make the stage picture interesting.", "End with a sudden freeze, then one person breaking away in slow motion to focus the audience."], "a": "A repeated, speeding-up movement motif with levels, a freeze and a slow-motion moment shows stress clearly without any speech."}, "walk": [{"h": "Voice and body", "b": "Every character is built from vocal and physical choices. A nervous character might use a fast pace, high pitch and fidgety hands. A powerful character might speak slowly with a low pitch and stand tall and still."}, {"h": "Stylised movement", "b": "Stylised movement is not trying to look exactly like real life. Slow motion, freeze frames, repetition and exaggerated gestures help the audience notice an important moment. For example, a fight shown in slow motion lets the audience see each reaction clearly and safely."}, {"h": "Frantic Assembly and chorus", "b": "Frantic Assembly is a physical theatre company that creates movement through simple tasks. In a chair duet, two performers repeat a sequence of touches and movements on chairs to show a relationship. Choral speaking works in a similar group way: a chorus might speak in unison to sound powerful, or in canon to sound like overlapping thoughts."}], "qs": [["Which of these is a vocal skill?", ["Pitch", "Gesture", "Posture", "Facial expression"], "Pitch is how high or low the voice is, so it is a vocal skill; the others are physical skills."], ["In vocal skills, what does 'pace' mean?", ["How fast or slow you speak", "How loud you speak", "How high or low your voice is", "The accent you use"], "Pace is the speed of speech, for example speaking quickly to show panic."], ["What is proxemics?", ["The use of space and distance between performers", "Speaking lines at the same time", "A type of stage lighting", "Moving in slow motion"], "Proxemics is about space between characters, which can show how close or distant their relationship is."], ["What is a freeze frame (tableau)?", ["A still image made with performers' bodies", "A scene performed in the dark", "A long speech by one character", "A song sung by the whole cast"], "A freeze frame is a frozen picture that captures one important moment."], ["Which company is known for chair duets and hymn hands?", ["Frantic Assembly", "Shakespeare's Globe", "The National Youth Choir", "The Royal Ballet"], "Frantic Assembly are a physical theatre company famous for these building-block exercises."], ["What does choral speaking in unison mean?", ["The whole group says the same words at the same time", "Each person speaks one after another", "One person speaks while others mime", "The group sings the lines as a song"], "Unison means together at exactly the same moment, which sounds strong and powerful."], ["In choral speaking, what is canon?", ["Performers start the same line one after another, overlapping", "Everyone whispers the line together", "One person speaks the line alone", "The group hums under the line"], "In canon, voices come in at different times so the line overlaps, like a round."], ["Why might a director use slow motion?", ["To highlight a key moment so the audience notices detail", "To make the play finish sooner", "So the actors do not need to learn lines", "To change the scenery quietly"], "Slowing the action draws the audience's attention to an important moment."], ["An actor lowers their voice and slows down to give bad news. Which skills are they using?", ["Volume and pace", "Gesture and posture", "Accent and eye contact", "Levels and proxemics"], "Getting quieter is volume and slowing down is pace, both vocal skills."], ["In Frantic Assembly's Round/By/Through, what do performers do?", ["Move round, by and through each other in a flowing sequence", "Speak a line round the circle one by one", "Stand in a round freeze frame", "Pass a prop round the group"], "Round/By/Through is a movement exercise where performers travel round, past and through each other's space."]], "bonus": ["What is facial expression used for in drama?", ["Showing a character's feelings through the face", "Making your voice louder", "Moving the set between scenes", "Changing the lighting colour"], "Facial expressions, like a frown or wide eyes, show the audience what a character is feeling."]}, {"ht": "Aut2", "t": "Practitioners: Stanislavski and Brecht", "intro": "A theatre practitioner is someone who created a style of theatre and a set of techniques that others still use. Stanislavski wanted acting to look truthful and real, while Brecht wanted audiences to stay alert and think about society. Knowing both helps you make clear, deliberate choices when you devise and perform.", "how": ["Stanislavski is linked to naturalism: acting that looks like real life.", "Stanislavski's techniques include given circumstances, the magic if, objectives, emotion memory and subtext.", "Brecht created epic theatre, which reminds the audience they are watching a play so they think rather than just feel.", "Brecht's techniques include breaking the fourth wall, placards, narration, multi-role, gestus and visible set changes.", "Brecht's aim is often called the distancing (or alienation) effect: stopping the audience getting lost in the story."], "example": {"q": "You are playing a teenager who has just been told they are moving away. How would you prepare using Stanislavski?", "steps": ["Write down the given circumstances: who you are, where you are, when it is and what has just happened.", "Ask the magic if: what would I do if I were really in this situation?", "Decide your objective in the scene, for example 'I want to persuade my parent to let me stay'.", "Use emotion memory by recalling a time you felt upset about a big change.", "Think about subtext: what you really feel underneath the words you say."], "a": "By using given circumstances, the magic if, an objective, emotion memory and subtext, the performance becomes truthful and believable."}, "walk": [{"h": "Stanislavski's naturalism", "b": "Konstantin Stanislavski was a Russian director and actor. He wanted actors to believe in their characters so the audience would too. For example, before entering a scene, an actor might imagine exactly where their character has just come from."}, {"h": "Brecht's epic theatre", "b": "Bertolt Brecht was a German playwright and director. He did not want audiences to simply cry or laugh; he wanted them to think about unfairness in society and want to change it. So he kept reminding them it was a play, for example by having an actor step out of a scene to speak to the audience."}, {"h": "Brecht's techniques", "b": "A placard is a sign showing information, such as the title of a scene. Multi-role means one actor plays several characters, often changing costume in view of the audience. Gestus is a clear gesture that sums up a character's attitude, such as a boss clicking their fingers to show power."}], "qs": [["Which practitioner is most linked to naturalism?", ["Stanislavski", "Brecht", "Frantic Assembly", "Sophocles"], "Stanislavski wanted acting to look like real life, which is naturalism."], ["What is Stanislavski's 'magic if'?", ["Asking 'What would I do if I were this character here?'", "A trick using hidden stage effects", "Changing the ending of a play", "Speaking directly to the audience"], "The magic if helps an actor imagine themselves truthfully in the character's situation."], ["What are 'given circumstances'?", ["The facts of the character's situation: who, where, when and what", "The props the director gives you", "The rules for the audience", "The costumes in the wardrobe"], "Given circumstances are the details from the script that shape how a character behaves."], ["In Stanislavski's system, what is an objective?", ["What a character wants in a scene", "The set design for a scene", "The lighting cue at the start", "A line the actor forgets"], "An objective is the character's goal, such as 'I want to be forgiven'."], ["What is emotion memory?", ["Recalling a real feeling from your own life to use in a role", "Memorising lines in the right order", "Remembering where to stand", "Writing a diary in role"], "Emotion memory uses your own past feelings to make an emotion truthful on stage."], ["What did Brecht want his audiences to do?", ["Think critically about society", "Forget they are in a theatre", "Cry as much as possible", "Join in singing every song"], "Brecht wanted audiences to stay alert and think about the issues shown."], ["What is 'breaking the fourth wall'?", ["Speaking or acting directly to the audience", "Knocking down part of the set", "Changing scene in a blackout", "Using four actors in a scene"], "The fourth wall is the invisible wall between stage and audience; breaking it means addressing them."], ["In Brecht's theatre, what is a placard?", ["A sign that gives the audience information", "A type of costume", "A long emotional speech", "A spotlight on one actor"], "Placards, such as scene titles, remind the audience they are watching a play."], ["What is gestus?", ["A clear gesture that sums up a character's attitude or status", "A sound effect played offstage", "A song at the end of the play", "A memory exercise for actors"], "Gestus is a clear, often exaggerated gesture that shows a character's social attitude."], ["Which choice would Brecht be most likely to use?", ["Multi-role with costume changes in view of the audience", "A fully realistic living-room set", "Emotion memory to make the audience cry", "Hidden lighting to create a real sunset"], "Brecht liked showing the workings of theatre, so visible costume changes fit his style."]], "bonus": ["What is a theatre practitioner?", ["Someone who created a style of theatre and techniques others use", "Anyone who buys a theatre ticket", "The person who sells programmes", "A building where plays are performed"], "Practitioners like Stanislavski and Brecht developed methods that actors and directors still use."]}, {"ht": "Spr1", "t": "Monologues and devising", "intro": "A monologue is a long speech by one character, and devising means creating your own original drama as a group. This half-term you build a group monologue based on real people and devise a piece from a stimulus. Devising is a big part of the GCSE, where you perform your piece and write a portfolio about how you made it.", "how": ["A monologue lets the audience hear one character's thoughts and feelings in depth.", "When basing drama on real people, research carefully and represent them respectfully and accurately.", "Verbatim theatre uses the real words of real people, often taken from interviews.", "A stimulus is a starting point, such as a photo, poem, song, object, news story or quotation.", "Devising follows a process: explore the stimulus, research, improvise, select ideas, rehearse, refine and evaluate."], "example": {"q": "Your stimulus is a photograph of an empty playground. How would your group begin devising?", "steps": ["Mind-map first reactions: who used to play here, why is it empty, what has changed?", "Pick the strongest idea, for example a community where a local school has closed.", "Improvise short scenes and hot-seat characters to develop them.", "Choose a style and structure, such as using a flashback to show the playground when it was busy.", "Rehearse, refine and note your decisions for the portfolio."], "a": "The group turns the photo into a clear story by brainstorming, improvising, choosing a structure and refining their work."}, "walk": [{"h": "What makes a monologue", "b": "In a monologue, one character speaks for a long time, often sharing private thoughts. Good monologues have a clear journey, such as starting calm and ending angry. For example, a character might begin by describing a normal day and slowly reveal a shocking event."}, {"h": "A group monologue", "b": "In a group monologue, several performers share one person's speech. They can split lines, speak some phrases in unison and use movement to show the person's feelings. If the speech is about a real person, the group must research their story and treat it with respect."}, {"h": "Devising from a stimulus", "b": "A stimulus is just a spark for ideas. Start broad, then narrow down to one clear message you want the audience to understand. Techniques like improvisation, hot-seating, flashback and narration help you build and structure the piece."}], "qs": [["What is a monologue?", ["A long speech spoken by one character", "A conversation between two characters", "A scene with no words", "A song sung by a chorus"], "Mono means one: a monologue is one character speaking at length."], ["In devising, what is a stimulus?", ["A starting point that inspires ideas", "The final bow at the end", "A script written by a playwright", "The theatre's lighting desk"], "A stimulus, such as a photo or poem, sparks the ideas for your piece."], ["What is verbatim theatre?", ["Drama using the exact words of real people", "Drama performed without any words", "Drama that is fully improvised", "Drama performed only by puppets"], "Verbatim means word for word, so it uses real people's actual words, often from interviews."], ["What is usually the best first step when devising from a stimulus?", ["Explore and brainstorm ideas, for example with a mind map", "Design the costumes", "Perform it for an audience", "Write the evaluation"], "You need ideas before you can shape, rehearse or evaluate anything."], ["Why research when your drama is based on a real person?", ["To represent their experience accurately and respectfully", "So you can change their story completely", "Because it makes the piece longer", "So you can avoid rehearsing"], "Research helps you show real people truthfully and sensitively."], ["What is improvisation?", ["Making up drama on the spot without a script", "Learning lines word for word", "Writing the programme notes", "Copying a scene from a film"], "Improvising lets a group test ideas quickly before choosing what to keep."], ["What is hot-seating?", ["A performer answers questions in role as their character", "Sitting in the audience to watch", "A fast warm-up game", "Swapping parts with another actor"], "Hot-seating helps you understand a character's thoughts, history and motives."], ["Which technique shows events from earlier in time?", ["Flashback", "Unison", "Thrust staging", "Underscoring"], "A flashback jumps back in time to show something that happened before."], ["In a group monologue, how might performers share the speech?", ["Split the lines and speak key phrases in unison", "Only one person speaks while others leave", "Each performer writes a different story", "Everyone reads silently"], "Sharing and combining lines turns one voice into a powerful group performance."], ["Besides the performance, what else do you create for the Edexcel devising component?", ["A portfolio explaining and evaluating your process", "A full-length published script", "A film of a rehearsal only", "A poster for the show"], "The devising component is assessed on a portfolio and the devised performance."]], "bonus": ["What is the difference between a monologue and a dialogue?", ["A monologue is one person speaking; a dialogue is two or more", "A monologue is sung; a dialogue is spoken", "A monologue is silent; a dialogue is loud", "There is no difference"], "Dialogue is conversation between characters, while a monologue is one character speaking alone."]}, {"ht": "Spr2", "t": "Theatre design", "intro": "Designers create the world of the play through set, costume, lighting and sound. Their choices tell the audience where and when the play is set and how they should feel. At GCSE you need to use design vocabulary accurately and explain the effect of every choice.", "how": ["Know the staging types: proscenium arch or end on, thrust, in the round, traverse and promenade.", "Set design includes furniture, props, backdrops, flats and levels such as rostra.", "Costume design considers colour, fabric, fit, condition, period, accessories, hair and make-up.", "Lighting design uses lanterns, colour gels, gobos, intensity, fades and blackouts.", "Sound design uses sound effects, music, underscoring, soundscapes, volume and direction."], "example": {"q": "Design the lighting for a tense scene where a character waits alone at night in a forest.", "steps": ["Choose a low-intensity, cold blue wash to suggest night-time.", "Use a gobo in a profile lantern to project the pattern of branches on the floor.", "Add a tight spotlight on the character to show isolation.", "Slowly fade the wash down as tension builds, leaving only the spotlight.", "Explain the effect: the audience feels the character is alone and in danger."], "a": "A dim blue wash, a branch gobo and a slowly tightening spotlight create a cold, lonely and tense atmosphere."}, "walk": [{"h": "Staging and set", "b": "The staging type decides where the audience sits. In the round, the audience surrounds the stage, so tall set pieces would block the view. A set designer might use a few key items, such as a single bed and a window frame, to suggest a whole bedroom."}, {"h": "Costume and lighting", "b": "Costume shows character, status and time period. A torn, faded coat suggests poverty, while a crisp suit suggests wealth. Lighting sets mood and focus: a warm amber wash feels safe, while harsh white light feels clinical or exposed."}, {"h": "Sound and the designer's job", "b": "Sound can be live or recorded and can tell the audience the location, like seagulls for a beach. A soundscape layers several sounds to build an atmosphere. As a designer, always explain what you would do, how, and why: the effect on the audience."}], "qs": [["Where does the audience sit for theatre in the round?", ["On all sides of the stage", "Only in front of the stage", "On two sides facing each other", "On three sides of the stage"], "In the round means the audience surrounds the acting area."], ["What is a thrust stage?", ["A stage with the audience on three sides", "A stage with the audience on all sides", "A stage that moves up and down", "A stage outdoors only"], "A thrust stage pushes out into the audience, who sit on three sides."], ["What is traverse staging?", ["The audience sits on two sides facing each other", "The audience follows actors to different places", "The audience sits on all four sides", "The audience sits only in front"], "In traverse, the stage is like a catwalk with the audience on either side."], ["What is a gobo?", ["A stencil in a lantern that projects a pattern", "A coloured sheet for a lantern", "A type of microphone", "A platform for levels"], "Gobos project shapes like windows, leaves or stars onto the stage."], ["What is a gel in lighting?", ["A coloured filter placed in front of a lantern", "A lantern that makes a sharp beam", "A sound effect", "A costume fabric"], "Gels change the colour of the light, such as blue for night."], ["Which lantern gives a sharp, hard-edged beam?", ["Profile", "Fresnel", "Floodlight", "Par can wash"], "A profile spot gives a crisp edge and can hold a gobo; a fresnel is soft-edged."], ["What is underscoring?", ["Music played quietly under action or speech", "Drawing lines on the script", "Loud music between scenes only", "A sound made by the audience"], "Underscoring supports the mood without drowning out the actors."], ["What are rostra?", ["Platforms used to create different levels", "Curtains at the side of the stage", "Coloured light filters", "Painted backdrops"], "Rostra are blocks or platforms that let actors stand at different heights."], ["A character has fallen on hard times. Which costume shows this best?", ["Worn, faded and patched clothing", "A brand-new tailored suit", "A sparkly party dress", "A crisp school uniform"], "The condition of a costume shows status and circumstances."], ["What is a soundscape?", ["Layers of sounds combined to create an atmosphere or place", "A single loud bang", "A song sung by the cast", "Silence between scenes"], "Combining sounds, such as wind, birds and distant traffic, builds a whole environment."]], "bonus": ["In drama, what are props?", ["Objects actors use on stage, like a cup or a letter", "The lights above the stage", "The seats for the audience", "The words in the script"], "Props, short for properties, are items that actors handle during a performance."]}, {"ht": "Sum1", "t": "Antigone by Sophocles", "intro": "Antigone is an ancient Greek tragedy by Sophocles and is one of the GCSE set texts. It tells the story of a young woman who defies the king to bury her brother. You need to know the plot, characters, themes and how Greek theatre worked.", "how": ["After a civil war, brothers Eteocles and Polynices kill each other; King Creon honours Eteocles but forbids anyone to bury Polynices.", "Antigone buries Polynices because she believes the laws of the gods matter more than the king's law.", "Key characters: Antigone, Creon, Ismene (her sister), Haemon (Creon's son), Tiresias (a blind prophet) and the Chorus of Theban elders.", "Main themes include power, law versus conscience, family loyalty, pride and fate.", "Greek theatre used masks, a chorus, an all-male cast and outdoor theatres, with violence reported rather than shown."], "example": {"q": "Explain how Creon's choices lead to his downfall.", "steps": ["Creon makes a harsh law that Polynices must not be buried.", "He refuses to listen to Antigone, Haemon and the Chorus because of his pride.", "He ignores Tiresias at first, then changes his mind too late.", "Antigone kills herself, then Haemon and Creon's wife Eurydice die too.", "Creon is left alone, realising his stubbornness has destroyed his family."], "a": "Creon's pride and refusal to listen cause the deaths of those he loves, leaving him broken."}, "walk": [{"h": "The story", "b": "Antigone asks her sister Ismene to help bury their brother, but Ismene is too afraid. Antigone does it alone, is caught and brought before Creon, and refuses to back down. Creon sentences her to be sealed alive in a rocky tomb."}, {"h": "Characters and conflict", "b": "Haemon, Creon's son, is engaged to Antigone and argues with his father to spare her. Tiresias, the blind prophet, warns Creon that the gods are angry. The Chorus of elders comments on events and helps the audience reflect on what is happening."}, {"h": "Greek theatre context", "b": "The play was written around 2,500 years ago and performed in huge open-air theatres in Athens at a festival for the god Dionysus. All actors were men and wore masks, and the Chorus sang and moved together in the orchestra, a circular space in front of the stage building. Deaths happened offstage and a messenger described them to the audience."}], "qs": [["Who wrote Antigone?", ["Sophocles", "Shakespeare", "Euripides", "Aristophanes"], "Antigone is a tragedy by the ancient Greek playwright Sophocles."], ["Which brother does Creon forbid anyone to bury?", ["Polynices", "Eteocles", "Haemon", "Tiresias"], "Creon sees Polynices as a traitor, so he orders that his body be left unburied."], ["Why does Antigone bury her brother?", ["She believes the gods' laws come before the king's law", "She wants to become queen", "Creon secretly asks her to", "She wants to anger Ismene"], "Antigone puts her duty to the gods and her family above Creon's order."], ["Who is Ismene?", ["Antigone's sister, who at first refuses to help", "Creon's wife", "A blind prophet", "Leader of the Chorus"], "Ismene is too afraid to break the law, which contrasts with Antigone's courage."], ["Who is Haemon?", ["Creon's son, who is engaged to Antigone", "Antigone's brother", "A guard", "King of Athens"], "Haemon is torn between loyalty to his father and his love for Antigone."], ["What role does Tiresias play?", ["A blind prophet who warns Creon about the gods' anger", "A soldier who guards the body", "Antigone's servant", "The narrator of the play"], "Tiresias's warning finally makes Creon change his mind, but too late."], ["What is the Chorus in Antigone?", ["A group of Theban elders who comment on the action", "A band playing modern music", "Antigone's group of friends", "The audience joining in"], "The Chorus reflects on events and themes and speaks to the audience."], ["In ancient Greek theatre, who played the female roles?", ["Men", "Women", "Children", "The audience"], "Only male actors performed, using masks to play female characters."], ["What is Creon's main flaw?", ["Pride and stubbornness", "Laziness", "Cowardice", "Greed for money"], "His refusal to listen, a kind of hubris, leads to his downfall."], ["How does the play end?", ["Antigone, Haemon and Eurydice are dead and Creon is left in grief", "Antigone marries Haemon happily", "Creon is crowned again with celebrations", "Polynices comes back to life"], "The tragic ending shows the terrible cost of Creon's choices."]], "bonus": ["In drama, what is a tragedy?", ["A play that ends in suffering or death, often caused by a flaw", "A play that always ends with a wedding", "A play with only songs", "A short funny sketch"], "Tragedies show a main character's downfall, often caused by their own mistakes."]}, {"ht": "Sum2", "t": "Writing about drama", "intro": "In the written exam you explain how you would perform, design or direct a set text such as Antigone. Examiners reward specific, practical ideas that are clearly linked to the extract and their effect on the audience. Practising 4, 6 and 12 mark questions now builds the habits you need for Year 11.", "how": ["For every point, say what you would do, how you would do it and why: the effect on the audience.", "Use precise drama vocabulary, such as pitch, pause, gesture, proxemics, gobo or fresnel.", "Refer closely to the extract by naming a moment or a short line.", "Short questions (4 and 6 marks) need focused, clearly explained ideas; a 12-mark answer needs several developed ideas across the extract.", "Use your time according to the marks: spend longest on the highest-mark questions."], "example": {"q": "As a performer playing Creon, explain how you would use vocal skills in the moment he first learns someone has buried Polynices.", "steps": ["Pick the moment: Creon hears the guard's news.", "What: a sudden rise in volume and a sharp, clipped tone.", "How: pause before replying, then speak quickly with emphasis on the word ordering the guard to find the culprit.", "Why: the audience sees Creon's anger and his fear that his authority is being challenged.", "Link to context: a Greek king's power depended on being obeyed."], "a": "A tense pause followed by a loud, sharp, fast reply shows Creon's anger and fear of losing authority."}, "walk": [{"h": "What, how, why", "b": "A weak answer says 'I would say it angrily'. A strong answer says 'I would raise my volume and use a sharp tone on the order, so the audience sees Creon's need for control'. The difference is detail and effect."}, {"h": "Answering as a designer", "b": "Designers also need what, how and why. For example: 'I would use a harsh white profile spot on Antigone as she is led away, so she looks exposed and alone.' Name the element, describe it precisely and explain the effect."}, {"h": "Building a 12-mark answer", "b": "A 12-mark answer needs a range of developed ideas, not just one. Move through the extract, pick three or four key moments and explain each choice and its effect. Where it fits, link to context, such as Greek beliefs about the gods."}], "qs": [["What three things should each exam point include?", ["What you would do, how, and why (the effect)", "A title, a date and a drawing", "The author, the year and the theatre", "A quote, a question and a joke"], "What, how and why makes a point practical, detailed and linked to the audience."], ["Which performer point is most precise?", ["I'd lower my pitch and pause before 'Go' to show threat", "I'd say the line really well", "I'd act it in a good way", "I'd do lots of acting"], "It names exact vocal skills, a moment and the intended effect."], ["Why should you mention the audience in your answers?", ["Marks reward explaining the intended effect on the audience", "The audience writes the mark scheme", "It makes the answer longer", "It is the only thing that matters"], "Drama is about communicating with an audience, so explaining effect shows understanding."], ["Which of these is a design term?", ["Gobo", "Gesture", "Pace", "Posture"], "A gobo is a lighting tool; the others are performance skills."], ["In exam questions, what does 'justify' mean?", ["Give reasons for your choices", "Draw a diagram", "Repeat the question", "Write a list of characters"], "To justify is to explain why your choice works."], ["How is a 12-mark answer different from a 4-mark answer?", ["It needs more developed ideas across the extract", "It needs no reference to the extract", "It should be one sentence long", "It only lists vocabulary words"], "Higher-mark questions need a range of detailed, explained ideas."], ["What does 'context' mean when writing about Antigone?", ["The time, place and culture the play comes from, like ancient Greece", "The colour of the costumes", "The number of actors on stage", "The length of the play"], "Context includes beliefs and theatre conventions of ancient Greece."], ["Which sentence best explains a lighting choice?", ["A cold blue wash on Creon alone suggests his isolation", "I would use some lights", "The lights would be nice", "Lighting is important in plays"], "It names a specific colour and state and explains the effect."], ["How should you share your time in the exam?", ["Spend longer on questions with more marks", "Spend equal time on every question", "Spend most time on the first question", "Answer only the 12-mark question"], "Matching time to marks helps you finish and score well."], ["Which detail best supports a point about Haemon's anger?", ["Naming the moment he argues with his father and the skills used", "Saying Haemon is in the play", "Describing the theatre's seats", "Saying how long the play is"], "Precise reference to a key moment shows close knowledge of the text."]], "bonus": ["What does a director do?", ["Leads the creative vision and guides the actors", "Sells tickets at the box office", "Writes reviews in newspapers", "Only operates the lights"], "The director decides how the play will be staged and helps actors bring it to life."]}]}, {"id": "music", "name": "Music", "board": "OCR (J536)", "weeks": [{"ht": "Aut1", "t": "Rhythm and time signatures", "intro": "Rhythm is the pattern of long and short sounds in music. Knowing note values, rests and time signatures lets you read, write and perform music accurately. Rhythmic dictation, where you write down a rhythm you hear, comes up in the GCSE listening exam.", "how": ["Note values: semibreve = 4 beats, minim = 2, crotchet = 1, quaver = ½, semiquaver = ¼.", "Every note value has a matching rest that shows a silence of the same length.", "A dot after a note adds half its value again, so a dotted minim lasts 3 beats.", "In a simple time signature, the top number says how many beats are in a bar and the bottom number says what kind of beat (4 means crotchets).", "For rhythmic dictation, find the beat first, then fit each sound into the beats of the bar."], "example": {"q": "A bar in 3/4 contains a minim. What single note is needed to complete the bar?", "steps": ["3/4 means 3 crotchet beats in every bar.", "A minim lasts 2 crotchet beats.", "3 − 2 = 1 beat is still needed.", "A note lasting 1 beat is a crotchet."], "a": "One crotchet completes the bar, because 2 + 1 = 3 beats."}, "walk": [{"h": "Note values", "b": "Each note value is half of the one before: one semibreve equals two minims, which equals four crotchets, which equals eight quavers. Quavers are often joined with a beam in pairs. For example, two quavers together last 1 beat, the same as one crotchet."}, {"h": "Rests and dots", "b": "Rests are silences, and each one matches a note: a crotchet rest lasts 1 beat and a minim rest lasts 2. A dot adds half the note's length, so a dotted crotchet is 1 + ½ = 1½ beats. A dotted crotchet followed by a quaver adds up to 2 beats."}, {"h": "Time signatures", "b": "4/4 has four crotchet beats per bar and is so common it is called common time. 3/4 has three beats and feels like a waltz, while 2/4 has two and feels like a march. 6/8 is compound time: six quavers grouped into two dotted-crotchet beats, giving a lilting feel."}], "qs": [["How many beats does a crotchet last?", ["1", "2", "½", "4"], "A crotchet is one beat in simple time signatures like 4/4."], ["How many beats does a semibreve last?", ["4", "2", "3", "1"], "A semibreve is the longest common note value, lasting 4 crotchet beats."], ["How many quavers equal one minim?", ["4", "2", "8", "3"], "A minim is 2 beats and each quaver is ½ beat, so 2 ÷ ½ = 4."], ["What does the top number of the time signature 3/4 tell you?", ["There are 3 beats in each bar", "Each note lasts 3 beats", "The piece is in 3 sections", "Play 3 times faster"], "The top number counts how many beats fit in one bar."], ["How long is a dotted minim?", ["3 beats", "2 beats", "2½ beats", "4 beats"], "The dot adds half of 2, which is 1, so 2 + 1 = 3 beats."], ["What is a rest?", ["A symbol showing silence for a set length", "A sign to play louder", "A long held note", "The end of the piece"], "Rests tell you how long to stay silent."], ["Which time signature is often called common time?", ["4/4", "3/4", "6/8", "2/4"], "4/4 is so widely used that it is called common time and can be shown as a C."], ["Which group fills exactly one bar of 4/4?", ["Minim + crotchet + two quavers", "Minim + minim + crotchet", "Semibreve + crotchet", "Three crotchets"], "2 + 1 + ½ + ½ = 4 beats, which fills a bar of 4/4."], ["What is the total length of a dotted crotchet followed by a quaver?", ["2 beats", "1½ beats", "2½ beats", "1 beat"], "A dotted crotchet is 1½ beats and a quaver is ½, so together they make 2."], ["How is 6/8 usually felt?", ["Two beats per bar, each a dotted crotchet", "Six crotchet beats per bar", "Three beats per bar, each a minim", "Eight beats per bar"], "6/8 is compound duple time: six quavers grouped in two sets of three."]], "bonus": ["What is the beat (pulse) in music?", ["The steady regular pulse you can tap along to", "The highest note in a song", "The loudest part of a piece", "The words of a song"], "The beat is the steady pulse that rhythms are built on."]}, {"ht": "Aut2", "t": "African drumming and Western classical", "intro": "African drumming and Western classical music come from very different traditions, but both use rhythm, melody and texture in clever ways. African drumming is passed on by ear and is built on layered rhythms, while Western classical music is usually written down and played by orchestras. OCR's Rhythms of the World area of study includes African drumming, and melodic keywords help you describe any music.", "how": ["Key African instruments include the djembe, dundun drums and the talking drum.", "African drumming uses call and response, polyrhythms, cyclic rhythms and ostinatos, often led by a master drummer.", "African music is traditionally learned through oral tradition: by listening and copying, not from written notes.", "The Western orchestra has four families: strings, woodwind, brass and percussion.", "Melodic keywords: conjunct (moving by step), disjunct (leaps), ascending, descending, sequence and ostinato."], "example": {"q": "You hear a drum ensemble where a leader plays a pattern and the group replies, while different drums play different repeating rhythms at the same time. Name two features.", "steps": ["The leader plays and the group answers: this is call and response.", "Different rhythms played together at once create polyrhythm.", "Repeating patterns that go round and round are cyclic rhythms or ostinatos.", "The leader is likely the master drummer, who signals changes."], "a": "Call and response and polyrhythm, led by a master drummer."}, "walk": [{"h": "African instruments", "b": "The djembe is a goblet-shaped drum played with the hands, making bass, tone and slap sounds. Dundun are cylindrical drums played with sticks that keep the low parts. The talking drum can be squeezed under the arm to change its pitch, copying the rise and fall of speech."}, {"h": "African drumming features", "b": "Many layers of different rhythms play together, creating polyrhythm and a thick texture. The master drummer plays calls to start, change or end sections, and the others respond. Players often improvise over the repeated cycles."}, {"h": "Western classical and melody", "b": "In an orchestra, violins and cellos are strings, flutes and clarinets are woodwind, trumpets and trombones are brass, and timpani are percussion. A conjunct melody moves by step, like walking up a scale, while a disjunct melody jumps. A sequence repeats a phrase at a higher or lower pitch."}], "qs": [["Which instrument is a goblet-shaped hand drum from West Africa?", ["Djembe", "Timpani", "Tabla", "Snare drum"], "The djembe is played with the hands and has a goblet shape."], ["What is call and response?", ["A leader plays or sings and a group answers", "Everyone plays the same rhythm together", "A solo with no accompaniment", "Playing music from written notes"], "Call and response is a key feature of African music."], ["What is a polyrhythm?", ["Two or more different rhythms played at the same time", "A rhythm played very slowly", "A rhythm played only once", "A melody with no rhythm"], "Poly means many: many rhythms layered together."], ["How is traditional African drumming usually learned?", ["By ear through oral tradition", "From printed sheet music", "Only from video lessons", "By reading tab"], "Rhythms are passed on by listening, copying and memory."], ["Who leads an African drum ensemble?", ["The master drummer", "The conductor with a baton", "The lead guitarist", "The audience"], "The master drummer gives the signals for changes in the music."], ["Which orchestral family does the clarinet belong to?", ["Woodwind", "Brass", "Strings", "Percussion"], "The clarinet is blown and uses a reed, so it belongs to the woodwind family."], ["What does a conjunct melody do?", ["Moves mainly by step", "Moves mainly by large leaps", "Stays on one note", "Only goes downwards"], "Conjunct means joined, so the notes move to neighbouring pitches."], ["What is a melodic sequence?", ["A phrase repeated at a higher or lower pitch", "A phrase repeated at exactly the same pitch", "A sudden key change", "A long held note"], "Sequences repeat a pattern but start on a different note."], ["Which drum can change pitch when the player squeezes it?", ["Talking drum", "Djembe", "Bass drum", "Cymbal"], "Squeezing the talking drum's cords tightens the skin and raises the pitch."], ["Which word describes a melody with big jumps between notes?", ["Disjunct", "Conjunct", "Scalic", "Sustained"], "Disjunct melodies leap rather than move by step."]], "bonus": ["What is an ostinato?", ["A short pattern repeated over and over", "A very fast solo", "A sudden silence", "The last note of a piece"], "Ostinatos are repeating patterns used in many styles, including African drumming."]}, {"ht": "Spr1", "t": "Conventions of pop", "intro": "Pop songs follow conventions: shared features that listeners recognise, like catchy choruses and familiar chord patterns. Understanding harmony, tonality and song structure helps you analyse songs in the exam and write your own. Conventions of Pop is one of OCR's areas of study.", "how": ["Tonality is whether music is major (often bright) or minor (often sad or dark).", "A triad is a three-note chord built from a root, a third and a fifth, such as C–E–G.", "The primary chords in a major key are I, IV and V; in C major these are C, F and G.", "Many pop songs use the four chords I–V–vi–IV; in C major that is C, G, Am and F.", "Common song structure: intro, verse, pre-chorus, chorus, bridge (middle 8) and outro."], "example": {"q": "Work out chords I, IV, V and vi in the key of G major.", "steps": ["Write the G major scale: G A B C D E F♯ G.", "Chord I starts on the 1st note: G (G–B–D).", "Chord IV starts on the 4th note: C (C–E–G).", "Chord V starts on the 5th note: D (D–F♯–A).", "Chord vi starts on the 6th note and is minor: Em (E–G–B)."], "a": "In G major, I = G, IV = C, V = D and vi = E minor."}, "walk": [{"h": "Major and minor", "b": "Tonality tells you the overall feel of a key. A major key often sounds happy or confident, while a minor key often sounds sad, tense or mysterious. Many songs switch between them to change the mood, for example a minor verse leading to a major chorus."}, {"h": "Building chords", "b": "To build a triad, take a note and add every other note of the scale above it. In C major, starting on C gives C–E–G, and starting on A gives A–C–E, which is A minor. Chords I, IV and V are the primary chords and are major in a major key."}, {"h": "Song structure", "b": "The verse tells the story and usually changes words each time. The chorus repeats the same words and contains the hook, the catchiest part. The bridge or middle 8 offers something different before the final chorus."}], "qs": [["What is tonality?", ["Whether music is in a major or minor key", "How loud the music is", "How fast the music is", "Which instruments play"], "Tonality describes the key, usually major or minor."], ["How many notes are in a triad?", ["3", "2", "4", "5"], "Tri means three: root, third and fifth."], ["What are the notes of a C major triad?", ["C–E–G", "C–D–E", "C–F–A", "C–E♭–G"], "Take C, skip D, take E, skip F, take G."], ["What are the primary chords in C major?", ["C, F and G", "C, D and E", "C, G and Am", "D, E and F"], "Primary chords are I, IV and V: C, F and G in C major."], ["What is chord vi in C major?", ["A minor", "A major", "F major", "G major"], "The 6th note of C major is A, and its triad A–C–E is minor."], ["In a pop song, what is the hook?", ["The catchy, memorable part, often in the chorus", "The first chord of the song", "The final note of the outro", "The drum fill before the chorus"], "Hooks are designed to grab the listener and be remembered."], ["Which part of a song usually repeats with the same words each time?", ["Chorus", "Verse", "Intro", "Bridge"], "Verses change words, but the chorus usually keeps the same lyrics."], ["What is a middle 8 (bridge)?", ["A contrasting section, often before the last chorus", "The eighth verse of a song", "An 8-bar intro", "The loudest chorus"], "The bridge adds contrast so the final chorus feels fresh."], ["Which four chords make the I–V–vi–IV pattern in C major?", ["C, G, Am, F", "C, F, G, Am", "C, Am, F, G", "C, G, F, Dm"], "I = C, V = G, vi = Am and IV = F, in that order."], ["Which cadence goes from chord V to chord I?", ["Perfect cadence", "Imperfect cadence", "Plagal cadence", "Interrupted cadence"], "V–I sounds finished, which makes it a perfect cadence."]], "bonus": ["What is a chord?", ["Two or more notes played at the same time", "One note played very loudly", "A rhythm played on drums", "A type of guitar string"], "Chords are notes sounding together, which create harmony."]}, {"ht": "Spr2", "t": "Film and game music", "intro": "Music in films and video games tells you how to feel and what is happening, often without you noticing. Composers use musical elements like tempo, pitch, harmony and instruments to create mood and tension. Film and Game Music is an OCR area of study, and you need to explain how music matches what is on screen.", "how": ["Use the musical elements to describe music: tempo, dynamics, pitch, harmony, tonality, timbre, texture and rhythm.", "A leitmotif is a short musical idea linked to a character, place or idea, which returns whenever they appear.", "Diegetic music can be heard by the characters; non-diegetic music, like a soundtrack, only the audience hears.", "Tension is often built with low pitch, dissonance, ostinatos, crescendos and minor keys.", "Game music often loops and is dynamic, changing as the player moves, fights or wins."], "example": {"q": "Describe how a composer might create tension as a shark approaches a swimmer.", "steps": ["Use a low pitch on cellos and double basses to sound threatening.", "Play a simple two-note ostinato that repeats.", "Gradually speed up the tempo as the shark gets closer.", "Add a crescendo so the music grows louder.", "Use a dissonant, clashing chord at the moment of attack."], "a": "A low, repeating ostinato that speeds up and gets louder, ending with dissonance, builds tension."}, "walk": [{"h": "Creating mood", "b": "Composers change the musical elements to change the feeling. A fast tempo, major key and bright brass can feel heroic, while slow, quiet strings in a minor key can feel sad. High, thin textures might suggest something magical or eerie."}, {"h": "Leitmotifs", "b": "A leitmotif helps audiences recognise characters before they even appear. Famous film villains often have a heavy, low brass theme in a minor key. Composers can transform a leitmotif, for example playing a hero's theme slowly and quietly when the hero is in trouble."}, {"h": "Music in games", "b": "In a game, the music has to keep going for as long as the player plays, so it often loops. Many games use dynamic or adaptive music that changes when danger appears or a level is completed. Early games used chiptune: simple electronic sounds from basic sound chips."}], "qs": [["What is a leitmotif?", ["A musical idea linked to a character, place or idea", "The final song in the credits", "A loud sound effect", "A type of camera shot"], "Leitmotifs return whenever their character or idea appears."], ["What is non-diegetic music?", ["Music only the audience can hear, like a soundtrack", "Music the characters play on screen", "Music with no instruments", "Music played live in the cinema"], "Non-diegetic music is added for the audience and is not part of the story world."], ["A character switches on a radio in the scene and music plays. What is this?", ["Diegetic music", "Non-diegetic music", "A leitmotif", "Underscoring"], "Characters can hear the radio, so the music is diegetic."], ["Which musical feature most often suggests sadness?", ["A slow tempo in a minor key", "A fast tempo in a major key", "Loud brass fanfares", "A bouncy, staccato rhythm"], "Slow speed and minor tonality usually create a sad mood."], ["What is dissonance?", ["Notes that clash and sound tense", "Notes that sound smooth and calm", "Music with no rhythm", "A very quiet note"], "Clashing notes create unease, which is useful for tension."], ["What is a crescendo?", ["Gradually getting louder", "Gradually getting quieter", "Gradually getting faster", "Suddenly stopping"], "A crescendo builds volume, often adding excitement or tension."], ["Why does video game music often loop?", ["Because players spend different amounts of time in each level", "Because games can only play one note", "Because loops are louder", "Because film music cannot loop"], "Looping lets the music continue for as long as the player needs."], ["What is dynamic (adaptive) game music?", ["Music that changes in response to what the player does", "Music that is always very loud", "Music written for orchestras only", "Music that never changes"], "Adaptive music reacts to gameplay, such as becoming intense in a battle."], ["What is 'Mickey-Mousing'?", ["Music that exactly matches actions on screen", "Music played by a cartoon character", "Music recorded backwards", "Music with no melody"], "Like old cartoons, the music copies every movement, such as falling notes for a fall."], ["Which choice would best suit a heroic moment?", ["Loud brass, a major key and a strong rhythm", "Quiet, low strings in a minor key", "A slow, solo music box melody", "Dissonant, clashing chords"], "Bold brass and major tonality sound triumphant and confident."]], "bonus": ["What does 'tempo' mean in music?", ["The speed of the music", "The loudness of the music", "How high or low the notes are", "The number of instruments"], "Tempo is how fast or slow the music goes."]}, {"ht": "Sum1", "t": "Rock anthems", "intro": "Rock anthems are big, powerful songs designed to be sung along to by huge crowds in arenas and stadiums. They use electric guitars, strong drum beats, memorable riffs and big choruses. Rock music is part of OCR's Conventions of Pop area of study.", "how": ["A typical rock line-up is lead guitar, rhythm guitar, bass guitar, drum kit and vocals, sometimes with keyboards.", "A riff is a short, catchy repeated pattern, often played on electric guitar.", "A broken chord plays the notes of a chord one after another instead of all together.", "Power chords use just the root and fifth, often played with distortion for a heavy sound.", "Anthems have a strong beat, loud dynamics, guitar solos and a chorus the crowd can join in with."], "example": {"q": "Turn a C major chord into a broken chord pattern on a keyboard.", "steps": ["Find the three notes of C major: C, E and G.", "Instead of playing them together, play C, then E, then G.", "Repeat the pattern evenly as quavers, for example C–E–G–E.", "Keep it going over the bar to create a flowing accompaniment."], "a": "Playing C, E and G one after another in a repeating pattern creates a broken chord."}, "walk": [{"h": "Rock sound", "b": "Rock is driven by a loud drum kit, a solid bass line and electric guitars. Guitarists use effects like distortion to make a gritty, powerful sound. Many rock songs are in 4/4 with a strong backbeat, where the snare hits on beats 2 and 4."}, {"h": "Riffs and power chords", "b": "A riff is a short phrase that repeats and becomes the song's signature, often heard in the intro. A power chord, such as C5, uses only C and G, so it sounds strong and works well with distortion. Riffs often combine single notes with power chords."}, {"h": "Broken chords and anthems", "b": "A broken chord, also called an arpeggio when played in order up or down, spreads a chord out over time. It is often used in quieter intros before the band crashes in. Anthems build up to a huge chorus that the whole crowd can sing or clap along to."}], "qs": [["What is a riff?", ["A short, catchy repeated musical pattern", "A long guitar solo that never repeats", "A type of drum", "The words of a chorus"], "Riffs repeat and often become the most recognisable part of a rock song."], ["What is a broken chord?", ["The notes of a chord played one after another", "A chord played out of tune", "A chord with a missing note", "Two chords played at once"], "Breaking a chord spreads its notes out instead of playing them together."], ["Which notes make a C5 power chord?", ["C and G", "C, E and G", "C and E", "C, F and A"], "A power chord uses only the root and the fifth."], ["Which effect makes an electric guitar sound gritty and heavy?", ["Distortion", "Reverb only", "Mute", "Pizzicato"], "Distortion overloads the signal for the classic rock sound."], ["Which instrument usually plays the low notes in a rock band?", ["Bass guitar", "Lead guitar", "Hi-hat", "Vocals"], "The bass guitar plays the bass line and locks in with the drums."], ["On which beats does the backbeat usually fall in 4/4?", ["2 and 4", "1 and 3", "1 only", "3 and 4"], "The snare on beats 2 and 4 gives rock its driving backbeat."], ["What makes a rock song an 'anthem'?", ["A big, memorable chorus crowds can sing along to", "It is very quiet and slow", "It has no lyrics at all", "It is only played on the radio"], "Anthems are built for mass singing at live concerts."], ["What is an arpeggio?", ["A broken chord played in order, up or down", "A very fast drum roll", "A sudden key change", "Two guitars playing in unison"], "Arpeggios play chord notes in sequence, such as C–E–G–C."], ["What is the classical-music word for a repeated pattern, similar to a riff?", ["Ostinato", "Cadenza", "Crescendo", "Legato"], "An ostinato is a repeated pattern, which is what a riff is in rock."], ["Which notes form a G major broken chord?", ["G, B and D", "G, A and B", "G, C and E", "G, B♭ and D"], "The G major triad is G–B–D, played one note at a time."]], "bonus": ["Which family of instruments does a drum kit belong to?", ["Percussion", "Strings", "Woodwind", "Brass"], "Drums are struck to make a sound, so they are percussion."]}, {"ht": "Sum2", "t": "The Concerto Through Time", "intro": "A concerto is a piece where a soloist, or small group, plays with an orchestra. It changed a lot between the Baroque, Classical and Romantic periods, as orchestras grew and soloists became more show-stopping. The Concerto Through Time is an OCR area of study, so you need to recognise features from each period.", "how": ["Baroque (about 1600–1750): concerto grosso and solo concerto, with basso continuo, terraced dynamics and ritornello form; composers include Vivaldi, Bach and Handel.", "In a concerto grosso, a small group called the concertino contrasts with the full orchestra, called the ripieno or tutti.", "Classical (about 1750–1810): solo concerto in three movements (fast–slow–fast), balanced phrases and a cadenza; composers include Mozart and Haydn.", "Romantic (about 1810–1910): bigger orchestras, very virtuosic solos, expressive melodies, wide dynamics and rubato; composers include Tchaikovsky, Grieg and Rachmaninoff.", "A cadenza is a showy solo passage, often near the end of a movement, where the orchestra stops."], "example": {"q": "You hear a concerto with a harpsichord playing chords throughout, sudden changes between loud and soft, and a small group of soloists alternating with a string orchestra. Which period is it from?", "steps": ["A harpsichord filling in chords suggests basso continuo.", "Sudden loud-to-soft changes are terraced dynamics.", "A small group contrasting with the orchestra is a concerto grosso.", "All three features point to the Baroque period."], "a": "It is a Baroque concerto grosso."}, "walk": [{"h": "Baroque concertos", "b": "Baroque orchestras were mainly strings, with a basso continuo of harpsichord and cello playing the bass line and chords. Ritornello form has a main theme that keeps returning between solo sections. Vivaldi's The Four Seasons is a famous set of Baroque solo violin concertos."}, {"h": "Classical concertos", "b": "In the Classical period the piano replaced the harpsichord, and the solo concerto became the main type. Concertos had three movements: fast, slow, fast. Mozart wrote many piano concertos with clear, elegant melodies and a cadenza where the soloist shows off."}, {"h": "Romantic concertos", "b": "Romantic composers wanted big emotions, so orchestras grew, with more brass and percussion. Soloists played extremely difficult music, often against a powerful orchestra. Players used rubato, stretching and squeezing the tempo, for expression."}], "qs": [["What is a concerto?", ["A piece for soloist(s) and orchestra", "A song for a choir", "A piece for solo piano only", "A type of opera"], "Concertos contrast a soloist or small group with an orchestra."], ["Which keyboard instrument often played the continuo in Baroque music?", ["Harpsichord", "Electric keyboard", "Synthesiser", "Celesta"], "The harpsichord filled in chords as part of the basso continuo."], ["In a concerto grosso, what is the concertino?", ["The small group of soloists", "The full orchestra", "The conductor", "The final movement"], "The concertino contrasts with the larger ripieno."], ["What are terraced dynamics?", ["Sudden changes between loud and soft", "Gradual crescendos", "Music that stays very quiet", "Dynamics written by the audience"], "Baroque music often switches suddenly between forte and piano, like steps."], ["Who composed The Four Seasons?", ["Vivaldi", "Mozart", "Tchaikovsky", "Beethoven"], "Vivaldi wrote The Four Seasons, a set of Baroque violin concertos."], ["What is the usual order of movements in a Classical concerto?", ["Fast–slow–fast", "Slow–fast–slow", "Fast–fast–slow", "Slow–slow–fast"], "Classical concertos usually have three movements in fast–slow–fast order."], ["What is a cadenza?", ["A showy solo passage where the orchestra stops", "A section where only the orchestra plays", "The tuning at the start", "A slow introduction"], "Cadenzas let the soloist display their skill."], ["Which composer is best known for Classical-period piano concertos?", ["Mozart", "Vivaldi", "Rachmaninoff", "Handel"], "Mozart wrote many piano concertos in the Classical period."], ["What is rubato?", ["Slightly speeding up and slowing down for expression", "Playing very loudly", "Plucking the strings", "Playing in a strict tempo"], "Rubato means robbed time and is typical of Romantic music."], ["Which feature best suggests a Romantic concerto?", ["A large orchestra and a very virtuosic soloist", "A small string orchestra with harpsichord continuo", "Terraced dynamics and ritornello form", "A concertino and ripieno"], "Romantic concertos used bigger orchestras and very demanding solo parts."]], "bonus": ["Which orchestral family includes the violin, viola, cello and double bass?", ["Strings", "Woodwind", "Brass", "Percussion"], "These instruments make sound with strings, played with a bow or plucked."]}]}, {"id": "media", "name": "Media Studies", "board": "WJEC Eduqas", "weeks": [{"ht": "Aut1", "t": "Key media concepts", "intro": "Media Studies uses four key concepts, called the theoretical framework, to study any media product: media language, representation, media industries and audiences. They help you ask how a product creates meaning, how it shows people and places, who made it and who it is for. Every set product at GCSE is studied using these four ideas.", "how": ["Media language is how a product communicates meaning, through technical, visual and written codes, conventions, genre and narrative.", "Denotation is what you literally see; connotation is what it suggests or makes you think of.", "Representation is how people, places, groups and ideas are shown, including stereotypes.", "Media industries are the companies that make, distribute and regulate media, such as the BBC or Ofcom.", "Audiences are the people a product targets, often described by age, gender, interests and lifestyle."], "example": {"q": "A film poster shows a woman in a red dress holding a gun in a dark alley. Analyse it using denotation and connotation.", "steps": ["Denotation: a woman, a red dress, a gun, a dark alley.", "Connotation of red: danger, passion or blood.", "Connotation of the gun and the alley: crime, threat and secrecy.", "Put together, these codes suggest the thriller or crime genre.", "Link to representation: the woman is shown as powerful and dangerous."], "a": "The codes connote danger and crime, suggesting a thriller with a powerful female character."}, "walk": [{"h": "Media language", "b": "Codes are the signs that create meaning. Technical codes include camera shots and lighting, symbolic codes include colour, clothing and objects, and written codes include headlines and slogans. Anchorage is when text fixes the meaning of an image, like a caption under a photo."}, {"h": "Representation", "b": "Media products never show reality exactly; they re-present it by choosing what to include. A stereotype is a simplified, often unfair, idea about a group, such as showing teenagers only as lazy. Media can reinforce stereotypes or challenge them."}, {"h": "Industries and audiences", "b": "Media industries include institutions like the BBC and companies like Disney, and regulators like Ofcom and the ASA. A target audience is the group a product is aimed at, such as 16–24 year olds who love gaming. Uses and gratifications theory says audiences use media for information, entertainment, personal identity and social interaction."}], "qs": [["Which of these is one of the four key media concepts?", ["Representation", "Typography", "Photography", "Advertising"], "The four concepts are media language, representation, media industries and audiences."], ["What does denotation mean?", ["What you literally see or hear", "The hidden meaning of a sign", "The audience for a product", "The company that made it"], "Denotation is the simple, literal description of a sign."], ["What does connotation mean?", ["The ideas or feelings a sign suggests", "The exact size of an image", "The price of a product", "The date a product was made"], "Connotations are the associations, like a red rose suggesting love."], ["Which of these is a technical code?", ["A close-up camera shot", "A character's red dress", "A headline", "A brand slogan"], "Technical codes are about how the product is made, like camera shots and lighting."], ["What is a stereotype?", ["A simplified, generalised view of a group of people", "A type of stereo speaker", "A realistic portrait of one person", "A media regulator"], "Stereotypes reduce a group to a few, often negative, traits."], ["What is a target audience?", ["The specific group a media product is aimed at", "Everyone who lives in the UK", "The people who make the product", "The critics who review it"], "Producers design products to appeal to a particular group."], ["What is anchorage?", ["Text that fixes the meaning of an image", "A shot of a ship at sea", "The end of a radio show", "The cost of an advert"], "Captions and slogans anchor an image to one preferred meaning."], ["Which organisation regulates adverts in the UK?", ["The Advertising Standards Authority (ASA)", "The BBC", "The British Film Institute", "The Premier League"], "The ASA makes sure UK adverts are legal, decent, honest and truthful."], ["Which is a convention of a magazine front cover?", ["A masthead", "End credits", "A jingle", "A level select screen"], "The masthead, the magazine's title, is a standard cover convention."], ["In uses and gratifications theory, watching a comedy to relax is an example of what?", ["Entertainment (diversion)", "Personal identity", "Surveillance (information)", "Social interaction"], "Using media to escape and enjoy yourself is the entertainment or diversion need."]], "bonus": ["Which of these is an example of a media product?", ["A TV advert", "A school desk", "A football", "A sandwich"], "Media products communicate to audiences, like adverts, films, games and radio shows."]}, {"ht": "Aut2", "t": "Quality Street print advert", "intro": "The Quality Street advert from 1956 is a historical print advert and a GCSE set product. It shows how chocolates were sold as an affordable luxury in 1950s Britain, a time of recovery after the Second World War. Studying it helps you see how advertising codes and ideas about gender have changed over time.", "how": ["Quality Street was made by Mackintosh's, launched in 1936 and named after a play by J. M. Barrie.", "The brand's mascots, the Major and Miss, are Regency-style characters that suggest old-fashioned elegance and quality.", "The 1956 advert is hand-drawn, with a smartly dressed man at the centre holding the tin and two women gathered around him.", "Print advert conventions include a central image, the product shot, the brand name or logo, a slogan and persuasive copy.", "Context: rationing had recently ended (sweets in 1953, all food in 1954), so treats were becoming part of normal shopping."], "example": {"q": "How does the 1956 Quality Street advert represent gender?", "steps": ["Describe the layout: the man is central and holds the tin, so he has the most status.", "The women are placed around him, looking towards him and the chocolates.", "This suggests a patriarchal view where the man has power and the women depend on him.", "Link to context: in the 1950s many women were expected to be homemakers and men the main earners.", "Compare with today: most modern adverts try to avoid such clear gender stereotypes."], "a": "The advert shows the man as powerful and in control, with women depending on him, which reflects 1950s gender roles."}, "walk": [{"h": "The product and brand", "b": "Harold Mackintosh wanted to sell boxed chocolates that ordinary working families could afford. The name and the Regency mascots connote tradition, class and quality, even though the price was modest. The colourful wrapped sweets are shown in a close-up to make them look tempting."}, {"h": "Codes and conventions", "b": "The advert uses a hand-drawn illustration, typical of 1950s print adverts before photography became normal. The layout guides the eye to the man and the tin at the centre, and the bold brand name stands out. The copy uses persuasive language such as superlatives and alliteration to make the sweets sound special."}, {"h": "Historical context", "b": "Britain was recovering from the war, and the end of rationing meant people could enjoy luxuries again. The advert reflects the values of the time, when men usually held more economic power. Comparing it with modern adverts shows how both media language and representation have changed."}], "qs": [["In which decade was the set Quality Street advert published?", ["1950s", "1930s", "1980s", "2010s"], "The set product is a print advert from 1956."], ["Which company made Quality Street?", ["Mackintosh's", "Cadbury", "Mars", "Rowntree's"], "Quality Street was created by Mackintosh's in 1936."], ["What kind of image does the advert use?", ["A hand-drawn illustration", "A black-and-white photograph", "A digital 3D render", "A cartoon comic strip"], "Many 1950s adverts used colourful illustrations rather than photographs."], ["Who are the Major and Miss?", ["Regency-style brand mascots", "Famous film stars of 1956", "The company's owners", "The advert's photographers"], "These old-fashioned characters connote elegance and tradition."], ["Who is at the centre of the image?", ["A smartly dressed man holding the tin", "A child eating chocolate", "A shopkeeper behind a counter", "A soldier in uniform"], "Central framing gives the man, and the product he holds, the most importance."], ["Which recent change in Britain is important context for this advert?", ["The end of rationing", "The invention of the internet", "Joining the European Union", "The start of the Second World War"], "With rationing over, sweets could be sold as everyday treats."], ["What is a product shot?", ["An image of the product itself, to show it clearly", "A photograph of the factory", "The price of the product", "The name of the designer"], "Product shots make the item recognisable and tempting."], ["What does a Regency-style mascot connote?", ["Tradition, class and quality", "Modern technology", "Danger and crime", "Sport and fitness"], "The historical style suggests an upmarket, elegant brand."], ["Which word best describes the gender representation in the advert?", ["Patriarchal", "Equal", "Gender-neutral", "Female-dominated"], "The man holds the power and the women depend on him, reflecting a patriarchal society."], ["Why was the brand sold as an 'affordable luxury'?", ["To appeal to ordinary families wanting a special treat", "Because it was the most expensive chocolate", "Because it was only sold to royalty", "Because it was given away free"], "Mackintosh wanted working families to feel they could enjoy luxury."]], "bonus": ["What is the main purpose of most adverts?", ["To persuade an audience to buy or do something", "To tell a true story about the past", "To review a film", "To report the news"], "Adverts are designed to persuade, usually to buy a product or take an action."]}, {"ht": "Spr1", "t": "This Girl Can and NHS 111", "intro": "Not every advert sells a product: some campaigns try to change how people behave. This Girl Can, from Sport England, encourages women and girls to be active, and NHS 111 adverts tell people how to get the right medical help. They are useful for studying purpose, audience and representation, especially of gender.", "how": ["This Girl Can was launched in 2015 by Sport England, funded by the National Lottery.", "It aims to tackle the fear of being judged, which research showed stopped many women from exercising.", "It shows real women of different ages, sizes, ethnicities and abilities, sweating and enjoying sport, challenging stereotypes.", "NHS 111 is a free service, by phone or online, for urgent medical help that is not a life-threatening emergency.", "Public information campaigns persuade the audience to change behaviour, such as using 111 rather than going straight to A&E."], "example": {"q": "How does This Girl Can challenge stereotypes of women in the media?", "steps": ["Identify the usual stereotype: women in sport adverts are often slim models looking perfect.", "Describe the campaign: real women of different shapes, ages and backgrounds, sweaty and red-faced.", "Explain the technical codes: close-ups and slow motion celebrate effort, not looks.", "Explain the effect: ordinary women see people like themselves and feel more confident.", "Link to purpose: the aim is to get more women active."], "a": "It replaces the 'perfect' stereotype with real, diverse women enjoying exercise, which encourages more women to take part."}, "walk": [{"h": "Purpose of campaigns", "b": "Commercial adverts sell products, but public service campaigns try to change behaviour or give information. This Girl Can wants women to exercise more, and NHS 111 wants people to use health services wisely. The 'product' is really an action or an idea."}, {"h": "Representation of gender", "b": "Traditionally, media often showed women as passive or focused on appearance. This Girl Can shows women as active, strong and confident, and suggests that no one should feel judged. This is called a counter-stereotype because it challenges the usual image."}, {"h": "Audience", "b": "This Girl Can targets women and girls of all ages, especially those who feel exercise is not for them. NHS 111 adverts target the whole public, especially parents and people unsure whether an illness is serious. Both use a clear call to action, telling the audience exactly what to do next."}], "qs": [["Which organisation created This Girl Can?", ["Sport England", "Nike", "The BBC", "The NHS"], "Sport England launched the campaign in 2015."], ["What is the main aim of This Girl Can?", ["To get more women and girls active", "To sell sports clothing", "To advertise a gym chain", "To promote the Olympics"], "It tries to increase physical activity among women and girls."], ["What did research suggest stopped many women from exercising?", ["Fear of being judged", "A lack of sports channels", "Too many gyms", "Bad weather only"], "The campaign was built around tackling the fear of judgement."], ["What is NHS 111 for?", ["Urgent medical help that is not life-threatening", "Life-threatening emergencies only", "Booking holidays", "Reporting crimes"], "For life-threatening emergencies you call 999; 111 is for urgent but not emergency needs."], ["How is a public information campaign different from a commercial advert?", ["It aims to change behaviour rather than sell a product", "It is always longer", "It never uses images", "It is only shown at night"], "Public campaigns persuade people to act for their own or society's benefit."], ["What is a call to action?", ["A direct instruction telling the audience what to do", "A phone call from the advertiser", "The music at the end of the advert", "The name of the director"], "Examples include 'call 111' or 'get active'."], ["Which women does This Girl Can mainly show?", ["Real women of different ages, sizes and backgrounds", "Professional models only", "Only Olympic athletes", "Only teenagers"], "Using everyday women helps the audience relate to them."], ["What is a counter-stereotype?", ["A representation that challenges a usual stereotype", "A stereotype that is repeated", "A type of shop counter", "A sound effect"], "Showing women as strong and sweaty counters the idea that they should look perfect."], ["Why might This Girl Can use close-ups of sweating faces?", ["To show effort and enjoyment matter more than looks", "To show the women are unhappy", "To advertise a skincare product", "To hide who the women are"], "The technical code celebrates real effort, supporting the campaign's message."], ["Who is the target audience for NHS 111 adverts?", ["The general public who may need urgent medical advice", "Only doctors and nurses", "Only children under 5", "Only people living abroad"], "The service is for anyone who needs urgent medical advice."]], "bonus": ["What is a gender stereotype?", ["A fixed, simplified idea about how men or women should be", "A fact about biology", "A type of advert", "A law about equality"], "Gender stereotypes are generalisations, like 'girls don't like sport'."]}, {"ht": "Spr2", "t": "Gaming: Fortnite", "intro": "Video games are one of the biggest media industries in the world, and Fortnite is one of the most successful games ever. Studying it shows how games are made, how they reach huge audiences and how a free game can earn billions. You will look at the industry, the audience and the business model.", "how": ["Fortnite was made by Epic Games and released in 2017; its Battle Royale mode is free to play.", "In Battle Royale, up to 100 players drop onto an island and fight to be the last one standing as the storm shrinks the map.", "It makes money through microtransactions: players buy V-Bucks to spend on skins, emotes and the Battle Pass.", "Most purchases are cosmetic, so they change how you look, not how well you play.", "It is cross-platform, rated PEGI 12, and uses live events and collaborations with films, music and sport to keep players interested."], "example": {"q": "Explain how Fortnite can make money when it is free to play.", "steps": ["Being free removes the barrier, so millions of players try it.", "Players can buy V-Bucks, an in-game currency, with real money.", "V-Bucks are spent on cosmetic items like skins and on the Battle Pass.", "Limited-time items and collaborations create pressure to buy now.", "A small spend from a huge number of players adds up to billions."], "a": "Fortnite earns money through optional microtransactions from a massive free-to-play audience."}, "walk": [{"h": "The games industry", "b": "The games industry makes more money worldwide than film and music combined. Epic Games develops and publishes Fortnite and also owns Unreal Engine, the technology used to build it and many other games. Games are rated by PEGI in the UK, and Fortnite is rated 12."}, {"h": "How games make money", "b": "Some games are sold for a one-off price, but Fortnite uses a free-to-play model. It earns money from microtransactions, such as buying a new outfit for your character. The Battle Pass gives rewards for playing each season, which keeps people coming back."}, {"h": "Audiences", "b": "Fortnite has a huge audience, especially teenagers and young adults. Uses and gratifications theory helps explain why: players enjoy entertainment, social interaction with friends and showing personal identity through their skins. Live in-game events such as concerts have turned the game into a social space as well as a game."}], "qs": [["Which company makes Fortnite?", ["Epic Games", "Nintendo", "EA Sports", "Rockstar Games"], "Epic Games developed and published Fortnite."], ["In which year was Fortnite first released?", ["2017", "2007", "2012", "2021"], "Fortnite launched in 2017, with Battle Royale arriving that September."], ["What does 'free-to-play' mean?", ["The game costs nothing to download and play", "The game is only free for one week", "The players are paid to play", "The game has no adverts"], "Free-to-play games make money in other ways, such as in-game purchases."], ["What is the in-game currency in Fortnite called?", ["V-Bucks", "Robux", "Gold coins", "Gems"], "Players buy V-Bucks with real money and spend them in the game."], ["What is a microtransaction?", ["A small purchase made inside a game", "A very short game", "A tiny game controller", "A type of game review"], "Microtransactions are small in-game purchases, such as skins."], ["What are cosmetic items?", ["Items that change appearance but not gameplay", "Items that make you stronger", "Make-up adverts in the game", "Extra lives"], "Skins and emotes change how you look, not how well you play."], ["What is Fortnite's PEGI age rating?", ["12", "3", "18", "7"], "PEGI rates Fortnite as 12 because of its cartoon-style violence."], ["What does cross-platform mean?", ["Players on different devices can play together", "The game is only on one console", "The game is played on trains", "The game has two different stories"], "Cross-platform play lets console, PC and mobile players join the same match."], ["Why does Fortnite use collaborations, such as film and music tie-ins?", ["To attract new players and keep existing ones engaged", "To make the game more difficult", "To avoid paying staff", "Because the law requires it"], "Collaborations create excitement and limited items for players to buy."], ["Which audience pleasure fits using a rare skin to stand out?", ["Personal identity", "Surveillance", "Information", "Escapism only"], "Choosing how you look lets players express who they are to others."]], "bonus": ["What is a media audience?", ["The people who use or consume a media product", "The people who build the game", "The company's shareholders", "The game's soundtrack"], "Audiences are the readers, viewers, listeners or players of media."]}, {"ht": "Sum1", "t": "Radio: Desert Island Discs and The Archers", "intro": "Radio is one of the oldest broadcast media and is still listened to by millions every week. Desert Island Discs and The Archers are long-running BBC Radio 4 programmes that show how public service broadcasting works. They also show how radio has adapted to digital listening through BBC Sounds and podcasts.", "how": ["The BBC is a public service broadcaster, funded mainly by the licence fee rather than adverts.", "Its mission is to inform, educate and entertain, and it is regulated by Ofcom under a Royal Charter.", "Desert Island Discs began in 1942; guests choose eight recordings, a book and a luxury to take to an imaginary desert island.", "The Archers began in 1951 and is the world's longest-running drama serial, set in the fictional village of Ambridge.", "Radio audiences now listen live, on catch-up and as podcasts, often on BBC Sounds."], "example": {"q": "Explain how The Archers fits the BBC's public service aims.", "steps": ["Inform: it was first created to share farming information after the Second World War.", "Educate: storylines have explored real issues such as farming changes and difficult relationships.", "Entertain: it is a gripping soap opera with ongoing characters and cliffhangers.", "It is funded by the licence fee, so it does not depend on advertisers.", "It serves a loyal audience and is available on BBC Sounds."], "a": "The Archers informs, educates and entertains, so it meets the BBC's public service mission."}, "walk": [{"h": "The BBC and PSB", "b": "Public service broadcasting means making programmes for the benefit of the public, not just for profit. The BBC's first Director-General, John Reith, set the aim to inform, educate and entertain. Because it is funded by the licence fee, the BBC has no adverts on its UK channels."}, {"h": "Desert Island Discs", "b": "Desert Island Discs was created by Roy Plomley and was taken over by Lauren Laverne in 2018. Each guest talks about their life through eight pieces of music they would take to a desert island. It is a speech-based programme, or chat show format, and many past episodes are available as podcasts."}, {"h": "The Archers", "b": "The Archers is a radio soap opera set in Ambridge, in the fictional county of Borsetshire. Like TV soaps, it has many characters, overlapping storylines and cliffhangers to keep listeners coming back. Its loyal audience tends to be older and middle class, but online listening helps it reach new listeners."}], "qs": [["Which BBC station broadcasts Desert Island Discs and The Archers?", ["BBC Radio 4", "BBC Radio 1", "BBC Radio 2", "BBC 6 Music"], "Both are long-running BBC Radio 4 programmes."], ["How is the BBC mainly funded?", ["The licence fee", "Adverts", "Subscriptions to each show", "Government lottery tickets only"], "The licence fee pays for most BBC programmes, so there are no adverts."], ["What is the BBC's famous mission?", ["Inform, educate and entertain", "Sell, promote and advertise", "Watch, listen and share", "Report, review and repeat"], "This mission comes from John Reith, the first Director-General."], ["How many recordings does a Desert Island Discs guest choose?", ["8", "5", "10", "3"], "Guests choose eight pieces, plus a book and a luxury item."], ["Who created Desert Island Discs?", ["Roy Plomley", "John Reith", "Lauren Laverne", "Harold Mackintosh"], "Roy Plomley devised and presented the programme from 1942."], ["Where is The Archers set?", ["Ambridge, a fictional village", "London's East End", "Manchester city centre", "A desert island"], "Ambridge is in the fictional county of Borsetshire."], ["Why was The Archers first created?", ["To share farming information in an entertaining way", "To advertise tractors", "To teach music", "To report sports results"], "After the war it helped give farmers useful information through drama."], ["What is public service broadcasting?", ["Broadcasting for the benefit of the public, not just profit", "Broadcasting paid for by adverts only", "Broadcasting only news", "Broadcasting by private individuals"], "PSB aims to serve all audiences with quality, varied content."], ["Which BBC app lets people listen to radio live, on catch-up and as podcasts?", ["BBC Sounds", "BBC iPlayer Kids", "Spotify Radio", "BBC Bitesize"], "BBC Sounds is the BBC's audio app."], ["Who regulates the BBC?", ["Ofcom", "The ASA", "PEGI", "The BBFC"], "Ofcom regulates UK broadcasting, including the BBC."]], "bonus": ["What is a soap opera?", ["A long-running drama serial about the everyday lives of characters", "An advert for soap", "A singing competition", "A news bulletin"], "Soaps follow the same characters over many episodes, like The Archers."]}, {"ht": "Sum2", "t": "Film industry: James Bond", "intro": "James Bond is one of the longest-running film franchises in the world. Comparing The Man with the Golden Gun (1974) and No Time to Die (2021) shows how films are produced, distributed and marketed, and how the industry has changed in nearly 50 years. You will focus on the media industries concept.", "how": ["Both films were produced by Eon Productions, run at the time by the Broccoli family.", "The Man with the Golden Gun (1974) starred Roger Moore, with Christopher Lee as the villain Scaramanga, and was distributed by United Artists.", "No Time to Die (2021) was Daniel Craig's final Bond film, distributed by Universal internationally and by MGM in the USA.", "No Time to Die's release was delayed for about 18 months because of the COVID-19 pandemic.", "Marketing moved from posters, cinema trailers and press to online trailers, social media and brand partnerships."], "example": {"q": "Compare how the two Bond films were marketed.", "steps": ["1974: posters, newspaper ads, cinema trailers and a theme song (sung by Lulu) on the radio.", "2021: teaser trailers released online and shared on social media.", "2021: a theme song by Billie Eilish released long before the film, creating buzz.", "Both used product placement and brand tie-ins, such as cars and watches.", "Digital marketing let No Time to Die reach a global audience instantly."], "a": "Both used posters, trailers and theme songs, but No Time to Die relied far more on digital and social media marketing."}, "walk": [{"h": "Production", "b": "Production is making the film, from finance to filming and editing. Bond films have huge budgets; No Time to Die cost around $250 million. Eon Productions produces the films, while big studios help to fund and distribute them."}, {"h": "Distribution", "b": "Distribution is getting the film to audiences. In 1974, film prints were physically sent to cinemas, and later the film was shown on TV. In 2021, digital copies went to cinemas worldwide, and the film later came out on streaming and digital download."}, {"h": "How the industry changed", "b": "Today big companies are often conglomerates that own many media businesses. In 2022 Amazon bought MGM, which co-owns the Bond films, showing how streaming companies are now part of the film industry; in 2025 Amazon MGM Studios took creative control of the franchise. Marketing is also global, with trailers launched online on the same day around the world."}], "qs": [["Which actor played Bond in The Man with the Golden Gun?", ["Roger Moore", "Daniel Craig", "Sean Connery", "Pierce Brosnan"], "Roger Moore played Bond in the 1974 film."], ["Which film was Daniel Craig's last as Bond?", ["No Time to Die", "Skyfall", "Spectre", "Casino Royale"], "No Time to Die (2021) was his fifth and final Bond film."], ["Which company produces the Bond films?", ["Eon Productions", "Disney", "Pixar", "Warner Bros. Games"], "Eon Productions, run by the Broccoli family, produced both films and every official Bond film since 1962."], ["What does film distribution mean?", ["Getting the film to audiences, such as cinemas and streaming", "Writing the script", "Filming the action scenes", "Choosing the actors"], "Distributors release, promote and deliver films to audiences."], ["Why was No Time to Die delayed?", ["The COVID-19 pandemic closed cinemas", "The actors went on strike", "The script was lost", "It was banned"], "Its release moved from 2020 to 2021 because of the pandemic."], ["Who played the villain Scaramanga in The Man with the Golden Gun?", ["Christopher Lee", "Rami Malek", "Javier Bardem", "Christoph Waltz"], "Christopher Lee played the assassin Scaramanga."], ["Who sang the theme song for No Time to Die?", ["Billie Eilish", "Adele", "Lulu", "Sam Smith"], "Billie Eilish's theme won an Oscar; Lulu sang the 1974 theme."], ["What is product placement?", ["Brands paying for their products to appear in a film", "Placing posters in shops", "Showing a film in cinemas", "Selling DVDs online"], "Bond films feature brands like Aston Martin and Omega watches."], ["What is a conglomerate?", ["A large company that owns many different businesses", "A small independent film studio", "A type of camera", "A film festival"], "Conglomerates own businesses across media, such as film, TV and streaming."], ["Which change best shows how film marketing developed between 1974 and 2021?", ["Trailers shared instantly worldwide on social media", "Films stopped using posters entirely", "Films were no longer shown in cinemas", "Theme songs were no longer used"], "Digital and social media let studios reach global audiences instantly."]], "bonus": ["What is a film franchise?", ["A series of related films using the same characters or world", "A single short film", "A cinema ticket", "A film review website"], "Bond is a franchise because many films share the same character and brand."]}]}, {"id": "business", "name": "Business", "board": "Pearson Edexcel (1BS0)", "weeks": [{"ht": "Aut1", "t": "New business ideas and purpose", "intro": "This topic looks at why new business ideas come about, how entrepreneurs think of them and what businesses are for. Businesses exist to provide goods and services that meet customer needs, and they succeed by adding value. These ideas underpin everything else in Theme 1.", "how": ["New ideas come about because of changes in technology, changes in what consumers want, and products becoming obsolete.", "A new idea can be completely original, or it can adapt an existing product, service or idea.", "The purpose of business is to produce goods or services that meet customer needs.", "Businesses add value through convenience, branding, quality, design and a unique selling point (USP).", "Added value is the difference between the selling price and the cost of the bought-in materials."], "example": {"q": "A café buys coffee beans, milk and cups costing £0.80 per cup and sells each coffee for £3.20. Calculate the added value per cup and suggest one way the café adds value.", "steps": ["Added value = selling price − cost of bought-in materials.", "Added value = £3.20 − £0.80.", "Added value = £2.40 per cup.", "The café adds value through convenience, for example a location next to a train station."], "a": "The added value is £2.40 per cup, created for example by a convenient location."}, "walk": [{"h": "Why ideas appear", "b": "Business ideas often appear when something changes. New technology made ideas like food delivery apps possible, and changing tastes led to more plant-based foods. When a product becomes obsolete, such as DVDs being replaced by streaming, there is a gap for something new."}, {"h": "Original or adapted", "b": "Some ideas are truly original, like the first smartphone. Most new businesses, though, adapt an existing idea, such as a coffee shop that also offers a children's play area. Adapting an idea is usually less risky because people already understand the product."}, {"h": "Purpose and added value", "b": "Businesses produce goods (physical things like trainers) and services (things done for you, like haircuts) to meet customer needs. They make money by adding value, so customers will pay more than the cost of the materials. A strong brand, good design, high quality, convenience or a USP all let a business charge more."}], "qs": [["Which of these is a service rather than a good?", ["A haircut", "A pair of trainers", "A chocolate bar", "A mobile phone"], "A service is something done for the customer, like a haircut; the others are physical goods."], ["What is the main purpose of a business?", ["To provide goods or services that meet customer needs", "To employ as many people as possible", "To pay as much tax as possible", "To avoid all risk"], "Businesses exist to produce goods or services that customers need or want."], ["What does USP stand for?", ["Unique selling point", "Universal sales price", "Unique service product", "United selling plan"], "A USP is a unique selling point, a feature that makes a product different from competitors."], ["What does 'obsolete' mean for a product?", ["It is out of date and no longer wanted", "It is brand new on the market", "It is the cheapest in the market", "It is sold only online"], "An obsolete product has been replaced by something newer, so demand for it falls."], ["Which is an example of adapting an existing idea?", ["A gym that adds a crèche for parents", "Inventing the first ever telephone", "Closing down a shop", "Raising the price of a product"], "Adapting means changing an existing product or service, such as adding a crèche to a gym."], ["Which change most directly led to the growth of food delivery apps?", ["Changes in technology", "Products becoming cheaper to make", "More people learning to cook", "Shops opening longer hours"], "Smartphones and apps (new technology) made ordering food online possible."], ["How is added value calculated?", ["Selling price − cost of bought-in materials", "Selling price + cost of materials", "Profit × number of sales", "Revenue − fixed costs"], "Added value is the difference between the selling price and the cost of bought-in materials."], ["A baker spends £1.50 on ingredients for a cake and sells it for £6. What is the added value?", ["£4.50", "£7.50", "£6.00", "£1.50"], "Added value = £6.00 − £1.50 = £4.50."], ["Which way of adding value is a shop next to a bus station using?", ["Convenience", "Branding", "Design", "Quality"], "Being easy to reach and saving customers time is adding value through convenience."], ["Why might a famous brand charge more than a supermarket own brand for similar jeans?", ["Branding adds value, so customers will pay more", "Its materials always cost less", "It has no competitors", "The law says brands must charge more"], "A strong brand makes customers trust and want the product, so it can charge a higher price."]], "bonus": ["Pens cost a shop £0.40 each and it sells them for £1. How much more is the selling price than the cost?", ["£0.60", "£1.40", "£0.40", "£0.06"], "£1.00 − £0.40 = £0.60, a simple subtraction used in added value."]}, {"ht": "Aut2", "t": "Risk, reward and entrepreneurs", "intro": "Starting a business is exciting but risky. In this topic you weigh up the risks and rewards of enterprise and learn what entrepreneurs actually do. You also look at the qualities that help entrepreneurs succeed.", "how": ["An entrepreneur is someone who takes the risk of starting or running a business.", "Risks include business failure, financial loss and lack of security (no guaranteed income).", "Rewards include business success, profit and independence (being your own boss).", "The role of an entrepreneur is to organise resources, make business decisions and take risks.", "Useful characteristics include hard work, determination, creativity, risk-taking and good communication."], "example": {"q": "Priya leaves her job as a teacher to open a dog-grooming salon, using £8,000 of her savings. Explain one risk and one reward for Priya.", "steps": ["Identify a risk: financial loss.", "Apply it: if the salon fails, Priya could lose her £8,000 savings.", "Identify a reward: independence.", "Apply it: Priya can make her own decisions, such as choosing her opening hours."], "a": "Priya risks losing her £8,000 savings if the salon fails, but gains the reward of being her own boss."}, "walk": [{"h": "What entrepreneurs do", "b": "An entrepreneur organises resources such as money, staff, premises and equipment to make a business work. They make decisions, like what to sell and at what price. Most importantly, they take risks, because there is no guarantee the business will succeed."}, {"h": "Weighing risk and reward", "b": "The main risks are business failure, financial loss (such as losing savings) and lack of security, since there is no fixed monthly wage. The rewards are business success, profit and independence. An entrepreneur starts a business when they believe the possible rewards are worth the risks."}, {"h": "Entrepreneur qualities", "b": "Successful entrepreneurs are usually hard-working, determined and willing to take calculated risks. They are creative, so they can spot new ideas, and good at communicating with customers, staff and lenders. For example, determination helps an owner keep going during a slow first year."}], "qs": [["What is an entrepreneur?", ["Someone who takes the risk of starting a business", "Someone who works for a large company", "A person who lends money to businesses", "A government official"], "An entrepreneur takes the risk of setting up and running a business."], ["Which of these is a reward of starting a business?", ["Independence", "Financial loss", "Lack of security", "Business failure"], "Independence (being your own boss) is a reward; the others are risks."], ["Which of these is a risk of starting a business?", ["Losing your savings", "Making a profit", "Being your own boss", "Business success"], "Losing your savings is a financial loss, which is a risk."], ["What does 'lack of security' mean for an entrepreneur?", ["There is no guaranteed regular income", "The shop has no locks or alarms", "The business has no customers at all", "The owner has no qualifications"], "Entrepreneurs do not get a guaranteed wage, so their income is uncertain."], ["Which is part of the role of an entrepreneur?", ["Organising resources", "Setting interest rates", "Writing employment law", "Collecting taxes"], "Entrepreneurs organise resources such as money, staff and equipment."], ["Which characteristic helps an entrepreneur keep going when sales are slow?", ["Determination", "Shyness", "Impatience", "Carelessness"], "Determination helps entrepreneurs push through difficult times."], ["Why might someone with a well-paid job decide not to start a business?", ["They would lose the security of a regular wage", "Businesses never make a profit", "Entrepreneurs cannot make decisions", "Starting a business has no risks"], "Leaving a job means giving up a secure income, which some people see as too risky."], ["An entrepreneur decides to sell online instead of renting a shop. Which role is this?", ["Making business decisions", "Taking out a loan", "Paying tax", "Hiring a supplier"], "Choosing how to sell is an example of making a business decision."], ["Why is being creative useful for an entrepreneur?", ["It helps them spot new ideas and solve problems", "It guarantees the business will succeed", "It removes all financial risk", "It means they never need customers"], "Creativity helps an entrepreneur come up with new ideas and ways to stand out."], ["What does a 'calculated risk' mean?", ["A risk taken after weighing up the likely outcomes", "Any risk, however dangerous", "A risk with no possible reward", "Refusing to take any risk at all"], "A calculated risk is one the entrepreneur has thought through before deciding."]], "bonus": ["Which word means the money a business has left after paying all its costs?", ["Profit", "Revenue", "Loss", "Price"], "Profit is what is left from revenue after all costs are paid."]}, {"ht": "Spr1", "t": "Spotting a business opportunity", "intro": "Before starting, a business must understand its customers and its market. This topic covers customer needs, market research, market segmentation and competition. Getting this right helps a business avoid wasting money on products nobody wants.", "how": ["Customer needs include the right price, quality, choice and convenience.", "Primary research is new data you collect yourself, such as surveys, questionnaires, focus groups and observation.", "Secondary research uses data that already exists, such as the internet, market reports and government reports.", "Market segmentation splits a market into groups by location, demographics, lifestyle, income or age.", "A market map plots brands on two features, such as price and quality, to spot gaps and competitors."], "example": {"q": "Ben wants to open a smoothie bar in his town. Suggest one primary and one secondary research method, with one benefit of each.", "steps": ["Primary: a questionnaire handed out to people in the town centre.", "Benefit: it gives answers to Ben's exact questions, like which flavours people want.", "Secondary: a government report on the town's population.", "Benefit: it is quick and cheap to find, showing how many young people live nearby."], "a": "Ben could use a questionnaire (primary, specific answers) and a government population report (secondary, quick and cheap)."}, "walk": [{"h": "Customer needs", "b": "Customers want a fair price, good quality, plenty of choice and convenience. A business that meets these needs better than rivals will win more customers. For example, a corner shop meets the need for convenience even if its prices are higher than a supermarket."}, {"h": "Market research", "b": "Primary research is first-hand and specific but costs more time and money. Secondary research is cheaper and quicker but may be out of date or not quite relevant. Quantitative data is numbers (70% like mango), while qualitative data is opinions and reasons (it tastes too sweet)."}, {"h": "Segments and competition", "b": "Segmentation lets a business target a group, such as teenagers or people on high incomes. A market map, for example with price on one axis and quality on the other, shows where competitors are and where there might be a gap. Businesses compare rivals on price, quality, location, product range and customer service."}], "qs": [["Which is an example of primary research?", ["A survey of local shoppers", "Reading a government report", "Searching online statistics", "Using a newspaper article"], "A survey collects new, first-hand data, so it is primary research."], ["Which is an example of secondary research?", ["A published market report", "A focus group", "A questionnaire", "Observing customers in a shop"], "A market report already exists, so using it is secondary research."], ["Which customer need is a 24-hour shop mainly meeting?", ["Convenience", "Quality", "Low price", "Choice of brands"], "Being open all the time makes shopping easy, which is convenience."], ["What is market segmentation?", ["Dividing a market into groups of similar customers", "Selling a product in every country", "Lowering prices to beat rivals", "Counting a firm's competitors"], "Segmentation splits customers into groups so a business can target them."], ["'65% of people asked prefer strawberry' is an example of what kind of data?", ["Quantitative", "Qualitative", "Secondary only", "Demographic"], "It is a number, so it is quantitative data."], ["What is one disadvantage of primary research?", ["It can be expensive and time-consuming", "It is always out of date", "It is never relevant to the business", "Anyone can get the same data"], "Collecting your own data takes time and money."], ["Segmenting customers by age and gender is called segmentation by what?", ["Demographics", "Location", "Lifestyle", "Market mapping"], "Demographics are features of a population such as age and gender."], ["What is a market map used for?", ["Spotting gaps in the market and seeing competitors", "Showing the route to the shop", "Calculating break-even", "Planning a cash flow forecast"], "A market map plots brands on two features to show gaps and rivals."], ["A new café opens next door to yours. What is the most likely impact?", ["You may need to lower prices or improve service", "Your sales will definitely rise", "You will have no customers at all", "Your costs will fall automatically"], "More competition usually pressures a business to compete on price or quality."], ["Why might social media be useful for market research?", ["It gives quick, cheap feedback from many customers", "Every comment online is totally reliable", "It replaces the need to know customer needs", "It is a source of government data"], "Social media lets businesses gather opinions quickly and cheaply, though not always reliably."]], "bonus": ["In a survey, 30 out of 120 people chose cheese. What percentage is that?", ["25%", "30%", "40%", "4%"], "30 ÷ 120 = 0.25, and 0.25 × 100 = 25%."]}, {"ht": "Spr2", "t": "Revenue, costs, profit and cash", "intro": "This topic covers the key business calculations: revenue, costs, profit, break-even and cash flow. You also learn where a small business can get money from. These calculations appear in every Edexcel Business paper, so practise them carefully.", "how": ["Revenue = selling price × quantity sold, and total costs = fixed costs + total variable costs.", "Profit = total revenue − total costs; a negative answer is a loss.", "Break-even output = fixed costs ÷ (selling price − variable cost per unit), and margin of safety = actual sales − break-even output.", "Net cash flow = cash inflows − cash outflows, and closing balance = opening balance + net cash flow.", "Interest (%) = (total repayment − amount borrowed) ÷ amount borrowed × 100."], "example": {"q": "A cupcake stall has fixed costs of £300 a month. Each cupcake sells for £2.50 and has a variable cost of £1. It sells 500 a month. Calculate break-even output, profit and margin of safety.", "steps": ["Contribution per cupcake = £2.50 − £1 = £1.50, so break-even = £300 ÷ £1.50 = 200 cupcakes.", "Revenue = 500 × £2.50 = £1,250.", "Total costs = £300 + (500 × £1) = £800, so profit = £1,250 − £800 = £450.", "Margin of safety = 500 − 200 = 300 cupcakes."], "a": "Break-even is 200 cupcakes, profit is £450 and the margin of safety is 300 cupcakes."}, "walk": [{"h": "Revenue, costs, profit", "b": "Fixed costs stay the same however much you sell, like rent. Variable costs change with output, like ingredients. If a shop sells 100 items at £5, revenue is £500; if total costs are £350, profit is £500 − £350 = £150."}, {"h": "Break-even", "b": "Break-even is the output where total revenue equals total costs, so there is no profit or loss. With fixed costs of £1,200, a price of £5 and a variable cost of £2, break-even = £1,200 ÷ £3 = 400 units. On a break-even diagram it is where the total revenue and total costs lines cross."}, {"h": "Cash and finance", "b": "Cash is different from profit: a profitable business can still fail if it runs out of cash to pay bills. A cash flow forecast shows inflows, outflows, net cash flow and balances; for example, an opening balance of £400 plus a net cash flow of −£150 gives a closing balance of £250. Short-term finance includes overdrafts and trade credit, while long-term finance includes personal savings, loans, share capital, venture capital, retained profit and crowdfunding."}], "qs": [["A business sells 150 T-shirts at £8 each. What is its revenue?", ["£1,200", "£158", "£1,500", "£800"], "Revenue = 150 × £8 = £1,200."], ["Which of these is a fixed cost?", ["Rent on a shop", "Ingredients for each pizza", "Packaging for each item", "Delivery cost per order"], "Rent stays the same however much is sold, so it is a fixed cost."], ["Fixed costs are £500 and variable costs are £3 per unit. What are total costs for 100 units?", ["£800", "£503", "£300", "£530"], "Total costs = £500 + (100 × £3) = £500 + £300 = £800."], ["Revenue is £2,000 and total costs are £1,400. What is the profit?", ["£600", "£3,400", "£1,400", "−£600"], "Profit = £2,000 − £1,400 = £600."], ["Fixed costs are £600, price is £10 and variable cost is £4 per unit. What is break-even output?", ["100 units", "60 units", "150 units", "43 units"], "Break-even = £600 ÷ (£10 − £4) = £600 ÷ £6 = 100 units."], ["Cash inflows are £3,000 and cash outflows are £3,500 in a month. What is net cash flow?", ["−£500", "£500", "£6,500", "−£6,500"], "Net cash flow = £3,000 − £3,500 = −£500."], ["The opening balance is £1,000 and net cash flow is −£500. What is the closing balance?", ["£500", "£1,500", "−£500", "£1,000"], "Closing balance = £1,000 + (−£500) = £500."], ["A business borrows £5,000 and repays £5,400 in total. What is the interest rate?", ["8%", "7.4%", "4%", "40%"], "Interest = (£5,400 − £5,000) ÷ £5,000 × 100 = £400 ÷ £5,000 × 100 = 8%."], ["Which is a short-term source of finance?", ["Bank overdraft", "Share capital", "Venture capital", "Retained profit over many years"], "An overdraft lets a business spend more than it has in its account for a short time."], ["Fixed costs are £2,400 and variable cost is £2. If price falls from £10 to £8, what is the new break-even?", ["400 units", "300 units", "240 units", "1,200 units"], "New break-even = £2,400 ÷ (£8 − £2) = £2,400 ÷ £6 = 400 units (it was 300 before)."]], "bonus": ["What is 10% of £250?", ["£25", "£2.50", "£250", "£10"], "10% means divide by 10, so £250 ÷ 10 = £25."]}, {"ht": "Sum1", "t": "Stakeholders and technology", "intro": "Businesses do not work alone: many groups, called stakeholders, are affected by what they do. This topic looks at what each stakeholder wants and how their aims can clash. It also covers how technology changes the way businesses sell, communicate and get paid.", "how": ["A stakeholder is any individual or group affected by, or interested in, a business.", "Key stakeholders are owners (shareholders), employees, customers, suppliers, the local community, pressure groups and the government.", "Stakeholders have different objectives, which can conflict, such as higher pay for staff versus higher profit for owners.", "Key technologies are e-commerce, social media, digital communication and payment systems.", "Technology can increase sales and reduce some costs, but often has set-up costs such as building a website."], "example": {"q": "A supermarket plans to open a large store on the edge of a town. Explain how this might create a conflict between two stakeholders.", "steps": ["Identify stakeholder 1: the owners, who want higher profit from more sales.", "Identify stakeholder 2: the local community, who may worry about traffic and noise.", "Explain the conflict: the store helps owners but may harm residents' quality of life.", "Note that it may also benefit the community by creating local jobs."], "a": "Owners want profit from the new store while local residents may object to the extra traffic and noise, so their objectives conflict."}, "walk": [{"h": "Who stakeholders are", "b": "Stakeholders include owners, employees, customers, suppliers, the local community, pressure groups and the government. Each wants something different: employees want good pay and job security, customers want quality at a fair price. Suppliers want regular orders and prompt payment, and the government wants taxes paid and laws followed."}, {"h": "Stakeholder conflict", "b": "Stakeholders often want different things. If owners cut costs by paying staff less, profit rises but employees are unhappy. Businesses must decide whose objectives matter most, and good decisions often try to balance them."}, {"h": "Technology in business", "b": "E-commerce lets businesses sell online to customers anywhere, at any time. Social media offers cheap marketing and quick customer feedback, and digital communication such as email and video calls speeds up work. Payment systems like contactless cards and mobile payments make buying faster, which can increase sales."}], "qs": [["What is a stakeholder?", ["Anyone affected by or interested in a business", "Only the owner of a business", "Only the business's customers", "A type of business loan"], "A stakeholder is any individual or group with an interest in, or affected by, a business."], ["What is a main objective of employees as stakeholders?", ["Good pay and job security", "Low prices", "High taxes", "Prompt payment for supplies"], "Employees mainly want fair pay and secure jobs."], ["Which stakeholder mainly wants the business to pay taxes and obey the law?", ["The government", "Customers", "Suppliers", "Employees"], "The government collects taxes and makes laws that businesses must follow."], ["What do suppliers mainly want from a business?", ["Regular orders and prompt payment", "Low prices for their own goods", "Higher wages", "Less traffic in the area"], "Suppliers want steady orders and to be paid on time."], ["What is e-commerce?", ["Buying and selling goods online", "Sending emails to staff", "Paying with cash only", "Selling door to door"], "E-commerce means trading online, for example through a website or app."], ["Which is an example of a digital payment system?", ["Contactless card payment", "Paying with coins", "Writing an IOU note", "Bartering goods"], "Contactless card payment is an electronic payment system."], ["Which pair of stakeholders is most likely to conflict over wage levels?", ["Employees and owners", "Customers and the government", "Suppliers and pressure groups", "The local community and customers"], "Employees want higher wages, while owners may want lower costs to increase profit."], ["How might social media help a small business?", ["It offers cheap marketing to many customers", "It removes the need for any staff", "It guarantees good reviews", "It sets the business's prices"], "Social media lets a small business reach many customers at low cost."], ["What is one cost of using e-commerce?", ["Building and maintaining a website", "Paying higher rent for a shop", "Fewer customers worldwide", "Being unable to sell at night"], "Setting up and updating a website costs money, even if it saves shop costs."], ["A factory wants to expand. Which stakeholder is most likely to object over pollution?", ["The local community", "The owners", "The suppliers", "The bank"], "Local residents are directly affected by pollution and noise from the factory."]], "bonus": ["Which of these is an example of a business's customer?", ["A person buying a sandwich in a café", "The café's chef", "The farmer who sells the café eggs", "The café's owner"], "A customer is the person who buys the goods or services; the others are staff, a supplier and the owner."]}, {"ht": "Sum2", "t": "Legislation and the economy", "intro": "Businesses must obey the law and are affected by what happens in the wider economy. This topic covers consumer and employment law, and how interest rates, unemployment and exchange rates affect businesses. These factors are outside a business's control, so it must react to them.", "how": ["Consumer law (such as the Consumer Rights Act 2015) says goods must be of satisfactory quality, fit for purpose and as described.", "Employment law covers recruitment, pay (the National Minimum Wage), discrimination and health and safety.", "Higher interest rates make loans more expensive and usually reduce consumer spending.", "Rising unemployment means people have less income, so demand often falls, especially for luxuries.", "A stronger pound makes imports cheaper and exports more expensive (remember SPICED: Strong Pound, Imports Cheaper, Exports Dearer)."], "example": {"q": "A UK company sells a gadget for £20. It exports to the USA. What is the US price when £1 = $1.25, and when £1 = $1.50? What happens to demand?", "steps": ["At £1 = $1.25, the US price is £20 × 1.25 = $25.", "At £1 = $1.50, the US price is £20 × 1.50 = $30.", "The pound has strengthened, so the gadget is more expensive for US customers.", "US demand is likely to fall."], "a": "The US price rises from $25 to $30, so US demand for the gadget is likely to fall."}, "walk": [{"h": "Consumer law", "b": "Consumer law protects buyers. Under the Consumer Rights Act 2015, goods must be of satisfactory quality, fit for purpose and as described. If a new kettle breaks after one week, the customer has the right to a refund, repair or replacement."}, {"h": "Employment law", "b": "Employment law protects workers. Businesses must pay at least the National Minimum Wage, must not discriminate when hiring or promoting (Equality Act 2010) and must keep workplaces safe (Health and Safety at Work Act 1974). Following the law costs money, for example for training, but breaking it can lead to fines and a damaged reputation."}, {"h": "The economic climate", "b": "When interest rates rise, loan repayments go up and customers with mortgages have less to spend. When unemployment rises, people have less income, so sales of luxuries usually fall, though businesses find it easier to recruit. Exchange rates matter for trade: if £1 rises from $1.20 to $1.40, UK imports get cheaper but UK exports become dearer abroad."}], "qs": [["Under consumer law, goods must be which of these?", ["Of satisfactory quality", "The cheapest on the market", "Made in the UK", "Sold with free delivery"], "The Consumer Rights Act 2015 says goods must be of satisfactory quality, fit for purpose and as described."], ["Which area does employment law cover?", ["Pay, discrimination and health and safety", "The quality of goods sold", "Exchange rates", "How much profit a firm makes"], "Employment law protects workers, including their pay, fair treatment and safety."], ["Which law protects workers from discrimination in the UK?", ["Equality Act 2010", "Consumer Rights Act 2015", "Health and Safety at Work Act 1974", "Companies Act 2006"], "The Equality Act 2010 makes it illegal to discriminate against people at work."], ["What usually happens to consumer spending when interest rates rise?", ["It falls", "It rises", "It stays exactly the same", "It doubles"], "Higher interest rates make borrowing dearer and increase loan repayments, so people spend less."], ["How does a rise in interest rates affect a business with a large bank loan?", ["Its repayments increase", "Its repayments decrease", "Its loan is cancelled", "It no longer needs to repay"], "Higher interest rates make loan repayments more expensive."], ["When unemployment rises, which business is likely to lose the most sales?", ["A luxury holiday company", "A discount supermarket", "A pharmacy", "A budget clothing shop"], "People with less income cut back on luxuries first."], ["What is one benefit to businesses when unemployment is high?", ["It is easier to recruit staff", "Customers spend much more", "Wages must rise quickly", "Interest rates must fall"], "With more people looking for work, businesses have more applicants to choose from."], ["A new phone breaks after a week. What is the customer entitled to?", ["A refund, repair or replacement", "Nothing at all", "Only a discount voucher", "A free second phone"], "Goods must be of satisfactory quality, so the customer can claim a refund, repair or replacement."], ["If the pound gets stronger, what happens to UK imports?", ["They become cheaper", "They become more expensive", "They are banned", "Nothing changes"], "A strong pound buys more foreign currency, so imports are cheaper (SPICED)."], ["A UK firm sells a product for £40 in the USA. What is the US price if £1 = $1.30?", ["$52", "$30.77", "$41.30", "$40"], "US price = £40 × 1.30 = $52."]], "bonus": ["£1 = $1.20. How many dollars is £10?", ["$12", "$8.33", "$11.20", "$120"], "Multiply by the exchange rate: 10 × 1.20 = $12."]}]}, {"id": "sociology", "name": "Sociology", "board": "AQA (8192)", "weeks": [{"ht": "Aut1", "t": "Sociological perspectives", "intro": "Sociology is the study of society and how people behave in groups. Sociologists use different perspectives, like different pairs of glasses, to explain society, and you will use these ideas in every topic.", "how": ["Socialisation is how we learn the norms and values of our society.", "Norms are unwritten rules of behaviour; values are beliefs about what is important.", "Functionalists see society as working together, like parts of a body.", "Marxists see conflict between social classes; feminists focus on inequality between men and women.", "Interactionists study small-scale, everyday interactions and how people give meaning to them."], "example": {"q": "Explain how a child learns gender roles through primary socialisation.", "steps": ["Primary socialisation happens in the family during early childhood.", "Parents may give boys and girls different toys, a process called canalisation.", "Children also copy adults through imitation, and are praised or told off (sanctions).", "Over time the child learns what their society expects of their gender."], "a": "Children learn gender roles mainly from their family through canalisation, imitation and sanctions."}, "walk": [{"h": "Norms, values and socialisation", "b": "A value is an idea that something is important, such as respect for elders. A norm is a rule that comes from a value, like letting an older person have your seat on the bus. Primary socialisation happens in the family; secondary socialisation comes from school, friends, media and religion."}, {"h": "Structural perspectives", "b": "Functionalists, such as Émile Durkheim and Talcott Parsons, think each institution has a useful job, like the family raising children. Marxists, following Karl Marx, believe society benefits the rich ruling class (bourgeoisie) at the expense of the working class (proletariat). Feminists argue society is patriarchal, meaning it is run in the interests of men."}, {"h": "Interactionism", "b": "Interactionists look at how people interpret situations and label each other. For example, if a teacher labels a pupil as 'troublemaker', the pupil may start to act that way, which is called a self-fulfilling prophecy. This is a micro (small-scale) approach, while the others are macro (whole-society) approaches."}], "qs": [["What is socialisation?", ["Learning the norms and values of society", "Going to parties with friends", "Studying the history of society", "A type of government"], "Socialisation is the lifelong process of learning how to behave in society."], ["Which is an example of a norm in the UK?", ["Queuing to buy a ticket", "Believing education is important", "Being born in Britain", "Having brown hair"], "A norm is an expected behaviour; queuing is a common UK norm."], ["What is a value?", ["A belief that something is important", "A written law", "A punishment for bad behaviour", "A type of family"], "Values are general beliefs about what is good or worthwhile."], ["Where does primary socialisation mainly take place?", ["The family", "The workplace", "Secondary school", "Social media"], "Primary socialisation happens in early childhood, mostly in the family."], ["Which perspective sees society as working like parts of a body?", ["Functionalism", "Marxism", "Feminism", "Interactionism"], "Functionalists use the organic analogy: each part helps the whole work."], ["According to Marxists, the bourgeoisie are:", ["The ruling class who own the means of production", "The working class", "Teachers and nurses", "Women in the home"], "Marx said the bourgeoisie own factories and land and exploit workers."], ["What does 'patriarchy' mean?", ["A society dominated by men", "A society run by children", "A society with no leaders", "A society where everyone is equal"], "Feminists use patriarchy to describe male dominance in society."], ["Which perspective focuses on labelling and small-scale interactions?", ["Interactionism", "Functionalism", "Marxism", "Feminism"], "Interactionism is a micro approach that studies how people interpret one another."], ["What is a self-fulfilling prophecy?", ["A label that makes a person act in the labelled way", "A prediction about the weather", "A rule written in law", "A sociologist's research method"], "When people believe a label about themselves, they may start to live up to it."], ["Which is the best criticism of functionalism?", ["It ignores conflict and inequality in society", "It only looks at women", "It says the rich exploit the poor", "It only studies tiny groups"], "Marxists and feminists say functionalists paint too positive a picture."]], "bonus": ["Which of these is an example of a social group?", ["A football team", "A single tree", "A mountain", "A computer"], "A social group is people who interact and share something in common."]}, {"ht": "Aut2", "t": "Introduction to research methods", "intro": "Sociologists collect evidence to test their ideas, just like scientists. This topic explains how to plan a study and choose between methods such as questionnaires, interviews and observation.", "how": ["Start with a hypothesis (a testable idea) or a research question.", "Quantitative data is numbers; qualitative data is words, feelings and meanings.", "Questionnaires use closed or open questions and can reach many people quickly.", "Interviews can be structured (set questions) or unstructured (like a guided conversation).", "Observation can be participant (joining in) or non-participant, and covert (secret) or overt (open)."], "example": {"q": "A sociologist wants to find out how many hours of homework Year 9 pupils do each week. Which method should they choose?", "steps": ["Identify the type of data needed: a number of hours, so quantitative data.", "A questionnaire with closed questions gives numbers that are easy to compare.", "It can reach a large sample quickly and cheaply.", "A pilot study could be used first to check the questions are clear."], "a": "A questionnaire with closed questions is best, because it gives quantitative data from many pupils."}, "walk": [{"h": "Planning research", "b": "The research process starts with choosing a topic and writing a hypothesis, such as 'Girls do more homework than boys'. Next, the researcher chooses a sample from the target population. A pilot study is a small trial run that helps fix problems before the main research."}, {"h": "Quantitative versus qualitative", "b": "Quantitative data is numerical, like 65% of pupils own a phone; it is easy to compare and test for reliability. Qualitative data is detailed and descriptive, like a pupil explaining how they feel about school; it often has high validity because it shows the true picture. Reliability means getting the same results if repeated; validity means the data truly reflects reality."}, {"h": "Interviews and observation", "b": "Structured interviews ask everyone the same questions, so they are reliable, while unstructured interviews allow deeper answers, so they are more valid. In covert participant observation, the researcher joins a group in secret, which can give rich data but raises ethical problems. The Hawthorne effect is when people change their behaviour because they know they are being watched."}], "qs": [["What is quantitative data?", ["Data in the form of numbers", "Data in the form of words and feelings", "Data that is always untrue", "Data from old diaries"], "Quantitative data is numerical and can be shown in tables and graphs."], ["What is qualitative data?", ["Detailed data in words, meanings and feelings", "Data shown only as percentages", "Data collected by the government", "Data that cannot be written down"], "Qualitative data describes quality and meaning rather than quantity."], ["What is a hypothesis?", ["A testable statement or prediction", "The final result of a study", "A type of interview", "A list of people to study"], "A hypothesis is an idea the research sets out to test."], ["What is a closed question?", ["A question with fixed answers to choose from", "A question allowing any answer", "A question asked in secret", "A question with no answer"], "Closed questions, like yes/no, produce quantitative data."], ["What is a pilot study?", ["A small trial run before the main research", "Research about pilots", "The final stage of research", "A study done only online"], "A pilot study tests the method so problems can be fixed."], ["What does covert observation mean?", ["Watching a group without them knowing", "Watching openly with permission", "Reading official statistics", "Asking a questionnaire online"], "Covert means hidden; the group does not know they are being studied."], ["What does reliability mean?", ["The research gives the same results if repeated", "The research shows the true picture", "The research is very cheap", "The research uses many interviewers"], "Reliable research can be repeated and get consistent results."], ["What does validity mean?", ["The data gives a true picture of reality", "The data can be repeated exactly", "The data is in number form", "The data was collected quickly"], "Valid data accurately reflects what it claims to measure."], ["Which method usually gives the most valid, in-depth data?", ["Unstructured interviews", "Closed-question questionnaires", "Structured interviews", "Official statistics"], "Unstructured interviews let people explain views fully in their own words."], ["What is the Hawthorne effect?", ["People act differently because they know they are watched", "People forget answers in interviews", "Researchers lie about results", "Samples are too large"], "Being observed can change behaviour, which reduces validity."]], "bonus": ["What is a 'survey'?", ["Collecting information from many people", "A type of family", "A famous sociologist", "A punishment in school"], "A survey gathers information from lots of people, often using questionnaires."]}, {"ht": "Spr1", "t": "Functions and forms of the family", "intro": "The family is one of the most important institutions in society. Sociologists ask what jobs the family does and what different types of family exist in Britain today.", "how": ["Learn the main family forms: nuclear, extended, lone-parent, reconstituted (step), same-sex and beanpole.", "Know Murdock's four functions: sexual, reproductive, economic and educational.", "Know Parsons' two functions: primary socialisation and stabilising adult personalities.", "Marxists and feminists criticise these positive views.", "Use real examples to explain each family type."], "example": {"q": "A mother and father live with their two children, and the father's son from a previous relationship. What family type is this?", "steps": ["Look at who lives in the household: two parents and children.", "Notice that one child is from a previous relationship.", "A family that includes step-children from earlier relationships is reconstituted.", "This is also called a blended or step family."], "a": "This is a reconstituted (blended) family."}, "walk": [{"h": "Family types", "b": "A nuclear family is two parents and their children living together. An extended family includes other relatives, such as grandparents, aunts or cousins. A beanpole family is long and thin: several generations alive at once, but few aunts, uncles and cousins, because families have fewer children."}, {"h": "Functionalist views", "b": "George Murdock (1949) studied many societies and said the nuclear family is universal, with four functions: sexual, reproductive, economic and educational. Talcott Parsons said modern families have two basic functions: primary socialisation of children and the stabilisation of adult personalities. Parsons also said the nuclear family 'fits' industrial society because families can move for work."}, {"h": "Critical views", "b": "Marxists, such as Zaretsky, argue the family helps capitalism, for example by raising future workers and buying consumer goods. Feminists argue the traditional family can benefit men more than women, for instance when women do most of the housework. These views show the family does not affect everyone in the same way."}], "qs": [["What is a nuclear family?", ["Two parents and their children", "One parent and children", "Grandparents, parents, children and cousins", "People sharing a house who are not related"], "The nuclear family is two generations: parents and children."], ["What is an extended family?", ["A family including relatives beyond parents and children", "A family with only one parent", "A couple with no children", "A family with step-children"], "Extended families include grandparents, aunts, uncles or cousins."], ["What is a lone-parent family?", ["One parent living with their children", "Two parents and children", "A family with no children", "A family with three generations"], "A lone-parent family is headed by one parent, often after separation."], ["What is a reconstituted family?", ["A family including step-children from previous relationships", "A family that has moved house", "A family living abroad", "A family with only grandparents"], "Reconstituted families are formed when partners with children form new families."], ["How many functions did Murdock say the family has?", ["Four", "Two", "Six", "Ten"], "Murdock named sexual, reproductive, economic and educational functions."], ["Which was one of Parsons' two basic functions of the family?", ["Primary socialisation of children", "Paying taxes", "Running schools", "Making laws"], "Parsons named primary socialisation and stabilisation of adult personalities."], ["What is a beanpole family?", ["Several generations alive but few relatives in each", "A family where everyone is tall", "A family with many cousins", "A family with one child only"], "Beanpole families are long and thin across generations."], ["Which perspective says the family benefits capitalism?", ["Marxism", "Functionalism", "Interactionism", "New Right"], "Marxists argue the family serves the ruling class and capitalism."], ["Which perspective argues the traditional family often benefits men more?", ["Feminism", "Functionalism", "Marxism", "Interactionism"], "Feminists highlight unequal housework and power within families."], ["Why did Parsons think the nuclear family suits industrial society?", ["It is small and can move easily for work", "It has many relatives to share jobs", "It lives on farms", "It does not need money"], "Parsons said a small nuclear family is geographically mobile."]], "bonus": ["What is a 'generation' in a family?", ["People born at roughly the same time, like siblings", "A family's house", "A family's surname", "The number of pets"], "Grandparents, parents and children are three different generations."]}, {"ht": "Spr2", "t": "Roles and relationships in families", "intro": "This topic looks at how partners share housework, childcare and decisions, and how relationships between parents, children and grandparents have changed. It helps you judge whether families today are more equal than in the past.", "how": ["Conjugal roles are the roles of partners in a couple, at home and at work.", "Segregated roles are separate (one earns, one does housework); joint roles are shared.", "Willmott and Young argued families became symmetrical, with more equal roles.", "Oakley and other feminists argued women still do most of the housework.", "Childhood has become more child-centred, and grandparents often help with childcare."], "example": {"q": "A couple both work full time, but the woman also does most of the cooking and cleaning. What is this called?", "steps": ["Notice that she does paid work and most of the unpaid housework.", "Feminists call this the 'dual burden'.", "This suggests roles are not fully equal, even if both partners work.", "It supports Oakley's view against the idea of the symmetrical family."], "a": "This is the dual burden, showing conjugal roles are not yet fully equal."}, "walk": [{"h": "Segregated and joint roles", "b": "Elizabeth Bott described segregated conjugal roles, where the husband was the breadwinner and the wife a housewife. Joint conjugal roles mean partners share tasks and leisure time. For example, a couple who take turns cooking and both do the school run have joint roles."}, {"h": "The symmetrical family debate", "b": "Willmott and Young (1973) said families were becoming symmetrical, with partners doing similar amounts of work in and out of the home. Ann Oakley (1974) found that only a small minority of husbands helped a lot with housework, and that 'helping' was not the same as equal sharing. Many studies today still find women do more housework and childcare than men on average."}, {"h": "Changing relationships", "b": "Families have become more child-centred, with children having more say and parents spending more on them. Power in relationships is shared more often, and decision-making may be more joint. Grandparents now often provide childcare, which links to the beanpole family."}], "qs": [["What are conjugal roles?", ["The roles of partners in a couple", "The roles of children in school", "Jobs in the government", "Roles in a sports team"], "Conjugal roles describe how a couple divides tasks."], ["What are segregated conjugal roles?", ["Separate roles, such as breadwinner and housewife", "Equal sharing of all tasks", "Roles shared with grandparents", "Roles in a lone-parent family"], "Segregated means separate tasks for each partner."], ["What are joint conjugal roles?", ["Partners share tasks and decisions", "One partner does everything", "Children do all the housework", "Partners never see each other"], "Joint roles mean tasks are shared between partners."], ["Who argued the family was becoming 'symmetrical'?", ["Willmott and Young", "Ann Oakley", "Karl Marx", "George Murdock"], "Willmott and Young described the symmetrical family in 1973."], ["What does a 'symmetrical family' mean?", ["Partners' roles are similar and more equal", "Everyone in the family looks alike", "The family has two children", "One parent works abroad"], "Symmetrical means roles are balanced between partners."], ["Which sociologist criticised the idea of the symmetrical family?", ["Ann Oakley", "Talcott Parsons", "Willmott and Young", "Émile Durkheim"], "Oakley found women still did most housework."], ["What is the 'dual burden'?", ["Women doing paid work and most of the housework", "Having two jobs in one company", "Having two children at once", "Paying two lots of tax"], "The dual burden is carrying both paid and unpaid work."], ["Who first described segregated and joint conjugal roles?", ["Elizabeth Bott", "Ann Oakley", "Karl Marx", "Charles Murray"], "Bott studied couples' roles in the 1950s."], ["What does 'child-centred' family mean?", ["Children's needs and views are a high priority", "Children make all the rules", "Children work to support parents", "Children live apart from parents"], "Child-centred families focus time and money on children."], ["Which evidence most challenges the idea that roles are now equal?", ["Studies showing women still do more housework", "More women in paid work", "More men doing some childcare", "Couples sharing some decisions"], "If women still do more, roles are not fully equal."]], "bonus": ["What is 'housework'?", ["Unpaid jobs done at home, like cleaning", "Paid work in an office", "Homework given by school", "Building a new house"], "Housework is the unpaid labour of running a home."]}, {"ht": "Sum1", "t": "Family diversity and divorce", "intro": "Families in modern Britain come in many shapes, and divorce has become more common since the 1970s. This topic explores why family life has become more diverse, what critics say about the family, and how divorce affects people.", "how": ["Family diversity means there are many different family types in Britain today.", "The Rapoports (1982) identified five types of diversity, including cultural, class and life-course.", "The Divorce Reform Act 1969 (in force 1971) made divorce easier, and no-fault divorce began in 2022.", "Reasons for rising divorce include changing laws, less stigma, secularisation and women's independence.", "Know both positive and negative consequences of divorce, and criticisms of the family."], "example": {"q": "Give two reasons why the divorce rate increased in Britain after 1971.", "steps": ["Look at changes in the law: the Divorce Reform Act 1969 came into effect in 1971.", "It allowed divorce for 'irretrievable breakdown', making divorce easier to get.", "Look at social changes: more women in paid work could support themselves.", "This meant women were less financially dependent on staying married."], "a": "Divorce rose because the law made it easier and women became more financially independent."}, "walk": [{"h": "Diversity in modern Britain", "b": "Robert and Rhona Rapoport said family diversity includes organisational, cultural, class, life-course and generational differences. For example, a family's structure may change across the life course, from a couple, to parents, to empty nesters. Families can also differ by culture, such as some British Asian families living in extended households."}, {"h": "Criticisms of the family", "b": "Edmund Leach said the nuclear family can be too inward-looking, causing stress and conflict. Feminists highlight unequal roles and domestic abuse, which affects some families and is a serious crime. Marxists say families pass on inequality, for example through inheritance of wealth."}, {"h": "Divorce: causes and effects", "b": "Divorce rates rose sharply after the Divorce Reform Act came into force in 1971, and the 2020 Divorce, Dissolution and Separation Act brought in no-fault divorce in 2022. Less stigma, secularisation and higher expectations of marriage also help explain the rise. Divorce can be hard for children and lead to money worries, but it can also end an unhappy relationship and create new reconstituted families."}], "qs": [["What does family diversity mean?", ["There are many different types of family", "All families are the same", "Families are getting larger", "Only nuclear families exist"], "Diversity means variety in family structures."], ["Which law made divorce easier, coming into force in 1971?", ["The Divorce Reform Act 1969", "The Equality Act 2010", "The Education Act 1944", "The Children Act 1989"], "The Divorce Reform Act 1969 allowed divorce for irretrievable breakdown."], ["What does 'stigma' mean?", ["Shame or disapproval attached to something", "A type of marriage", "A legal document", "A rise in income"], "Less stigma means divorce is more socially accepted."], ["What is secularisation?", ["The decline of religious influence in society", "An increase in marriages", "A new type of school", "Moving to the countryside"], "As religion's influence falls, fewer people see marriage as unbreakable."], ["When did no-fault divorce begin in England and Wales?", ["2022", "1971", "1857", "1999"], "The Divorce, Dissolution and Separation Act 2020 came into force in April 2022."], ["Which sociologists identified five types of family diversity?", ["The Rapoports", "Willmott and Young", "Marx and Engels", "Bott and Oakley"], "Rapoport and Rapoport (1982) described five types of diversity."], ["How might women's paid employment increase divorce?", ["Women can support themselves financially", "Women have less free time to marry", "It makes marriage illegal", "It means fewer people work"], "Financial independence means women need not stay in unhappy marriages."], ["Which is a positive consequence of divorce?", ["It can end an unhappy or harmful relationship", "It always makes children happier", "It always reduces money problems", "It means families never change"], "Divorce can allow people to leave relationships that are not working."], ["Who argued the nuclear family can be too inward-looking and cause conflict?", ["Edmund Leach", "George Murdock", "Talcott Parsons", "Willmott and Young"], "Leach called the family a 'cereal packet' ideal that can create stress."], ["Which is the best evaluation of 'Rising divorce shows marriage is less popular'?", ["Many divorced people remarry, so marriage is still valued", "Nobody gets married any more", "Divorce has never changed", "Marriage is now illegal"], "High remarriage rates suggest people still value marriage."]], "bonus": ["What is marriage?", ["A legally recognised union between two people", "Living with a friend", "A type of school", "A job contract"], "Marriage is a legal union recognised by the state."]}, {"ht": "Sum2", "t": "Primary and secondary data, ethics", "intro": "Sociologists can collect their own evidence or use evidence that already exists. This topic teaches you how to interpret data, and the practical and ethical issues every researcher must think about.", "how": ["Primary data is collected first-hand by the researcher, such as from interviews.", "Secondary data already exists, such as official statistics, diaries or newspapers.", "When interpreting data, look for trends, the biggest and smallest values, and the source.", "Practical issues include time, cost, access and the researcher's skills.", "Ethical issues include informed consent, confidentiality, anonymity and protection from harm."], "example": {"q": "A table shows the number of divorces in a town fell from 400 in 2010 to 300 in 2020. By what percentage did divorces fall?", "steps": ["Find the change: 400 − 300 = 100.", "Divide by the original amount: 100 ÷ 400 = 0.25.", "Multiply by 100 to get a percentage: 0.25 × 100 = 25%.", "Describe the trend: divorces decreased over the decade."], "a": "Divorces fell by 25% between 2010 and 2020."}, "walk": [{"h": "Primary versus secondary data", "b": "Primary data is collected by the researcher themselves, so they control what is asked. Secondary data has been collected by someone else, such as the census from the Office for National Statistics (ONS). Secondary data saves time and money but may not answer the researcher's exact question."}, {"h": "Interpreting data", "b": "When reading a graph or table, check the title, the units and where the data came from. Spot the trend, such as 'rising steadily', and pick out key figures to support your point. For example, if 40 out of 200 people answer 'yes', that is 20%."}, {"h": "Practical and ethical issues", "b": "Practical issues include cost, time and whether the researcher can gain access to a group. Ethical issues include getting informed consent, keeping identities anonymous and data confidential, and avoiding harm. Research with children usually needs consent from parents or carers, and covert research is controversial because participants have not agreed to take part."}], "qs": [["What is primary data?", ["Data collected first-hand by the researcher", "Data that already exists", "Data from primary schools only", "Data that is always numerical"], "Primary means the researcher collected it themselves."], ["What is secondary data?", ["Data that already exists, collected by others", "Data the researcher collects now", "Data from secondary schools only", "Data that cannot be used"], "Secondary data includes official statistics and documents."], ["Which is an example of secondary data?", ["Official statistics from the ONS", "A questionnaire you hand out", "An interview you carry out", "An observation you make"], "Official statistics are collected by the government, not the researcher."], ["What is informed consent?", ["Agreeing to take part after being told about the research", "Taking part in secret", "Being paid for research", "Refusing to take part"], "Participants should know what the study involves before agreeing."], ["What does anonymity mean in research?", ["Participants' names are not revealed", "Research is done in secret", "The researcher has no name", "Results are not published"], "Anonymity protects participants' identities."], ["Which is a practical issue in research?", ["The cost of the study", "Getting informed consent", "Protecting people from harm", "Keeping data confidential"], "Cost, time and access are practical issues; the others are ethical."], ["40 out of 200 people answered 'yes'. What percentage is this?", ["20%", "40%", "25%", "5%"], "40 ÷ 200 = 0.2, and 0.2 × 100 = 20%."], ["Divorces rose from 200 to 250. What is the percentage increase?", ["25%", "50%", "20%", "250%"], "The rise is 50, and 50 ÷ 200 × 100 = 25%."], ["Why is covert research seen as an ethical problem?", ["People have not given informed consent", "It is always too expensive", "It only uses numbers", "It always takes ten years"], "In covert research, participants do not know they are being studied."], ["What is the main disadvantage of secondary data?", ["It may not answer the researcher's exact question", "It always costs more than primary data", "It can never be trusted at all", "It always takes longer to collect"], "Secondary data was collected for another purpose, so it may not fit."]], "bonus": ["What is 25% as a fraction?", ["¼", "½", "⅓", "⅕"], "25% means 25 out of 100, which simplifies to ¼."]}]}, {"id": "statistics", "name": "Statistics", "board": "Pearson Edexcel (1ST0)", "weeks": [{"ht": "Aut1", "t": "Types of Data", "intro": "Statistics starts with data, and different kinds of data need different methods. Knowing whether data is qualitative or quantitative, discrete or continuous, and primary or secondary helps you choose the right tables, graphs and calculations.", "how": ["Qualitative data is described in words, such as eye colour or favourite sport.", "Quantitative data is numerical, such as height or number of pets.", "Discrete data can only take certain values (usually counted), while continuous data can take any value in a range (measured).", "Primary data is collected by you or for you; secondary data has already been collected by someone else.", "Bivariate data is a pair of values for each item, such as the height and arm span of each student."], "example": {"q": "Classify the data: the times taken by 30 students to run 100 m, measured by the PE teacher for a class project.", "steps": ["Time is a number, so the data is quantitative.", "Time is measured and can take any value, such as 14.37 seconds, so it is continuous.", "It was collected first-hand for this project, so it is primary data."], "a": "The data is quantitative, continuous and primary."}, "walk": [{"h": "Qualitative or quantitative", "b": "Ask yourself: is the answer a word or a number? Hair colour (brown, black, blonde) is qualitative. Shoe size or the number of siblings is quantitative."}, {"h": "Discrete or continuous", "b": "Quantitative data splits further. Discrete data is counted and has gaps between values, like the number of goals (you cannot score 2.5 goals). Continuous data is measured, like mass or time, and could be any value. Shoe size is discrete because it only comes in set sizes, such as 5 or 5½."}, {"h": "Primary or secondary", "b": "Primary data is collected for your own investigation, for example by a survey or experiment. It is reliable for your purpose but takes time and money. Secondary data, like census results or a website's figures, is quick and cheap but may be out of date or collected for a different purpose."}], "qs": [["Which of these is qualitative data?", ["Favourite colour", "Height in cm", "Number of pets", "Age in years"], "Favourite colour is described in words, not numbers."], ["Which of these is quantitative data?", ["Number of siblings", "Eye colour", "Type of pet", "Favourite subject"], "The number of siblings is a numerical value."], ["Which of these is continuous data?", ["Mass of an apple", "Number of goals scored", "Shoe size", "Number of cars"], "Mass is measured and can take any value in a range."], ["Which of these is discrete data?", ["Number of students in a class", "Time taken to run 1 km", "Length of a leaf", "Temperature"], "The number of students is counted and can only be whole numbers."], ["Shoe size is an example of which type of data?", ["Discrete", "Continuous", "Qualitative", "Bivariate"], "Shoe sizes only come in set values like 5, 5½ and 6, so they are discrete."], ["A student uses census figures from a government website. What type of data is this?", ["Secondary", "Primary", "Qualitative", "Bivariate"], "The data was collected by someone else, so it is secondary data."], ["What is one advantage of primary data?", ["You know exactly how it was collected", "It is always cheaper", "It is always quicker to get", "It is always larger"], "Because you collected it yourself, you know how accurate and relevant it is."], ["What is one disadvantage of secondary data?", ["It may be out of date", "It takes a long time to collect", "It is always biased", "It can never be trusted"], "Secondary data was collected earlier, possibly for a different purpose."], ["A scientist records the height and mass of each of 20 people. What kind of data is this?", ["Bivariate", "Qualitative", "Discrete", "Secondary"], "Two variables are recorded for each person, which makes it bivariate data."], ["Ages are recorded as 'age last birthday'. How should this data be described?", ["Discrete, as only whole numbers are recorded", "Continuous, as only whole numbers are recorded", "Qualitative, as it is about people", "Primary, as all ages are discrete"], "Age itself is continuous, but 'age last birthday' only takes whole-number values, so it is discrete."]], "bonus": ["Which of these is a whole number?", ["7", "7.5", "¾", "0.7"], "Whole numbers have no fractional or decimal part, so 7 is the only one."]}, {"ht": "Aut2", "t": "Populations and Sampling", "intro": "A population is everyone or everything you want to find out about, but asking everyone is often too slow or costly. Instead we take a sample, and the method we use affects how fair and representative the results are.", "how": ["A census collects data from the whole population; a sample uses only part of it.", "In simple random sampling, every member has an equal chance of being chosen, for example using random numbers.", "Systematic sampling picks every kth item from a list after a random start.", "Stratified sampling takes the same fraction from each group: (group size ÷ population) × sample size.", "Quota, cluster and convenience sampling are quicker but can be less representative."], "example": {"q": "A school has 600 students: 240 in Year 9 and 360 in Year 10. Take a stratified sample of 50.", "steps": ["Year 9: 240 ÷ 600 × 50 = 20.", "Year 10: 360 ÷ 600 × 50 = 30.", "Check the total: 20 + 30 = 50.", "Choose the students within each year group at random."], "a": "Sample 20 Year 9 students and 30 Year 10 students."}, "walk": [{"h": "Population, census, sample", "b": "The population is the whole group you are studying, such as all students at a school. A census asks every member, which is accurate but slow and expensive. A sample is cheaper and quicker, but must be big enough and fairly chosen to represent the population. A sampling frame is the list of members you choose from."}, {"h": "Random and systematic", "b": "For a simple random sample, number every member and use a random number generator to pick them. For a systematic sample, divide the population size by the sample size to find k, pick a random start, then choose every kth one. With 500 people and a sample of 50, k = 10, so you might choose the 3rd, 13th, 23rd and so on."}, {"h": "Stratified, quota and others", "b": "Stratified sampling makes each group appear in the right proportion, then picks randomly within each group. Quota sampling also fills a set number from each group, but the interviewer chooses who, so it is not random. Cluster sampling picks whole groups, like a few classes, and convenience sampling uses whoever is easiest to reach, which is the most likely to be biased."}], "qs": [["What is a census?", ["Data collected from every member of a population", "Data collected from a small group", "A list of the population", "A type of graph"], "A census surveys the whole population, not a sample."], ["What is a sampling frame?", ["A list of all the members of the population", "The number of people in a sample", "A chart showing sample results", "The questions in a survey"], "The sampling frame is the list that the sample is chosen from."], ["Which is an advantage of a sample over a census?", ["It is quicker and cheaper", "It is always more accurate", "It includes everyone", "It cannot be biased"], "A sample uses fewer people, so it saves time and money."], ["In simple random sampling, which statement is true?", ["Every member has an equal chance of being chosen", "Every 10th person is chosen", "The easiest people to reach are chosen", "Only one group is chosen"], "Random sampling gives every member the same chance of selection."], ["You need a systematic sample of 50 from a list of 500. How often do you pick?", ["Every 10th person", "Every 50th person", "Every 5th person", "Every 25th person"], "500 ÷ 50 = 10, so pick every 10th person after a random start."], ["A school has 240 Year 9 and 360 Year 10 students. How many Year 9s are in a stratified sample of 50?", ["20", "30", "24", "25"], "240 ÷ 600 × 50 = 20."], ["A club has 120 adults and 80 juniors. How many juniors in a stratified sample of 30?", ["12", "18", "15", "8"], "80 ÷ 200 × 30 = 12."], ["An interviewer must ask 20 men and 20 women but chooses who to stop in the street. Which method is this?", ["Quota sampling", "Stratified sampling", "Systematic sampling", "Simple random sampling"], "Quota sampling fills set numbers from each group, but people are not chosen at random."], ["A researcher randomly picks 3 classes and surveys every student in them. Which method is this?", ["Cluster sampling", "Quota sampling", "Convenience sampling", "Systematic sampling"], "Cluster sampling chooses whole groups and then surveys everyone in those groups."], ["Why is surveying your own friends likely to give a biased sample?", ["Friends may be similar and not represent everyone", "The sample is chosen at random", "It always uses too many people", "Friends always tell the truth"], "A convenience sample of friends often shares similar views, so it does not represent the population."]], "bonus": ["What is ¼ of 200?", ["50", "40", "25", "800"], "200 ÷ 4 = 50."]}, {"ht": "Spr1", "t": "Planning and Collecting Data", "intro": "A good statistical investigation starts with a clear plan: a hypothesis to test, a fair way to collect data, and checks to avoid bias. This topic shows you how to write hypotheses, design good questionnaires and test them with a pilot study.", "how": ["A hypothesis is a statement you can test with data, such as 'Year 10 students are taller than Year 9 students'.", "Plan your investigation: decide the data you need, how to collect it, and how you will present and analyse it.", "Good questionnaire questions are clear, not leading, include a time frame, and have response boxes that do not overlap and cover every option.", "Bias is anything that makes results unfair or unrepresentative, such as a leading question or a poor sample.", "A pilot study is a small trial run that finds problems before the main survey."], "example": {"q": "Improve this question: 'How much TV do you watch? 0–1 hours, 1–2 hours, 2–3 hours.'", "steps": ["Add a time frame, such as 'per day', so the answers are comparable.", "Fix the overlaps: 1 and 2 hours each appear in two boxes.", "Cover every option by adding a box for more than 3 hours.", "New boxes: 0 to less than 1 hour, 1 to less than 2, 2 to less than 3, 3 hours or more."], "a": "'How many hours of TV do you watch per day?' with non-overlapping boxes that cover every possible answer."}, "walk": [{"h": "Writing a hypothesis", "b": "A hypothesis is a statement, not a question, so it can be shown to be true or false. 'Do boys like football more than girls?' is a question; 'Boys spend more time playing football than girls' is a hypothesis. Then collect data that could support or reject it."}, {"h": "Designing questionnaires", "b": "Questions should be easy to understand and have clear answers. Avoid leading questions like 'Don't you agree that school dinners are tasty?', which push people towards one answer. Response boxes must not overlap and must cover all possible answers, and personal questions should be handled sensitively."}, {"h": "Bias and pilot studies", "b": "Bias can come from leading questions, a sample that leaves out groups, or people not answering honestly. A pilot study tests your questionnaire on a few people first, so you can spot confusing questions and fix them. It can also show how long the survey takes."}], "qs": [["Which of these is a hypothesis?", ["Year 11 students do more homework than Year 9 students", "How much homework do you do?", "Homework is set on Mondays", "Do you like homework?"], "A hypothesis is a testable statement that the data can support or reject."], ["What is a pilot study?", ["A small trial run before the main survey", "The final results of a survey", "A survey of the whole population", "A graph of the results"], "A pilot study tests the method on a small group to find problems early."], ["Which of these is a leading question?", ["Don't you agree that cycling is great exercise?", "How many times a week do you cycle?", "Do you own a bicycle?", "How far do you live from school?"], "It pushes the person towards agreeing, which causes bias."], ["Response boxes read: 0–5, 5–10, 10–15. What is the main problem?", ["The boxes overlap", "There are too few people", "The question is leading", "The boxes are too wide"], "5 and 10 each appear in two boxes, so some answers fit in two places."], ["Response boxes read: 1–2, 3–4, 5–6. What is wrong if 0 or 7 are possible answers?", ["They do not cover every possible answer", "The boxes overlap", "The boxes are uneven", "Nothing is wrong"], "There is no box for 0 or 7 and above, so some people cannot answer."], ["Why add a time frame such as 'per week' to a question?", ["So everyone answers over the same period", "To make the question longer", "To make it a leading question", "To get qualitative data"], "Without a time frame, people may answer about different periods, so results cannot be compared."], ["Which of these is a cause of bias?", ["Only asking people at a gym about exercise", "Using random sampling", "Doing a pilot study", "Using clear questions"], "People at a gym probably exercise more than average, so the sample is unrepresentative."], ["Why might people not answer a question about their income honestly?", ["It is a sensitive, personal question", "It is a leading question", "It has a time frame", "It uses primary data"], "People may feel embarrassed, so sensitive questions can produce unreliable answers."], ["A pilot study shows people misunderstand question 3. What should you do?", ["Reword question 3 before the main survey", "Leave it and carry on", "Delete all the questions", "Only ask question 3"], "The purpose of a pilot study is to find and fix problems before collecting the real data."], ["Which is the best reason to use a random sample in an investigation?", ["It reduces bias in who is chosen", "It guarantees the hypothesis is true", "It means no questionnaire is needed", "It always gives a census"], "Random selection gives everyone an equal chance, which reduces sampling bias."]], "bonus": ["Which of these is a question rather than a statement?", ["How many pets do you have?", "I have two pets.", "Cats are popular pets.", "Dogs need walking."], "It asks for information and ends with a question mark."]}, {"ht": "Spr2", "t": "Tabulation", "intro": "Tables organise raw data so it is easier to read and analyse. This topic covers tally and frequency tables, grouped frequency tables using class intervals, and two-way tables that show two variables at once.", "how": ["A frequency table shows each value or group and how many times it occurs.", "Tally marks are drawn in groups of five, with the fifth mark crossing the first four.", "Grouped data uses class intervals such as 10 ≤ t < 20, which must not overlap.", "The midpoint of a class interval is the value halfway between its ends.", "In a two-way table, each row and column adds up to its total, which helps you find missing values."], "example": {"q": "60 students choose PE or Art. 35 are boys. 20 boys chose PE. 15 girls chose Art. How many students chose Art?", "steps": ["Girls: 60 − 35 = 25.", "Boys who chose Art: 35 − 20 = 15.", "Total choosing Art: 15 boys + 15 girls = 30.", "Check: girls choosing PE = 25 − 15 = 10, and total PE = 20 + 10 = 30, with 30 + 30 = 60."], "a": "30 students chose Art."}, "walk": [{"h": "Frequency tables", "b": "List each value, make a tally, then count the frequency. For example, one gate of five plus one extra mark is a frequency of 6. Always check that the frequencies add up to the total amount of data."}, {"h": "Grouped data", "b": "When there are lots of different values, put them in class intervals. For continuous data like time, use inequalities such as 10 ≤ t < 20 so no value fits two groups. The midpoint of 10 ≤ t < 20 is (10 + 20) ÷ 2 = 15. Grouping loses the exact values, so some detail is lost."}, {"h": "Two-way tables", "b": "A two-way table shows two categories at once, such as gender and favourite sport. Each row and column has a total, and the grand total sits in the corner. If you know enough of the numbers, use the totals to fill in the missing ones."}], "qs": [["A tally shows two complete gates of five and then three single marks. What is the frequency?", ["13", "3", "11", "15"], "Each gate is 5, so 5 + 5 + 3 = 13."], ["What does 'frequency' mean?", ["How many times something occurs", "The largest value", "The middle value", "The difference between values"], "Frequency is the count of how often each value or group appears."], ["What is the midpoint of the class interval 20 ≤ x < 30?", ["25", "20", "30", "10"], "(20 + 30) ÷ 2 = 25."], ["Which set of class intervals is correct for times in seconds?", ["0 ≤ t < 10, 10 ≤ t < 20", "0–10, 10–20", "0 < t < 10, 10 < t < 20", "0 ≤ t ≤ 10, 10 ≤ t ≤ 20"], "These intervals do not overlap and leave no gaps, so 10 fits in exactly one group."], ["Frequencies in a table are 4, 7, 9 and 5. How many items of data are there?", ["25", "9", "20", "4"], "4 + 7 + 9 + 5 = 25."], ["What is one disadvantage of grouping data?", ["The exact values are lost", "It makes data harder to read", "It always creates bias", "It needs more data"], "Once data is grouped, you only know which interval each value is in."], ["In a two-way table, 30 people chose tea. 12 of them were men. How many women chose tea?", ["18", "42", "12", "30"], "30 − 12 = 18."], ["A two-way table has a grand total of 80. The boys' total is 45. What is the girls' total?", ["35", "45", "125", "40"], "80 − 45 = 35."], ["60 students: 35 boys. 20 boys chose PE and 15 girls chose Art. How many girls chose PE?", ["10", "15", "20", "25"], "There are 60 − 35 = 25 girls, and 25 − 15 = 10 chose PE."], ["Masses are grouped 0 < m ≤ 10, 10 < m ≤ 20. Which group does 10 kg go in?", ["0 < m ≤ 10", "10 < m ≤ 20", "Both groups", "Neither group"], "The first group includes 10 (≤) and the second does not (<)."]], "bonus": ["What is 14 + 9 + 7?", ["30", "29", "31", "23"], "14 + 9 = 23, and 23 + 7 = 30."]}, {"ht": "Sum1", "t": "Averages: Mode, Median and Mean", "intro": "An average is a single value that represents a set of data. This topic covers the mode, median and mean, how to find them from lists and frequency tables, and how to choose the best one for a situation.", "how": ["The mode is the value that appears most often; for grouped data it is the modal class.", "The median is the middle value when the data is in order; its position is (n + 1) ÷ 2.", "The mean is the total of all the values divided by how many values there are.", "From a frequency table, mean = Σfx ÷ Σf (add up value × frequency, then divide by total frequency).", "For grouped data, use the midpoints to find an estimate of the mean."], "example": {"q": "Goals scored: 0 goals (frequency 3), 1 goal (5), 2 goals (8), 3 goals (4). Find the mean.", "steps": ["Multiply each value by its frequency: 0 × 3 = 0, 1 × 5 = 5, 2 × 8 = 16, 3 × 4 = 12.", "Add them: Σfx = 0 + 5 + 16 + 12 = 33.", "Total frequency: Σf = 3 + 5 + 8 + 4 = 20.", "Mean = 33 ÷ 20 = 1.65."], "a": "The mean is 1.65 goals."}, "walk": [{"h": "Mode, median and mean", "b": "For 3, 5, 5, 7, 10 the mode is 5 (most common), the median is 5 (middle value), and the mean is 30 ÷ 5 = 6. If there is an even number of values, the median is halfway between the two middle ones. The mean is affected by extreme values (outliers) but the median is not."}, {"h": "Averages from frequency tables", "b": "In a frequency table the mode is the value with the highest frequency. For the median, find the position (n + 1) ÷ 2 and count through the frequencies. For the mean, work out f × x for each row, add them up and divide by the total frequency."}, {"h": "Grouped data and choosing", "b": "For grouped data, use each class midpoint as x to estimate the mean, because the exact values are not known. The modal class is the group with the highest frequency. Choose the median when there are outliers, the mode for qualitative data, and the mean when you want to use every value."}], "qs": [["What is the mode of 4, 7, 7, 2, 9, 7, 3?", ["7", "4", "5.6", "9"], "7 appears three times, more than any other value."], ["What is the median of 3, 8, 1, 6, 4?", ["4", "6", "8", "4.4"], "In order: 1, 3, 4, 6, 8, so the middle value is 4."], ["What is the mean of 3, 5, 5, 7, 10?", ["6", "5", "7", "30"], "The total is 30, and 30 ÷ 5 = 6."], ["What is the median of 2, 5, 7, 10?", ["6", "7", "5", "6.5"], "The two middle values are 5 and 7, and halfway between them is 6."], ["Which average is best for favourite colours?", ["Mode", "Mean", "Median", "Range"], "Colours are qualitative, so only the mode can be found."], ["Salaries are £20k, £22k, £23k, £25k and £150k. Which average best represents them?", ["Median", "Mean", "Range", "Mode"], "The £150k outlier pulls the mean up, but the median is not affected."], ["Goals: 0 (3 times), 1 (5), 2 (8), 3 (4). What is the median?", ["2", "1.5", "1", "8"], "There are 20 values, so the median is between the 10th and 11th, which are both 2."], ["Goals: 0 (3 times), 1 (5), 2 (8), 3 (4). What is the mean?", ["1.65", "1.5", "2", "8.25"], "Σfx = 0 + 5 + 16 + 12 = 33, and 33 ÷ 20 = 1.65."], ["Times: 0 ≤ t < 10 (frequency 4), 10 ≤ t < 20 (6). What is the estimated mean?", ["11", "10", "15", "5"], "Midpoints 5 and 15: (5 × 4 + 15 × 6) ÷ 10 = (20 + 90) ÷ 10 = 11."], ["The mean of 4 numbers is 8. A fifth number makes the mean 9. What is the fifth number?", ["13", "9", "17", "1"], "The total goes from 4 × 8 = 32 to 5 × 9 = 45, so the fifth number is 45 − 32 = 13."]], "bonus": ["What is 36 ÷ 4?", ["9", "8", "6", "12"], "4 × 9 = 36, so 36 ÷ 4 = 9."]}, {"ht": "Sum2", "t": "Measures of Spread", "intro": "An average tells you a typical value, but measures of spread tell you how varied or consistent the data is. This topic covers the range, quartiles, interquartile range and percentiles, which help you compare data sets fairly.", "how": ["Range = largest value − smallest value.", "Put the data in order before finding quartiles; the lower quartile (Q1) is a quarter of the way through and the upper quartile (Q3) is three quarters.", "For a list of n values, Q1 is at position (n + 1) ÷ 4 and Q3 is at position 3(n + 1) ÷ 4.", "Interquartile range (IQR) = Q3 − Q1, the spread of the middle 50% of the data.", "Percentiles split the data into 100 equal parts; the 50th percentile is the median."], "example": {"q": "Find the IQR of 2, 4, 5, 7, 8, 10, 12, 13, 15, 18, 20.", "steps": ["The data is already in order, and n = 11.", "Q1 is at position (11 + 1) ÷ 4 = 3rd value, which is 5.", "Q3 is at position 3 × (11 + 1) ÷ 4 = 9th value, which is 15.", "IQR = 15 − 5 = 10."], "a": "The interquartile range is 10."}, "walk": [{"h": "The range", "b": "The range is the simplest measure of spread: biggest minus smallest. For 3, 7, 9, 15 the range is 15 − 3 = 12. A small range means the data is consistent, but one extreme value can make the range misleading."}, {"h": "Quartiles and IQR", "b": "Quartiles split ordered data into four equal parts. For 1, 3, 4, 6, 8, 9, 11 (n = 7), Q1 is the 2nd value (3), the median is the 4th value (6) and Q3 is the 6th value (9). The IQR is 9 − 3 = 6. The IQR ignores the extreme values at each end, so it is not affected by outliers."}, {"h": "Percentiles and comparing", "b": "The 10th percentile is the value below which 10% of the data lies; the 25th percentile is Q1 and the 75th is Q3. When comparing two data sets, compare an average and a measure of spread. For example, 'Class A has a higher median, but Class B has a smaller IQR, so its marks are more consistent.'"}], "qs": [["What is the range of 3, 9, 15, 7?", ["12", "15", "8.5", "6"], "15 − 3 = 12."], ["What does the interquartile range measure?", ["The spread of the middle 50% of the data", "The middle value", "The most common value", "The spread of all the data"], "IQR = Q3 − Q1, covering the middle half of the data."], ["Q1 = 12 and Q3 = 30. What is the IQR?", ["18", "42", "21", "30"], "IQR = Q3 − Q1 = 30 − 12 = 18."], ["Which percentile is the same as the median?", ["50th", "25th", "75th", "100th"], "The median is halfway, which is the 50th percentile."], ["Which percentile is the same as the upper quartile?", ["75th", "25th", "50th", "90th"], "The upper quartile is three quarters of the way through, the 75th percentile."], ["For 1, 3, 4, 6, 8, 9, 11, what is the lower quartile?", ["3", "4", "1", "6"], "n = 7, so Q1 is the (7 + 1) ÷ 4 = 2nd value, which is 3."], ["For 1, 3, 4, 6, 8, 9, 11, what is the upper quartile?", ["9", "8", "11", "6"], "Q3 is the 3 × (7 + 1) ÷ 4 = 6th value, which is 9."], ["Find the IQR of 2, 4, 5, 7, 8, 10, 12, 13, 15, 18, 20.", ["10", "18", "8", "11"], "Q1 is the 3rd value (5) and Q3 is the 9th value (15), so IQR = 15 − 5 = 10."], ["Why is the IQR often better than the range?", ["It is not affected by extreme values", "It uses only the largest value", "It is always bigger", "It includes outliers"], "The IQR ignores the top and bottom quarters, where outliers are found."], ["Class A has an IQR of 8 marks; Class B has an IQR of 15 marks. What can you say?", ["Class A's marks are more consistent", "Class B's marks are more consistent", "Class A has higher marks", "Class B has higher marks"], "A smaller IQR means the middle 50% of marks are closer together, so they are more consistent."]], "bonus": ["Put 9, 2, 7, 4 in order from smallest to largest.", ["2, 4, 7, 9", "9, 7, 4, 2", "2, 7, 4, 9", "4, 2, 7, 9"], "Smallest to largest means ascending order: 2, 4, 7, 9."]}]}, {"id": "pe", "name": "Physical Education", "board": "GCSE PE", "weeks": [{"ht": "Aut1", "t": "Health-related components of fitness", "intro": "Health-related fitness is about the parts of fitness that keep your body healthy and help you cope with everyday life. There are five components: cardiovascular endurance, muscular strength, muscular endurance, flexibility and body composition. Every sport needs a mix of them, so knowing them helps you understand performance and plan training.", "how": ["Cardiovascular endurance is the ability of the heart and lungs to supply oxygen to the working muscles for a long time.", "Muscular strength is the maximum force a muscle or muscle group can apply against a resistance.", "Muscular endurance is the ability of muscles to keep contracting repeatedly without getting tired.", "Flexibility is the range of movement possible at a joint.", "Body composition is the proportion of body weight made up of fat compared with muscle, bone and other tissue."], "example": {"q": "Which health-related component is most important for a marathon runner, and why? Name a test for it.", "steps": ["A marathon takes over 2 hours, so the athlete must keep working for a long time.", "This needs the heart and lungs to keep delivering oxygen to the muscles.", "That is cardiovascular endurance.", "It can be measured with the multi-stage fitness test (bleep test) or the Cooper 12-minute run."], "a": "Cardiovascular endurance, because the runner must supply oxygen to the muscles for over 2 hours; test it with the bleep test."}, "walk": [{"h": "Heart, lungs and muscles", "b": "Cardiovascular endurance lets a footballer keep running for 90 minutes; the multi-stage fitness test measures it. Muscular endurance is about one muscle group working again and again, like a rower's arms during a race; the one-minute sit-up or press-up test measures it. The difference is that cardiovascular endurance is about the whole body's oxygen supply, while muscular endurance is about specific muscles resisting fatigue."}, {"h": "Strength and flexibility", "b": "Muscular strength is the biggest force you can produce in one go, like a weightlifter lifting a heavy bar or a rugby player pushing in a scrum; the handgrip dynamometer test measures it. Flexibility is the range of movement at a joint, vital for gymnasts and hurdlers; the sit and reach test measures it. Good flexibility also helps prevent injuries such as pulled muscles."}, {"h": "Body composition", "b": "Body composition compares the amount of fat in your body with your lean mass, such as muscle, bone and organs. It can be estimated with skinfold callipers or body mass index (BMI). Different sports suit different body compositions: a long-distance runner usually has low body fat, because extra fat is extra weight to carry."}], "qs": [["How many health-related components of fitness are there?", ["Five", "Six", "Three", "Eleven"], "The five are cardiovascular endurance, muscular strength, muscular endurance, flexibility and body composition."], ["What is flexibility?", ["The range of movement possible at a joint", "The maximum force a muscle can apply", "The ability to change direction quickly", "The ability to keep running for a long time"], "Flexibility is the range of movement at a joint, such as how far you can reach in a stretch."], ["Which test measures muscular strength?", ["Handgrip dynamometer test", "Sit and reach test", "Multi-stage fitness test", "Ruler drop test"], "The handgrip dynamometer measures the maximum force your grip muscles can produce."], ["Which test measures flexibility?", ["Sit and reach test", "Handgrip dynamometer test", "Illinois agility run", "30 m sprint test"], "The sit and reach test measures flexibility in the lower back and hamstrings."], ["Which of these is a health-related component of fitness?", ["Body composition", "Agility", "Reaction time", "Coordination"], "Body composition is health-related; agility, reaction time and coordination are skill-related."], ["A gymnast does the splits. Which component is she showing?", ["Flexibility", "Muscular endurance", "Cardiovascular endurance", "Muscular strength"], "The splits need a large range of movement at the hip joints, which is flexibility."], ["What does the one-minute press-up test measure?", ["Muscular endurance", "Muscular strength", "Flexibility", "Body composition"], "Doing as many press-ups as possible in a minute tests how long muscles can keep working without tiring."], ["What is the difference between muscular strength and muscular endurance?", ["Strength is maximum force; endurance is repeating without tiring", "Strength is repeating; endurance is maximum force", "They mean exactly the same thing", "Strength is for legs; endurance is for arms"], "Strength is one maximum effort, while muscular endurance is keeping going over many contractions."], ["Which tool can be used to estimate body composition?", ["Skinfold callipers", "A stopwatch", "A metre ruler", "A sit and reach box"], "Skinfold callipers measure the thickness of fat under the skin to estimate body fat."], ["Why might a long-distance runner want low body fat?", ["Extra fat is extra weight to carry, so they tire sooner", "Fat makes muscles contract faster", "Low fat improves flexibility at every joint", "Fat stops the heart pumping blood"], "Carrying less extra weight means the runner uses less energy over a long distance."]], "bonus": ["Which organ pumps blood around the body?", ["The heart", "The lungs", "The liver", "The stomach"], "The heart is a muscular pump that sends blood carrying oxygen around the body."]}, {"ht": "Aut2", "t": "Skill-related fitness and fitness tests", "intro": "Skill-related fitness covers the components that help you perform the skills of a sport well: agility, balance, coordination, power, reaction time and speed. Fitness tests let you measure each component, compare yourself with others and track your progress. Choosing the right test and doing it the same way every time makes the results useful.", "how": ["Agility is changing direction quickly while staying in control; test it with the Illinois agility run.", "Balance is keeping your centre of mass over your base of support; test it with the stork stand.", "Coordination is using two or more body parts together smoothly; test it with the wall toss test.", "Power is strength × speed; reaction time is the time from a stimulus to the start of a response; speed is distance ÷ time.", "Test reliably: same conditions, same equipment, same warm-up and the same order each time."], "example": {"q": "Sam runs the 30 m sprint test in 5 seconds. What is his average speed, and what does the test measure?", "steps": ["Speed = distance ÷ time.", "Distance = 30 m and time = 5 s.", "30 ÷ 5 = 6.", "So his average speed is 6 metres per second (m/s)."], "a": "Sam's average speed is 6 m/s, and the test measures speed."}, "walk": [{"h": "Agility, balance, coordination", "b": "Agility helps a netball player dodge a defender, and it is measured by the Illinois agility run. Balance can be static, like a gymnast holding a handstand, or dynamic, like a surfer riding a wave; the stork stand test times how long you can balance on one foot. Coordination lets a tennis player watch the ball and swing at the same time; the alternate-hand wall toss test counts catches in 30 seconds."}, {"h": "Power, speed and reaction", "b": "Power combines strength and speed, like a high jumper's take-off, and it is measured by the vertical jump test. Speed is how quickly you can cover a distance, measured by the 30 m sprint test. Reaction time is how quickly you respond to a stimulus, like a sprinter reacting to the gun; in the ruler drop test, a lower catch distance means a quicker reaction."}, {"h": "Why and how we test", "b": "Fitness tests help identify strengths and weaknesses, show whether training is working, set goals and motivate performers. A test is reliable if it gives similar results when repeated in the same conditions, and valid if it really measures the component it claims to. Maximal tests, like the bleep test, push you to exhaustion, while submaximal tests do not."}], "qs": [["Which of these is a skill-related component of fitness?", ["Agility", "Flexibility", "Body composition", "Muscular endurance"], "Agility is skill-related; the other three are health-related components."], ["What does the ruler drop test measure?", ["Reaction time", "Speed", "Balance", "Power"], "Catching a dropped ruler measures how quickly you respond to a stimulus, which is reaction time."], ["Which test measures balance?", ["Stork stand test", "Vertical jump test", "30 m sprint test", "Sit and reach test"], "The stork stand times how long you can balance on one foot."], ["Power is a combination of which two things?", ["Strength and speed", "Balance and agility", "Flexibility and speed", "Reaction time and balance"], "Power = strength × speed, so it is force applied quickly."], ["Which test measures agility?", ["Illinois agility run", "Handgrip dynamometer", "Stork stand test", "Ruler drop test"], "The Illinois agility run times you weaving around cones, testing quick changes of direction."], ["A sprinter starts the instant the gun fires. Which component is this?", ["Reaction time", "Speed", "Coordination", "Agility"], "Responding to the sound of the gun is reaction time; speed is how fast they then run."], ["Which test is used to measure power?", ["Vertical jump test", "Stork stand test", "Ruler drop test", "Wall toss test"], "The vertical jump measures how high you can jump, which needs explosive power."], ["In the ruler drop test, Ali catches at 8 cm and Ben at 15 cm. Who reacted faster?", ["Ali, because a lower distance means a quicker reaction", "Ben, because a higher distance means quicker", "They reacted at the same speed", "You cannot tell from these results"], "The ruler falls further the longer you take, so Ali's lower distance shows a faster reaction."], ["A runner covers 100 m in 12.5 seconds. What is her average speed?", ["8 m/s", "1,250 m/s", "0.125 m/s", "12.5 m/s"], "Speed = distance ÷ time = 100 ÷ 12.5 = 8 m/s."], ["What makes a fitness test reliable?", ["It gives similar results when repeated in the same conditions", "It measures the component it claims to measure", "It is done by a famous athlete", "It always pushes you to exhaustion"], "Reliability means consistent results when repeated; measuring the right thing is validity."]], "bonus": ["Speed needs division. What is 30 ÷ 6?", ["5", "180", "24", "36"], "30 ÷ 6 = 5, because 6 × 5 = 30."]}, {"ht": "Spr1", "t": "Principles of training: SPORT and FITT", "intro": "Training works best when it follows some simple rules called the principles of training. SPORT reminds you of five: specificity, progression, overload, reversibility and tedium. FITT (frequency, intensity, time and type) is a tool for making training harder safely and in a planned way.", "how": ["Specificity: make training match the sport, the muscles and the type of fitness you need.", "Progression and overload: gradually make the body work harder than normal so it adapts and improves.", "Reversibility: if you stop training, fitness gains are lost.", "Tedium: vary your training to avoid boredom.", "Use FITT to overload: train more often (frequency), harder (intensity) or for longer (time), and choose the right type."], "example": {"q": "Priya jogs for 20 minutes twice a week. After a month it feels easy. Use FITT to suggest three ways to overload her training.", "steps": ["Frequency: train more often, for example three times a week instead of two.", "Intensity: run faster, or add some hills.", "Time: run for longer, for example 25 minutes instead of 20.", "Change one thing at a time and increase gradually to avoid injury."], "a": "She could run three times a week, run faster or run for 25 minutes, increasing gradually."}, "walk": [{"h": "Specificity and overload", "b": "Specificity means training should be relevant to your sport: a sprinter does short, fast runs, while a marathon runner does long, steady runs. Overload means making your body work harder than it is used to, so it adapts and improves. For example, a swimmer who always swims 400 m will improve more by building up to 600 m."}, {"h": "Progression and reversibility", "b": "Progression means increasing the training load gradually over time, because doing too much too soon can cause injury or overtraining. Reversibility means that if you stop training, for example because of an injury, you start to lose the fitness you gained. Gains in cardiovascular endurance can begin to drop within just a few weeks."}, {"h": "Tedium and FITT", "b": "Tedium is boredom from doing the same training again and again, so mix it up, for example by swapping a run for a swim or a circuit. FITT stands for Frequency (how often), Intensity (how hard), Time (how long) and Type (which method). Increasing frequency, intensity or time is a way to apply overload."}], "qs": [["In SPORT, what does the S stand for?", ["Specificity", "Speed", "Strength", "Stamina"], "S stands for specificity: training should match the needs of your sport."], ["What does the principle of reversibility mean?", ["Fitness gains are lost when training stops", "Training gets harder over time", "Training matches the sport", "Training is varied to avoid boredom"], "Reversibility means fitness is lost if you stop training."], ["In FITT, what does the I stand for?", ["Intensity", "Interval", "Improvement", "Individual"], "I stands for intensity, which is how hard you work."], ["Which principle is about avoiding boredom by varying training?", ["Tedium", "Overload", "Specificity", "Progression"], "Tedium means boredom, so training should be varied to keep motivation high."], ["What is overload?", ["Making the body work harder than it is used to", "Training while injured", "Stopping training to rest", "Doing the same session every week"], "Overload pushes the body beyond its normal level so that it adapts and improves."], ["A sprinter only does long, slow 10 km runs. Which principle is she ignoring?", ["Specificity", "Tedium", "Reversibility", "Frequency"], "Sprinting needs short, fast efforts, so slow 10 km runs do not match her event."], ["Increasing training from 2 to 3 sessions a week changes which part of FITT?", ["Frequency", "Intensity", "Time", "Type"], "Frequency is how often you train, so more sessions per week increases frequency."], ["Why should overload be increased gradually?", ["Doing too much too soon can cause injury", "The body cannot adapt to any overload", "It makes reversibility happen faster", "It makes training more boring"], "Gradual progression lets the body adapt safely without injury or overtraining."], ["A footballer breaks his leg and cannot train for 8 weeks. Which principle explains his fitness dropping?", ["Reversibility", "Specificity", "Overload", "Tedium"], "Without training, his fitness gains are lost, which is reversibility."], ["Which change uses 'Time' to overload a cycling session?", ["Cycling for 45 minutes instead of 30", "Cycling up steeper hills", "Cycling 4 days a week instead of 3", "Swapping cycling for swimming"], "Time is how long each session lasts, so riding for longer increases time."]], "bonus": ["Why do we warm up before exercise?", ["To raise body temperature and prepare the muscles", "To make the muscles colder and stiffer", "To use up all our energy before we start", "To lower our heart rate"], "A warm-up gradually raises heart rate and muscle temperature, helping performance and reducing injury risk."]}, {"ht": "Spr2", "t": "Training methods and heart rate zones", "intro": "Training methods are the different ways of exercising to improve fitness. Each method suits certain components of fitness and certain sports. Working out heart rate training zones from your maximum heart rate (220 − age) tells you how hard to work.", "how": ["Continuous: steady exercise for at least 20 minutes without rest, for cardiovascular endurance.", "Fartlek ('speed play'): running with changes of speed and terrain, without rest.", "Interval: periods of hard work followed by rest; circuit: a series of different exercises at stations.", "Weights: heavy loads and few reps for strength, light loads and many reps for muscular endurance; plyometrics: jumps and bounds for power.", "Maximum heart rate = 220 − age; the aerobic zone is 60–80% of it and the anaerobic zone is 80–90%."], "example": {"q": "Work out the aerobic training zone (60–80% of maximum heart rate) for a 15-year-old.", "steps": ["Maximum heart rate = 220 − age = 220 − 15 = 205 bpm.", "60% of 205 = 0.6 × 205 = 123 bpm.", "80% of 205 = 0.8 × 205 = 164 bpm.", "So the aerobic zone runs from 123 to 164 beats per minute."], "a": "The aerobic training zone for a 15-year-old is 123–164 bpm."}, "walk": [{"h": "Endurance methods", "b": "Continuous training means exercising at a steady pace for at least 20 minutes, such as a 30-minute jog, and suits long-distance runners and cyclists. Fartlek, Swedish for 'speed play', mixes speeds and terrain, like jogging, then sprinting to a lamp post, then walking uphill; it suits games players who change pace a lot. Interval training alternates hard work with rest, like 6 × 200 m sprints with a 1-minute rest after each."}, {"h": "Circuits, weights, plyometrics", "b": "Circuit training uses a series of stations, such as press-ups, squats and skipping, with a set time at each, and can be adapted to almost any sport. Weight training uses free weights or machines: heavy loads with few repetitions build strength, while light loads with many repetitions build muscular endurance. Plyometrics uses explosive jumps, such as box jumps and bounding, to develop power for sports like basketball and long jump."}, {"h": "Heart rate zones", "b": "Your maximum heart rate (MHR) is roughly 220 − your age, so a 20-year-old's is 200 bpm. Training at 60–80% of MHR is the aerobic zone, which improves cardiovascular endurance; for a 20-year-old that is 120–160 bpm. Training at 80–90% is the anaerobic zone, used for speed and high-intensity work; for a 20-year-old that is 160–180 bpm."}], "qs": [["What is the formula for estimating maximum heart rate?", ["220 − age", "200 − age", "220 + age", "180 − age"], "Maximum heart rate is estimated as 220 minus your age."], ["What does 'fartlek' mean?", ["Speed play", "Steady running", "Weight lifting", "Jump training"], "Fartlek is Swedish for 'speed play', because the pace keeps changing."], ["Which training method uses a series of exercises at different stations?", ["Circuit training", "Continuous training", "Fartlek training", "Plyometric training"], "Circuit training moves you around stations, each with a different exercise."], ["Which method alternates periods of hard work with periods of rest?", ["Interval training", "Continuous training", "Fartlek training", "Weight training"], "Interval training has set work periods followed by rest or recovery periods."], ["Which training method is best for developing power?", ["Plyometric training", "Continuous training", "Stretching", "Fartlek training"], "Plyometrics uses explosive jumps and bounds, which develop power."], ["What is the maximum heart rate of a 14-year-old?", ["206 bpm", "234 bpm", "214 bpm", "196 bpm"], "220 − 14 = 206 bpm."], ["To improve muscular endurance in weight training, what should you use?", ["Light weights with many repetitions", "Heavy weights with few repetitions", "No weights and no repetitions", "Maximum weight once a week"], "Many repetitions with lighter loads train muscles to keep working without tiring."], ["What percentage of maximum heart rate is the aerobic training zone?", ["60–80%", "80–90%", "20–40%", "90–100%"], "The aerobic training zone is 60–80% of maximum heart rate."], ["A 40-year-old's MHR is 180 bpm. What is 60% of this?", ["108 bpm", "120 bpm", "144 bpm", "72 bpm"], "0.6 × 180 = 108 bpm, the bottom of the aerobic zone."], ["Work out the anaerobic zone (80–90% of MHR) for a 20-year-old.", ["160–180 bpm", "120–160 bpm", "176–198 bpm", "180–200 bpm"], "MHR = 220 − 20 = 200; 0.8 × 200 = 160 and 0.9 × 200 = 180."]], "bonus": ["Percentages are needed for heart rate zones. What is 50% of 180?", ["90", "130", "360", "45"], "50% means a half, and half of 180 is 90."]}, {"ht": "Sum1", "t": "The muscular system", "intro": "Your muscles move your body by pulling on your bones. Knowing the names and actions of the major muscles helps you explain how any sporting movement happens. Muscles work in antagonistic pairs: while one contracts, the other relaxes.", "how": ["Muscles are attached to bones by tendons; when a muscle contracts, it pulls on the bone and causes movement.", "Muscles can only pull, not push, so they work in antagonistic pairs.", "The agonist (prime mover) contracts to cause the movement; the antagonist relaxes to allow it.", "Key pairs: biceps and triceps; quadriceps and hamstrings; hip flexors and gluteals; gastrocnemius and tibialis anterior.", "Always name the muscle, the joint and the action, for example: the quadriceps extend the leg at the knee."], "example": {"q": "Explain how the arm moves during the upward phase of a bicep curl.", "steps": ["The movement happens at the elbow joint.", "The arm bends, which is called flexion.", "The biceps is the agonist: it contracts and shortens, pulling the forearm up.", "The triceps is the antagonist: it relaxes and lengthens to allow the movement."], "a": "The biceps contracts as the agonist and the triceps relaxes as the antagonist, flexing the arm at the elbow."}, "walk": [{"h": "Major muscles and actions", "b": "In the upper body, the deltoid moves the arm at the shoulder, the biceps bends (flexes) the elbow and the triceps straightens (extends) it. The pectorals pull the arm across the chest, the latissimus dorsi pulls the arm down and back, the rotator cuff rotates the shoulder and the abdominals bend the trunk forward, as in a sit-up. In the legs, the hip flexors lift the knee, the gluteals extend the hip, the quadriceps straighten the knee, the hamstrings bend it, the gastrocnemius points the toes and the tibialis anterior pulls them up."}, {"h": "Antagonistic pairs", "b": "Because muscles can only pull, they are arranged in pairs that work opposite each other. The agonist contracts to make the movement while the antagonist relaxes; to move back, they swap roles. For example, when kicking a football, the quadriceps contract to straighten the knee while the hamstrings relax."}, {"h": "Types of contraction", "b": "In a concentric contraction the muscle shortens as it works, like the biceps lifting a weight. In an eccentric contraction it lengthens while still working, like the biceps slowly lowering the weight. In an isometric contraction the muscle works but does not change length, like the abdominals holding a plank."}], "qs": [["What attaches muscles to bones?", ["Tendons", "Ligaments", "Cartilage", "Nerves"], "Tendons join muscle to bone; ligaments join bone to bone."], ["Which muscle extends (straightens) the arm at the elbow?", ["Triceps", "Biceps", "Deltoid", "Pectorals"], "The triceps, at the back of the upper arm, extends the elbow."], ["Which muscle group is at the front of the thigh?", ["Quadriceps", "Hamstrings", "Gluteals", "Gastrocnemius"], "The quadriceps are at the front of the thigh; the hamstrings are at the back."], ["Which muscle is the antagonistic partner of the biceps?", ["Triceps", "Deltoid", "Pectorals", "Latissimus dorsi"], "The biceps and triceps work as a pair to bend and straighten the elbow."], ["Which muscle points the toes, as when standing on tiptoe?", ["Gastrocnemius", "Tibialis anterior", "Quadriceps", "Hip flexors"], "The gastrocnemius (calf) points the toes, which is plantar flexion."], ["What is the job of the agonist?", ["It contracts to cause the movement", "It relaxes to allow the movement", "It joins bone to bone", "It stops the joint moving at all"], "The agonist, or prime mover, is the muscle that contracts to produce the movement."], ["During a sit-up, which muscles are the agonist that bend the trunk forward?", ["Abdominals", "Latissimus dorsi", "Deltoids", "Gluteals"], "The abdominals contract to flex the trunk and lift the upper body in a sit-up."], ["Why do muscles work in antagonistic pairs?", ["Muscles only pull, so one moves a joint and the other moves it back", "Muscles only push, so two are needed to push together", "One muscle rests completely while the other grows", "Working in pairs makes bones grow longer"], "Since a muscle can only pull, a second muscle is needed to pull the joint back the other way."], ["A footballer bends his knee back to prepare to kick. Which muscle is the agonist?", ["Hamstrings", "Quadriceps", "Gluteals", "Tibialis anterior"], "Bending (flexing) the knee is done by the hamstrings, while the quadriceps relax."], ["Lowering a weight slowly in a bicep curl, the biceps lengthens while working. What type of contraction is this?", ["Eccentric", "Concentric", "Isometric", "Antagonistic"], "An eccentric contraction is when a muscle lengthens under tension, controlling the movement."]], "bonus": ["What is a joint?", ["A place where two or more bones meet", "A muscle that bends the arm", "The middle of a long bone", "A tube that carries blood"], "A joint is where two or more bones meet, allowing movement such as at the knee or elbow."]}, {"ht": "Sum2", "t": "Muscles and exercise", "intro": "Not all muscle fibres are the same: some are built for long, steady work and others for short, explosive bursts. Exercise changes your muscles straight away and, if you keep training, over months and years too. Understanding this explains why sprinters and marathon runners train so differently.", "how": ["Slow twitch fibres contract slowly with less force but resist fatigue, so they suit endurance events.", "Fast twitch fibres contract quickly and powerfully but tire fast, so they suit sprinting and power events.", "Short-term effects happen during and just after exercise, such as warmer muscles, lactic acid and fatigue.", "Long-term effects come from regular training over months, such as hypertrophy (bigger, stronger muscles).", "Rest and recovery are needed so muscles can repair and adapt."], "example": {"q": "Explain why a marathon runner is likely to have a high percentage of slow twitch fibres.", "steps": ["A marathon is a long event that is done mainly aerobically, using oxygen.", "Slow twitch fibres use oxygen efficiently and are very resistant to fatigue.", "They have lots of capillaries and mitochondria, which help them keep working.", "Fast twitch fibres would tire far too quickly over 42 km."], "a": "Slow twitch fibres let the runner keep working aerobically for hours without tiring."}, "walk": [{"h": "Slow and fast twitch fibres", "b": "Slow twitch (type I) fibres contract slowly and with low force, but can keep going for a long time because they use oxygen (aerobic). Fast twitch (type II) fibres contract quickly and with great force, but tire quickly because they mainly work without oxygen (anaerobic). Everyone has a mix: a 100 m sprinter usually has more fast twitch fibres, while a long-distance cyclist usually has more slow twitch."}, {"h": "Short-term effects", "b": "During exercise, muscles need more energy and oxygen, so heart rate and breathing rate rise, and the muscles get warmer. In hard, anaerobic exercise, lactic acid builds up, causing muscle fatigue and a burning feeling. After exercise, extra oxygen is needed to remove the lactic acid (oxygen debt), and muscles may feel sore for a day or two (DOMS)."}, {"h": "Long-term effects", "b": "Regular training over months causes muscle hypertrophy: muscles get bigger and stronger. Endurance training also increases muscular endurance, the number of capillaries supplying the muscles and the number of mitochondria, so more oxygen can be used. Muscles become better at tolerating lactic acid, and tendons get stronger, lowering the risk of injury."}], "qs": [["Which type of muscle fibre is best suited to a marathon?", ["Slow twitch", "Fast twitch", "Neither type", "Both exactly equally"], "Slow twitch fibres resist fatigue and work aerobically, ideal for long events."], ["Which feature belongs to fast twitch fibres?", ["They contract quickly and powerfully but tire fast", "They contract slowly and rarely tire", "They only work when oxygen is present", "They are only found in the heart"], "Fast twitch fibres give quick, powerful contractions but fatigue quickly."], ["Which event relies mostly on fast twitch fibres?", ["100 m sprint", "Marathon", "Long-distance cycling", "1,500 m swim"], "A 100 m sprint is short and explosive, which needs fast twitch fibres."], ["What substance builds up in muscles during hard anaerobic exercise?", ["Lactic acid", "Oxygen", "Glucose", "Calcium"], "Without enough oxygen, muscles produce lactic acid, which causes fatigue."], ["What is muscle hypertrophy?", ["An increase in muscle size", "A decrease in muscle size", "A muscle cramp", "A torn tendon"], "Hypertrophy means muscles grow bigger and stronger as a result of training."], ["Which is a short-term effect of exercise on muscles?", ["Muscles get warmer", "Muscles get bigger (hypertrophy)", "More capillaries grow", "Tendons get stronger"], "Warmer muscles happen during exercise; the others take months of training."], ["Which is a long-term effect of regular endurance training?", ["More capillaries supply the muscles", "Lactic acid builds up during a sprint", "Muscles feel tired during a run", "Muscles get warmer during a session"], "Over months, endurance training grows more capillaries to deliver oxygen to muscles."], ["Why do slow twitch fibres resist fatigue?", ["They use oxygen efficiently to release energy aerobically", "They contract with maximum force", "They work without any oxygen", "They store lots of lactic acid"], "Using oxygen aerobically releases energy without a build-up of lactic acid, so they keep going."], ["What is meant by 'oxygen debt'?", ["Extra oxygen needed after exercise to remove lactic acid", "The oxygen breathed in before a race", "Oxygen stored in the bones", "Not breathing at all during exercise"], "After hard exercise you keep breathing heavily to take in extra oxygen to break down lactic acid."], ["Which athlete would benefit most from training to tolerate lactic acid?", ["A 400 m runner", "A darts player", "A snooker player", "An archer"], "A 400 m race is a long, intense anaerobic effort that produces lots of lactic acid."]], "bonus": ["Which gas do muscles need from the blood to release energy aerobically?", ["Oxygen", "Carbon dioxide", "Nitrogen", "Helium"], "Aerobic respiration uses oxygen to release energy from glucose, producing carbon dioxide and water."]}]}];
